(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("strabo-geography-3-e", [{"sp": "HDR", "t": "Γεωγραφικά (Ηʹ–Ιʹ)"}, {"sp": "HDR", "t": "Βιβλίον Ηʹ", "st": "8"}, {"sp": "N", "t": "ἐπεὶ δ’ ἐπιόντες ἀπὸ τῶν ἑσπερίων τῆς Εὐρώπης μερῶν, ὅσα τῇ θαλάττῃ περιέχεται τῇ ἐντὸς καὶ τῇ ἐκτός, τά τε βάρβαρα ἔθνη περιωδεύσαμεν πάντα ἐν αὐτῇ μέχρι τοῦ Τανάιδος καὶ τῆς Ἑλλάδος οὐ πολὺ μέρος, ἀποδώσομεν νυνὶ τὰ λοιπὰ τῆς Ἑλλαδικῆς γεωγραφίας, ἅπερ Ὅμηρος μὲν πρῶτος, ἔπειτα καὶ ἄλλοι πλείους ἐπραγματεύσαντο, οἱ μὲν ἰδίᾳ λιμένας ἢ περίπλους ἢ περιόδους γῆς ἤ τι τοιοῦτον ἄλλο ἐπιγράψαντες, ἐν οἷς καὶ τὰ Ἑλλαδικὰ περιέχεται, οἱ δ’ ἐν τῇ κοινῇ τῆς ἱστορίας γραφῇ χωρὶς ἀποδείξαντες τὴν τῶν ἠπείρων τοπογραφίαν, καθάπερ Ἔφορός τε ἐποίησε καὶ Πολύβιος· ἄλλοι δ’ εἰς τὸν φυσικὸν τόπον καὶ τὸν μαθηματικὸν προσέλαβόν τινα καὶ τῶν τοιούτων, καθάπερ Ποσειδώνιός τε καὶ Ἵππαρχος. τὰ μὲν οὖν τῶν ἄλλων εὐδιαίτητά ἐστι, τὰ δ’ Ὁμήρου σκέψεως δεῖται κριτικῆς, ποιητικῶς τε λέγοντος καὶ οὐ τὰ νῦν ἀλλὰ τὰ ἀρχαῖα, ὧν ὁ χρόνος ἠμαύρωκε τὰ πολλά. ὡς δ’ οὖν δυνατὸν ἐγχειρητέον ἀρξαμένοις ἀφ’ ὧνπερ ἀπελίπομεν· ἐτελεύτα δ’ ἡμῖν ὁ λόγος ἀπὸ μὲν τῆς ἑσπέρας καὶ τῶν ἄρκτων εἰς τὰ Ἠπειρωτικὰ ἔθνη καὶ τὰ τῶν Ἰλλυριῶν, ἀπὸ δὲ τῆς ἕω εἰς τὰ τῶν Μακεδόνων μέχρι Βυζαντίου. μετὰ μὲν οὖν τοὺς Ἠπειρώτας καὶ τοὺς Ἰλλυριοὺς τῶν Ἑλλήνων Ἀκαρνᾶνές εἰσι καὶ Αἰτωλοὶ καὶ Λοκροὶ οἱ Ὀζόλαι· πρὸς δὲ τούτοις Φωκεῖς τε καὶ Βοιωτοί· τούτοις δ’ ἀντίπορθμός ἐστιν ἡ Πελοπόννησος, ἀπολαμβάνουσα μεταξὺ τὸν Κορινθιακὸν κόλπον καὶ σχηματίζουσά τε τοῦτον καὶ σχηματιζομένη ὑπ’ αὐτοῦ· μετὰ δὲ Μακεδονίαν Θετταλοὶ μέχρι Μαλιέων καὶ τῶν ἄλλων τῶν ἐκτὸς Ἰσθμοῦ καὶ αὐτῶν τῶν ἐντός.", "st": "8.1.1"}, {"sp": "N", "t": "Ἑλλάδος μὲν οὖν πολλὰ ἔθνη γεγένηται, τὰ δ’ ἀνωτάτω τοσαῦτα ὅσας καὶ διαλέκτους παρειλήφαμεν τὰς Ἑλληνίδας· τούτων δ’ αὐτῶν τεττάρων οὐσῶν τὴν μὲν Ἰάδα τῇ παλαιᾷ Ἀτθίδι τὴν αὐτὴν φαμέν (καὶ γὰρ Ἴωνες ἐκαλοῦντο οἱ τότε Ἀττικοί, καὶ ἐκεῖθέν εἰσιν οἱ τὴν Ἀσίαν ἐποικήσαντες Ἴωνες καὶ χρησάμενοι τῇ νῦν λεγομένῃ γλώττῃ Ἰάδι), τὴν δὲ Δωρίδα τῇ Αἰολίδι· πάντες γὰρ οἱ ἐκτὸς Ἰσθμοῦ πλὴν Ἀθηναίων καὶ Μεγαρέων καὶ τῶν περὶ τὸν Παρνασσὸν Δωριέων καὶ νῦν ἔτι Αἰολεῖς καλοῦνται· καὶ τοὺς Δωριέας δὲ ὀλίγους ὄντας καὶ τραχυτάτην οἰκοῦντας χώραν εἰκός ἐστι τῷ ἀνεπιμίκτῳ παρατρέψαι τὴν γλῶτταν καὶ τὰ ἄλλα ἔθη πρὸς τὸ μὴ ὁμογενές, ὁμογενεῖς πρότερον ὄντας. τοῦτο δ’ αὐτὸ καὶ τοῖς Ἀθηναίοις συνέβη, λεπτόγεών τε καὶ τραχεῖαν οἰκοῦντας χώραν ἀπορθήτους μεῖναι διὰ τοῦτο καὶ αὐτόχθονας νομισθῆναι φησὶν ὁ Θουκυδίδης, κατέχοντας τὴν αὐτὴν ἀεί, μηδενὸς ἐξελαύνοντος αὐτοὺς μηδ’ ἐπιθυμοῦντος ἔχειν τὴν ἐκείνων· τοῦτο τοίνυν αὐτὸ καὶ τοῦ ἑτερογλώττου καὶ τοῦ ἑτεροεθοῦς αἴτιον, ὡς εἰκός, ὑπῆρξε καίπερ ὀλίγοις οὖσιν. οὕτω δὲ τοῦ Αἰολικοῦ πλήθους ἐπικρατοῦντος ἐν τοῖς ἐκτὸς Ἰσθμοῦ, καὶ οἱ ἐντὸς Αἰολεῖς πρότερον ἦσαν, εἶτ’ ἐμίχθησαν, Ἰώνων μὲν ἐκ τῆς Ἀττικῆς τὸν Αἰγιαλὸν κατασχόντων, τῶν δ’ Ἡρακλειδῶν τοὺς Δωριέας καταγαγόντων, ὑφ’ ὧν τά τε Μέγαρα ᾠκίσθη καὶ πολλαὶ τῶν ἐν τῇ Πελοποννήσῳ πόλεων. οἱ μὲν οὖν Ἴωνες ἐξέπεσον πάλιν ταχέως ὑπὸ Ἀχαιῶν, Αἰολικοῦ ἔθνους· ἐλείφθη δ’ ἐν τῇ Πελοποννήσῳ τὰ δύο ἔθνη, τό τε Αἰολικὸν καὶ τὸ Δωρικόν. ὅσοι μὲν οὖν ἧττον τοῖς Δωριεῦσιν ἐπεπλέκοντο (καθάπερ συνέβη τοῖς τε Ἀρκάσι καὶ τοῖς Ἠλείοις, τοῖς μὲν ὀρεινοῖς τελέως οὖσι καὶ οὐκ ἐμπεπτωκόσιν εἰς τὸν κλῆρον, τοῖς δ’ ἱεροῖς νομισθεῖσι τοῦ Ὀλυμπίου Διὸς καὶ καθ’ αὑτοὺς εἰρήνην ἄγουσι πολὺν χρόνον, ἄλλως τε καὶ τοῦ Αἰολικοῦ γένους οὖσι καὶ δεδεγμένοις τὴν Ὀξύλῳ συγκατελθοῦσαν στρατιὰν περὶ τὴν τῶν Ἡρακλειδῶν κάθοδον), οὗτοι αἰολιστὶ διελέχθησαν, οἱ δ’ ἄλλοι μικτῇ τινι ἐχρήσαντο ἐξ ἀμφοῖν, οἱ μὲν μᾶλλον οἱ δ’ ἧττον αἰολίζοντες· σχεδὸν δέ τι καὶ νῦν κατὰ πόλεις ἄλλοι ἄλλως διαλέγονται, δοκοῦσι δὲ δωρίζειν ἅπαντες διὰ τὴν συμβᾶσαν ἐπικράτειαν. τοσαῦτα μὲν οὖν τὰ τῶν Ἑλλήνων ἔθνη καὶ οὕτως, ὡς τύπῳ εἰπεῖν, ἀφωρισμένα. λέγωμεν δὴ διαλαβόντες ὃν χρὴ τρόπον τῇ τάξει περὶ αὐτῶν.", "st": "8.1.2"}, {"sp": "N", "t": "Ἔφορος μὲν οὖν ἀρχὴν εἶναι τῆς Ἑλλάδος τὴν Ἀκαρνανίαν φησὶν ἀπὸ τῶν ἑσπερίων μερῶν· ταύτην γὰρ συνάπτειν πρώτην τοῖς Ἠπειρωτικοῖς ἔθνεσιν. ἀλλ’ ὥσπερ οὗτος τῇ παραλίᾳ μέτρῳ χρώμενος ἐντεῦθεν ποιεῖται τὴν ἀρχήν, ἡγεμονικόν τι τὴν θάλατταν κρίνων πρὸς τὰς τοπογραφίας, ἐπεὶ ἄλλως γ’ ἐνεχώρει κατὰ τὴν Μακεδόνων καὶ Θετταλῶν τὴν ἀρχὴν ἀποφαίνεσθαι τῆς Ἑλλάδος· οὕτω καὶ ἡμῖν προσήκει ἀκολουθοῦσι τῇ φύσει τῶν τόπων σύμβουλον ποιεῖσθαι τὴν θάλατταν. αὕτη δ’ ἐκ τοῦ Σικελικοῦ πελάγους προσπεσοῦσα τῇ μὲν ἀναχεῖται πρὸς τὸν Κορινθιακὸν κόλπον, τῇ δ’ ἀποτελεῖ χερρόνησον μεγάλην τὴν Πελοπόννησον, ἰσθμῷ στενῷ κλειομένην. ἔστι δὲ τὰ δύο μέγιστα συστήματα τῆς Ἑλλάδος τό τε ἐντὸς Ἰσθμοῦ καὶ τὸ ἐκτὸς μέχρι τῆς ἐκβολῆς τοῦ Πηνειοῦ· ἔστι δὲ καὶ μεῖζον καὶ ἐπιφανέστερον τὸ ἐντὸς Ἰσθμοῦ· σχεδὸν δέ τι καὶ ἀκρόπολίς ἐστιν ἡ Πελοπόννησος τῆς συμπάσης Ἑλλάδος … χωρὶς γὰρ τῆς λαμπρότητος καὶ δυνάμεως τῶν ἐνοικησάντων ἐθνῶν αὐτὴ ἡ τῶν τόπων θέσις ὑπογράφει τὴν ἡγεμονίαν ταύτην, κόλποις τε καὶ ἄκραις πολλαῖς καὶ τοῖς σημειωδεστάτοις, χερρονήσοις μεγάλαις, διαπεποικιλμένη, ὧν ἐκ διαδοχῆς ἑτέρα τὴν ἑτέραν ἔχει. ἔστι δὲ πρώτη μὲν τῶν χερρονήσων ἡ Πελοπόννησος, ἰσθμῷ κλειομένη τετταράκοντα σταδίων. δευτέρα δὲ ἡ καὶ ταύτην περιέχουσα, ἧς ἰσθμός ἐστιν ὁ ἐκ Παγῶν τῶν Μεγαρικῶν εἰς Νίσαιαν, τὸ Μεγαρέων ἐπίνειον, ὑπερβολῇ σταδίων ἑκατὸν εἴκοσιν ἀπὸ θαλάττης ἐπὶ θάλατταν. τρίτη δ’ ἡ καὶ ταύτην περιέχουσα, ἧς ἰσθμὸς ἀπὸ τοῦ μυχοῦ τοῦ Κρισαίου κόλπου μέχρι Θερμοπυλῶν· ἡ δ’ ἐπινοουμένη εὐθεῖα γραμμὴ ὅσον πεντακοσίων ὀκτὼ σταδίων τὴν μὲν Βοιωτίαν ἅπασαν ἐντὸς ἀπολαμβάνουσα, τὴν δὲ Φωκίδα τέμνουσα λοξὴν καὶ τοὺς Ἐπικνημιδίους. τετάρτη δὲ ἡ ἀπὸ τοῦ Ἀμβρακικοῦ κόλπου διὰ τῆς Οἴτης καὶ τῆς Τραχινίας εἰς τὸν Μαλιακὸν κόλπον καθήκοντα ἔχουσα τὸν ἰσθμὸν καὶ τὰς Θερμοπύλας, ὅσον ὀκτακοσίων ὄντα σταδίων· πλειόνων δ’ ἢ χιλίων ἄλλος ἐστὶν ἀπὸ τοῦ αὐτοῦ κόλπου τοῦ Ἀμβρακικοῦ διὰ Θετταλῶν καὶ Μακεδόνων εἰς τὸν Θερμαῖον διήκων μυχόν. ὑπαγορεύει δή τινα τάξιν οὐ φαύλην ἡ τῶν χερρονήσων διαδοχή· δεῖ δ’ ἀπὸ τῆς ἐλαχίστης ἄρξασθαι, ἐπιφανεστάτης δέ.", "st": "8.1.3"}, {"sp": "N", "t": "ἔστι τοίνυν ἡ Πελοπόννησος ἐοικυῖα φύλλῳ πλατάνου τὸ σχῆμα, ἴση σχεδόν τι κατὰ μῆκος καὶ κατὰ πλάτος ὅσον χιλίων καὶ τετρακοσίων σταδίων, τὸ μὲν ἀπὸ τῆς ἑσπέρας ἐπὶ τὴν ἕω, τοῦτο δ’ ἐστὶ τὸ ἀπὸ τοῦ Χελωνάτα δι’ Ὀλυμπίας καὶ τῆς Μεγαλοπολίτιδος ἐπὶ Ἰσθμόν· τὸ δ’ ἀπὸ τοῦ νότου πρὸς τὴν ἄρκτον, ὅ ἐστι τὸ ἀπὸ Μαλεῶν δι’ Ἀρκαδίας εἰς Αἴγιον· ἡ δὲ περίμετρος μὴ κατακολπίζοντι τετρακισχιλίων σταδίων, ὡς Πολύβιος· Ἀρτεμίδωρος δὲ καὶ τετρακοσίους προστίθησι· κατακολπίζοντι δὲ πλείους τῶν ἑξακοσίων ἐπὶ τοῖς πεντακισχιλίοις. ὁ δ’ Ἰσθμὸς κατὰ τὸν δίολκον, δι’ οὗ τὰ πορθμεῖα ὑπερνεωλκοῦσιν ἀπὸ τῆς ἑτέρας εἰς τὴν ἑτέραν θάλατταν, εἴρηται ὅτι τετταράκοντα σταδίων ἐστίν.", "st": "8.2.1"}, {"sp": "N", "t": "ἔχουσι δὲ τῆς χερρονήσου ταύτης τὸ μὲν ἑσπέριον μέρος Ἠλεῖοι καὶ Μεσσήνιοι, κλυζόμενοι τῷ Σικελικῷ πελάγει· προσλαμβάνουσι δὲ καὶ τῆς ἑκατέρωθεν παραλίας, ἡ μὲν Ἠλεία πρὸς ἄρκτον ἐπιστρέφουσα καὶ τὴν ἀρχὴν τοῦ Κορινθιακοῦ κόλπου μέχρι ἄκρας Ἀράξου, καθ’ ἣν ἀντίπορθμός ἐστιν ἥ τε Ἀκαρνανία καὶ αἱ προκείμεναι νῆσοι, Ζάκυνθος καὶ Κεφαλληνία καὶ Ἰθάκη καὶ [αἱ] Ἐχινάδες, ὧν ἐστι καὶ τὸ Δουλίχιον· τῆς δὲ Μεσσηνίας τὸ πλέον ἀνεῳγμένον πρὸς νότον καὶ τὸ Λιβυκὸν πέλαγος μέχρι τῶν καλουμένων Θυρίδων πλησίον Ταινάρου. ἑξῆς δὲ μετὰ μὲν τὴν Ἠλείαν ἐστὶ τὸ τῶν Ἀχαιῶν ἔθνος πρὸς ἄρκτους βλέπον καὶ τῷ Κορινθιακῷ κόλπῳ παρατεῖνον, τελευτᾷ δ’ εἰς τὴν Σικυωνίαν· ἐντεῦθεν δὲ Σικυὼν καὶ Κόρινθος ἐκδέχεται μέχρι τοῦ Ἰσθμοῦ· μετὰ δὲ τὴν Μεσσηνίαν ἡ Λακωνικὴ καὶ ἡ Ἀργεία, μέχρι τοῦ Ἰσθμοῦ καὶ αὕτη. κόλποι δ’ εἰσὶν ἐνταῦθα ὅ τε Μεσσηνιακὸς καὶ ὁ Λακωνικὸς καὶ τρίτος ὁ Ἀργολικός, τέταρτος δ’ ὁ Ἑρμιονικὸς καὶ Σαρωνικός (οἱ δὲ Σαλαμινιακὸν καλοῦσιν), ὧν τοὺς μὲν ἡ Λιβυκὴ τοὺς δ’ ἡ Κρητικὴ θάλαττα πληροῖ καὶ τὸ Μυρτῷον πέλαγος· τινὲς δὲ καὶ τὸν Σαρωνικὸν πόρον [ἢ] πέλαγος ὀνομάζουσι. μέση δ’ ἐστὶν ἡ Ἀρκαδία πᾶσιν ἐπικειμένη καὶ γειτνιῶσα τοῖς ἄλλοις ἔθνεσιν.", "st": "8.2.2"}, {"sp": "N", "t": "ὁ δὲ Κορινθιακὸς κόλπος ἄρχεται μὲν ἀπὸ τῶν ἐκβολῶν τοῦ Εὐήνου (τινὲς δέ φασιν τοῦ Ἀχελώου τοῦ ὁρίζοντος Ἀκαρνᾶνας καὶ τοὺς Αἰτωλοὺς) καὶ τοῦ Ἀράξου. ἐνταῦθα γὰρ πρῶτον ἀξιόλογον συναγωγὴν λαμβάνουσι πρὸς ἀλλήλας αἱ ἑκατέρωθεν ἀκταί· προϊοῦσαι δὲ πλέον τελέως συμπίπτουσι κατὰ τὸ Ῥίον καὶ τὸ Ἀντίρριον, ὅσον δὴ πέντε σταδίων ἀπολείπουσαι πορθμόν. ἔστι δὲ τὸ μὲν Ῥίον τῶν Ἀχαιῶν ἁλιτενὴς ἄκρα, δρεπανοειδῆ τινα ἐπιστροφὴν εἰς τὸ ἐντὸς ἔχουσα· καὶ δὴ καὶ καλεῖται Δρέπανον· κεῖται δὲ μεταξὺ Πατρῶν καὶ Αἰγίου Ποσειδῶνος ἱερὸν ἔχουσα· τὸ δ’ Ἀντίρριον ἐν μεθορίοις τῆς Αἰτωλίας καὶ τῆς Λοκρίδος ἵδρυται, καλοῦσι δὲ [καὶ] Μολύκριον Ῥίον. εἶτ’ ἐντεῦθεν διίσταται πάλιν ἡ παραλία μετρίως ἑκατέρωθεν, προελθοῦσα δ’ εἰς τὸν Κρισαῖον κόλπον ἐνταῦθα τελευτᾷ, κλειομένη τοῖς προσεσπερίοις τῆς Βοιωτίας καὶ τῆς Μεγαρικῆς τέρμοσιν. ἔχει δὲ τὴν περίμετρον ὁ Κορινθιακὸς κόλπος ἀπὸ μὲν τοῦ Εὐήνου μέχρι Ἀράξου σταδίων δισχιλίων διακοσίων τριάκοντα· εἰ δ’ ἀπὸ τοῦ Ἀχελώου, πλεονάζοι ἂν ἑκατόν που σταδίοις. ἀπὸ μέντοι Ἀχελώου ἐπὶ τὸν Εὔηνον Ἀκαρνᾶνές εἰσιν, εἶθ’ ἑξῆς ἐπὶ τὸ Ἀντίρριον Αἰτωλοί, τὸ δὲ λοιπὸν μέχρι Ἰσθμοῦ Φωκέων ἐστὶ καὶ Βοιωτῶν καὶ τῆς Μεγαρίδος, στάδιοι χίλιοι ἑκατὸν εἴκοσι δυεῖν δέοντες· ἡ δὲ ἀπὸ τοῦ Ἀντιρρίου μέχρι Ἰσθμοῦ θάλαττα … Ἀλκυονὶς καλεῖται, μέρος οὖσα τοῦ Κρισαίου κόλπου· ἀ[πὸ δὲ τοῦ] Ἰσθμοῦ ἐπὶ τὸν Ἄραξον τριάκοντα ἐπὶ τοῖς [χιλίοις]. ὡς μὲν δὴ τύπῳ εἰπεῖν τοιαύτη τις καὶ τοσαύτη ἡ τῆς Πελοποννήσου θέσις καὶ τῆς ἀντιπόρθμου γῆς μέχρι τοῦ μυχοῦ, τοιοῦτος δὲ καὶ ὁ μεταξὺ ἀμφοῖν κόλπος. εἶτα καθ’ ἕκαστα ἐροῦμεν, τὴν ἀρχὴν ἀπὸ τῆς Ἠλείας ποιησάμενοι.", "st": "8.2.3"}, {"sp": "N", "t": "νῦν μὲν δὴ πᾶσαν Ἠλείαν ὀνομάζουσι τὴν μεταξὺ Ἀχαιῶν τε καὶ Μεσσηνίων παραλίαν, ἀνέχουσαν εἰς τὴν μεσόγαιαν τὴν πρὸς Ἀρκαδίᾳ τῇ κατὰ Φολόην καὶ Ἀζᾶνας καὶ Παρρασίους. τοῦτο δὲ τὸ παλαιὸν εἰς πλείους δυναστείας διῄρητο, εἶτ’ εἰς δύο, τήν τε τῶν Ἐπειῶν καὶ τὴν ὑπὸ Νέστορι τῷ Νηλέως· καθάπερ καὶ Ὅμηρος εἴρηκε, τὴν μὲν τῶν Ἐπειῶν ὀνομάζων Ἦλιν<br>ἠδὲ παρ’ Ἤλιδα δῖαν, ὅθι κρατέουσιν Ἐπειοί,<br>τὴν δ’ ὑπὸ τῷ Νέστορι Πύλον, δι’ ἧς τὸν Ἀλφειὸν ῥεῖν φησιν,<br>Ἀλφειοῦ, ὅς τ’ εὐρὺ ῥέει Πυλίων διὰ γαίης.<br>Πύλον μὲν οὖν καὶ πόλιν οἶδεν ὁ ποιητής<br>οἱ δὲ Πύλον, Νηλῆος ἐυκτίμενον πτολίεθρον,<br>ἷξον.<br>οὐ διὰ τῆς πόλεως δὲ οὐδὲ παρ’ αὐτὴν ῥεῖ ὁ Ἀλφειός, ἀλλὰ παρ’ αὐτὴν μὲν ἕτερος, ὃν οἱ μὲν Παμισὸν οἱ δὲ Ἄμαθον καλοῦσιν, ἀφ’ οὗ καὶ ὁ Πύλος Ἠμαθόεις εἰρῆσθαι οὗτος δοκεῖ, διὰ δὲ τῆς χώρας τῆς Πυλίας ὁ Ἀλφειός.", "st": "8.3.1"}, {"sp": "N", "t": "Ἦλις δὲ ἡ νῦν πόλις οὔπω ἔκτιστο καθ’ Ὅμηρον, ἀλλ’ ἡ χώρα κωμηδὸν ᾠκεῖτο· ἐκαλεῖτο δὲ κοίλη Ἦλις ἀπὸ τοῦ συμβεβηκότος· τοιαύτη γὰρ ἦν ἡ πλείστη καὶ ἀρίστη· ὀψὲ δέ ποτε συνῆλθον εἰς τὴν νῦν πόλιν Ἦλιν, μετὰ τὰ Περσικά, ἐκ πολλῶν δήμων. σχεδὸν δὲ καὶ τοὺς ἄλλους τόπους τοὺς κατὰ Πελοπόννησον πλὴν ὀλίγων, οὓς κατέλεξεν ὁ ποιητής, οὐ πόλεις ἀλλὰ χώρας νομίζειν [δεῖ], συστήματα δήμων ἔχουσαν ἑκάστην πλείω, ἐξ ὧν ὕστερον αἱ γνωριζόμεναι πόλεις συνῳκίσθησαν, οἷον τῆς Ἀρκαδίας Μαντίνεια μὲν ἐκ πέντε δήμων ὑπ’ Ἀργείων συνῳκίσθη, Τεγέα δ’ ἐξ ἐννέα, ἐκ τοσούτων δὲ καὶ Ἡραία ὑπὸ Κλεομβρότου ἢ ὑπὸ Κλεωνύμου· ὡς δ’ αὕτως Αἴγιον ἐξ ἑπτὰ ἢ ὀκτὼ δήμων συνεπολίσθη, Πάτραι δὲ ἐξ ἑπτά, Δύμη δὲ ἐξ ὀκτώ· οὕτω δὲ καὶ ἡ Ἦλις ἐκ τῶν περιοικίδων συνεπολίσθη· μία τούτων προσκτις … Ἀγριάδες. ῥεῖ δὲ διὰ τῆς πόλεως ὁ Πηνειὸς ποταμὸς παρὰ τὸ γυμνάσιον αὐτῆς· ἔπραξάν τε τοῦτο Ἠλεῖοι χρόνοις ὕστερον πολλοῖς τῆς εἰς αὐτοὺς μεταστάσεως τῶν χωρίων τῶν ὑπὸ τῷ Νέστορι.", "st": "8.3.2"}, {"sp": "N", "t": "ἦν δὲ ταῦτα ἥ τε Πισᾶτις, ἧς ἡ Ὀλυμπία μέρος, καὶ ἡ Τριφυλία καὶ ἡ τῶν Καυκώνων. Τριφύλιοι δ’ ἐκλήθησαν ἀπὸ τοῦ συμβεβηκότος, ἀπὸ τοῦ τρία φῦλα συνεληλυθέναι, τό τε τῶν ἀπ’ ἀρχῆς Ἐπειῶν καὶ τὸ τῶν ἐποικησάντων ὕστερον Μινυῶν καὶ τὸ τῶν ὕστατα ἐπικρατησάντων Ἠλείων· οἱ δ’ ἀντὶ τῶν Μινυῶν Ἀρκάδας φασίν, ἀμφισβητήσαντας τῆς χώρας πολλάκις, ἀφ’ οὗ καὶ Ἀρκαδικὸς Πύλος ἐκλήθη ὁ αὐτὸς καὶ Τριφυλιακός. Ὅμηρος δὲ ταύτην ἅπασαν τὴν χώραν μέχρι Μεσσήνης καλεῖ Πύλον ὁμωνύμως τῇ πόλει. ὅτι δὲ διώριστο ἡ κοίλη Ἦλις ἀπὸ τῶν ὑπὸ τῷ Νέστορι τόπων, ὁ τῶν νεῶν κατάλογος δηλοῖ τοῖς τῶν ἡγεμόνων καὶ τῶν κατοικιῶν ὀνόμασι. λέγω δὲ ταῦτα συμβάλλων τά τε νῦν καὶ τὰ ὑφ’ Ὁμήρου λεγόμενα· ἀνάγκη γὰρ ἀντεξετάζεσθαι ταῦτα ἐκείνοις διὰ τὴν τοῦ ποιητοῦ δόξαν καὶ συντροφίαν πρὸς ἡμᾶς, τότε νομίζοντος ἑκάστου κατορθοῦσθαι τὴν παροῦσαν πρόθεσιν, ὅταν ᾖ μηδὲν ἀντιπῖπτον τοῖς οὕτω σφόδρα πιστευθεῖσι περὶ τῶν αὐτῶν λόγοις· δεῖ δὴ τά τε ὄντα λέγειν καὶ τὰ τοῦ ποιητοῦ παρατιθέντας ἐφ’ ὅσον προσήκει προσσκοπεῖν.", "st": "8.3.3"}, {"sp": "N", "t": "ἔστι δέ τις ἄκρα τῆς Ἠλείας πρόσβορρος ἀπὸ ἑξήκοντα Δύμης Ἀχαϊκῆς πόλεως Ἄραξος. ταύτην μὲν οὖν ἀρχὴν τίθεμεν τῆς τῶν Ἠλείων παραλίας· μετὰ δὲ ταύτην ἐστὶν ἐπὶ τὴν ἑσπέραν προϊοῦσι τὸ τῶν Ἠλείων ἐπίνειον ἡ Κυλλήνη, ἀνάβασιν ἔχουσα ἐπὶ τὴν νῦν πόλιν ἑκατὸν καὶ εἴκοσι σταδίων. μέμνηται δὲ τῆς Κυλλήνης ταύτης καὶ Ὅμηρος λέγων Ὦτον Κυλλήνιον ἀρχὸν Ἐπειῶν. οὐ γὰρ ἀπὸ τοῦ Ἀρκαδικοῦ ὄρους ὄντα ἔμελλεν ἡγεμόνα τῶν Ἐπειῶν ἀποφῆναι· ἔστι δὲ κώμη μετρία, τὸν Ἀσκληπιὸν ἔχουσα τὸν Κολώτου, θαυμαστὸν ἰδεῖν ξόανον ἐλεφάντινον. μετὰ δὲ Κυλλήνην ἀκρωτήριόν ἐστιν ὁ Χελωνάτας, δυσμικώτατον τῆς Πελοποννήσου σημεῖον. πρόκειται δ’ αὐτοῦ νησίον καὶ βραχέα ἐν μεθορίοις τῆς τε κοίλης Ἤλιδος [καὶ τῆς] Πισατῶν, ὅθεν εἰς Κεφαλληνίαν πλέοντι ε[ἰσὶν οὐ πλεί]ους στάδιοι ὀγδοήκοντα. αὐτοῦ δέ που καὶ ὁ Ἐλίσων ἢ Ἔλισα ῥεῖ ποταμὸς ἐν τῇ λεχθείσῃ μεθορίᾳ.", "st": "8.3.4"}, {"sp": "N", "t": "μεταξὺ δὲ τοῦ Χελωνάτα καὶ τῆς Κυλλήνης ὅ τε Πηνειὸς ἐκδίδωσι ποταμὸς καὶ ὁ Σελλήεις ὑπὸ τοῦ ποιητοῦ λεγόμενος, ῥέων ἐκ Φολόης· ἐφ’ ᾧ Ἐφύρα πόλις, ἑτέρα τῆς Θεσπρωτικῆς καὶ Θετταλικῆς καὶ τῆς Κορίνθου, τετάρτη τις ἐπὶ τῇ ὁδῷ κειμένη τῇ ἐπὶ Λασίωνα, ἤτοι ἡ αὐτὴ οὖσα τῇ Βοινώᾳ (τὴν γὰρ Οἰνόην οὕτω καλεῖν εἰώθασιν) ἢ πλησίον ἐκείνης, διέχουσα τῆς Ἠλείων πόλεως σταδίους ἑκατὸν εἴκοσιν· ἐξ ἧς ἥ τε Τληπολέμου τοῦ Ἡρακλέους δοκεῖ λέγεσθαι μήτηρ<br>τὴν ἄγετ’ ἐξ Ἐφύρης ποταμοῦ ἄπο Σελλήεντος<br>(ἐκεῖ γὰρ μᾶλλον αἱ τοῦ Ἡρακλέους στρατεῖαι, πρὸς ἐκείναις τε οὐδεὶς ποταμὸς Σελλήεις), καὶ ὁ τοῦ Μέγητος [θώραξ]<br>τόν ποτε Φυλεὺς<br>ἤγαγεν ἐξ Ἐφύρης ποταμοῦ ἄπο Σελλήεντος<br>ἐξ ἧς καὶ τὰ φάρμακα τὰ ἀνδροφόνα. εἰς Ἐφύραν γὰρ ἀφῖχθαι [ἡ Ἀθηνᾶ] φησὶ τὸν Ὀδυσσέα<br>φάρμακον ἀνδροφόνον διζήμενον, ὄφρα οἱ εἴη<br>ἰοὺς χρίεσθαι<br>καὶ τὸν Τηλέμαχον οἱ μνηστῆρες<br>ἠὲ καὶ εἰς Ἐφύρην ἐθέλει πίειραν ἄρουραν<br>ἐλθεῖν, ὄφρ’ ἔνθεν θυμοφθόρα φάρμακ’ ἐνείκῃ.<br>καὶ γὰρ τὴν Αὐγέου θυγατέρα τοῦ τῶν Ἐπειῶν βασιλέως ὁ Νέστωρ ἐν τῇ διηγήσει τοῦ πρὸς αὐτοὺς πολέμου φαρμακίδα εἰσάγει<br>πρῶτος ἐγὼν ἕλον ἄνδρα φήσας<br>Μούλιον αἰχμητήν, γαμβρὸς δ’ ἦν Αὐγείαο,<br>πρεσβυτάτην δὲ θύγατρ’ εἶχεν,<br>ἣ τόσα φάρμακα ᾔδη, ὅσα τρέφει εὐρεῖα χθών.<br>ἔστι δὲ καὶ περὶ Σικυῶνα Σελλήεις ποταμὸς καὶ Ἐφύρα πλησίον κώμη, καὶ ἐν τῇ Ἀγραίᾳ τῆς Αἰτωλίας Ἐφύρα κώμη, οἱ δ’ ἀπ’ αὐτῆς Ἔφυροι· καὶ ἄλλοι οἱ Περραιβῶν πρὸς Μακεδονία, οἱ Κραννώνιοι, καὶ οἱ Θεσπρωτικοὶ οἱ ἐκ Κιχύρου τῆς πρότερον Ἐφύρας.", "st": "8.3.5"}, {"sp": "N", "t": "Ἀπολλόδωρος δὲ διδάσκων ὃν τρόπον ὁ ποιητὴς εἴωθε διαστέλλεσθαι τὰς ὁμωνυμίας, οἷον ἐπὶ τοῦ Ὀρχομενοῦ τὸν μὲν Ἀρκαδικὸν πολύμηλον καλῶν τὸν δὲ Βοιωτιακὸν Μινύειον, καὶ Σάμον Θρηικίην συντιθείς<br>μεσσηγύς τε Σάμοιο καὶ Ἴμβρου,<br>ἵνα χωρίσῃ ἀπὸ τῆς Ἰωνικῆς, οὕτω φησὶ καὶ τὴν Θεσπρωτικὴν Ἐφύραν διαστέλλεσθαι τῷ τε τηλόθεν καὶ τῷ<br>ποταμοῦ ἄπο Σελλήεντος.<br>ταῦτα δ’ οὐχ ὁμολογεῖ τοῖς ὑπὸ τοῦ Σκηψίου Δημητρίου λεγομένοις, παρ’ οὗ μεταφέρει τὰ πλεῖστα. ἐκεῖνος γὰρ οὔ φησιν εἶναι Σελλήεντα ἐν Θεσπρωτοῖς ποταμόν, ἀλλ’ ἐν τῇ Ἠλείᾳ παρὰ τὴν ἐκεῖ Ἐφύραν, ὡς προείπομεν. τοῦτό τε οὖν εἴρηκε σκέψεως δεόμενον καὶ περὶ τῆς Οἰχαλίας ὅτι φησὶν οὐ μιᾶς οὔσης, μίαν εἶναι πόλιν Εὐρύτου Οἰχαλιῆος· δῆλον οὖν ὅτι τὴν Θετταλικήν, ἐφ’ ἧς φησιν<br>οἵ τ’ ἔχον Οἰχαλίην, πόλιν Εὐρύτου Οἰχαλιῆος<br>τίς οὖν ἔστιν ἐξ ἧς ὁρμηθέντα αἱ Μοῦσαι κατὰ Δώριον<br>ἀντόμεναι Θάμυριν τὸν Θρήικα παῦσαν ἀοιδῆς;<br>εἰ μὲν γὰρ ἡ Θετταλική, οὐκ εὖ πάλιν ὁ Σκήψιος Ἀρκαδικήν τινα λέγων, ἣν νῦν Ἀνδανίαν καλοῦσιν· εἰ δ’ οὗτος εὖ, καὶ ἡ Ἀρκαδικὴ πόλις Εὐρύτου εἴρηται, ὥστ’ οὐ μία μόνον· ἐκεῖνος δὲ μίαν φησί.", "st": "8.3.6"}, {"sp": "N", "t": "μεταξὺ δὲ τοῦ Πηνειοῦ καὶ τῆς Σελλήεντος ἐμβολῆς Πύλος ᾠκεῖτο κατὰ τὸ Σκόλλιον, οὐχ ἡ τοῦ Νέστορος πόλις, ἀλλ’ ἑτέρα τις, ᾗ πρὸς τὸν Ἀλφειὸν οὐδέν ἐστι κοινώνημα, οὐδὲ πρὸς τὸν Παμισόν, εἴτε Ἄμαθον χρὴ καλεῖν. βιάζονται δ’ ἔνιοι μνηστευόμενοι τὴν Νέστορος δόξαν καὶ τὴν εὐγένειαν· τριῶν γὰρ Πύλων ἱστορουμένων ἐν Πελοποννήσῳ (καθότι καὶ τὸ ἔπος εἴρηται τουτί<br>ἔστι Πύλος πρὸ Πύλοιο· Πύλος γε μέν ἐστι καὶ ἄλλος<br>)τούτου τε καὶ τοῦ Λεπρεατικοῦ τοῦ ἐν τῇ Τριφυλίᾳ καὶ τῇ Πισάτιδι, τρίτου δὲ τοῦ Μεσσηνιακοῦ τοῦ κατὰ Κορυφάσιον, ἕκαστοι τὸν παρά σφισιν ἠμαθόεντα πειρῶνται δεικνύναι, καὶ τὴν τοῦ Νέστορος πατρίδα τοῦτον ἀποφαίνουσιν. οἱ μὲν οὖν πολλοὶ τῶν νεωτέρων καὶ συγγραφέων καὶ ποιητῶν Μεσσήνιόν φασι τὸν Νέστορα, τῷ σωζομένῳ μέχρι εἰς αὐτοὺς προστιθέμενοι· οἱ δ’ Ὁμηρικώτεροι τοῖς ἔπεσιν ἀκολουθοῦντες τοῦτον εἶναί φασι τὸν τοῦ Νέστορος Πύλον, οὗ τὴν χώραν διέξεισιν ὁ Ἀλφειός· διέξεισι δὲ τὴν Πισᾶτιν καὶ τὴν Τριφυλίαν. οἱ δ’ οὖν ἐκ τῆς κοίλης Ἤλιδος καὶ τοιαύτην φιλοτιμίαν προσετίθεσαν τῷ παρ’ αὐτοῖς Πύλῳ, καὶ γνωρίσματα δεικνύντες Γέρηνον τόπον καὶ Γέροντα ποταμὸν καὶ ἄλλον Γεράνιον, εἶτ’ ἀπὸ τούτων ἐπιθέτως Γερήνιον εἰρῆσθαι πιστούμενοι τὸν Νέστορα. τοῦτο δὲ ταὐτὸ καὶ οἱ Μεσσήνιοι πεποιήκασι, καὶ πιθανώτεροί γε φαίνονται· μᾶλλον γὰρ γνώριμά φασιν εἶναι τὰ παρ’ ἐκείνοις Γέρηνα, συνοικουμένην ποτὲ εὖ. τοιαῦτα μὲν τὰ περὶ τὴν κοίλην Ἦλιν ὑπάρχοντα νυνί.", "st": "8.3.7"}, {"sp": "N", "t": "ὁ δὲ ποιητὴς εἰς τέτταρα μέρη διελὼν τήνδε τὴν χώραν, τέτταρας δὲ καὶ τοὺς ἡγεμόνας εἰπών, οὐ σαφῶς εἴρηκεν<br>οἳ δ’ ἄρα Βουπράσιόν τε καὶ Ἤλιδα δῖαν ἔναιον,<br>ὅσσον ἐφ’ Ὑρμίνη καὶ Μύρσινος ἐσχατόωσα<br>πέτρη τ’ Ὠλενίη καὶ Ἀλείσιον ἐντὸς ἐέργει,<br>τῶν αὖ τέσσαρες ἀρχοὶ ἔσαν, δέκα δ’ ἀνδρὶ ἑκάστῳ<br>νῆες ἕποντο θοαί· πολέες δ’ ἔμβαινον Ἐπειοί.<br>τῷ μὲν γὰρ Ἐπειοὺς ἀμφοτέρους προσαγορεύειν τούς τε Βουπρασιεῖς καὶ τοὺς Ἠλείους, Ἠλείους δὲ μηκέτι καλεῖν τοὺς Βουπρασιεῖς, οὐ τὴν Ἠλείαν δόξειεν ἂν εἰς τέτταρα μέρη διαιρεῖν, ἀλλὰ τὴν τῶν Ἐπειῶν, ἣν εἰς δύο μέρη διεῖλε πρότερον· οὐδ’ ἂν μέρος εἴη τῆς Ἤλιδος τὸ Βουπράσιον, ἀλλὰ τῶν Ἐπειῶν μᾶλλον. ὅτι γὰρ Ἐπειοὺς καλεῖ τοὺς Βουπρασίους, δῆλον<br>ὡς ὁπότε κρείοντ’ Ἀμαρυγκέα θάπτον Ἐπειοὶ<br>Βουπρασίῳ.<br>πάλιν δὲ τῷ συγκαταριθμεῖσθαι Βουπράσιόν τε καὶ Ἤλιδα δῖαν λέγοντα, εἶτ’ εἰς τέτταρας διαιρεῖν μερίδας, ὡς ἂν κοινῷ δοκεῖ τῷ τε Βουπρασίῳ καὶ τῇ Ἤλιδι αὐτὰς ὑποτάττειν. ἦν δ’, ὡς ἔοικε, κατοικία τῆς Ἠλείας τὸ Βουπράσιον ἀξιόλογος, ἣ νῦν οὐκέτ’ ἐστίν· ἡ δὲ χώρα καλεῖται μόνον οὕτως ἡ ἐπὶ τῆς ὁδοῦ τῆς ἐπὶ Δύμην ἐξ Ἤλιδος τῆς νῦν πόλεως. ὑπολάβοι δ’ ἄν τις καὶ ὑπεροχήν τινα ἔχειν τότε τὸ Βουπράσιον παρὰ τὴν Ἦλιν, ὥσπερ καὶ οἱ Ἐπειοὶ παρὰ τούτους· ὕστερον δ’ ἀντ’ Ἐπειῶν Ἠλεῖοι ἐκλήθησαν. καὶ τὸ Βουπράσιον μὲν δὴ μέρος ἦν τῆς Ἤλιδος. ποιητικῷ δέ τινι σχήματι συγκαταλέγειν τὸ μέρος τῷ ὅλῳ φασὶ τὸν Ὅμηρον, ὡς τό<br>ἀν’ Ἑλλάδα καὶ μέσον Ἄργος<br>καί<br>ἀν’ Ἑλλάδα τε Φθίην τε<br>; καὶ<br>Κουρῆτές τ’ ἐμάχοντο καὶ Αἰτωλοί,<br>καὶ<br>οἱ δ’ ἐκ Δουλιχίοιο Ἐχινάων θ’ ἱεράων.<br>καὶ γὰρ τὸ Δουλίχιον τῶν Ἐχινάδων. χρῶνται δὲ καὶ οἱ νεώτεροι· Ἱππῶναξ μέν<br>Κυπρίων βέκος φαγοῦσι καὶ Ἀμαθουσίων πυρόν·<br>Κύπριοι γὰρ καὶ οἱ Ἀμαθούσιοι· καὶ Ἀλκμὰν δέ<br>Κύπρον ἱμερτὰν λιποῖσα καὶ Πάφον περιρρύταν<br>καὶ Αἰσχύλος<br>Κύπρου Πάφου τ’ ἔχουσα πάντα κλῆρον.<br>εἰ δ’ οὐκ εἴρηκεν Ἠλείους τοὺς Βουπρασίους, οὐδ’ ἄλλα πολλὰ τῶν ὄντων, φήσομεν· ἀλλὰ τοῦτ’ οὐκ ἔστιν ἀπόδειξις τοῦ μὴ εἶναι, ἀλλὰ τοῦ μὴ εἰπεῖν μόνον.", "st": "8.3.8"}, {"sp": "N", "t": "Ἑκαταῖος δ’ ὁ Μιλήσιος ἑτέρους λέγει τῶν Ἠλείων τοὺς Ἐπειούς· τῷ γοῦν Ἡρακλεῖ συστρατεῦσαι τοὺς Ἐπειοὺς ἐπὶ Αὐγέαν καὶ συνανελεῖν αὐτῷ τόν τε Αὐγέαν καὶ τὴν Ἦλιν· φησὶ δὲ καὶ τὴν Δύμην Ἐπειίδα καὶ Ἀχαιίδα. πολλὰ μὲν οὖν καὶ μὴ ὄντα λέγουσιν οἱ ἀρχαῖοι συγγραφεῖς, συντεθραμμένοι τῷ ψεύδει διὰ τὰς μυθογραφίας· διὰ δὲ τοῦτο καὶ οὐχ ὁμολογοῦσι πρὸς ἀλλήλους περὶ τῶν αὐτῶν. οὐ μέντοι ἄπιστον οὐδ’ εἴ ποτε διάφοροι τοῖς Ἠλείοις ὄντες οἱ Ἐπειοὶ καὶ ἑτεροεθνεῖς εἰς ταὐτὸ συνήρχοντο κατ’ ἐπικράτειαν, καὶ κοινὴν ἔνεμον τὴν πολιτείαν· ἐπεκράτουν δὲ καὶ μέχρι Δύμης. ὁ μὲν γὰρ ποιητὴς οὐκ ὠνόμακε τὴν Δύμην, οὐκ ἀπεικὸς δ’ ἐστὶ τότε μὲν αὐτὴν ὑπὸ τοῖς Ἐπειοῖς ὑπάρξαι, ὕστερον δὲ τοῖς Ἴωσιν, ἢ μηδ’ ἐκείνοις ἀλλὰ τοῖς τὴν ἐκείνων χώραν κατασχοῦσιν Ἀχαιοῖς· τῶν δὲ τεττάρων μερίδων, ὧν ἐντός ἐστι καὶ τὸ Βουπράσιον, ἡ μὲν Ὑρμίνη καὶ ἡ Μύρσινος τῆς Ἠλείας ἐστίν, αἱ λοιπαὶ δὲ ἐπὶ τῶν ὅρων ἤδη τῆς Πισάτιδος, ὡς οἴονταί τινες.", "st": "8.3.9"}, {"sp": "N", "t": "Ὑρμίνη μὲν οὖν πολίχνιον ἦν, νῦν δ’ οὐκ ἔστιν· ἀλλ’ ἀκρωτήριον πλησίον Κυλλήνης ὀρεινόν ἐστι, καλούμενον Ὅρμινα ἢ Ὕρμινα· Μύρσινος δὲ τὸ νῦν Μυρτούντιον, ἐπὶ θάλατταν καθήκουσα κατὰ τὴν ἐκ Δύμης εἰς Ἦλιν ὁδὸν κατοικία, στάδια τῆς Ἠλείων πόλεως διέχουσα ἑβδομήκοντα. πέτρην δ’ Ὠλενίην εἰκάζουσι τὴν νῦν Σκόλλιν· ἀνάγκη γὰρ εἰκότα λέγειν, καὶ τῶν τόπων καὶ τῶν ὀνομάτων μεταβεβλημένων, ἐκείνου τε μὴ σφόδρα ἐπὶ πολλῶν σαφηνίζοντος· ἔστι δ’ ὄρος πετρῶδες κοινὸν Δυμαίων τε καὶ Τριταιέων καὶ Ἠλείων, ἐχόμενον ἑτέρου τινὸς Ἀρκαδικοῦ ὄρους Λαμπείας, ὃ τῆς Ἤλιδος μὲν διέστηκεν ἑκ[ατὸν καὶ] τριάκοντα σταδίους, Τριταίας δὲ ἑκατόν, [καὶ Δύμης] τοὺς ἴσους, Ἀχαϊκῶν πόλεων. τὸ δ’ Ἀλείσιον ἔστι τὸ νῦν Ἀλεσιαῖον, χώρα περὶ τὴν Ἀμφιδολίδα, ἐν ᾗ καὶ κατὰ μῆνα ἀγορὰν συνάγουσιν οἱ περίοικοι· κεῖται δὲ ἐπὶ τῆς ὀρεινῆς ὁδοῦ τῆς ἐξ Ἤλιδος εἰς Ὀλυμπίαν· πρότερον δ’ ἦν πόλις τῆς Πισάτιδος, ἄλλοτ’ ἄλλως τῶν ὅρων ἐπαλλαττόντων διὰ τὰς τῶν ἡγεμόνων μεταβολάς· τὸ δ’ Ἀλείσιον καὶ Ἀλεισίου κολώνην ὁ ποιητὴς καλεῖ ὅταν φῇ<br>μέσφ’ ἐπὶ Βουπρασίου πολυπύρου βήσαμεν<br>ἵππους πέτρης τ’ Ὠλενίης καὶ Ἀλεισίου ἔνθα κολώνη κέκληται.<br>ὑπερβατῶς γὰρ δεῖ δέξασθαι ἴσον τῷ “καὶ ἔνθ’ Ἀλεισίου κολώνη κέκληται.” ἔνιοι δὲ καὶ ποταμὸν δεικνύουσιν Ἀλείσιον.", "st": "8.3.10"}, {"sp": "N", "t": "λεγομένων δέ τινων ἐν τῇ Τριφυλίᾳ Καυκώνων πρὸς τῇ Μεσσηνίᾳ, λεγομένης δὲ καὶ τῆς Δύμης Καυκωνίδος ὑπό τινων, ὄντος δὲ καὶ ποταμοῦ ἐν τῇ Δυμαίᾳ μεταξὺ Δύμης καὶ Τριταίας ὃς καλεῖται Καύκων, ζητοῦσι περὶ τῶν Καυκώνων μὴ διττοὶ λέγονται, οἱ μὲν περὶ τὴν Τριφυλίαν οἱ δὲ περὶ Δύμην καὶ Ἦλιν καὶ τὸν Καύκωνα· ἐμβάλλει δ’ οὗτος εἰς ἕτερον, ὃς Τευθέας ἀρσενικῶς καλεῖται, ὁμώνυμος πολίχνῃ τινὶ τῶν εἰς τὴν Δύμην συνῳκισμένων, πλὴν ὅτι χωρὶς τοῦ σίγμα Τευθέα λέγεται θηλυκῶς αὕτη, ἐκτεινόντων τὴν ἐσχάτην συλλαβήν, ὅπου τὸ τῆς Νεμυδίας Ἀρτέμιδος ἱερόν. ὁ δὲ Τευθέας εἰς τὸν Ἀχελῶον ἐμβάλλει τὸν κατὰ Λύμην ῥέοντα, ὁμώνυμον τῷ κατὰ Ἀκαρνανίαν, καλούμενον καὶ Πεῖρον. τοῦ δ’ Ἡσιόδου εἰπόντος<br>ᾤκεε δ’ Ὠλενίην πέτρην ποταμοῖο παρ’ ὄχθας<br>εὐρεῖος Πείροιο,<br>μεταγράφουσί τινες Πώροιο οὐκ εὖ. οὔτε γὰρ τὴν Δύμην ὁπόθεν Καυκωνίδα εἰρῆσθαι συμβέβηκε παραλιπεῖν ἄξιον, οὔτε τὸν ποταμὸν ὁπόθεν Καύκων εἴρηται, διὰ τὸ τοὺς Καύκωνας παρέχειν ζήτησιν, οἵ τινές ποτέ εἰσιν, ὅπου φησὶν ἡ Ἀθηνᾶ βαδίζειν κατὰ τὴν τοῦ χρέους κομιδήν. εἰ γὰρ δὴ δεχοίμεθα τοὺς ἐν τῇ Τριφυλίᾳ λέγεσθαι τοὺς περὶ Λέπρειον, οὐκ οἶδ’ ὅπως πιθανὸς ἔσται ὁ λόγος· διὸ καὶ γράφουσί τινες<br>ἔνθα χρεῖός μοι ὀφείλεται Ἤλιδι δίῃ,<br>οὐκ ὀλίγον.<br>σαφεστέραν δ’ ἕξει τὴν ἐπίσκεψιν τοῦτο, ἐπειδὰν τὴν ἑξῆς χώραν περιοδεύσωμεν τήν τε Πισᾶτιν καὶ τὴν Τριφυλίαν μέχρι τῆς τῶν Μεσσηνίων μεθορίας.", "st": "8.3.11"}, {"sp": "N", "t": "μετὰ δὲ τὸν Χελωνάταν ὁ τῶν Πισατῶν ἐστιν αἰγιαλὸς πολύς, εἶτ’ ἄκρα Φειά· ἦν δὲ καὶ πολίχνη<br>Φειᾶς πὰρ τείχεσσιν, Ἰαρδάνου ἀμφὶ ῥέεθρα·<br>ἔστι γὰρ καὶ ποτάμιον πλησίον. ἔνιοι δ’ ἀρχὴν τῆς Πισάτιδος τὴν Φειάν φασι· πρόκειται δὲ καὶ ταύτης νησίον καὶ λιμήν, ἔνθεν εἰς Ὀλυμπίαν τὸ ἐγγυτάτω ἐκ θαλάττης εἰσὶ στάδιοι ἑκατὸν εἴκοσιν. εἶτ’ ἄλλη ἄκρα εὐθὺς ἐπὶ πολὺ προὔχουσα ἐπὶ τὴν δύσιν, καθάπερ ὁ Χελωνάτας, ἀφ’ ἧς πάλιν ἐπὶ τὴν Κεφαλληνίαν στάδιοι ἑκατὸν εἴκοσιν. εἶθ’ ὁ Ἀλφειὸς ἐκδίδωσι, διέχων τοῦ Χελωνάτα σταδίους διακοσίους ὀγδοήκοντα, Ἀράξου δὲ πεντακοσίους τετταράκοντα πέντε. ῥεῖ δ’ ἐκ τῶν αὐτῶν τόπων ἐξ ὧν καὶ ὁ Εὐρώτας· καλεῖται δὲ Ἀσέα, κώμη τῆς Μεγαλοπολίτιδος, πλησίον ἀλλήλων ἔχουσα δύο πηγάς, ἐξ ὧν ῥέουσιν οἱ λεχθέντες ποταμοί· δύντες δ’ ὑπὸ γῆς ἐπὶ συχνοὺς σταδίους ἀνατέλλουσι πάλιν, εἶθ’ ὁ μὲν εἰς τὴν Λακωνικὴν ὁ δ’ εἰς τὴν Πισᾶτιν κατάγεται. ὁ μὲν οὖν Εὐρώτας κατὰ τὴν ἀρχὴν τῆς Βλεμινάτιδος ἀναδείξας τὸ ῥεῖθρον, παρ’ αὐτὴν τὴν Σπάρτην ῥυεὶς καὶ διεξιὼν αὐλῶνά τινα μακρὸν κατὰ τὸ Ἕλος, οὗ μέμνηται καὶ ὁ ποιητής, ἐκδίδωσι μεταξὺ Γυθείου τοῦ τῆς Σπάρτης ἐπινείου καὶ Ἀκραίων. ὁ δ’ Ἀλφειὸς παραλαβὼν τόν τε Λάδωνα καὶ τὸν Ἐρύμανθον καὶ ἄλλους ἀσημοτέρους διὰ τῆς Φρίξης καὶ τῆς Πισάτιδος καὶ Τριφυλίας ἐνεχθεὶς παρ’ αὐτὴν τὴν Ὀλυμπίαν ἐπὶ θάλατταν τὴν Σικελικὴν ἐκπίπτει μεταξὺ Φειᾶς τε καὶ Ἐπιταλίου. πρὸς δὲ τῇ ἐκβολῇ τὸ τῆς Ἀλφειωνίας Ἀρτέμιδος ἢ Ἀλφειούσης ἄλσος ἐστὶ (λέγεται γὰρ ἀμφοτέρως), ἀπέχον τῆς Ὀλυμπίας εἰς ὀγδοήκοντα σταδίους. ταύτῃ δὲ τῇ θεῷ καὶ ἐν Ὀλυμπίᾳ κατ’ ἔτος συντελεῖται πανήγυρις, καθάπερ καὶ τῇ Ἐλαφίᾳ καὶ τῇ Δαφνίᾳ. μεστὴ δ’ ἐστὶν ἡ γῆ πᾶσα ἀρτεμισίων τε καὶ ἀφροδισίων καὶ νυμφαίων ἐν ἄλσεσιν ἀνθέων [πλέ]ῳς τὸ πολὺ διὰ τὴν εὐυδρίαν, συχνὰ δὲ καὶ ἑρμεῖα ἐν ταῖς ὁδοῖς, ποσείδια δ’ ἐπὶ ταῖς ἀκταῖς. ἐν δὲ τῷ τῆς Ἀλφειωνίας ἱερῷ γραφαὶ Κλεάνθους τε καὶ Ἀρήγοντος, ἀνδρῶν Κορινθίων, τοῦ μὲν Τροίας ἅλωσις καὶ Ἀθηνᾶς γοναί, τοῦ δ’ Ἄρτεμις ἀναφερομένη ἐπὶ γρυπός, σφόδρα εὐδόκιμοι.", "st": "8.3.12"}, {"sp": "N", "t": "εἶτα τὸ διεῖργον ὄρος τῆς Τριφυλίας τὴν Μακιστίαν ἀπὸ τῆς Πισάτιδος· εἶτ’ ἄλλος ποταμὸς Χαλκὶς καὶ κρήνη Κρουνοὶ καὶ κατοικία Χαλκίς, καὶ τὸ Σαμικὸν μετὰ ταῦτα, ὅπου τὸ μάλιστα τιμώμενον τοῦ Σαμίου Ποσειδῶνος ἱερόν· ἔστι δ’ ἄλσος ἀγριελαιῶν πλέων· ἐπεμελοῦντο δ’ αὐτοῦ Μακίστιοι· οὗτοι δὲ καὶ τὴν ἐκεχειρίαν ἐπήγγελλον, ἣν καλοῦσι Σάμιον· συντελοῦσι δ’ εἰς τὸ ἱερὸν πάντες Τριφύλιοι.", "st": "8.3.13"}, {"sp": "N", "t": "κατὰ ταῦτα δέ πως τὰ ἱερὰ ὑπέρκειται τῆς θαλάττης ἐν τριάκοντα ἢ μικρῷ πλείοσι σταδίοις ὁ Τριφυλιακὸς Πύλος [ὁ] καὶ Λεπρεατικός, ὃν καλεῖ ὁ ποιητὴς ἠμαθόεντα καὶ παραδίδωσι τοῦ Νέστορος πατρίδα, ὡς ἄν τις ἐκ τῶν ἐπῶν τεκμαίροιτο· εἴτε τοῦ παραρρέοντος ποταμοῦ πρὸς ἄρκτον Ἀμάθου καλουμένου πρότερον, ὃς νῦν Μάμαος καὶ Ἀρκαδικὸς καλεῖται, ὥστ’ ἐντεῦθεν ἠμαθόεντα κεκλῆσθαι· εἴτε τούτου μὲν Παμισοῦ καλουμένου ὁμωνύμως τοῖς ἐν τῇ Μεσσηνίᾳ δυσί, τῆς δὲ πόλεως ἄδηλον ἐχούσης τὴν ἐτυμολογίαν τοῦ ἐπιθέτου· καὶ γὰρ τὸ ἀμαθώδη τὸν ποταμὸν ἢ τὴν χώραν εἶναι ψεῦδός φασι. πρὸς ἕω δ’ ἐστὶν ὄρος τοῦ Πύλου πλησίον ἐπώνυμον Μίνθης, ἣν μυθεύουσι παλλακὴν τοῦ Ἅιδου γενομένην πατηθεῖσαν ὑπὸ τῆς κόρης εἰς τὴν κηπαίαν μίνθην μεταβαλεῖν, ἥν τινες ἡδύοσμον καλοῦσι. καὶ δὴ καὶ τέμενός ἐστιν Ἅιδου πρὸς τῷ ὄρει τιμώμενον καὶ ὑπὸ Μακιστίων, καὶ Δήμητρος ἄλσος ὑπερκείμενον τοῦ Πυλιακοῦ πεδίου. τὸ δὲ πεδίον εὔγεών ἐστι τοῦτο, τῇ θαλάττῃ δὲ συνάψαν παρατείνει παρ’ ἅπαν τὸ μεταξὺ τοῦ τε Σαμικοῦ καὶ ποταμοῦ Νέδας διάστημα. θινώδης δὲ καὶ στενός ἐστιν ὁ τῆς θαλάττης αἰγιαλός, ὥστ’ οὐκ ἂν ἀπογνοίη τις ἐντεῦθεν ἠμαθόεντα ὠνομάσθαι τὸν Πύλον.", "st": "8.3.14"}, {"sp": "N", "t": "πρὸς ἄρκτον δ’ ὅμορα ἦν τῷ Πύλῳ δύο πολείδια Τριφυλιακὰ Ὕπανα καὶ Τυμπανέαι, ὧν τὸ μὲν εἰς Ἦλιν συνῳκίσθη τὸ δ’ ἔμεινε. καὶ ποταμοὶ δὲ δύο ἐγγὺς ῥέουσιν ὅ τε Δαλίων καὶ ὁ Ἀχέρων, ἐμβάλλοντες εἰς τὸν Ἀλφειόν. ὁ δὲ Ἀχέρων κατὰ τὴν πρὸς τὸν Ἅιδην οἰκειότητα ὠνόμασται· ἐκτετίμηται γὰρ δὴ σφόδρα τά τε τῆς Δήμητρος καὶ τῆς κόρης ἱερὰ ἐνταῦθα καὶ τὰ τοῦ Ἅιδου, τάχα διὰ τὰς ὑπεναντιότητας, ὥς φησιν ὁ Σκήψιος Δημήτριος. καὶ γὰρ εὔκαρπός ἐστι καὶ ἐρυσίβην γεννᾷ καὶ θρύον ἡ Τριφυλία· διόπερ ἀντὶ μεγάλης φορᾶς πυκνὰς ἀφορίας γίνεσθαι συμβαίνει κατὰ τοὺς τόπους.", "st": "8.3.15"}, {"sp": "N", "t": "τοῦ δὲ Πύλου πρὸς νότον ἐστὶ τὸ Λέπρειον. ἦν δὲ καὶ αὕτη ἡ πόλις ὑπὲρ τῆς θαλάττης ἐν τετταράκοντα σταδίοις· μεταξὺ δὲ τοῦ Λεπρείου καὶ τοῦ Ἀννίου τὸ ἱερὸν τοῦ Σαμίου Ποσειδῶνος ἔστιν, ἑκατὸν σταδίους ἑκατέρου διέχον. τοῦτο δ’ ἐστὶ τὸ ἱερὸν ἐν ᾧ καταληφθῆναί φησιν ὁ ποιητὴς ὑπὸ Τηλεμάχου τὴν θυσίαν συντελοῦντας τοὺς Πυλίους<br>οἱ δὲ Πύλον, Νηλῆος ἐυκτίμενον πτολίεθρον,<br>ἷξον· τοὶ δ’ ἐπὶ θινὶ θαλάσσης ἱερὰ ῥέζον,<br>ταύρους παμμέλανας, Ἐνοσίχθονι κυανοχαίτῃ.<br>πάρεστι μὲν γὰρ τῷ ποιητῇ καὶ πλάττειν τὰ μὴ ὄντα, ὅταν δ’ ᾖ δυνατόν, ἐφαρμόττειν τοῖς οὖσι τὰ ἔπη καὶ σώζειν τὴν διήγησιν. τὸ δ’ ἀπέχεσθαι προσῆκε μᾶλλον. χώραν δ’ εἶχον εὐδαίμονα οἱ Λεπρεᾶται· τούτοις δ’ ὅμοροι Κυπαρισσιεῖς. ἄμφω δὲ τὰ χωρία ταῦτα Καύκωνες κατεῖχον, καὶ τὸν Μάκιστον δέ, ὅν τινες Πλατανιστοῦντα καλοῦσιν. ὁμώνυμον τῇ χώρᾳ [δ’] ἐστὶ τὸ πόλισμα. φασὶ δ’ ἐν τῇ Λεπρεάτιδι καὶ Καύκωνος εἶναι μνῆμα, εἴτ’ ἀρχηγέτου τινὸς εἴτ’ ἄλλως ὁμωνύμου τῷ ἔθνει.", "st": "8.3.16"}, {"sp": "N", "t": "πλείους δ’ εἰσὶ λόγοι περὶ τῶν Καυκώνων· καὶ γὰρ Ἀρκαδικὸν ἔθνος φασί, καθάπερ τὸ Πελασγικόν, καὶ πλανητικὸν ἄλλως, ὥσπερ ἐκεῖνο. ἱστορεῖ γοῦν ὁ ποιητὴς καὶ τοῖς Τρωσὶν ἀφιγμένους συμμάχους, πόθεν δ’ οὐ λέγει· δοκοῦσι δ’ ἐκ Παφλαγονίας· ἐκεῖ γὰρ ὀνομάζουσι Καυκωνιάτας τινὰς Μαριανδυνοῖς ὁμόρους, οἳ καὶ αὐτοὶ Παφλαγόνες εἰσί. μνησθησόμεθα δ’ αὐτῶν ἐπὶ πλέον, ὅταν εἰς ἐκεῖνον περιστῇ τὸν τόπον ἡ γραφή. νυνὶ δὲ περὶ τῶν ἐν τῇ Τριφυλίᾳ Καυκώνων ἔτι καὶ ταῦτα προσιστορητέον. οἱ μὲν γὰρ καὶ ὅλην τὴν νῦν Ἠλείαν ἀπὸ τῆς Μεσσηνίας μέχρι Δύμης Καυκωνίαν λεχθῆναί φασιν· Ἀντίμαχος γοῦν καὶ Ἐπειοὺς καὶ Καύκωνας ἅπαντας προσαγορεύει. τινὲς δὲ ὅλην μὲν μὴ κατασχεῖν αὐτούς, δίχα δὲ μεμερισμένους οἰκεῖν, τοὺς μὲν πρὸς τῇ Μεσσηνίᾳ κατὰ τὴν Τριφυλίαν τοὺς δὲ πρὸς τῇ Δύμῃ κατὰ τὴν Βουπρασίδα καὶ τὴν κοίλην Ἦλιν· Ἀριστοτέλης δ’ ἐνταῦθα μάλιστα οἶδεν ἱδρυμένους αὐτούς. καὶ δὴ τοῖς ὑφ’ Ὁμήρου λεγομένοις ὁμολογεῖ μᾶλλον ἡ ὑστάτη ἀπόφασις, τό τε ζητούμενον πρότερον λαμβάνει λύσιν. ὁ μὲν γὰρ Νέστωρ ὑπόκειται τὸν Τριφυλιακὸν οἰκῶν Πύλον, τά τε πρὸς νότον καὶ τὰ ἑωθινά (ταῦτα δ’ ἐστὶ τὰ συγκυροῦντα πρὸς τὴν Μεσσηνίαν καὶ τὴν Λακωνικήν) ὑπ’ ἐκείνῳ ἐστίν, ἔχουσι δ’ οἱ Καύκωνες, ὥστε τοῖς ἀπὸ τοῦ Πύλου βαδίζουσιν εἰς Λακεδαίμονα ἀνάγκη διὰ Καυκώνων εἶναι τὴν ὁδόν. τὸ δὲ ἱερὸν τοῦ Σαμίου Ποσειδῶνος καὶ ὁ κατ’ αὐτὸ ὅρμος, εἰς ὃν κατήχθη Τηλέμαχος, πρὸς δύσιν καὶ πρὸς ἄρκτον ἀπονεύει. εἰ μὲν τοίνυν οἱ Καύκωνες ἐνταῦθα μόνον οἰκοῦσιν, οὐ σώζεται τῷ ποιητῇ ὁ λόγος. κελεύει γὰρ ἡ μὲν Ἀθηνᾶ κατὰ τὸν Σωτάδην τῷ Νέστορι, τὸν μὲν Τηλέμαχον εἰς τὴν Λακεδαίμονα πέμψαι σὺν δίφρῳ τε καὶ υἱέι εἰς τὰ πρὸς ἕω μέρη· αὐτὴ δ’ ἐπὶ ναῦν βαδιεῖσθαι νυκτερεύσουσα φησιν ἐπὶ τὴν δύσιν καὶ εἰς τοὐπίσω,<br>ἀτὰρ ἠῶθεν μετὰ Καύκωνας μεγαθύμους<br>πορεύσεσθαι ἐπὶ τὸ χρέος πάλιν εἰς τοὔμπροσθεν. τίς οὖν ὁ τρόπος; παρῆν γὰρ τῷ Νέστορι λέγειν ἀλλ’ οἵ γε Καύκωνες ὑπ’ ἐμοί εἰσι καὶ πρὸ ὁδοῦ τοῖς εἰς Λακεδαίμονα βαδίζουσιν· ὥστε τί οὐ συνοδεύεις τοῖς περὶ Τηλέμαχον, ἀλλ’ ἀναχωρεῖς εἰς τοὐπίσω; ἅμα δ’ οἰκεῖον ἦν τῷ βαδίζοντι ἐπὶ χρέους κομιδὴν οὐκ ὀλίγου, ὥς φησι, πρὸς ἀνθρώπους ὑπὸ τῷ Νέστορι ὄντας, αἰτήσασθαί τινα παρ’ αὐτοῦ βοήθειαν, εἴ τι ἀγνωμονοῖτο (ὥσπερ εἴωθε) περὶ τὸ συμβόλαιον· οὐ γέγονε δὲ τοῦτο. εἰ μὲν τοίνυν ἐνταῦθα μόνον οἰκοῖεν οἱ Καύκωνες, ταῦτ’ ἂν συμβαίνοι τὰ ἄτοπα· μεμερισμένων δὲ τινῶν καὶ εἰς τοὺς πρὸς Δύμῃ τόπους τῆς Ἠλείας, ἐκεῖσε ἂν εἴη λέγουσα τὴν ἔφοδον ἡ Ἀθηνᾶ, καὶ οὐκ ἂν ἔτι οὔθ’ ἡ εἰς τὴν ναῦν κατάβασις ἔχοι τι ἀπεμφαῖνον οὔθ’ ὁ τῆς συνοδίας ἀποσπασμός, εἰς τἀναντία τῆς ὁδοῦ οὔσης. παραπλησίως δ’ ἂν καὶ τὰ περὶ τοῦ Πύλου διαπορούμενα τύχοι τῆς προσηκούσης διαίτης ἐπελθοῦσι μικρὸν ἔτι τῆς χωρογραφίας μέχρι τοῦ Πύλου τοῦ Μεσσηνιακοῦ.", "st": "8.3.17"}, {"sp": "N", "t": "ἐλέγοντο δὲ Παρωρεᾶται τινὲς τῶν ἐν τῇ Τριφυλίᾳ κατέχοντες ὄρη περὶ τὸ Λέπρειον καὶ τὸ Μάκιστον καθήκοντα ἐπὶ θάλατταν πλησίον τοῦ Σαμιακοῦ ποσειδίου.", "st": "8.3.18"}, {"sp": "N", "t": "ὑπὸ τούτοις ἐστὶν ἐν τῇ παραλίᾳ δύο ἄντρα, τὸ μὲν νυμφῶν Ἀνιγριάδων τὸ δὲ ἐν ᾧ τὰ περὶ τὰς Ἀτλαντίδας καὶ τὴν Δαρδάνου γένεσιν. ἐνταῦθα δὲ καὶ τὰ ἄλση τό τε Ἰωναῖον καὶ τὸ Εὐρυκύδειον. τὸ μὲν οὖν Σαμικὸν ἔστιν ἔρυμα, πρότερον δὲ καὶ πόλις Σάμος προσαγορευομένη διὰ τὸ ὕψος ἴσως, ἐπειδὴ Σάμους ἐκάλουν τὰ ὕψη· τάχα δὲ τῆς Ἀρήνης ἀκρόπολις ἦν τοῦτο, ἧς ἐν τῷ καταλόγῳ μέμνηται ὁ ποιητής<br>οἳ δὲ Πύλον τ’ ἐνέμοντο καὶ Ἀρήνην ἐρατεινήν.<br>οὐδαμοῦ γὰρ σαφῶς εὑρίσκοντες ἐνταῦθα μάλιστα εἰκάζουσι τὴν Ἀρήνην, ὅπου καὶ ὁ παρακείμενος Ἄνιγρος ποταμός, καλούμενος πρότερον Μινύειος, δίδωσιν οὐ μικρὸν σημεῖον· λέγει γὰρ ὁ ποιητής<br>ἔστι δέ τις ποταμὸς Μινυήιος εἰς ἅλα βάλλων<br>ἐγγύθεν Ἀρήνης.<br>πρὸς γὰρ δὴ τῷ ἄντρῳ τῶν Ἀνιγριάδων νυμφῶν ἐστι πηγή, ὑφ’ ἧς ἕλειον καὶ τιφῶδες τὸ ὑποπῖπτον γίνεται χωρίον· ὑποδέχεται δὲ τὸ πλεῖστον τοῦ ὕδατος ὁ Ἄνιγρος βαθὺς καὶ ὕπτιος ὢν ὥστε λιμνάζειν· θινώδης δ’ ὢν ὁ τόπος ἐξ εἴκοσι σταδίων βαρεῖαν ὀσμὴν παρέχει καὶ τοὺς ἰχθῦς ἀβρώτους ποιεῖ. μυθεύουσι δ’ οἱ μὲν ἀπὸ τοῦ τῶν τετρωμένων Κενταύρων τινὰς ἐνταῦθ’ ἀπονίψασθαι τὸν ἐκ τῆς Ὕδρας ἰόν, οἱ δ’ ἀπὸ τοῦ Μελάμποδα τοῖς ὕδασι τούτοις καθαρσίοις χρήσασθαι πρὸς τὸν τῶν Προιτίδων καθαρμόν· ἀλφοὺς δὲ καὶ λεύκας καὶ λειχῆνας ἰᾶται τὸ ἐντεῦθεν λουτρόν. φασὶ δὲ καὶ τὸν Ἀλφειὸν ἀπὸ τῆς τῶν ἀλφῶν θεραπείας οὕτως ὠνομάσθαι. ἐπεὶ οὖν ἥ τε ὑπτιότης τοῦ Ἀνίγρου καὶ αἱ ἀνακοπαὶ τῆς θαλάττης μονὴν μᾶλλον ἢ ῥύσιν παρέχουσι τοῖς ὕδασι, Μινυήιόν φασιν εἰρῆσθαι πρότερον, παρατρέψαι δέ τινας τοὔνομα καὶ ἀντ’ αὐτοῦ ποιῆσαι Μινυήιον. ἔχει δ’ ἡ ἐτυμότης καὶ ἄλλας ἀφορμάς, εἴτ’ ἀπὸ τῶν μετὰ Χλωρίδος τῆς Νέστορος μητρὸς ἐλθόντων ἐξ Ὀρχομενοῦ τοῦ Μινυείου, [εἴτε] Μινυῶν, οἳ τῶν Ἀργοναυτῶν ἀπόγονοι ὄντες ἐκ Λήμνου μὲν εἰς Λακεδαίμονα ἐξέπεσον ἐντεῦθεν δ’ εἰς τὴν Τριφυλίαν, καὶ ᾤκησαν περὶ τὴν Ἀρήνην ἐν τῇ χώρᾳ τῇ νῦν Αἰπασίᾳ καλουμένῃ, οὐκ ἐχούσῃ οὐκέτι τὰ τῶν Μινυῶν κτίσματα· ὧν τινὲς μετὰ Θήρα τοῦ Αὐτεσίωνος (ἦν δ’ οὗτος Πολυνείκους ἀπόγονος) πλεύσαντες εἰς τὴν μεταξὺ Κυρηναίας καὶ τῆς Κρήτης νῆσον<br>καλλίστην τὸ πάροιθε, τὸ δ’ ὕστερον οὔνομα Θήρην,<br>ὥς φησι Καλλίμαχος, ἔκτισαν τὴν μητρόπολιν τῆς Κυρήνης Θήραν, ὁμώνυμον δ’ ἀπέδειξαν τῇ πόλει καὶ τὴν νῆσον.", "st": "8.3.19"}, {"sp": "N", "t": "μεταξὺ δὲ τοῦ Ἀνίγρου καὶ τοῦ ὄρους, ἐξ οὗ ῥεῖ, ὁ τοῦ Ἰαρδάνου λειμὼν δείκνυται καὶ τάφος· καὶ Ἀχαιαὶ εἰσὶ δὲ πέτραι ἀπότομοι τοῦ αὐτοῦ ὄρους, ὑπὲρ ὧν ἡ Σάμος, ὡς ἔφαμεν, γέγονε πόλις· οὐ πάνυ δὲ ὑπὸ τῶν τοὺς περίπλους γραψάντων ἡ Σάμος μνημονεύεται, τάχα μέν γε διὰ τὸ πάλαι κατεσπάσθαι, τάχα δὲ καὶ διὰ τὴν θέσιν. τὸ μὲν γὰρ ποσείδιον ἔστιν ἄλσος, ὡς εἴρηται, πρὸς τῇ θαλάττῃ· ὑπέρκειται δ’ αὐτοῦ λόφος ὑψηλὸς ἐπίπροσθεν ὢν τοῦ νῦν Σαμικοῦ ἐφ’ οὗ ἦν ἡ Σάμος, ὥστ’ ἐκ θαλάττης μὴ ὁρᾶσθαι. καὶ πεδίον δ’ αὐτόθι καλεῖται Σαμικόν· ἐξ οὗ πλέον ἄν τις τεκμαίροιτο ὑπάρξαι ποτὲ πόλιν τὴν Σάμον. καὶ ἡ Ῥαδίνη δὲ ἣν Στησίχορος ποιῆσαι δοκεῖ (ἧς ἀρχή<br>ἄγε Μοῦσα λίγει’, ἄρξον ἀοιδᾶς, Ἐρατώ, νόμους<br>Σαμίων περὶ παίδων ἐρατᾷ φθεγγομένα λύρᾳ<br>ἐντεῦθεν λέγει τοὺς παῖδας. ἐκδοθεῖσαν γὰρ τὴν Ῥαδίνην εἰς Κόρινθον τυράννῳ φησὶν ἐκ τῆς Σάμου πλεῦσαι πνέοντος ζεφύρου, οὐ δήπουθεν τῆς Ἰωνικῆς Σάμου· [τῷ] δ’ αὐτῷ ἀνέμῳ καὶ ἀρχιθέωρον εἰς Δελφοὺς [τὸν ἀδ]ελφὸν αὐτῆς ἐλθεῖν καὶ τὸν ἀνεψιὸν ἐρῶντα αὐτῆς ἅρματι εἰς Κόρινθον ἐξορμῆσαι παρ’ αὐτήν· ὅ τε τύραννος κτείνας ἀμφοτέρους ἅρματι ἀποπέμπει τὰ σώματα, μεταγνοὺς δ’ ἀνακαλεῖ καὶ θάπτει.", "st": "8.3.20"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ Πύλου τούτου καὶ τοῦ Λεπρείου τετρακοσίων που σταδίων ἐστὶ διάστημα ἐπὶ τὴν Μεσσηνιακὴν Πύλον καὶ τὸ Κορυφάσιον ἐπὶ θαλάττῃ κείμενα φρούρια, καὶ τὴν παρακειμένην Σφαγίαν νῆσον, ἀπὸ δὲ Ἀλφειοῦ ἑπτακοσίων πεντήκοντα, ἀπὸ δὲ τοῦ Χελωνάτα χιλίων τριάκοντα. ἐν δὲ τῷ μεταξὺ τό τε τοῦ Μακιστίου Ἡρακλέους ἱερόν ἐστι καὶ ὁ Ἀκίδων ποταμός. ῥεῖ δὲ παρὰ τάφον Ἰαρδάνου καὶ Χάαν πόλιν ποτὲ ὑπάρξασαν πλησίον Λεπρείου, ὅπου καὶ τὸ πεδίον τὸ Αἰπάσιον. περὶ ταύτης δὲ τῆς Χάας γενέσθαι φασὶν ἔνιοι τὸν πόλεμον τοῖς Ἀρκάσι πρὸς τοὺς Πυλίους, ὃν ἔφρασεν Ὅμηρος, καὶ δεῖν οἴονται γράφειν<br>ἡβῷμ’, ὡς ὅτ’ ἐπ’ ὠκυρόῳ Ἀκίδοντι μάχοντο<br>ἀγρόμενοι Πύλιοί τε καὶ Ἀρκάδες<br>Χάας πὰρ τείχεσσιν,<br>οὐ Κελάδοντι, οὐδὲ Φειᾶς· τῷ γὰρ τάφῳ τοῦ Ἰαρδάνου τοῦτον πλησιάζειν καὶ τοῖς Ἀρκάσι τὸν τόπον μᾶλλον ἢ ἐκεῖνον.", "st": "8.3.21"}, {"sp": "N", "t": "Κυπαρισσία τέ ἐστιν ἐπὶ τῇ θαλάττῃ τῇ Τριφυλιακῇ καὶ Πύργοι καὶ ὁ Ἀκίδων ποταμὸς καὶ Νέδα. νυνὶ μὲν οὖν τῇ Τριφυλίᾳ πρὸς τὴν Μεσσηνίαν ὅριόν ἐστι τὸ τῆς Νέδας ῥεῦμα λάβρον ἐκ τοῦ Λυκαίου κατιὸν Ἀρκαδικοῦ ὄρους, ἐκ πηγῆς ἣν ἀναρρῆξαι τεκοῦσαν τὸν Δία μυθεύεται Ῥέαν νίπτρων χάριν. ῥεῖ δὲ παρὰ Φιγαλίαν, καθ’ ὃ γειτνιῶσι Πυργῖται Τριφυλίων ἔσχατοι Κυπαρισσιεῦσι πρώτοις Μεσσηνίων. τὸ δὲ παλαιὸν ἄλλως διώριστο, ὡς καὶ τινὰς τῶν πέραν τῆς Νέδας ὑπὸ τῷ Νέστορι εἶναι, τόν τε Κυπαρισσήεντα καὶ ἄλλα τινὰ ἐπέκεινα, καθάπερ καὶ τὴν θάλατταν τὴν Πυλίαν ὁ ποιητὴς ἐπεκτείνει μέχρι τῶν ἑπτὰ πόλεων ὧν ὑπέσχετο Ἀγαμέμνων τῷ Ἀχιλλεῖ<br>πᾶσαι δ’ ἐγγὺς ἁλὸς νέαται Πύλου ἠμαθόεντος.<br>τοῦτο γὰρ ἴσον τῷ “ἐγγὺς ἁλὸς τῆς Πυλίας.”", "st": "8.3.22"}, {"sp": "N", "t": "ἐφεξῆς δ’ οὖν τῷ Κυπαρισσήεντι ἐπὶ τὴν Μεσσηνιακὴν Πύλον παραπλέοντι [καὶ] τὸ Κορυφάσιον ἥ τε Ἔρανα ἔστιν, ἥν τινες οὐκ εὖ Ἀρήνην νομίζουσιν κεκλῆσθαι πρότερον ὁμωνύμως τῇ Πυλιακῇ, [καὶ ἡ ἄκρα] Πλαταμώδης, ἀφ’ ἧς ἐπὶ τὸ Κορυφάσιον καὶ τὴν νῦν καλουμένην Πύλον ἑκατόν εἰσι στάδιοι. ἔστι δὲ καὶ νησίον καὶ πολίχνιον ἐν αὐτῷ ὁμώνυμον Πρωτή. οὐκ ἂν δ’ ἐξητάζομεν ἴσως ἐπὶ τοσοῦτον τὰ παλαιά, ἀλλ’ ἤρκει λέγειν ὡς ἔχει νῦν ἕκαστα, εἰ μή τις ἦν ἐκ παίδων ἡμῖν παραδεδομένη φήμη περὶ τούτων· ἄλλων δ’ ἄλλα εἰπόντων ἀνάγκη διαιτᾶν. πιστεύονται δ’ ὡς ἐπὶ τὸ πολὺ οἱ ἐνδοξότατοί τε καὶ πρεσβύτατοι καὶ κατ’ ἐμπειρίαν πρῶτοι· Ὁμήρου δ’ εἰς ταῦτα ὑπερβεβλημένου πάντας, ἀνάγκη συνεπισκοπεῖν καὶ τὰ ὑπ’ ἐκείνου λεχθέντα καὶ συγκρούειν πρὸς τὰ νῦν, καθάπερ καὶ μικρὸν ἔμπροσθεν ἔφαμεν.", "st": "8.3.23"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς κοίλης Ἤλιδος καὶ τοῦ Βουπρασίου τὰ λεχθέντα ὑφ’ Ὁμήρου προεπέσκεπται ἡμῖν. περὶ δὲ τῆς ὑπὸ τῷ Νέστορι οὕτω φησίν<br>οἳ δὲ Πύλον τ’ ἐνέμοντο καὶ Ἀρήνην ἐρατεινὴν<br>καὶ Θρύον, Ἀλφειοῖο πόρον, καὶ ἐύκτιτον Αἶπυ<br>καὶ Κυπαρισσήεντα καὶ Ἀμφιγένειαν ἔναιον<br>καὶ Πτελεὸν καὶ Ἕλος καὶ Δώριον, ἔνθα τε Μοῦσαι<br>ἀντόμεναι Θάμυριν τὸν Θρήικα παῦσαν ἀοιδῆς,<br>Οἰχαλίηθεν ἰόντα παρ’ Εὐρύτου Οἰχαλιῆος.<br>Πύλος μὲν οὖν ἔστι περὶ ἧς ἡ ζήτησις· αὐτίκα δ’ ἐπισκεψόμεθα περὶ αὐτῆς. περὶ δὲ τῆς Ἀρήνης εἴρηται· ἣν δὲ λέγει νῦν Θρύον, ἐν ἄλλοις καλεῖ Θρυόεσσαν<br>ἔστι δέ τις Θρυόεσσα πόλις, αἰπεῖα κολώνη,<br>τηλοῦ ἐπ’ Ἀλφειῷ.<br>Ἀλφειοῦ δὲ πόρον φησίν, ὅτι πεζῇ περατὸς εἶναι δοκεῖ κατὰ τοῦτον τὸν τόπον· καλεῖται δὲ νῦν Ἐπιτάλιον τῆς Μακιστίας χωρίον. τὸ εὔκτιτον δ’ Αἶπυ ἔνιοι μὲν ζητοῦσι πότερον ποτέρου ἐπίθετον, καὶ τίς ἡ πόλις, καὶ εἰ αἱ νῦν Μαργάλαι τῆς Ἀμφιδολίας· αὗται μὲν οὖν οὐ φυσικὸν ἔρυμα, ἕτερον δὲ δείκνυται φυσικὸν ἐν τῇ Μακιστίᾳ. ὁ μὲν οὖν τοῦθ’ ὑπονοῶν φράζεσθαι ὄνομά φησι τῆς πόλεως τὸ Αἶπυ ἀπὸ τοῦ συμβεβηκότος φυσικῶς, ὡς Ἕλος καὶ Αἰγιαλὸν καὶ ἄλλα πλείω· ὁ δὲ τὴν Μαργάλαν τοὔμπαλιν ἴσως. Θρύον δὲ καὶ Θρυόεσσαν τὸ Ἐπιτάλιόν φασιν, ὅτι πᾶσα μὲν αὕτη ἡ χώρα θρυώδης, μάλιστα δ’ οἱ ποταμοί· ἐπὶ πλέον δὲ διαφαίνεται τοῦτο κατὰ τοὺς περατοὺς τοῦ ῥείθρου τόπους. τάχα δέ φασι Θρύον μὲν εἰρῆσθαι τὸν πόρον, εὔκτιτον δ’ Αἶπυ τὸ Ἐπιτάλιον· ἔστι γὰρ ἐρυμνὸν φύσει· καὶ γὰρ ἐν ἄλλοις αἰπεῖαν κολώνην λέγει<br>ἔστι δέ τις Θρυόεσσα πόλις, αἰπεῖα κολώνη,<br>τηλοῦ ἐπ’ Ἀλφειῷ, πυμάτη Πύλου ἠμαθόεντος.", "st": "8.3.24"}, {"sp": "N", "t": "ὁ δὲ Κυπαρισσήεις ἔστι μὲν περὶ τὴν πρότερον Μακιστίαν, ἡνίκα καὶ πέραν τῆς Νέδας ἔτι ἦν Μακιστία, ἀλλ’ οὐκ οἰκεῖται, ὡς οὐδὲ τὸ Μάκιστον· ἄλλη δ’ ἐστὶν ἡ Μεσσηνιακὴ Κυπαρισσία, ὁμώνυμος μὲν οὔ, ὁμοίως δὲ νῦν κἀκείνη λέγεται Κυπαρισσία ἑνικῶς τε καὶ θηλυκῶς, ὁ δὲ ποταμὸς Κυπαρισσήεις. καὶ Ἀμφιγένεια δὲ τῆς Μακιστίας ἐστὶ περὶ τὸν Ὑψόεντα, ὅπου τὸ τῆς Λητοῦς ἱερόν. τὸ δὲ Πτελεὸν κτίσμα μὲν γέγονε τῶν ἐκ Πτελεοῦ τοῦ Θετταλικοῦ ἐποικησάντων· λέγεται γὰρ κἀκεῖ<br>ἀγχίαλόν τ’ Ἀντρῶνα ἰδὲ Πτελεὸν λεχεποίην.<br>ἔστι δὲ δρυμῶδες χωρίον ἀοίκητον, Πτελεάσιον καλούμενον. ἕλος δ’ οἱ μὲν περὶ τὸν Ἀλφειὸν χώραν τινά φασιν, οἱ δὲ καὶ πόλιν, ὡς τὴν Λακωνικήν<br>ἕλος τ’ ἔφαλον πτολίεθρον.<br>οἱ δὲ περὶ τὸ Ἀλώριον ἕλος, οὗ τὸ τῆς Ἑλείας Ἀρτέμιδος ἱερὸν τῆς ὑπὸ τοῖς Ἀρκάσιν· ἐκεῖνοι γὰρ ἔσχον τὴν ἱερωσύνην. Δώριον δ’ οἱ μὲν ὄρος, οἱ δὲ πεδίον, [οἱ δὲ πολίδιον] φασίν· οὐδὲν δὲ νῦν δείκνυται· ὅμως δ’ ἔνιοι τὴν νῦν Ὄλουριν ἢ Ὄλουραν ἐν τῷ καλουμένῳ αὐλῶνι τῆς Μεσσηνίας κειμένην Δώριον λέγουσιν. αὐτοῦ δέ που καὶ ἡ Οἰχαλία ἐστὶν ἡ τοῦ Εὐρύτου ἡ νῦν Ἀνδανία, πολίχνιον Ἀρκαδικὸν ὁμώνυμον τῷ Θετταλικῷ καὶ τῷ Εὐβοϊκῷ· ὅθεν φησὶν ὁ ποιητὴς ἐς τὸ Δώριον ἀφικόμενον Θάμυριν τὸν Θρᾷκα ὑπὸ Μουσῶν ἀφαιρεθῆναι τὴν μουσικήν.", "st": "8.3.25"}, {"sp": "N", "t": "ἐκ δὴ τούτων δῆλον ὡς ἐφ’ ἑκάτερα τοῦ Ἀλφειοῦ ἡ ὑπὸ Νέστορι χώρα ἐστίν, ἣν πᾶσαν ὀνομάζει Πυλίων γῆν· οὐδαμοῦ δὲ ὁ Ἀλφειὸς οὔτε τῆς Μεσσηνίας ἐφάπτεται οὔτε τῆς κοίλης Ἤλιδος. ἐν ταύτῃ γὰρ τῇ χώρᾳ ἐστὶν ἡ πατρὶς τοῦ Νέστορος, ἥν φαμεν Τριφυλιακὸν Πύλον καὶ Ἀρκαδικὸν καὶ Λεπρεατικόν. καὶ γὰρ δὴ οἱ μὲν ἄλλοι Πύλοι ἐπὶ θαλάττῃ δείκνυνται, οὗτος δὲ πλείους ἢ τριάκοντα σταδίους ὑπὲρ αὐτῆς, ὅπερ καὶ ἐκ τῶν ἐπῶν δῆλον. ἐπί τε γὰρ τοὺς Τηλεμάχου ἑταίρους ἄγγελος πέμπεται πρὸς τὸ πλοῖον καλῶν ἐπὶ ξενίαν, ὅ τε Τηλέμαχος κατὰ τὴν ἐκ Σπάρτης ἐπάνοδον τὸν Πεισίστρατον οὐκ ἐᾷ πρὸς τὴν πόλιν ἐλαύνειν, ἀλλὰ παρατρέψαντα ἐπὶ [τὴν] ναῦν σπεύδειν, ὡς οὐ τὴν αὐτὴν οὖσαν ἐπὶ τὴν πόλιν καὶ τὸν ὅρμον. ὅ τε ἀπόπλους τοῦ Τηλεμάχου οὕτως ἂν οἰκείως λέγοιτο<br>βὰν δὲ παρὰ Κρουνοὺς καὶ Χαλκίδα καλλιρέεθρον.<br>δύετό τ’ ἠέλιος, σκιόωντό τε πᾶσαι ἀγυιαί·<br>ἡ δὲ Φεὰς ἐπέβαλλεν, ἀγαλλομένη Διὸς οὔρῳ,<br>ἠδὲ παρ’ Ἤλιδα δῖαν, ὅθι κρατέουσιν Ἐπειοί.<br>μέχρι μὲν δὴ δεῦρο πρὸς τὴν ἄρκτον ὁ πλοῦς, ἐντεῦθεν δ’ ἐπὶ τὸ πρὸς ἕω μέρος ἐπιστρέφει. παρίησι δὲ τὸν εὐθὺν πλοῦν ἡ ναῦς καὶ τὸν ἐξ ἀρχῆς καὶ τὸν εἰς Ἰθάκην διὰ τὸ τοὺς μνηστῆρας ἐκεῖ τὴν ἐνέδραν θέσθαι<br>ἐν πορθμῷ Ἰθάκης τε Σάμοιό τε·<br>ἔνθεν δ’ αὖ νήσοισιν ἐπιπροέηκε θοῇσι.<br>θοὰς δὲ εἴρηκε τὰς ὀξείας· τῶν Ἐχινάδων δ’ εἰσὶν αὗται, πλησιάζουσαι τῇ ἀρχῇ τοῦ Κορινθιακοῦ κόλπου καὶ ταῖς ἐκβολαῖς τοῦ Ἀχελώου. παραλλάξας δὲ τὴν Ἰθάκην, ὥστε κατὰ νώτου γενέσθαι, κάμπτει πάλιν πρὸς τὸν οἰκεῖον δρόμον τὸν μεταξὺ τῆς Ἀκαρνανίας καὶ τῆς Ἰθάκης, καὶ κατὰ θάτερα μέρη τῆς νήσου ποιεῖται τὴν καταγωγήν, οὐ κατὰ τὸν πορθμὸν τὸν Κεφαλληνιακόν, ὃν ἐφρούρουν οἱ μνηστῆρες.", "st": "8.3.26"}, {"sp": "N", "t": "εἰ γοῦν τὸν Ἠλιακὸν Πύλον εἶναί τις τὸν Νέστορος ἐπινοήσειεν, οὐκ ἂν οἰκείως λέγοιτο ἡ ἐντεῦθεν ἀναχθεῖσα ναῦς παρὰ Κρουνοὺς ἐνεχθῆναι καὶ Χαλκίδα μέχρι δύσεως, εἶτα Φεαῖς ἐπιβάλλειν νύκτωρ, καὶ τότε τὴν Ἠλείαν παραπλεῖν· οὗτοι γὰρ οἱ τόποι πρὸς νότον τῆς Ἠλείας εἰσί, πρῶται μὲν αἱ Φεαί, εἶθ’ ἡ Χαλκίς, εἶθ’ οἱ Κρουνοί, εἶθ’ ὁ Πύλος ὁ Τριφυλιακὸς καὶ τὸ Σαμικόν. τῷ μὲν οὖν πρὸς νότον πλέοντι ἐκ τοῦ Ἠλιακοῦ Πύλου οὗτος ἂν ὁ πλοῦς εἴη· τῷ δὲ πρὸς ἄρκτον, ὅπου ἐστὶν ἡ Ἰθάκη, ταῦτα μὲν πάντα ὀπίσω λείπεται, αὐτὴ δ’ ἡ Ἠλεία παραπλευστέα ἦν, καὶ πρὸ δύσεώς γε· ὁ δέ φησι μετὰ δύσιν. καὶ μὴν εἰ καὶ πάλιν ὑπόθοιτό τις τὸν Μεσσηνιακὸν Πύλον καὶ τὸ Κορυφάσιον ἀρχὴν τοῦ παρὰ Νέστορος πλοῦ, πολὺ ἂν εἴη τὸ διάστημα καὶ πλέονος χρόνου. αὐτὸ γοῦν τὸ ἐπὶ τὸν Τριφυλιακὸν Πύλον καὶ τὸ Σαμιακὸν ποσείδιον τετρακοσίων ἐστὶ σταδίων· καὶ ὁ παράπλους [οὐ] παρὰ Κρουνοὺς καὶ Χαλκίδα καὶ Φεάν, ἀδόξων ποταμῶν ὀνόματα μᾶλλον δὲ ὀχετῶν, ἀλλὰ παρὰ τὴν Νέδαν πρῶτον, εἶτ’ Ἀκίδωνα, εἶτα τὸν Ἀλφειὸν καὶ τόπους τούτων τοὺς μεταξύ· ὕστερον δ’, εἰ ἄρα, κἀκείνων ἐχρῆν μνησθῆναι· καὶ γὰρ παρ’ ἐκείνους ὑπῆρχεν ὁ πλοῦς.", "st": "8.3.27"}, {"sp": "N", "t": "καὶ μὴν ἥ γε τοῦ Νέστορος διήγησις, ἣν διατίθεται πρὸς Πάτροκλον περὶ τοῦ γενομένου τοῖς Πυλίοις πρὸς Ἠλείους πολέμου, συνηγορεῖ τοῖς ὑφ’ ἡμῶν ἐπιχειρουμένοις, ἐὰν σκοπῇ τις τὰ ἔπη. φησὶ γὰρ ἐν αὐτοῖς, ὅτι πορθήσαντος Ἡρακλέους τὴν Πυλίαν ὥστε τὴν νεότητα ἐκλειφθῆναι πᾶσαν, δώδεκα δὴ παίδων ὄντων τῷ Νηλεῖ, μόνον αὐτῷ περιγενέσθαι τὸν Νέστορα νέον τελέως· καταφρονήσαντες δ’ οἱ Ἐπειοὶ τοῦ Νηλέως διὰ γῆρας καὶ ἐρημίαν ὑπερηφάνως καὶ ὑβριστικῶς ἐχρῶντο τοῖς Πυλίοις. ἀντὶ τούτων οὖν ὁ Νέστωρ συναγαγὼν τοὺς οἰκείους ὅσους οἷός τε ἦν ἐπελθεῖν φησιν ἐπὶ τὴν Ἠλείαν, καὶ περιελάσαι παμπόλλην λείαν<br>πεντήκοντα βοῶν ἀγέλας, τόσα πώεα οἰῶν,<br>τόσσα συῶν συβόσια,<br>τοσαῦτα δὲ καὶ αἰπόλια, ἵππους δὲ ξανθὰς ἑκατὸν καὶ πεντήκοντα, ὑποπώλους τὰς πλείστας.<br>καὶ τὰ μὲν ἠλασάμεσθα Πύλον (φησί)Νηλήιον εἴσω,<br>ἐννύχιοι προτὶ ἄστυ,<br>ὡς μεθ’ ἡμέραν μὲν τῆς λεηλασίας γενομένης καὶ τῆς τροπῆς τῶν ἐκβοηθησάντων, ὅτε κτανεῖν λέγει τὸν Ἰτυμονέα, νύκτωρ δὲ τῆς ἀφόδου γενομένης ὥστ’ ἐννυχίους πρὸς τῷ ἄστει γενέσθαι· περὶ δὲ τὴν διανομὴν καὶ θυσίαν ὄντων οἱ Ἐπειοὶ τῇ τρίτῃ τῶν ἡμερῶν κατὰ πλῆθος ἀθροισθέντες πεζοί τε καὶ ἱππεῖς ἀντεπεξῆλθον καὶ τὸ Θρύον ἐπὶ τῷ Ἀλφειῷ κείμενον περιεστρατοπέδευσαν. αἰσθόμενοι δ’ εὐθὺς οἱ Πύλιοι βοηθεῖν ὥρμησαν· νυκτερεύσαντες δὲ περὶ τὸν Μινυήιον ποταμὸν ἐγγύθεν Ἀρήνης, ἐντεῦθεν ἔνδιοι πρὸς τὸν Ἀλφειὸν ἀφικνοῦνται· τοῦτο δ’ ἐστὶ κατὰ μεσημβρίαν· θύσαντες δὲ τοῖς θεοῖς καὶ νυκτερεύσαντες ἐπὶ τῷ ποταμῷ συμβάλλουσιν εἰς μάχην εὐθὺς ἕωθεν· λαμπρᾶς δὲ τῆς τροπῆς γενομένης οὐκ ἐπαύσαντο διώκοντές τε καὶ κτείνοντες πρὶν Βουπρασίου ἐπέβησαν<br>πέτρης τ’ Ὠλενίης καὶ Ἀλεισίου ἔνθα κολώνη<br>κέκληται, ὅθεν αὖτις ἀπέτραπε λαὸν Ἀθήνη.<br>καὶ ὑποβάς<br>αὐτὰρ Ἀχαιοὶ<br>ἂψ ἀπὸ Βουπρασίοιο Πύλονδ’ ἔχον ὠκέας ἵππους.", "st": "8.3.28"}, {"sp": "N", "t": "ἐκ τούτων δὴ πῶς ἂν ἢ τὸν Ἠλιακὸν Πύλον ὑπολάβοι τις ἢ τὸν Μεσσηνιακὸν λέγεσθαι; τὸν μὲν Ἠλιακόν, ὅτι τούτου πορθουμένου συνεπορθεῖτο καὶ ἡ τῶν Ἐπειῶν ὑπὸ τοῦ Ἡρακλέους· αὕτη δ’ ἐστὶν ἡ Ἠλεία. πῶς οὖν ἤμελλον οἱ συμπεπορθημένοι καὶ ὁμόφυλοι τοιαύτην ὑπερηφανίαν καὶ ὕβριν κτήσασθαι κατὰ τῶν συναδικηθέντων; πῶς δ’ ἂν τὴν οἰκείαν κατέτρεχον καὶ ἐλεηλάτουν; πῶς δ’ ἂν ἅμα καὶ Αὐγέας ἦρχε τῶν αὐτῶν καὶ Νηλεὺς ἐχθροὶ ὄντες ἀλλήλων; εἴγε τῷ Νηλεῖ<br>χρεῖος μέγ’ ὀφείλετ’ ἐν Ἤλιδι δίῃ,<br>τέσσαρες ἀθλοφόροι ἵπποι αὐτοῖσιν ὄχεσφιν,<br>ἐλθόντες μετ’ ἄεθλα· περὶ τρίποδος γὰρ ἔμελλον<br>θεύσεσθαι· τοὺς δ’ αὖθι ἄναξ ἀνδρῶν Αὐγείας<br>κάσχεθε, τὸν δ’ ἐλατῆρ’ ἀφίει.<br>εἰ δ’ ἐνταῦθα ᾤκει ὁ Νηλεύς, ἐνταῦθα καὶ ὁ Νέστωρ ἐπῆρχε. πῶς οὖν τῶν μὲν Ἠλείων καὶ Βουπρασίων<br>τέσσαρες ἀρχοὶ ἔσαν, δέκα δ’ ἀνδρὶ ἑκάστῳ<br>νῆες ἕποντο θοαί, πολέες δ’ ἔμβαινον Ἐπειοί;<br>εἰς τέτταρα δὲ καὶ ἡ χώρα διῄρητο, ὧν οὐδενὸς ἐπῆρχεν ὁ Νέστωρ,<br>οἳ δὲ Πύλον τ’ ἐνέμοντο καὶ Ἀρήνην ἐρατεινήν<br>καὶ τὰ ἑξῆς τὰ μέχρι Μεσσήνης; οἱ δὲ δὴ ἀντεπεξιόντες Ἐπειοὶ τοῖς Πυλίοις πῶς ἐπὶ τὸν Ἀλφειὸν ἐξορμῶσι καὶ τὸ Θρύον; πῶς δ’ ἐκεῖ τῆς μάχης γενομένης τρεφθέντες ἐπὶ Βουπρασίου φεύγουσι; πάλιν δ’, εἰ τὸν Μεσσηνιακὸν Πύλον ἐπόρθησεν ὁ Ἡρακλῆς, πῶς οἱ τοσοῦτον ἀφεστῶτες ὕβριζον εἰς αὐτούς, καὶ ἐν συμβολαίοις ἦσαν πολλοῖς, καὶ ταῦτ’ ἀπεστέρουν χρεοκοποῦντες, ὥστε διὰ ταῦτα συμβῆναι τὸν πόλεμον; πῶς δὲ ἐπὶ τὴν λεηλασίαν ἐξιὼν Νέστωρ τοσαύτην περιελάσας λείαν συῶν τε καὶ προβάτων, ὧν οὐδὲν ὠκυπορεῖν οὐδὲ μακροπορεῖν δύναται, πλειόνων ἢ χιλίων σταδίων ὁδὸν διήνυσεν εἰς τὴν πρὸς τῷ Κορυφασίῳ Πύλον, οἱ δὲ τρίτῳ ἤματι πάντες ἐπὶ τὴν Θρυόεσσαν καὶ τὸν ποταμὸν τὸν Ἀλφειὸν ἥκουσι πολιορκήσοντες τὸ φρούριον; πῶς δὲ ταῦτα τὰ χωρία προσήκοντα ἦν τοῖς ἐν τῇ Μεσσηνίᾳ δυναστεύουσιν ἐχόντων Καυκώνων καὶ Τριφυλίων καὶ Πισατῶν; τὰ δὲ Γέρηνα ἢ τὴν Γερηνίαν (ἀμφοτέρως γὰρ λέγεται) τάχα μὲν ἐπίτηδες ὠνόμασάν τινες· δύναται δὲ καὶ κατὰ τύχην οὕτως ὠνομάσθαι τὸ χωρίον. τὸ δ’ ὅλον, τῆς Μεσσηνίας ὑπὸ Μενελάῳ τεταγμένης, ὑφ’ ᾧ καὶ ἡ Λακωνικὴ ἐτέτακτο (ὡς δῆλον ἔσται καὶ ἐκ τῶν ὕστερον), καὶ τοῦ μὲν Παμισοῦ ῥέοντος διὰ ταύτης καὶ τοῦ Νέδωνος, Ἀλφειοῦ δ’ οὐδαμῶς<br>ὅς τ’ εὐρὺ ῥέει Πυλίων διὰ γαίης,<br>ἧς ἐπῆρχεν ὁ Νέστωρ, τίς ἂν γένοιτο πιθανὸς λόγος εἰς τὴν ἀλλοτρίαν ἀρχὴν ἐκβιβάζων τὸν ἄνδρα, ἀφαιρούμενος δὲ τὰς συγκαταλεγείσας αὐτῷ πόλεις πάνθ’ ὑπ’ ἐκείνῳ ποιῶν;", "st": "8.3.29"}, {"sp": "N", "t": "λοιπὸν δ’ ἐστὶν εἰπεῖν περὶ τῆς Ὀλυμπίας καὶ τῆς εἰς τοὺς Ἠλείους ἁπάντων μεταπτώσεως. ἔστι δ’ ἐν τῇ Πισάτιδι τὸ ἱερὸν σταδίους τῆς Ἤλιδος ἐλάττους ἢ τριακοσίους διέχον· πρόκειται δ’ ἄλσος ἀγριελαίων ἐν ᾧ τὸ στάδιον· παραρρεῖ δ’ ὁ Ἀλφειὸς ἐκ τῆς Ἀρκαδίας ῥέων εἰς τὴν Τριφυλιακὴν θάλατταν μεταξὺ δύσεως καὶ μεσημβρίας. τὴν δ’ ἐπιφάνειαν ἔσχεν ἐξ ἀρχῆς μὲν διὰ τὸ μαντεῖον τοῦ Ὀλυμπίου Διός· ἐκείνου δ’ ἐκλειφθέντος οὐδὲν ἧττον συνέμεινεν ἡ δόξα τοῦ ἱεροῦ, καὶ τὴν αὔξησιν ὅσην ἴσμεν ἔλαβε διά τε τὴν πανήγυριν καὶ τὸν ἀγῶνα τὸν Ὀλυμπιακόν, στεφανίτην τε καὶ ἱερὸν νομισθέντα, μέγιστον τῶν πάντων. ἐκοσμήθη δ’ ἐκ τοῦ πλήθους τῶν ἀναθημάτων, ἅπερ ἐκ πάσης ἀνετίθετο τῆς Ἑλλάδος· ὧν ἦν καὶ ὁ χρυσοῦς σφυρήλατος Ζεύς, ἀνάθημα Κυψέλου τοῦ Κορινθίων τυράννου. μέγιστον δὲ τούτων ὑπῆρξε τὸ τοῦ Διὸς ξόανον, ὃ ἐποίει Φειδίας Χαρμίδου Ἀθηναῖος ἐλεφάντινον, τηλικοῦτον τὸ μέγεθος ὡς καίπερ μεγίστου ὄντος τοῦ νεὼ δοκεῖν ἀστοχῆσαι τῆς συμμετρίας τὸν τεχνίτην, καθήμενον ποιήσαντα, ἁπτόμενον δὲ σχεδόν τι τῇ κορυφῇ τῆς ὀροφῆς ὥστ’ ἔμφασιν ποιεῖν, ἐὰν ὀρθὸς γένηται διαναστάς, ἀποστεγάσειν τὸν νεών. ἀνέγραψαν δέ τινες τὰ μέτρα τοῦ ξοάνου, καὶ Καλλίμαχος ἐν ἰάμβῳ τινὶ ἐξεῖπε. πολλὰ δὲ συνέπραξε τῷ Φειδίᾳ Πάναινος ὁ ζωγράφος, ἀδελφιδοῦς ὢν αὐτοῦ καὶ συνεργολάβος, πρὸς τὴν τοῦ ξοάνου διὰ τῶν χρωμάτων κόσμησιν καὶ μάλιστα τῆς ἐσθῆτος. δείκνυνται δὲ καὶ γραφαὶ πολλαί τε καὶ θαυμασταὶ περὶ τὸ ἱερὸν ἐκείνου ἔργα. ἀπομνημονεύουσι δὲ τοῦ Φειδίου, διότι πρὸς τὸν Πάναινον εἶπε πυνθανόμενον πρὸς τί παράδειγμα μέλλοι ποιήσειν τὴν εἰκόνα τοῦ Διός, ὅτι πρὸς τὴν Ὁμήρου δι’ ἐπῶν ἐκτεθεῖσαν τούτων<br>ἦ καὶ κυανέῃσιν ἐπ’ ὀφρύσι νεῦσε Κρονίων·<br>ἀμβρόσιαι δ’ ἄρα χαῖται ἐπερρώσαντο ἄνακτος<br>κρατὸς ἀπ’ ἀθανάτοιο, μέγαν δ’ ἐλέλιξεν Ὄλυμπον.<br>ἄξιοι δὲ μάλιστα τὴν αἰτίαν ἔχειν τῆς περὶ τὸ Ὀλυμπίασιν ἱερὸν μεγαλοπρεπείας τε καὶ τιμῆς Ἠλεῖοι. κατὰ μὲν γὰρ τὰ Τρωικὰ καὶ ἔτι πρὸ τούτων οὐκ ηὐτύχουν, ὑπό τε τῶν Πυλίων ταπεινωθέντες καὶ ὑφ’ Ἡρακλέους ὕστερον, ἡνίκα Αὐγέας ὁ βασιλεύων αὐτῶν κατελύθη. σημεῖον δέ· εἰς γὰρ τὴν Τροίαν ἐκεῖνοι μὲν τετταράκοντα ναῦς ἔστειλαν, Πύλιοι δὲ καὶ Νέστωρ ἐνενήκοντα. ὕστερον δὲ μετὰ τὴν τῶν Ἡρακλειδῶν κάθοδον συνέβη τἀναντία. Αἰτωλοὶ γὰρ συγκατελθόντες τοῖς Ἡρακλείδαις μετὰ Ὀξύλου καὶ συνοικήσαντες Ἐπειοῖς κατὰ συγγένειαν παλαιὰν ηὔξησαν τὴν κοίλην Ἦλιν καὶ τῆς τε Πισάτιδος ἀφείλοντο πολλήν, καὶ Ὀλυμπία ὑπ’ ἐκείνοις ἐγένετο· καὶ δὴ καὶ ὁ ἀγὼν εὕρημά ἐστιν ἐκείνων ὁ Ὀλυμπιακός, καὶ τὰς Ὀλυμπιάδας τὰς πρώτας ἐκεῖνοι συνετέλουν. ἐᾶσαι γὰρ δεῖ τὰ παλαιὰ καὶ περὶ τῆς κτίσεως τοῦ ἱεροῦ καὶ περὶ τῆς θέσεως τοῦ ἀγῶνος, τῶν μὲν ἕνα τῶν Ἰδαίων δακτύλων Ἡρακλέα λεγόντων ἀρχηγέτην τούτων, τῶν δὲ τὸν Ἀλκμήνης καὶ Διός, ὃν καὶ ἀγωνίσασθαι πρῶτον καὶ νικῆσαι· τὰ γὰρ τοιαῦτα πολλαχῶς λέγεται καὶ οὐ πάνυ πιστεύεται. ἐγγυτέρω δὲ πίστεως, ὅτι μέχρι τῆς ἕκτης καὶ εἰκοστῆς Ὀλυμπιάδος ἀπὸ τῆς πρώτης, ἐν ᾗ Κόροιβος ἐνίκα στάδιον Ἠλεῖος, τὴν προστασίαν εἶχον τοῦ τε ἱεροῦ καὶ τοῦ ἀγῶνος Ἠλεῖοι. κατὰ δὲ τὰ Τρωικὰ ἢ οὐκ ἦν ἀγὼν στεφανίτης ἢ οὐκ ἔνδοξος, οὔθ’ οὗτος οὔτ’ ἄλλος οὐδεὶς τῶν νῦν ἐνδόξων· οὐδὲ μέμνηται τούτων Ὅμηρος οὐδενός, ἀλλ’ ἑτέρων τινῶν ἐπιταφίων. καίτοι δοκεῖ τισὶ τοῦ Ὀλυμπιακοῦ μεμνῆσθαι, ὅταν φῇ τὸν Αὐγέαν ἀποστερῆσαι τέσσαρας ἀθλοφόρους ἵππους, ἐλθόντας μετ’ ἄεθλα· φασὶ δὲ τοὺς Πισάτας μὴ μετασχεῖν τοῦ Τρωικοῦ πολέμου ἱεροὺς νομισθέντας τοῦ Διός. ἀλλ’ οὔθ’ ἡ Πισᾶτις ὑπὸ Αὐγέᾳ τόθ’ ὑπῆρχεν, ἐν ᾗ ἐστι καὶ ἡ Ὀλυμπία, ἀλλ’ ἡ Ἠλεία μόνον, οὔτ’ ἐν Ἠλείᾳ συνετελέσθη ὁ Ὀλυμπιακὸς ἀγὼν οὐδ’ ἅπαξ, ἀλλ’ ἀεὶ ἐν Ὀλυμπίᾳ. ὁ δὲ νῦν παρατεθεὶς ἐν Ἤλιδι φαίνεται γενόμενος, ἐν ᾗ καὶ τὸ χρέος ὠφείλετο<br>καὶ γὰρ τῷ χρεῖος [μέγ’] ὀφείλετ’ ἐν Ἤλιδι δίῃ,<br>τέσσαρες ἀθλοφόροι ἵπποι.<br>καὶ οὗτος μὲν οὐ στεφανίτης (περὶ τρίποδος γὰρ ἔμελλον θεύσεσθαι), ἐκεῖνος δέ. μετὰ [δὲ] τὴν ἕκτην καὶ εἰκοστὴν Ὀλυμπιάδα οἱ Πισᾶται τὴν οἰκείαν ἀπολαβόντες αὐτοὶ συνετέλουν, τὸν ἀγῶνα ὁρῶντες εὐδοκιμοῦντα· χρόνοις δ’ ὕστερον μεταπεσούσης πάλιν τῆς Πισάτιδος εἰς τοὺς Ἠλείους μετέπεσεν εἰς αὐτοὺς πάλιν καὶ ἡ ἀγωνοθεσία. συνέπραξαν δὲ καὶ οἱ Λακεδαιμόνιοι μετὰ τὴν ἐσχάτην κατάλυσιν τῶν Μεσσηνίων συμμαχήσασιν αὐτοῖς τἀναντία τῶν Νέστορος ἀπογόνων καὶ τῶν Ἀρκάδων συμπολεμησάντων τοῖς Μεσσηνίοις· καὶ ἐπὶ τοσοῦτόν γε συνέπραξαν ὥστε τὴν χώραν ἅπασαν τὴν μέχρι Μεσσήνης Ἠλείαν ῥηθῆναι καὶ διαμεῖναι μέχρι νῦν, Πισατῶν δὲ καὶ Τριφυλίων καὶ Καυκώνων μηδ’ ὄνομα λειφθῆναι. καὶ αὐτὸν δὲ τὸν Πύλον τὸν ἠμαθόεντα εἰς τὸ Λέπρειον συνῴκισαν, χαριζόμενοι τοῖς Λεπρεάταις κρατήσασι πολέμῳ, καὶ ἄλλας πολλὰς τῶν κατοικιῶν κατέσπασαν, ὅσας γ’ ἑώρων αὐτοπραγεῖν ἐθελούσας, καὶ φόρους ἐπράξαντο.", "st": "8.3.30"}, {"sp": "N", "t": "Διωνομάσθη δὲ ἡ Πισᾶτις τὸ μὲν πρῶτον διὰ τοὺς ἡγεμόνας δυνηθέντας πλεῖστον, Οἰνόμαόν τε καὶ Πέλοπα τὸν ἐκεῖνον διαδεξάμενον καὶ τοὺς παῖδας αὐτοῦ πολλοὺς γενομένους· καὶ ὁ Σαλμωνεὺς δ’ ἐνταῦθα βασιλεῦσαι λέγεται· εἰς γοῦν ὀκτὼ πόλεις μεριζομένης τῆς Πισάτιδος, μία τούτων λέγεται καὶ ἡ Σαλμώνη. διὰ ταῦτά τε δὴ καὶ [διὰ] τὸ ἱερὸν τὸ Ὀλυμπίασι διατεθρύληται σφόδρα ἡ χώρα. δεῖ δὲ τῶν παλαιῶν ἱστοριῶν ἀκούειν οὕτως ὡς μὴ ὁμολογουμένων σφόδρα· οἱ γὰρ νεώτεροι πολλὰ καινίζουσιν, ὥστε καὶ τἀναντία λέγειν, οἷον τὸν μὲν Αὐγέαν τῆς Πισάτιδος ἄρξαι τὸν δ’ Οἰνόμαον καὶ τὸν Σαλμωνέα τῆς Ἠλείας· ἔνιοι δ’ εἰς ταὐτὸ συνάγουσι τὰ ἔθνη. δεῖ δὲ τοῖς ὁμολογουμένοις ὡς ἐπὶ πολὺ ἀκολουθεῖν, ἐπεὶ οὐδὲ τοὔνομα τὴν Πισᾶτιν ἐτυμολογοῦσιν ὁμοίως· οἱ μὲν γὰρ ἀπὸ Πίσης ὁμωνύμου τῇ κρήνῃ πόλεως, τὴν δὲ κρήνην Πῖσαν εἰρῆσθαι, οἷον πίστραν, ὅπερ ἐστὶ ποτίστρα· τὴν δὲ πόλιν ἱδρυμένην ἐφ’ ὕψους δεικνύουσι μεταξὺ δυεῖν ὀροῖν, Ὄσσης καὶ Ὀλύμπου, ὁμωνύμων τοῖς ἐν Θετταλίᾳ. τινὲς δὲ πόλιν μὲν οὐδεμίαν γεγονέναι Πῖσαν φασίν (εἶναι γὰρ ἂν μίαν τῶν ὀκτώ), κρήνην δὲ μόνην, ἣν νῦν καλεῖσθαι Βῖσαν, Κικυσίου πλησίον πόλεως μεγίστης τῶν ὀκτώ· Στησίχορον δὲ καλεῖν πόλιν τὴν χώραν Πῖσαν λεγομένην, ὡς ὁ ποιητὴς τὴν Λέσβον Μάκαρος πόλιν. Εὐριπίδης δ’ ἐν Ἴωνι<br>Εὔβοι’ Ἀθήναις ἐστί τις γείτων πόλις<br>καὶ ἐν Ῥαδαμάνθυι<br>οἳ γῆν ἔχουσ’ Εὐβοΐδα πρόσχωρον πόλιν·<br>Σοφοκλῆς δ’ ἐν Μυσοῖς<br>Ἀσία μὲν ἡ σύμπασα κλῄζεται, ξένε,<br>πόλις δὲ Μυσῶν Μυσία προσήγορος.", "st": "8.3.31"}, {"sp": "N", "t": "ἡ δὲ Σαλμώνη πλησίον ἐστὶ τῆς ὁμωνύμου κρήνης ἐξ ἧς ῥεῖ ὁ Ἐνιπεύς· ἐμβάλλει δ’ εἰς τὸν Ἀλφειόν. τούτου δ’ ἐρασθῆναι τὴν Τυρώ φασιν<br>ἣ ποταμοῦ ἠράσσατ’ Ἐνιπῆος θείοιο.<br>ἐνταῦθα γὰρ βασιλεῦσαι τὸν πατέρα αὐτῆς τὸν Σαλμωνέα, καθάπερ καὶ Εὐριπίδης ἐν Αἰόλῳ φησί. ἐγγὺς δὲ τῆς Σαλμώνης Ἡράκλεια, καὶ αὕτη μία τῶν ὀκτώ, διέχουσα περὶ τετταράκοντα σταδίους τῆς Ὀλυμπίας, κειμένη δὲ παρὰ τὸν Κυθήριον ποταμόν, οὗ τὸ τῶν Ἰωνιάδων νυμφῶν ἱερὸν τῶν πεπιστευμένων θεραπεύειν νόσους τοῖς ὕδασι. παρὰ δὲ τὴν Ὀλυμπίαν ἐστὶ καὶ ἡ Ἄρπινα, καὶ αὕτη τῶν ὀκτώ, δι’ ἧς ῥεῖ ποταμὸς Παρθενίας ὡς εἰς Ἡραίαν ἰόντων· αὐτοῦ δ’ ἔστι καὶ τὸ Κικύσιον τῶν ὀκτὼ καὶ τὸ Δυσπόντιον κατὰ τὴν ὁδὸν τὴν ἐξ Ἤλιδος εἰς Ὀλυμπίαν ἐν πεδίῳ κείμενον· ἐξελείφθη δέ, καὶ ἀπῆραν οἱ πλείους εἰς Ἐπίδαμνον καὶ Ἀπολλωνίαν· καὶ ἡ Φολόη δ’ ὑπέρκειται τῆς Ὀλυμπίας ἐγγυτάτω, ὄρος Ἀρκαδικόν, ὥστε τὰς ὑπωρείας τῆς Πισάτιδος εἶναι. καὶ πᾶσα δ’ ἡ Πισᾶτις καὶ τῆς Τριφυλίας τὰ πλεῖστα ὁμορεῖ τῇ Ἀρκαδίᾳ· διὰ δὲ τοῦτο καὶ Ἀρκαδικὰ εἶναι δοκεῖ τὰ πλεῖστα τῶν Πυλιακῶν ἐν καταλόγῳ φραζομένων χωρίων· οὐ μέντοι φασὶν οἱ ἔμπειροι· τὸν γὰρ Ἐρύμανθον εἶναι τὸν ὁρίζοντα τὴν Ἀρκαδίαν τῶν εἰς Ἀλφειὸν ἐμπιπτόντων ποταμῶν, ἔξω δ’ ἐκείνου τὰ χωρία ἱδρῦσθαι ταῦτα.", "st": "8.3.32"}, {"sp": "N", "t": "Ἔφορος δέ φησιν Αἰτωλὸν ἐκπεσόντα ὑπὸ Σαλμωνέως τοῦ βασιλέως Ἐπειῶν τε καὶ Πισατῶν ἐκ τῆς Ἠλείας εἰς τὴν Αἰτωλίαν, ὀνομάσαι τε ἀφ’ αὑτοῦ τὴν χώραν καὶ συνοικίσαι τὰς αὐτόθι πόλεις· τούτου δ’ ἀπόγονον ὑπάρξαντα Ὄξυλον φίλον τοῖς περὶ Τήμενον Ἡρακλείδαις ἡγήσασθαί τε τὴν ὁδὸν κατιοῦσιν εἰς τὴν Πελοπόννησον καὶ μερίσαι τὴν πολεμίαν αὐτοῖς χώραν καὶ τἆλλα ὑποθέσθαι τὰ περὶ τὴν κατάκτησιν τῆς χώρας, ἀντὶ δὲ τούτων λαβεῖν χάριν τὴν εἰς τὴν Ἠλείαν κάθοδον, προγονικὴν οὖσαν, κατελθεῖν δὲ ἀθροίσαντα στρατιὰν ἐκ τῆς Αἰτωλίας ἐπὶ τοὺς κατέχοντας Ἐπειοὺς τὴν Ἦλιν· ἀπαντησάντων δὲ τῶν Ἐπειῶν μεθ’ ὅπλων, ἐπειδὴ ἀντίπαλοι ἦσαν αἱ δυνάμεις, εἰς μονομαχίαν προελθεῖν κατὰ ἔθος τι παλαιὸν τῶν Ἑλλήνων Πυραίχμην Αἰτωλὸν Δέγμενόν τ’ Ἐπειόν, τὸν μὲν Δέγμενον μετὰ τόξου ψιλόν, ὡς περιεσόμενον ῥᾳδίως ὁπλίτου διὰ τῆς ἑκηβολίας, τὸν δὲ μετὰ σφενδόνης καὶ πήρας λίθων, ἐπειδὴ κατέμαθε τὸν δόλον· τυχεῖν δὲ νεωστὶ ὑπὸ τῶν Αἰτωλῶν εὑρημένον τὸ τῆς σφενδόνης εἶδος· μακροβολωτέρας δ’ οὔσης τῆς σφενδόνης πεσεῖν τὸν Δέγμενον, καὶ κατασχεῖν τοὺς Αἰτωλοὺς τὴν γῆν ἐκβαλόντας τοὺς Ἐπειούς· παραλαβεῖν δὲ καὶ τὴν ἐπιμέλειαν τοῦ ἱεροῦ τοῦ Ὀλυμπίασιν, ἣν εἶχον οἱ Ἀχαιοί· διὰ δὲ τὴν τοῦ Ὀξύλου φιλίαν πρὸς τοὺς Ἡρακλείδας συνομολογηθῆναι ῥᾳδίως ἐκ πάντων μεθ’ ὅρκου τὴν Ἠλείαν ἱερὰν εἶναι τοῦ Διός, τὸν δ’ ἐπιόντα ἐπὶ τὴν χώραν ταύτην μεθ’ ὅπλων ἐναγῆ εἶναι, ὡς δ’ αὕτως ἐναγῆ καὶ τὸν μὴ ἐπαμύνοντα εἰς δύναμιν· ἐκ δὲ τούτου καὶ τοὺς κτίσαντας τὴν Ἠλείων πόλιν ὕστερον ἀτείχιστον ἐᾶσαι, καὶ τοὺς δι’ αὐτῆς τῆς χώρας ἰόντας στρατοπέδῳ τὰ ὅπλα παραδόντας ἀπολαμβάνειν μετὰ τὴν ἐκ τῶν ὅρων ἔκβασιν· Ἴφιτόν τε θεῖναι τὸν Ὀλυμπικὸν ἀγῶνα, ἱερῶν ὄντων τῶν Ἠλείων. ἐκ δὴ τῶν τοιούτων αὔξησιν λαβεῖν τοὺς ἀνθρώπους· τῶν γὰρ ἄλλων πολεμούντων ἀεὶ πρὸς ἀλλήλους, μόνοις ὑπάρξαι πολλὴν εἰρήνην, οὐκ αὐτοῖς μόνον ἀλλὰ καὶ τοῖς ξένοις, ὥστε καὶ εὐανδρῆσαι μάλιστα πάντων παρὰ τοῦτο. Φείδωνα δὲ τὸν Ἀργεῖον, δέκατον μὲν ὄντα ἀπὸ Τημένου, δυνάμει δ’ ὑπερβεβλημένον τοὺς κατ’ αὐτόν, ἀφ’ ἧς τήν τε λῆξιν ὅλην ἀνέλαβε τὴν Τημένου διεσπασμένην εἰς πλείω μέρη, καὶ μέτρα ἐξεῦρε τὰ Φειδώνια καλούμενα καὶ σταθμοὺς καὶ νόμισμα κεχαραγμένον τό τε ἄλλο καὶ τὸ ἀργυροῦν, πρὸς τούτοις ἐπιθέσθαι καὶ ταῖς ὑφ’ Ἡρακλέους αἱρεθείσαις πόλεσι, καὶ τοὺς ἀγῶνας ἀξιοῦν τιθέναι αὐτόν, οὓς ἐκεῖνος ἔθηκε· τούτων δὲ εἶναι καὶ τὸν Ὀλυμπικόν· καὶ δὴ βιασάμενον ἐπελθόντα θεῖναι αὐτόν, οὔτε τῶν Ἠλείων ἐχόντων ὅπλα ὥστε κωλύειν διὰ τὴν εἰρήνην τῶν τε ἄλλων κρατουμένων τῇ δυναστείᾳ· οὐ μὴν τούς γε Ἠλείους ἀναγράψαι τὴν θέσιν ταύτην, ἀλλὰ καὶ ὅπλα κτήσασθαι διὰ τοῦτο καὶ ἀρξαμένους ἐπικουρεῖν σφίσιν αὐτοῖς· συμπράττειν δὲ καὶ Λακεδαιμονίους, εἴτε φθονήσαντας τῇ διὰ τὴν εἰρήνην εὐτυχίᾳ εἴτε καὶ συνεργοὺς ἕξειν νομίσαντας πρὸς τὸ καταλῦσαι τὸν Φείδωνα, ἀφῃρημένον αὐτοὺς τὴν ἡγεμονίαν τῶν Πελοποννησίων, [ἣν ἐκεῖ]νοι προεκέκτηντο· καὶ δὴ καὶ συγκαταλῦσαι τὸν Φείδωνα· τοὺς δὲ συγκατασκευάσαι τοῖς Ἠλείοις τήν τε Πισᾶτιν καὶ τὴν Τριφυλίαν. ὁ δὲ παράπλους ἅπας ὁ τῆς νῦν Ἠλείας μὴ κατακολπίζοντι χιλίων ὁμοῦ καὶ διακοσίων ἐστὶ σταδίων. ταῦτα μὲν περὶ τῆς Ἠλείας.", "st": "8.3.33"}, {"sp": "N", "t": "ἡ δὲ Μεσσηνία συνεχής ἐστι τῇ Ἠλείᾳ, περινεύουσα τὸ πλέον ἐπὶ τὸν νότον καὶ τὸ Λιβυκὸν πέλαγος. αὕτη δ’ ἐπὶ μὲν τῶν Τρωικῶν ὑπὸ Μενελάῳ ἐτέτακτο, μέρος οὖσα τῆς Λακωνικῆς, ἐκαλεῖτο δ’ ἡ χώρα Μεσσήνη· τὴν δὲ νῦν ὀνομαζομένην πόλιν Μεσσήνην, ἧς ἀκρόπολις ἡ Ἰθώμη ὑπῆρξεν, οὔπω συνέβαινεν ἐκτίσθαι· μετὰ δὲ τὴν Μενελάου τελευτήν, ἐξασθενησάντων τῶν διαδεξαμένων τὴν Λακωνικήν, οἱ Νηλεῖδαι τῆς Μεσσηνίας ἐπῆρχον. καὶ δὴ κατὰ τὴν τῶν Ἡρακλειδῶν κάθοδον καὶ τὸν τότε γενηθέντα μερισμὸν τῆς χώρας ἦν Μέλανθος βασιλεὺς τῶν Μεσσηνίων καθ’ αὑτοὺς ταττομένων, πρότερον δ’ ὑπήκοοι ἦσαν τοῦ Μενελάου. σημεῖον δέ· ἐκ γὰρ τοῦ Μεσσηνιακοῦ κόλπου καὶ τοῦ συνεχοῦς Ἀσιναίου λεγομένου ἀπὸ τῆς Μεσσηνιακῆς Ἀσίνης αἱ ἑπτὰ ἦσαν πόλεις, ἃς ὑπέσχετο δώσειν ὁ Ἀγαμέμνων τῷ Ἀχιλλεῖ<br>Καρδαμύλην Ἐνόπην τε καὶ Ἱρὴν ποιήεσσαν<br>Φηράς τε ζαθέας ἠδ’ Ἄνθειαν βαθύλειμον<br>καλήν τ’ Αἴπειαν καὶ Πήδασον ἀμπελόεσσαν,<br>οὐκ ἂν τάς γε μὴ προσηκούσας μήτ’ αὐτῷ μήτε τῷ ἀδελφῷ ὑποσχόμενος. ἐκ δὲ τῶν Φηρῶν καὶ συστρατεύσαντας τῷ Μενελάῳ δηλοῖ ὁ ποιητής, τὸν δὲ [Οἴτυλον] καὶ συγκαταλέγει τῷ Λακωνικῷ καταλόγῳ, ἱδ[ρυμένον] ἐν τῷ Μεσσηνιακῷ κόλπῳ. ἔστι δ’ ἡ Μεσσήνη μετὰ Τριφυλίαν· κοινὴ δ’ ἐστὶν ἀμφοῖν ἄκρα, μεθ’ ἣν τὸ Κορυφάσιον· ὑπέρκειται δ’ ὄρος ἐν ἑπτὰ σταδίοις τὸ Αἰγαλέον τούτου τε καὶ τῆς θαλάττης.", "st": "8.4.1"}, {"sp": "N", "t": "ἡ μὲν οὖν παλαιὰ Πύλος ἡ Μεσσηνιακὴ ὑπὸ τῷ Αἰγαλέῳ πόλις ἦν, κατεσπασμένης δὲ ταύτης ἐπὶ τῷ Κορυφασίῳ τινὲς αὐτῶν ᾤκησαν· προσέκτισαν δ’ αὐτὴν Ἀθηναῖοι τὸ δεύτερον ἐπὶ Σικελίαν πλέοντες μετ’ Εὐρυμέδοντος ἐπὶ Στρατοκλέους, ἐπιτείχισμα τοῖς Λακεδαιμονίοις. αὐτοῦ δ’ ἐστὶ καὶ ἡ Κυπαρισσία ἡ Μεσσηνιακὴ καὶ ἡ … καὶ ἡ προκειμένη πλησίον τοῦ Πύλου Σφαγία νῆσος, ἡ δ’ αὐτὴ καὶ Σφακτηρία λεγομένη, περὶ ἣν ἀπέβαλον ζωγρίᾳ Λακεδαιμόνιοι τριακοσίους ἐξ ἑαυτῶν ἄνδρας ὑπ’ Ἀθηναίων ἐκπολιορκηθέντας. κατὰ δὲ τὴν παραλίαν ταύτην τῶν Κυπαρισσιέων πελάγιαι πρόκεινται δύο νῆσοι προσαγορευόμεναι Στροφάδες, τετρακοσίους ἀπέχουσαι μάλιστά πως τῆς ἠπείρου σταδίους ἐν τῷ Λιβυκῷ καὶ μεσημβρινῷ πελάγει. φησὶ δὲ Θουκυδίδης ναύσταθμον ὑπάρξαι τῶν Μεσσηνίων ταύτην τὴν Πύλον· διέχει δὲ Σπάρτης τετρακοσίους.", "st": "8.4.2"}, {"sp": "N", "t": "ἑξῆς δ’ ἐστὶ Μεθώνη· ταύτην δ’ εἶναί φασι τὴν ὑπὸ τοῦ ποιητοῦ Πήδασον προσαγορευομένην, μίαν τῶν ἑπτὰ ὧν ὑπέσχετο τῷ Ἀχιλλεῖ ὁ Ἀγαμέμνων· ἐνταῦθα Ἀγρίππας τὸν τῶν Μαυρουσίων βασιλέα τῆς Ἀντωνίου στάσεως ὄντα Βόγον κατὰ τὸν πόλεμον τὸν Ἀκτιακὸν διέφθειρε, λαβὼν ἐξ ἐπίπλου τὸ χωρίον.", "st": "8.4.3"}, {"sp": "N", "t": "τῇ δὲ Μεθώνῃ συνεχής ἐστιν ὁ Ἀκρίτας, ἀρχὴ τοῦ Μεσσηνιακοῦ κόλπου· καλοῦσι δ’ αὐτὸν καὶ Ἀσιναῖον ἀπὸ Ἀσίνης, πολίχνης πρώτης ἐν τῷ κόλπῳ, ὁμωνύμου τῇ Ἑρμιονικῇ. αὕτη μὲν οὖν ἡ ἀρχὴ πρὸς δύσιν τοῦ κόλπου ἐστί, πρὸς ἕω δὲ αἱ καλούμεναι Θυρίδες, ὅμοροι τῇ νῦν Λακωνικῇ τῇ κατὰ Κιναίθιον καὶ Ταίναρον. μεταξὺ δὲ ἀπὸ τῶν Θυρίδων ἀρξαμένοις Οἴτυλός ἐστι· καλεῖται δ’ ὑπό τινων Βοίτυλος· εἶτα Λεῦκτρον τῶν ἐν τῇ Βοιωτίᾳ Λεύκτρων ἄποικος, εἶτ’ ἐπὶ πέτρας ἐρυμνῆς ἵδρυται Καρδαμύλη, εἶτα Φηραὶ ὅμορος Θουρίᾳ καὶ Γερήνοις, ἀφ’ οὗ τόπου Γερήνιον τὸν Νέστορα κληθῆναί φασι διὰ τὸ ἐνταῦθα σωθῆναι αὐτόν, ὡς προειρήκαμεν. δείκνυται δ’ ἐν τῇ Γερηνίᾳ Τρικκαίου ἱερὸν Ἀσκληπιοῦ, ἀφίδρυμα τοῦ ἐν τῇ Θετταλικῇ Τρίκκῃ. οἰκίσαι δὲ λέγεται Πέλοψ τό τε Λεῦκτρον καὶ Χαράδραν καὶ Θαλάμας, τοὺς νῦν Βοιωτοὺς καλουμένους, τὴν ἀδελφὴν Νιόβην ἐκδοὺς Ἀμφίονι καὶ ἐκ τῆς Βοιωτίας ἀγαγόμενός τινας. παρὰ δὲ Φηρὰς Νέδων ἐκβάλλει ῥέων διὰ τῆς Λακωνικῆς, ἕτερος ὢν τῆς Νέδας· ἔχει δ’ ἱερὸν ἐπίσημον Ἀθηνᾶς Νεδουσίας. καὶ ἐν Ποιαέσσῃ δ’ ἐστὶν Ἀθηνᾶς Νεδουσίας ἱερόν, ἐπώνυμον τόπου τινὸς Νέδοντος, ἐξ οὗ φασιν οἰκίσαι Τήλεκλον Ποιάεσσαν καὶ Ἐχειὰς καὶ Τράγιον.", "st": "8.4.4"}, {"sp": "N", "t": "τῶν δὲ προταθεισῶν ἑπτὰ πόλεων τῷ Ἀχιλλεῖ περὶ μὲν Καρδαμύλης καὶ Φηρῶν εἰρήκαμεν καὶ Πηδάσου. Ἐνόπην δὲ οἱ μὲν τὰ Πέλλανά φασιν, οἱ δὲ τόπον τινὰ περὶ Καρδαμύλην, οἱ δὲ τὴν Γερηνίαν· τὴν δὲ Ἱρὴν κατὰ τὸ ὄρος δεικνύουσι τὸ κατὰ τὴν Μεγαλόπολιν τῆς Ἀρκαδίας ὡς ἐπὶ τὴν Ἀνδανίαν ἰόντων, ἣν ἔφαμεν Οἰχαλίαν ὑπὸ τοῦ ποιητοῦ κεκλῆσθαι· οἱ δὲ τὴν νῦν Μεσόλαν οὕτω καλεῖσθαί φασι καθήκουσαν εἰς τὸν μεταξὺ κόλπον τοῦ Ταϋγέτου καὶ τῆς Μεσσηνίας. ἡ δ’ Αἴπεια νῦν Θουρία καλεῖται, ἣν ἔφαμεν ὅμορον Φαραῖς· ἵδρυται δ’ ἐπὶ λόφου ὑψηλοῦ, ἀφ’ οὗ καὶ τοὔνομα. ἀπὸ δὲ τῆς Θουρίας καὶ ὁ Θουριάτης κόλπος, ἐν ᾧ πόλισμα ἦν Ῥίον τοὔνομα ἀπεναντίον Ταινάρου. Ἄνθειαν δὲ οἱ μὲν αὐτὴν τὴν Θουρίαν φασίν, Αἴπειαν δὲ τὴν Μεθώνην, οἱ δὲ τὴν μεταξὺ Ἀσίνην τῶν Μεσσηνίων πόλεων οἰκειότατα βαθύλειμον λεχθεῖσαν, ἧς πρὸς θαλάττῃ πόλις Κορώνη καὶ ταύτην δέ τινες Πήδασον λεχθῆναί φασιν ὑπὸ τοῦ ποιητοῦ.<br>πᾶσαι δ’ ἐγγὺς ἁλός,<br>Καρδαμύλη μὲν ἐπ’ αὐτῇ, Φαραὶ δ’ ἀπὸ πέντε σταδίων, ὕφορμον ἔχουσα θερινόν, αἱ δ’ ἄλλαι ἀνωμάλοις κέχρηνται τοῖς ἀπὸ θαλάττης διαστήμασι.", "st": "8.4.5"}, {"sp": "N", "t": "πλησίον δὲ τῆς Κορώνης κατὰ μέσον πως τὸν κόλπον ὁ Παμισὸς ποταμὸς ἐκβάλλει, ταύτην μὲν ἐν δεξιᾷ ἔχων καὶ τὰς ἑξῆς· ὧν εἰσιν ἔσχαται πρὸς δύσιν Πύλος καὶ Κυπαρισσία, μέση δὲ τούτων Ἔρανα, ἣν οὐκ εὖ τινες Ἀρήνην … νενομίκασι πρότερον· Θουρίαν δὲ καὶ Φαρὰς ἐν ἀ[ριστερᾷ]. μέγιστος δ’ ἐστὶ ποταμῶν τῶν ἐντὸς Ἰσθμοῦ καίπερ οὐ πλείους ἢ ἑκατὸν σταδίους ἐκ τῶν πηγῶν ῥυεὶς δαψιλὴς τῷ ὕδατι διὰ τοῦ Μεσσηνιακοῦ πεδίου καὶ τῆς Μακαρίας καλουμένης· ἀφέστηκέ τε τῆς νῦν Μεσσηνίων πόλεως ὁ ποταμὸς σταδίους πεντήκοντα. ἔστι δὲ καὶ ἄλλος Παμισὸς χαραδρώδης μικρὸς περὶ Λεῦκτρον ῥέων τὸ Λακωνικόν, περὶ οὗ κρίσιν ἔσχον Μεσσήνιοι πρὸς Λακεδαιμονίους ἐπὶ Φιλίππου· τὸν δὲ Παμισόν, ὃν Ἄμαθόν τινες ὠνόμασαν, προειρήκαμεν.", "st": "8.4.6"}, {"sp": "N", "t": "Ἔφορος δὲ τὸν Κρεσφόντην, ἐπειδὴ εἷλε Μεσσήνην, διελεῖν φησιν εἰς πέντε πόλεις αὐτήν, ὥστε Στενύκλαρον μὲν ἐν τῷ μέσῳ τῆς χ[ώρας ταύτης] κειμένην ἀποδεῖξαι βασίλειον αὑτῷ, [εἰς δὲ τὰς ἄλλας] βασιλέας πέμψαι, Πύλον καὶ Ῥίον κ[αὶ Μεσόλαν καὶ] Ὑαμεῖτιν, ποιήσαντα ἰσονόμους πάντας τοῖς Δωριεῦσι τοὺς Μεσσηνίους· ἀγανακτούντων δὲ τῶν Δωριέων μεταγνόντα μόνον τὸν Στενύκλαρον νομίσαι πόλιν, εἰς τοῦτον δὲ καὶ τοὺς Δωριέας συναγαγεῖν πάντας.", "st": "8.4.7"}, {"sp": "N", "t": "ἡ δὲ Μεσσηνίων πόλις ἔοικε Κορίνθῳ· ὑπέρκειται γὰρ τῆς πόλεως ἑκατέρας ὄρος ὑψηλὸν καὶ ἀπότομον τείχει κοινῷ περιειλημμένον ὥστ’ ἀκροπόλει χρῆσθαι, τὸ μὲν καλούμενον Ἰθώμη τὸ δὲ Ἀκροκόρινθος· ὥστ’ οἰκείως δοκεῖ Δημήτριος ὁ Φάριος πρὸς Φίλιππον εἰπεῖν τὸν Δημητρίου, παρακελευόμενος τούτων ἔχεσθαι τῶν πόλεων ἀμφοῖν ἐπιθυμοῦντα τῆς Πελοποννήσου· “τῶν κεράτων γὰρ ἀμφοῖν” ἔφη “καθέξεις τὴν βοῦν.” κέρατα μὲν λέγων τὴν Ἰθώμην καὶ τὸν Ἀκροκόρινθον, βοῦν δὲ τὴν Πελοπόννησον. καὶ δὴ διὰ τὴν εὐκαιρίαν ταύτην ἀμφήριστοι γεγόνασιν αἱ πόλεις αὗται. Κόρινθον μὲν οὖν κατέσκαψαν [Ῥωμαῖοι] καὶ ἀνέστησαν πάλιν· Μεσσήνην δὲ ἀνεῖλον μὲν Λακεδαιμόνιοι, πάλιν δ’ ἀνέλαβον Θηβαῖοι καὶ μετὰ ταῦτα Φίλιππος Ἀμύντου· αἱ δ’ ἀκροπόλεις ἀοίκητοι διέμειναν.", "st": "8.4.8"}, {"sp": "N", "t": "τὸ δ’ ἐν Λίμναις τῆς Ἀρτέμιδος ἱερόν, ἐφ’ ᾧ Μεσσήνιοι περὶ τὰς παρθένους ὑβρίσαι δοκοῦσι τὰς ἀφιγμένας ἐπὶ τὴν θυσίαν, ἐν μεθορίοις ἐστὶ τῆς τε Λακωνικῆς καὶ τῆς Μεσσηνίας, ὅπου κοινὴν συνετέλουν πανήγυριν καὶ θυσίαν ἀμφότεροι· μετὰ δὲ τὴν ὕβριν οὐ διδόντων δίκας τῶν Μεσσηνίων συστῆναί φασι τὸν πόλεμον. ἀπὸ δὲ τῶν Λιμνῶν τούτων καὶ τὸ ἐν τῇ Σπάρτῃ Λιμναῖον εἴρηται τῆς Ἀρτέμιδος ἱερόν.", "st": "8.4.9"}, {"sp": "N", "t": "πλεονάκις δ’ ἐπολέμησαν διὰ τὰς ἀποστάσεις τῶν Μεσσηνίων. τὴν μὲν οὖν πρώτην κατάκτησιν αὐτῶν φησι Τυρταῖος ἐν τοῖς ποιήμασι κατὰ τοὺς τῶν πατέρων πατέρας γενέσθαι· τὴν δὲ δευτέραν, καθ’ ἣν ἑλόμενοι συμμάχους Ἀργείους τε καὶ Ἀρκάδας καὶ Πισάτας ἀπέστησαν, Ἀρκάδων μὲν Ἀριστοκράτην τὸν Ὀρχομενοῦ βασιλέα παρεχομένων στρατηγόν, Πισατῶν δὲ Πανταλέοντα τὸν Ὀμφαλίωνος· ἡνίκα φησὶν αὐτὸς στρατηγῆσαι τὸν πόλεμον τοῖς Λακεδαιμονίοις [ἐλθὼν ἐξ Ἐρινεοῦ]· καὶ γὰρ εἶναί φησιν ἐκεῖθεν ἐν τῇ ἐλεγείᾳ ἣν ἐπιγράφουσιν εὐνομίαν<br>αὐτὸς γὰρ Κρονίων, καλλιστεφάνου πόσις Ἥρης,<br>Ζεὺς Ἡρακλείδαις τήνδε δέδωκε πόλιν·<br>οἷσιν ἅμα προλιπόντες Ἐρινεὸν ἠνεμόεντα,<br>εὐρεῖαν Πέλοπος νῆσον ἀφικόμεθα.<br>ὥστ’ ἢ ταῦτα ἠκύρωται τὰ ἐλεγεῖα, ἢ Φιλοχόρῳ ἀπιστητέον τῷ φήσαντι Ἀθηναῖόν τε καὶ Ἀφιδναῖον, καὶ Καλλισθένει καὶ ἄλλοις πλείοσι τοῖς εἰποῦσιν ἐξ Ἀθηνῶν ἀφικέσθαι δεηθέντων Λακεδαιμονίων κατὰ χρησμόν, ὃς ἐπέταττε παρ’ Ἀθηναίων λαβεῖν ἡγεμόνα. ἐπὶ μὲν οὖν τοῦ Τυρταίου ὁ δεύτερος ὑπῆρξε πόλεμος· τρίτον δὲ καὶ τέταρτον συστῆναί φασιν, ἐν ᾧ κατελύθησαν οἱ Μεσσήνιοι. ὁ δὲ πᾶς παράπλους ὁ Μεσσηνιακὸς στάδιοι ὀκτακόσιοί που κατακολπίζοντι.", "st": "8.4.10"}, {"sp": "N", "t": "ἀλλὰ γὰρ εἰς πλείω λόγον τοῦ μετρίου πρόιμεν ἀκολουθοῦντες τῷ πλήθει τῶν ἱστορουμένων περὶ χώρας ἐκλελειμμένης τῆς πλείστης· ὅπου γε καὶ ἡ Λακωνικὴ λιπανδρεῖ κρινομένη πρὸς τὴν παλαιὰν εὐανδρίαν. ἔξω γὰρ τῆς Σπάρτης αἱ λοιπαὶ πολίχναι τινές εἰσι περὶ τριάκοντα τὸν ἀριθμόν· τὸ δὲ παλαιὸν ἑκατόμπολίν φασιν αὐτὴν καλεῖσθαι, καὶ τὰ ἑκατόμβαια διὰ τοῦτο θύεσθαι παρ’ αὐτοῖς κατ’ ἔτος.", "st": "8.4.11"}, {"sp": "N", "t": "ἔστι δ’ οὖν μετὰ τὸν Μεσσηνιακὸν κόλπον ὁ Λακωνικὸς μεταξὺ Ταινάρου καὶ Μαλεῶν, ἐκκλίνων μικρὸν ἀπὸ μεσημβρίας πρὸς ἕω· διέχουσι δὲ σταδίους ἑκατὸν τριάκοντα αἱ Θυρίδες τοῦ Ταινάρου ἐν τῷ Μεσσηνιακῷ οὖσαι κόλπῳ, ῥοώδης κρημνός. τούτων δ’ ὑπέρκειται τὸ Ταΰγετον· ἔστι δ’ ὄρος μικρὸν ὑπὲρ τῆς θαλάττης ὑψηλόν τε καὶ ὄρθιον, συνάπτον κατὰ τὰ προσάρκτια μέρη ταῖς Ἀρκαδικαῖς ὑπωρείαις, ὥστε καταλείπεσθαι μεταξὺ αὐλῶνα, καθ’ ὃν ἡ Μεσσηνία συνεχής ἐστι τῇ Λακωνικῇ. ὑποπέπτωκε δὲ τῷ Ταϋγέτῳ ἡ Σπάρτη ἐν μεσογαίᾳ καὶ Ἀμύκλαι, οὗ τὸ τοῦ Ἀπόλλωνος ἱερόν, καὶ ἡ Φᾶρις. ἔστι μὲν οὖν ἐν κοιλοτέρῳ χωρίῳ τὸ τῆς πόλεως ἔδαφος καίπερ ἀπολαμβάνον ὄρη μεταξύ· ἀλλ’ οὐδέν γε μέρος αὐτοῦ λιμνάζει, τὸ δὲ παλαιὸν ἐλίμναζε τὸ προάστειον, καὶ ἐκάλουν αὐτὸ Λίμνας· καὶ τὸ τοῦ Διονύσου ἱερὸν ἐν Λίμναις ἐφ’ ὑγροῦ βεβηκὸς ἐτύγχανε, νῦν δ’ ἐπὶ ξηροῦ τὴν ἵδρυσιν ἔχει. ἐν δὲ τῷ κόλπῳ τῆς παραλίας τὸ μὲν Ταίναρον ἀκτή ἐστιν ἐκκειμένη τὸ ἱερὸν ἔχουσα τοῦ Ποσειδῶνος ἐν ἄλσει ἱδρυμένον· πλησίον δ’ ἐστὶν ἄντρον, δι’ οὗ τὸν Κέρβερον ἀναχθῆναι μυθεύουσιν ὑφ’ Ἡρακλέους ἐξ ᾄδου. ἐντεῦθεν δ’ εἰς μὲν Φυκοῦντα ἄκραν τῆς Κυρηναίας πρὸς νότον δίαρμά ἐστι σταδίων τρισχιλίων· εἰς δὲ Πάχυνον πρὸς δύσιν, τὸ τῆς Σικελίας ἀκρωτήριον, τετρακισχιλίων ἑξακοσίων, τινὲς δὲ τετρακισχιλίων φασίν· εἰς δὲ Μαλέας πρὸς ἕω ἑξακοσίων ἑβδομήκοντα κατακολπίζοντι· εἰς δὲ Ὄνου γνάθον, ταπεινὴν χερρόνησον ἐνδοτέρω τῶν Μαλεῶν, πεντακοσίων εἴκοσι (πρόκειται δὲ κατὰ τούτου Κύθηρα ἐν τετταράκοντα σταδίοις, νῆσος εὐλίμενος, πόλιν ἔχουσα ὁμώνυμον, ἣν ἔσχεν Εὐρυκλῆς ἐν μέρει κτήσεως ἰδίας ὁ καθ’ ἡμᾶς τῶν Λακεδαιμονίων ἡγεμών· περίκειται δὲ νησίδια πλείω τὰ μὲν ἐγγὺς τὰ δὲ καὶ μικρὸν ἀπωτέρω)· εἰς δὲ Κώρυκον ἄκραν τῆς Κρήτης ἐγγυτάτω πλοῦς ἐστι σταδίων ἑπτακοσίων πεντήκοντα.", "st": "8.5.1"}, {"sp": "N", "t": "μετὰ δὲ Ταίναρον πλέοντι ἐπὶ τὴν Ὄνου γνάθον καὶ Μαλέας Ψαμαθοῦς ἐστι πόλις· εἶτ’ Ἀσίνη καὶ Γύθειον τὸ τῆς Σπάρτης ἐπίνειον ἐν διακοσίοις καὶ τετταράκοντα σταδίοις ἱδρυμένον· ἔχει δ’, ὥς φασι, τὸ ναύσταθμον ὀρυκτόν· εἶθ’ ὁ Εὐρώτας ἐκδίδωσι μεταξὺ Γυθείου καὶ Ἀκραίων. τέως μὲν οὖν ὁ πλοῦς ἐστι παρ’ αἰγιαλὸν ὅσον διακοσίων καὶ τετταράκοντα σταδίων· εἶθ’ ἑλῶδες ὑπέρκειται χωρίον καὶ κώμη Ἕλος· πρότερον δ’ ἦν πόλις, καθάπερ καὶ Ὅμηρός φησιν<br>οἵ τ’ ἄρ’ Ἀμύκλας εἶχον Ἕλος τ’ ἔφαλον πτολίεθρον<br>κτίσμα δ’ Ἑλίου φασὶ τοῦ Περσέως. ἔστι δὲ καὶ πεδίον καλούμενον Λεύκη· εἶτα πόλις ἐπὶ χερρονήσου ἱδρυμένη Κυπαρισσία λιμένα ἔχουσα· εἶτα ἡ Ὄνου γνάθος λιμένα ἔχουσα· εἶτα Βοία πόλις, εἶτα Μαλέαι· στάδιοι δ’ εἰς αὐτὰς ἀπὸ τῆς Ὄνου γνάθου πεντήκοντα καὶ ἑκατόν· ἔστι δὲ καὶ Ἀσωπὸς πόλις ἐν τῇ Λακωνικῇ.", "st": "8.5.2"}, {"sp": "N", "t": "τῶν δ’ ὑφ’ Ὁμήρου καταλεγομένων τὴν μὲν Μέσσην οὐδαμοῦ δείκνυσθαί φασι· Μεσσόαν δ’ οὐ τῆς χώρας εἶναι μέρος [ἀλλὰ] τῆς Σπάρτης, καθάπερ καὶ τὸ Λιμναῖον, κατὰ τὸν … κα. ἔνιοι δὲ κατὰ ἀποκοπὴν δέχονται τὴν Μεσσήνην· εἴρηται γὰρ ὅτι καὶ αὕτη μέρος ἦν τῆς Λακωνικῆς. παραδείγμασι δὲ χρῶνται τοῦ μὲν ποιητοῦ τῷ κρῖ καὶ δῶ καὶ μάψ, καὶ ἔτι<br>ἥρως δ’ Αὐτομέδων τε καὶ Ἄλκιμος,<br>ἀντὶ τοῦ Ἀλκιμέδων· Ἡσιόδου δέ, ὅτι τὸ βριθὺ καὶ βριαρὸν βρῖ λέγει· Σοφοκλῆς δὲ καὶ Ἴων τὸ ῥᾴδιον ῥᾴ· Ἐπίχαρμος δὲ τὸ λίαν λῖ, Συρακὼ δὲ τὰς Συρακούσσας· παρ’ Ἐμπεδοκλεῖ δέ<br>μία γίνεται ἀμφοτέρων ὄψ<br>ἡ ὄψις· καὶ παρ’ Ἀντιμάχῳ<br>Δήμητρός τοι Ἐλευσινίης· ἱερὴ ὄψ.<br>καὶ τὸ ἄλφιτον ἄλφι· Εὐφορίων δὲ καὶ τὸν ἧλον λέγει ἧλ· παρὰ Φιλήτᾳ δέ<br>δμωίδες εἰς ταλάρους λευκὸν ἄγουσιν ἔρι<br>εἰς ἄνεμον δὲ τὰ πηδά<br>τὰ πηδάλια Ἄρατός φησι, Δωδὼ δὲ τὴν Δωδώνην Σιμμίας. τῶν δ’ ἄλλων τῶν ὑπὸ τοῦ ποιητοῦ κατωνομασμένων τὰ μὲν ἀνῄρηται, τῶν δ’ ἴχνη λείπεται, τὰ δὲ μετωνόμασται, καθάπερ αἱ Αὐγειαὶ Αἰγαιαί· [αἱ] γὰρ ἐν τῇ Λοκρίδι οὐδ’ ὅλως περίεισι. τὴν δὲ Λᾶν οἱ Διόσκουροί ποτε ἐκ πολιορκίας ἑλεῖν ἱστοροῦνται, ἀφ’ οὗ δὴ Λαπέρσαι προσηγορεύθησαν.", "st": "8.5.3"}, {"sp": "N", "t": "φησὶ δ’ Ἔφορος τοὺς κατασχόντας τὴν Λακωνικὴν Ἡρακλείδας Εὐρυσθένη τε καὶ Προκλῆ διελεῖν εἰς ἓξ μέρη καὶ πολίσαι τὴν χώραν· μίαν μὲν οὖν τῶν μερίδων, τὰς Ἀμύκλας, ἐξαίρετον δοῦναι τῷ προδόντι αὐτοῖς τὴν Λακωνικὴν καὶ πείσαντι τὸν κατέχοντα αὐτὴν ἀπελθεῖν ὑπόσπονδον μετὰ τῶν Ἀχαιῶν εἰς τὴν Ἰωνίαν· τὴν δὲ Σπάρτην βασίλειον ἀποφῆναι σφίσιν αὐτοῖς· εἰς δὲ τὰς ἄλλας πέμψαι βασιλέας, ἐπιτρέψαντας δέχεσθαι συνοίκους τοὺς βουλομένους τῶν ξένων διὰ τὴν λιπανδρίαν· χρῆσθαι δὲ Λαῒ μὲν να[υστάθμῳ διὰ τὸ εὐ]λίμενον, Αἴγυι δὲ πρὸς τοὺς πολέ[μους ὁρμητηρίῳ· καὶ] γὰρ ὁμορεῖν τοῖς κύκλῳ, Φάριδι δ[ὲ ἀρχείῳ, πλείστην] ἀπὸ τῶν ἐντὸς ἀσφάλειαν ἐχούσῃ, τ … ὑπακούοντας δ’ ἅπαντας τοὺς περιοίκους Σπαρτιατῶν ὅμως ἰσονόμους εἶναι, μετέχοντας καὶ πολιτείας καὶ ἀρχείων· Ἆγιν δὲ τὸν Εὐρυσθένους ἀφελέσθαι τὴν ἰσοτιμίαν καὶ συντελεῖν προστάξαι τῇ Σπάρτῃ. τοὺς μὲν οὖν ἄλλους ὑπακοῦσαι, τοὺς δ’ Ἑλείους τοὺς ἔχοντας τὸ Ἕλος (καλεῖσθαι δὲ Εἵλωτας) ποιησαμένους ἀπόστασιν κατὰ κράτος ἁλῶναι πολέμῳ καὶ κριθῆναι δούλους ἐπὶ τακτοῖς τισιν, ὥστε τὸν ἔχοντα μήτ’ ἐλευθεροῦν ἐξεῖναι μήτε πωλεῖν ἔξω τῶν ὅρων τούτους· τοῦτον δὲ λεχθῆναι τὸν πρὸς τοὺς Εἵλωτας πόλεμον. σχεδὸν δέ τι καὶ τὴν εἱλωτείαν τὴν ὕστερον συμμείνασαν μέχρι τῆς Ῥωμαίων ἐπικρατείας οἱ περὶ Ἆγιν εἰσὶν οἱ καταδείξαντες· τρόπον γάρ τινα δημοσίους δούλους εἶχον οἱ Λακεδαιμόνιοι τούτους, κατοικίας τινὰς αὐτοῖς ἀποδείξαντες καὶ λειτουργίας ἰδίας.", "st": "8.5.4"}, {"sp": "N", "t": "περὶ δὲ τῆς Λακώνων πολιτείας καὶ τῶν γενομένων παρ’ αὐτοῖς μεταβολῶν τὰ μὲν πολλὰ παρείη τις ἂν διὰ τὸ γνώριμον, τινῶν δ’ ἄξιον ἴσως μνησθῆναι. Ἀχαιοὺς γὰρ τοὺς Φθιώτας φασὶ συγκατελθόντας Πέλοπι εἰς τὴν Πελοπόννησον οἰκῆσαι τὴν Λακωνικήν, τοσοῦτον δ’ ἀρετῇ διενεγκεῖν ὥστε τὴν Πελοπόννησον, ἐκ πολλῶν ἤδη χρόνων Ἄργος λεγομένην, τότε Ἀχαϊκὸν Ἄργος λεχθῆναι, καὶ οὐ μόνον γε τὴν Πελοπόννησον ἀλλὰ καὶ ἰδίως τὴν Λακωνικὴν οὕτω προσαγορευθῆναι· τὸ γοῦν τοῦ ποιητοῦ<br>ποῦ Μενέλαος ἔην;<br>ἢ οὐκ Ἄργεος ἦεν Ἀχαιικοῦ;<br>δέχονταί τινες οὕτως “ἢ οὐκ ἦν ἐν τῇ Λακωνικῇ;” κατὰ δὲ τὴν τῶν Ἡρακλειδῶν κάθοδον Φιλονόμου προδόντος τὴν χώραν τοῖς Δωριεῦσι μετανέστησαν ἐκ τῆς Λακωνικῆς εἰς τὴν τῶν Ἰώνων τὴν καὶ νῦν Ἀχαΐαν καλουμένην· ἐροῦμεν δὲ περὶ αὐτῶν ἐν τοῖς Ἀχαϊκοῖς. οἱ δὲ κατασχόντες τὴν Λακωνικὴν κατ’ ἀρχὰς μὲν ἐσωφρόνουν, ἐπεὶ δ’ οὖν Λυκούργῳ τὴν πολιτείαν ἐπέτρεψαν, τοσοῦτον ὑπερεβάλοντο τοὺς ἄλλους ὥστε μόνοι τῶν Ἑλλήνων καὶ γῆς καὶ θαλάττης ἐπῆρξαν, διετέλεσάν τε ἄρχοντες τῶν Ἑλλήνων ἕως ἀφείλοντο αὐτοὺς τὴν ἡγεμονίαν Θηβαῖοι καὶ μετ’ ἐκείνους εὐθὺς Μακεδόνες. οὐ μὴν τελέως γε οὐδὲ τούτοις εἶξαν, ἀλλὰ φυλάττοντες τὴν αὐτονομίαν ἔριν εἶχον περὶ πρωτείων ἀεὶ πρός τε τοὺς ἄλλους Ἕλληνας καὶ πρὸς τοὺς τῶν Μακεδόνων βασιλέας· καταλυθέντων δὲ τούτων ὑπὸ Ῥωμαίων, μικρὰ μέν τινα προσέκρουσαν τοῖς πεμπομένοις ὑπὸ Ῥωμαίων στρατηγοῖς τυραννούμενοι τότε καὶ πολιτευόμενοι μοχθηρῶς· ἀναλαβόντες δὲ σφᾶς ἐτιμήθησαν διαφερόντως καὶ ἔμειναν ἐλεύθεροι, πλὴν τῶν φιλικῶν λειτουργιῶν ἄλλο συντελοῦντες οὐδέν. νεωστὶ δ’ Εὐρυκλῆς αὐτοὺς ἐτάραξε δόξας ἀποχρήσασθαι τῇ Καίσαρος φιλίᾳ πέρα τοῦ μετρίου πρὸς τὴν ἐπιστασίαν αὐτῶν, ἐπαύσατο δ’ ἡ ἀρχὴ ταχέως, ἐκείνου μὲν παραχωρήσαντος εἰς τὸ χρεών, τοῦ δ’ υἱοῦ τὴν φιλίαν ἀπεστραμμένου τὴν τοιαύτην πᾶσαν· συνέβη δὲ καὶ τοὺς Ἐλευθερολάκωνας λαβεῖν τινα τάξιν πολιτείας, ἐπειδὴ Ῥωμαίοις προσέθεντο πρῶτοι οἱ περίοικοι τυραννουμένης τῆς Σπάρτης, οἵ τε ἄλλοι καὶ οἱ Εἵλωτες. Ἑλλάνικος μὲν οὖν Εὐρυσθένη καὶ Προκλέα φησὶ διατάξαι τὴν πολιτείαν, Ἔφορος δ’ ἐπιτιμᾷ φήσας Λυκούργου μὲν αὐτὸν μηδαμοῦ μεμνῆσθαι, τὰ δ’ ἐκείνου ἔργα τοῖς μὴ προσήκουσιν ἀνατιθέναι· μόνῳ γοῦν Λυκούργῳ ἱερὸν ἱδρῦσθαι καὶ θύεσθαι κατ’ ἔτος, ἐκείνοις δὲ καίπερ οἰκισταῖς γενομένοις μηδὲ τοῦτο δεδόσθαι ὥστε τοὺς ἀπ’ αὐτῶν τοὺς μὲν Εὐρυσθενίδας τοὺς δὲ Προκλείδας καλεῖσθαι, ἀ[λλὰ τοὺς μὲν] Ἀγίδας ἀπὸ Ἄγιδος τοῦ Εὐρυσθένους τοὺς δ’ [Εὐρυπωντίδας ἀ]πὸ Εὐρυπῶντος τοῦ Προκλέους· τοὺς μὲν [γὰρ δυναστεῦ]σαι δικαίως, τοὺς δὲ δεξαμένους ἐπ[ήλυδας ἀνθρώ]πους, δι’ ἐκείνων δυναστεῦσαι· ὅθε[ν οὐδ’ ἀρχηγέτας] νομισθῆναι ὅπερ πᾶσιν ἀποδέδοτα[ι οἰκισταῖς. Παυ]σανίαν τε τῶν Εὐρυπωντιδῶν ἐκπεσόν[τα … τῆς] οἰκείας ἐν τῇ φυγῇ συντάξαι λόγ[ον κατὰ τοῦ Λυκούρ]γου, νόμων ὄντος τῆς ἐκβαλούση[ς αὐτὸν αἰτίου, καὶ] τοὺς χρησμοὺς λέγειν τοὺς δοθέντα[ς αὐτῷ περὶ τῶν] πλείστων.", "st": "8.5.5"}, {"sp": "N", "t": "περὶ δὲ τῆς φύσεως τῶν τόπων καὶ τούτων καὶ τῶν Μεσσηνιακῶν ταῦτα μὲν ἀποδεκτέον λέγοντος Εὐριπίδου· τὴν γὰρ Λακωνικήν φησιν ἔχειν<br>πολὺν μὲν ἄροτον, ἐκπονεῖν δ’ οὐ ῥᾴδιον·<br>κοίλη γάρ, ὄρεσι περίδρομος, τραχεῖά τε<br>δυσείσβολός τε πολεμίοις,<br>τὴν δὲ Μεσσηνιακὴν<br>καλλίκαρπον<br>κατάρρυτόν τε μυρίοισι νάμασι,<br>καὶ βουσὶ καὶ ποίμναισιν εὐβοτωτάτην<br>οὔτ’ ἐν πνοαῖσι χείματος δυσχείμερον,<br>οὔτ’ αὖ τεθρίπποις ἡλίου θερμὴν ἄγαν.<br>καὶ ὑποβὰς τῶν πάλων φησὶν ὧν οἱ Ἡρακλεῖδαι περὶ τῆς χώρας ἐποιήσαντο, τὸν μὲν πρότερον γενέσθαι<br>γαίας Λακαίνης κύριον, φαύλου χθονός·<br>τὸν δὲ δεύτερον τῆς Μεσσήνης<br>ἀρετὴν ἐχούσης μείζον’ ἢ λόγῳ φράσαι.<br>οἵαν καὶ ὁ Τυρταῖος φράζει. τὴν δὲ Λακωνικὴν καὶ τὴν Μεσσηνίαν ὁρίζειν αὐτοῦ φήσαντος<br>Παμισὸν εἰς θάλασσαν ἐξορμώμενον,<br>οὐ συγχωρητέον, ὃς διὰ μέσης ῥεῖ τῆς Μεσσηνίας, οὐδαμοῦ τῆς νῦν Λακωνικῆς ἁπτόμενος. οὐκ εὖ δὲ οὐδ’ ὅτι τῆς Μεσσηνίας ὁμοίως ἐπιθαλαττιαίας οὔσης τῇ Λακωνικῇ φησὶν αὐτὴν πρόσω ναυτίλοισιν εἶναι. ἀλλ’ οὐδὲ τὴν Ἦλιν εὖ διορίζει<br>πρόσω δὲ βάντι ποταμὸν Ἦλις ἡ Διὸς<br>γείτων κάθηται.<br>εἴτε γὰρ τὴν νῦν Ἠλείαν βούλεται λέγειν, ἥτις [ὁμο]ρεῖ τῇ Μεσσηνίᾳ, ταύτης οὐ προσάπτεται ὁ Παμι[σός], ὥσπερ γε [οὐδὲ] τῆς Λακωνικῆς· εἴρηται γὰρ ὅτι διὰ μέ[σης ῥ]εῖ τῆς Μεσσηνίας· εἴτε τὴν παλαιὰν τὴν κοίλην [καλουμέ]νην, πολὺ μᾶλλον ἐκπίπτει τῆς ἀληθείας· διαβάν[τι γὰρ τ]ὸν Παμισὸν ἔστι πολλὴ τῆς Μεσσηνίας, εἶθ’ ἡ τῶν Λεπρεατῶν ἅπασα καὶ Μακιστίων, ἣν Τριφυλίαν ἐκάλουν, [εἶθ’ ἡ Πι]σᾶτις καὶ ἡ Ὀλυμπία, εἶτα μετὰ τριακοσί[ους σταδίους] ἡ Ἦλις.", "st": "8.5.6"}, {"sp": "N", "t": "γραφόντων δὲ τῶν μὲν “Λακεδαίμονα κητώεσσαν” τῶν δὲ “καιετάεσσαν,” ζητοῦσι τὴν κητώεσσαν τίνα δέχεσθαι χρή, εἴτε ἀπὸ τῶν κητῶν εἴτε μεγάλην, ὅπερ δοκεῖ πιθανώτερον εἶναι· τὴν δὲ καιετάεσσαν οἱ μὲν καλαμινθώδη δέχονται, οἱ δὲ ὅτι οἱ ἀπὸ τῶν σεισμῶν ῥωχμοὶ καιετοὶ λέγονται· καὶ ὁ καιέτας τὸ δεσμωτήριον ἐντεῦθεν τὸ παρὰ Λακεδαιμονίοις, σπήλαιόν τι· ἔνιοι δὲ κώους μᾶλλον τὰ τοιαῦτα κοιλώματα λέγεσθαί φασιν, ἀφ’ οὗ καὶ τὸ<br>φηρσὶν ὀρεσκῴοισιν.<br>εὔσειστος δ’ ἡ Λακωνική· καὶ δὴ τοῦ Ταϋγέτου κορυφάς τινας ἀπορραγῆναι τινὲς μνημονεύουσιν. εἰσὶ δὲ λατομίαι λίθου πολυτελοῦς τοῦ μὲν Ταιναρίου ἐν Ταινάρῳ παλαιαί, νεωστὶ δὲ καὶ ἐν τῷ Ταϋγέτῳ μέταλλον ἀνέῳξάν τινες εὐμέγεθες, χορηγὸν ἔχοντες τὴν τῶν Ῥωμαίων πολυτέλειαν.", "st": "8.5.7"}, {"sp": "N", "t": "ὅτι δὲ Λακεδαίμων ὁμωνύμως λέγεται καὶ ἡ χώρα καὶ ἡ πόλις, δηλοῖ καὶ Ὅμηρος· λέγω δὲ χώραν σὺν τῇ Μεσσηνίᾳ. περὶ μ[ὲν δὴ τῶν] τόξων ὅταν λέγῃ<br>καλά, τὰ οἱ ξεῖνος Λακεδαίμονι δῶκε τυχήσας,<br>Ἴφιτος Εὐρυτίδης,<br>εἶτ’ ἐπενέγκῃ<br>τὼ δ’ ἐν Μεσσήνῃ ξυμβλήτην ἀλλήλοιιν<br>οἴκῳ ἐν Ὀρτιλόχοιο,<br>τὴν χώραν λέγει, ἧς μέρος ἦν καὶ ἡ Μεσσηνία· οὐ διήνεγκεν οὖν αὐτῷ καὶ οὕτως εἰπεῖν<br>ξεῖνος Λακεδαίμονι δῶκε τυχήσας,<br>καὶ<br>τὼ δ’ ἐν Μεσσήνῃ ξυμβλήτην.<br>ὅτι γὰρ αἱ Φηραὶ εἰσὶν ὁ τοῦ Ὀρτιλόχου οἶκος δῆλον·<br>ἐς Φηρὰς δ’ ἵκοντο Διοκλῆος ποτὶ δῶμα,<br>υἱέος Ὀρτιλόχοιο,<br>ὅ τε Τηλέμαχος καὶ ὁ Πεισίστρατος· αἱ δὲ Φηραὶ τῆς Μεσσηνίας εἰσίν. ὅταν δ’ ἐκ τῶν Φηρῶν ὁρμηθέντας τοὺς περὶ Τηλέμαχον πανημερίους φῇ σείειν ζυγόν, εἶτ’ εἴπῃ<br>δύσετό τ’ ἠέλιος, …<br>οἱ δ’ ἷξον κοίλην Λακεδαίμονα κητώεσσαν·<br>πρὸς δ’ ἄρα δώματ’ ἔλων Μενελάου,<br>τὴν πόλιν δεῖ δέχεσθαι· εἰ δὲ μή, ἐκ Λακεδαίμονος εἰς Λακεδαίμονα φανεῖται λέγων τὴν ἄφιξιν· ἄλλως τε οὐ πιθανὸν μὴ ἐν Σπάρτῃ τὴν οἴκησιν εἶναι τοῦ Μενελάου, [οὐδὲ] μὴ οὔσης ἐκεῖ τὸν Τηλέμαχον λέγειν<br>εἶμι γὰρ ἐς Σπάρτην τε καὶ εἰς Πύλον.<br>δοκεῖ [δὲ συμ]πίπτειν τούτῳ τὸ τοῖς τῆς χώρας ἐπιθέτοις αὐ … εἰ μὴ νὴ Δία ποιητικῇ τις τοῦτο συγχωρήσει ἐξο[υσίᾳ. βέλ]τιον γὰρ τὴν Μεσσήνην μετὰ τῆς Λακωνικῆ[ς καὶ Πύλου] τῆς ὑπὸ τῷ Νέστορι, μηδὲ δὴ καθ’ αὑτὴν τάτ[τεσθαι ἐν τῷ] καταλόγῳ μηδὲ κοινωνοῦσαν τῆς στρα[τείας].", "st": "8.5.8"}, {"sp": "N", "t": "μετὰ δὲ Μαλέας ὁ Ἀργολικὸς ἐκδέχεται κόλπος καὶ ὁ Ἑρμιονικός, ὁ μὲν μέχρι τοῦ Σκυλλαίου πλέοντι ὡς πρὸς ἕω βλέπων καὶ πρὸς τὰς Κυκλάδας, ὁ δὲ ἑωθινώτερος τούτου μέχρι πρὸς Αἴγιναν καὶ τὴν Ἐπιδαυρίαν. τὰ μὲν δὴ πρῶτα τοῦ Ἀργολικοῦ Λάκωνες ἔχουσι, τὰ δὲ λοιπὰ Ἀργεῖοι· ἐν οἷς ἐστι τῶν μὲν Λακώνων τὸ Δήλιον ἱερὸν Ἀπόλλωνος ὁμώνυμον τῷ Βοιωτιακῷ, καὶ Μινώα φρούριον ὁμώνυμος καὶ αὕτη τῇ Μεγαρικῇ, καὶ ἡ λιμηρὰ Ἐπίδαυρος, ὡς Ἀρτεμίδωρός φησιν. Ἀπολλόδωρος δὲ Κυθήρων πλησίον ἱστορεῖ ταύτην, εὐλίμενον δὲ οὖσαν βραχέως καὶ ἐπιτετμημένως λιμηρὰν εἰρῆσθαι ὡς ἂν λιμενηράν, μεταβεβληκέναι δὲ τοὔνομα. ἔστι δὲ τραχὺς ὁ παράπλους εὐθὺς ἀπὸ Μαλεῶν ἀρξάμενος μέχρι πολλοῦ ὁ Λακωνικός, ἔχει δ’ ὅμως ὑφόρμους καὶ λιμένας. ἡ λοιπὴ δ’ ἐστὶ παραλία εὐλίμενος, νησίδιά τε πολλὰ πρόκειται αὐτῆς οὐκ ἄξια μνήμης.", "st": "8.6.1"}, {"sp": "N", "t": "τῶν δ’ Ἀργείων αἵ τε Πρασιαὶ καὶ τὸ Τημένιον, ἐν ᾧ τέθαπται Τήμενος, καὶ ἔτι πρότερον τὸ χωρίον, δι’ οὗ ῥεῖ ποταμὸς ἡ Λέρνη καλουμένη ὁμώνυμος τῇ λίμνῃ, ἐν ᾗ μεμύθευται τὰ περὶ τὴν Ὕδραν. τὸ δὲ Τημένιον ἀπέχει τοῦ Ἄργους ἓξ καὶ εἴκοσι σταδίους ὑπὲρ τῆς θαλάττης, ἀπὸ δὲ τοῦ Ἄργους εἰς τὸ Ἡραῖον τετταράκοντα, ἔνθεν δὲ εἰς Μυκήνας δέκα. μετὰ δὲ τὸ Τημένιον ἡ Ναυπλία, τὸ τῶν Ἀργείων ναύσταθμον· τὸ δ’ ἔτυμον ἀπὸ τοῦ ταῖς ναυσὶ προσπλεῖσθαι. ἀπὸ τούτου δὲ πεπλάσθαι φασὶ τὸν Ναύπλιον καὶ τοὺς παῖδας αὐτοῦ παρὰ τοῖς νεωτέροις· οὐ γὰρ Ὅμηρον ἀμνημονῆσαι ἂν τούτων, τοῦ μὲν Παλαμήδους τοσαύτην σοφίαν καὶ σύνεσιν ἐπιδεδειγμένου, δολοφονηθέντος δὲ ἀδίκως, τοῦ δὲ Ναυπλίου τοσοῦτον ἀπεργασαμένου φθόρον ἀνθρώπων περὶ τὸν Καφηρέα. ἡ δὲ γενεαλογία πρὸς τῷ μυθώδει καὶ τοῖς χρόνοις διημάρτηται· δεδόσθω γὰρ Ποσειδῶνος εἶναι, Ἀμυμώνης δὲ πῶς τὸν κατὰ τὰ Τρωικὰ ἔτι ζῶντα; ἐφεξῆς δὲ τῇ Ναυπλίᾳ τὰ σπήλαια καὶ οἱ ἐν αὐτοῖς οἰκοδομητοὶ λαβύρινθοι, Κυκλώπεια δ’ ὀνομάζουσιν.", "st": "8.6.2"}, {"sp": "N", "t": "εἶτ’ ἄλλα χωρία καὶ ἐφεξῆς ὁ Ἑρμιονικὸς κόλπος· καὶ [γὰρ τοῦτον Ὁμ]ήρου τάξαντος ὑπὸ τῇ Ἀργείᾳ καὶ ἡμῖν οὐ [παροπτέος ἐνέ]φηνεν ὁ μερισμὸς τῆς περιοδείας οὗτος. ἄρχεται δ’ ἀπὸ Ἀσίνης πολίχνης· εἶθ’ Ἑρμιόνη καὶ Τροιζήν· ἐν παράπλῳ δὲ πρόκειται καὶ Καλαυρία νῆσος, κύκλον ἔχουσα τριάκοντα σταδίων, πορθμῷ δὲ τετρασταδίῳ διεστῶσα τῆς ἠπείρου.", "st": "8.6.3"}, {"sp": "N", "t": "εἶθ’ ὁ Σαρωνικὸς κόλπος· οἱ δὲ πόντον λέγουσιν, οἱ δὲ πόρον, καθ’ ὃ καὶ πέλαγος λέγεται Σαρωνικὸν πᾶς ὁ συνάπτων πόρος ἀπὸ τῆς Ἑρμιονικῆς καὶ τῆς περὶ τὸν Ἰσθμὸν θαλάττης τῷ τε Μυρτῴῳ πελάγει καὶ τῷ Κρητικῷ. τοῦ δὲ Σαρωνικοῦ Ἐπίδαυρός τέ ἐστι καὶ ἡ προκειμένη νῆσος Αἴγινα· εἶτα Κεγχρεαὶ τὸ τῶν Κορινθίων ἐπὶ τὰ πρὸς ἕω μέρη ναύσταθμον· εἶτα λιμὴν Σχοινοῦς πλεύσαντι τετταράκοντα καὶ πέντε σταδίους· ἀπὸ δὲ Μαλεῶν τοὺς πάντας περὶ χιλίους καὶ ὀκτακοσίους. κατὰ δὲ τὸν Σχοινοῦντα ὁ δίολκος τὸ στενώτατον τοῦ Ἰσθμοῦ, περὶ ὃν τὸ τοῦ Ἰσθμίου Ποσειδῶνος ἱερόν· ἀλλὰ [ταῦ]τα μὲν ὑπερκείσθω· ἔξω γάρ ἐστι τῆς Ἀργείας. ἀναλαβόντες δ’ ἐφοδεύσωμεν πάλιν τὰ κατὰ τὴν Ἀργείαν.", "st": "8.6.4"}, {"sp": "N", "t": "καὶ πρῶτον ποσαχῶς λέγεται παρὰ τῷ ποιητῇ τὸ Ἄργος καὶ καθ’ αὑτὸ καὶ μετὰ τοῦ ἐπιθέτου, Ἀχαιικὸν Ἄργος καλοῦντος ἢ Ἴασον ἢ ἵππιον ἢ Πελασγικὸν ἢ ἱππόβοτον. καὶ γὰρ ἡ πόλις Ἄργος λέγεται<br>Ἄργος τε Σπάρτη τε.<br>οἱ δ’ Ἄργος τ’ εἶχον Τίρυνθά τε.<br>καὶ ἡ Πελοπόννησος<br>ἡμετέρῳ ἐνὶ οἴκῳ ἐν Ἄργεϊ.<br>οὐ γὰρ ἡ πόλις γε ἦν οἶκος αὐτοῦ. καὶ ὅλη ἡ Ἑλλάς· Ἀργείους γοῦν καλεῖ πάντας καθάπερ καὶ Δαναοὺς καὶ Ἀχαιούς. τὴν δ’ οὖν ὁμωνυμίαν τοῖς ἐπιθέτοις διαστέλλεται, τὴν μὲν Θετταλίαν Πελασγικὸν Ἄργος καλῶν<br>νῦν αὖ τοὺς ὅσσοι τὸ Πελασγικὸν Ἄργος ἔναιον.<br>τὴν δὲ Πελοπόννησον [Ἀχαιικὸν]<br>εἰ δέ κεν Ἄργος ἱκοίμεθ’ Ἀχαιικὸν<br>ἢ οὐκ Ἄργεος ἦεν Ἀχαιικοῦ.<br>σημαίνων ἐνταῦθα, ὅτι καὶ Ἀχαιοὶ ἰδίως ὠνομάζοντο οἱ Πελοποννήσιοι κατ’ ἄλλην σημασίαν. Ἴασόν τε Ἄργος τὴν Πελοπόννησον λέγει<br>εἰ πάντες γ’ ἐσίδοιεν ἀν’ Ἴασον Ἄργος Ἀχαιοί<br>τὴν Πηνελόπην, ὅτι πλείους ἂν λάβοι μνηστῆρας· οὐ γὰρ τοὺς ἐξ ὅλης τῆς Ἑλλάδος εἰκός, ἀλλὰ τοὺς ἐγγύς. ἱππόβοτον δὲ καὶ ἵππιον κοινῶς εἴρηκε.", "st": "8.6.5"}, {"sp": "N", "t": "περὶ δὲ τῆς Ἑλλάδος καὶ Ἑλλήνων καὶ Πανελλήνων ἀντιλέγεται. Θουκυδίδης μὲν γὰρ τὸν ποιητὴν μηδαμοῦ βαρβάρους εἰπεῖν φησι διὰ τὸ μηδὲ Ἕλληνάς πω τὸ ἀντίπαλον εἰς ἓν ὄνομα ἀποκεκρίσθαι. καὶ Ἀπολλόδωρος δὲ μόνους τοὺς ἐν Θετταλίᾳ καλεῖσθαί φησιν “Μυρμιδόνες δὲ καλεῦντο καὶ Ἕλληνες.” Ἡσίοδον μέντοι καὶ Ἀρχίλοχον ἤδη εἰδέναι καὶ Ἕλληνας λεγομένους τοὺς σύμπαντας καὶ Πανέλληνας, τὸν μὲν περὶ τῶν Προιτίδων λέγοντα ὡς Πανέλληνες ἐμνήστευον αὐτάς, τὸν δὲ<br>ὡς Πανελλήνων ὀιζὺς ἐς Θάσον συνέδραμεν.<br>ἄλλοι δ’ ἀντιτιθέασιν ὅτι καὶ βαρβάρους εἴρηκεν, εἰπών γε βαρβαροφώνους τοὺς Κᾶρας, καὶ Ἕλληνας τοὺς πάντας<br>ἀνδρός, τοῦ κλέος εὐρὺ καθ’ Ἑλλάδα καὶ μέσον Ἄργος·<br>καὶ πάλιν<br>εἰ δ’ ἐθέλῃς [τραφθῆναι] ἀν’ Ἑλλάδα καὶ μέσον Ἄργος.", "st": "8.6.6"}, {"sp": "N", "t": "ἡ μὲν οὖν πόλις ἡ τῶν Ἀργείων ἐν χωρίοις ἐπιπέδοις ἵδρυται τὸ πλέον, ἄκραν δ’ ἔχει τὴν καλουμένην Λάρισαν, λόφον εὐερκῆ μετρίως ἔχοντα ἱερὸν Διός· ῥεῖ δ’ αὐτῆς πλησίον ὁ Ἴναχος χαραδρώδης ποταμὸς τὰς πηγὰς ἔχων ἐκ Λυρκείου. περὶ δὲ τῶν μυθευομένων πηγῶν εἴρηται διότι πλάσματα ποιητῶν ἐστί· πλάσμα δὲ καὶ τὸ Ἄργος ἄνυδρον “θεοὶ δ’ αὖ θέσαν Ἄργος ἔνυδρον” τῆς τε χώρας κοίλης οὔσης καὶ ποταμοῖς διαρρεομένης καὶ ἕλη καὶ λίμνας παρεχομένης, καὶ τῆς πόλεως εὐπορουμένης ὕδασι φρεάτων πολλῶν καὶ ἐπιπολαίων. αἰτιῶνται δὲ τῆς ἀπάτης τὸ<br>καί κεν ἐλέγχιστος πολυδίψιον Ἄργος ἱκοίμην.<br>τοῦτο δ’ ἤτοι ἀντὶ τοῦ πολυπόθητον κεῖται, ἢ χωρὶς τοῦ δ πολυίψιον, ὡς<br>πολύφθορόν τε δῶμα Πελοπιδῶν τόδε<br>φησὶ Σοφοκλῆς· τὸ γὰρ ἴψασθαι φθοράν τινα καὶ βλάβην σημαίνει<br>νῦν μὲν πειρᾶται, τάχα δ’ ἴψεται υἷας Ἀχαιῶν<br>κατὰ χρόα καλὸν ἰάψῃ.<br>Ἄιδι προίαψεν<br>ἄλλως τε οὐ τὴν πόλιν λέγει τὸ Ἄργος (οὐ γὰρ ἐκεῖσε ἔμελλεν ἀφίξεσθαι) ἀλλὰ τὴν Πελοπόννησον, οὐ δήπου καὶ ταύτην διψηρὰν οὖσαν. καὶ σὺν τῷ ⟨δ⟩ δὲ ὑπερβατῶς δέχονταί [τινες κατὰ] συναλιφὴν μετὰ τοῦ συνδέσμου τοῦ δέ, ἵν’ ᾖ οὕτως “καί κεν ἐλέγχιστος πολὺ δ’ ἴψιον Ἄργος ἱκοίμην,” … ⟨πολυί⟩ψιον Ἄργοσδε ἱκοίμην ἀντὶ τοῦ εἰς Ἄργος.", "st": "8.6.7"}, {"sp": "N", "t": "εἷς μὲν δὴ Ἴναχός ἐστιν ὁ διαρρέων τὴν Ἀργείαν· ἄλλος δὲ ποταμὸς Ἐρασῖνος ἐν τῇ Ἀργείᾳ ἐστίν· οὗτος δὲ τὰς ἀρχὰς ἐκ Στυμφάλου τῆς Ἀρκαδίας λαμβάνει καὶ τῆς ἐκεῖ λίμνης τῆς καλουμένης Στυμφαλίδος, ἐν ᾗ τὰς ὄρνεις μυθολογοῦσι τὰς ὑπὸ τοῦ Ἡρακλέους τοξεύμασι καὶ τυμπάνοις ἐξελαθείσας, [ἃς] καὶ αὐτὰς καλοῦσι Στυμφαλίδας· δύντα δ’ ὑπὸ γῆς φασὶ τὸν ποταμὸν τοῦτον ἐκπίπτειν εἰς τὴν Ἀργείαν καὶ ποιεῖν ἐπίρρυτον τὸ πεδίον· ῥεῖ δὲ καὶ ἄλλος ὁμώνυμος ἐκ τῆς Ἀρκαδίας εἰς τὸν κατὰ Βοῦραν αἰγιαλόν· ἄλλος δ’ ἐστὶν ὁ Ἐρετρικός, καὶ ὁ ἐν τῇ Ἀττικῇ κατὰ Βραυρῶνα. δείκνυται δὲ καὶ Ἀμυμώνη τις κρήνη κατὰ Λέρνην. ἡ δὲ Λέρνη λίμνη τῆς Ἀργείας ἐστὶ καὶ τῆς Μυκηναίας, ἐν ᾗ τὴν Ὕδραν ἱστοροῦσι· διὰ δὲ τοὺς γινομένους καθαρμοὺς ἐν αὐτῇ παροιμία τις ἐξέπεσε “Λέρνη κακῶν.” τὴν μὲν οὖν χώραν συγχωροῦσιν εὐυδρεῖν, αὐτὴν δὲ τὴν πόλιν ἐν ἀνύδρῳ χωρίῳ κεῖσθαι, φρεάτων δ’ εὐπορεῖν, ἃ ταῖς Δαναΐσιν ἀνάπτουσιν, ὡς ἐκείνων ἐξευρουσῶν, ἀφ’ οὗ καὶ τὸ ἔπος εἰπεῖν τοῦτο<br>Ἄργος ἄνυδρον ἐὸν Δανααὶ θέσαν Ἄργος ἔνυδρον,<br>τῶν δὲ φρεάτων τέτταρα καὶ ἱερὰ ἀποδειχθῆναι καὶ τιμᾶσθαι διαφερόντως, ἐν εὐπορίᾳ ὑδάτων ἀπορίαν εἰσάγοντες.", "st": "8.6.8"}, {"sp": "N", "t": "τὴν δὲ ἀκρόπολιν τῶν Ἀργείων οἰκίσαι λέγεται Δαναός, ὃς τοσοῦτον τοὺς πρὸ αὐτοῦ δυναστεύοντας ἐν τοῖς τόποις ὑπερβαλέσθαι δοκεῖ ὥστε κατ’ Εὐριπίδην<br>Πελασγιώτας ὠνομασμένους τὸ πρὶν<br>Δαναοὺς καλεῖσθαι νόμον ἔθηκ’ ἀν’ Ἑλλάδα.<br>ἔστι δὲ καὶ τάφος αὐτοῦ κατὰ μέσην τὴν τῶν Ἀργείων ἀγοράν· καλεῖται δὲ πλίνθος. οἶμαι δ’ ὅτι καὶ Πελασγιώτας καὶ Δαναούς, ὥσπερ καὶ Ἀργείους, ἡ δόξα τῆς πόλεως ταύτης ἀπ’ αὐτῆς καὶ τοὺς ἄλλους Ἕλληνας καλεῖσθαι παρεσκεύασεν· οὕτω δὲ καὶ Ἰασίδας καὶ Ἴασον Ἄργος. καὶ Ἀπίαν καὶ Ἀπιδόνας οἱ νεώτεροί φασιν· Ὅμηρος δ’ Ἀπιδόνας μὲν οὐ λέγει, ἀπίαν δὲ τὴν πόρρω μᾶλλον. ὅτι δ’ Ἄργος τὴν Πελοπόννησον λέγει, προσλαβεῖν ἔστι καὶ τάδε<br>Ἀργείη δ’ Ἑλένη<br>καὶ<br>ἔστι πόλις Ἐφύρη μυχῷ Ἄργεος<br>καὶ<br>μέσον Ἄργος<br>καὶ<br>πολλῇσιν νήσοισι καὶ Ἄργεϊ παντὶ ἀνάσσειν.<br>Ἄργος δὲ καὶ τὸ πεδίον λέγεται παρὰ τοῖς νεωτέροις, παρ’ Ὁμήρῳ δ’ οὐδ’ ἅπαξ· μάλιστα δ’ οἴονται Μακεδονικὸν καὶ Θετταλικὸν εἶναι.", "st": "8.6.9"}, {"sp": "N", "t": "τῶν δ’ ἀπογόνων τοῦ Δαναοῦ διαδεξαμένων τὴν ἐν Ἄργει δυναστείαν, ἐπιμιχθέντων δὲ τούτοις τῶν Ἀμυθαονιδῶν ὡρμημένων ἐκ τῆς Πισάτιδος καὶ τῆς Τριφυλίας, οὐκ ἂν θαυμάσειέ τις εἰ συγγενεῖς ὄντες οὕτω διείλοντο τὴν χώραν εἰς δύο βασιλείας τὸ πρῶτον, ὥστε τὰς ἡγεμονευούσας ἐν αὐταῖς δύο πόλεις ἀποδειχθῆναι πλησίον ἀλλήλων ἱδρυμένας ἐν ἐλάττοσιν ἢ πεντήκοντα σταδίοις, τό τε Ἄργος καὶ τὰς Μυκήνας, καὶ τὸ Ἡραῖον εἶναι κοινὸν ἱερὸν τὸ πρὸς ταῖς Μυκήναις ἀμφοῖν, ἐν ᾧ τὰ Πολυκλείτου ξόανα τῇ μὲν τέχνῃ κάλλιστα τῶν πάντων πολυτελείᾳ δὲ καὶ μεγέθει τῶν Φειδίου λειπόμενα. κατ’ ἀρχὰς μὲν οὖν τὸ Ἄργος ἐπεκράτει μᾶλλον, εἶθ’ αἱ Μυκῆναι μείζονα ἐπίδοσιν λαβοῦσαι διὰ τὴν τῶν Πελοπιδῶν εἰς αὐτὰς μεθίδρυσιν· περιστάντων γὰρ εἰς τοὺς Ἀτρέως παῖδας ἁπάντων, Ἀγαμέμνων ὢν πρεσβύτερος παραλαβὼν τὴν ἐξουσίαν ἅμα τύχῃ τε καὶ ἀρετῇ πρὸς τοῖς οὖσι πολλὴν προσεκτήσατο τῆς χώρας, καὶ δὴ καὶ τὴν Ἀργολικὴν τῇ Μυκηναίᾳ προσέθηκε. Μενέλαος μὲν δὴ τὴν Λακωνικὴν ἔσχε, Μυκήνας δὲ καὶ τὰ μέχρι Κορίνθου καὶ Σικυῶνος καὶ τῆς Ἰώνων μὲν τότε καὶ Αἰγιαλέων καλουμένης Ἀχαιῶν δὲ ὕστερον Ἀγαμέμνων παρέλαβε. μετὰ δὲ τὰ Τρωικὰ τῆς Ἀγαμέμνονος ἀρχῆς καταλυθείσης ταπεινωθῆναι [συνέβη] Μυκήνας καὶ μάλιστα μετὰ τὴν τῶν Ἡρακλειδῶν κάθοδον. κατασχόντες γὰρ οὗτοι τὴν Πελοπόννησον ἐξέβαλον τοὺς πρότερον κρατοῦντας ὥσθ’ οἱ τὸ Ἄργος ἔχοντες εἶχον καὶ τὰς Μυκήνας συντελούσας εἰς ἕν· χρόνοις δ’ ὕστερον κατεσκάφησαν ὑπ’ Ἀργείων ὥστε νῦν μηδ’ ἴχνος εὑρίσκεσθαι τῆς Μυκηναίων πόλεως. ὅπου δὲ Μυκῆναι τοιαῦτα πεπόνθασιν, οὐ δεῖ θαυμάζειν οὐδ’ εἴ τινες τῶν ὑπὸ τῷ Ἄργει καταλεγομένων ἀφανεῖς νῦν εἰσιν. ὁ μὲν δὴ κατάλογος ἔχει οὕτως<br>οἳ δ’ Ἄργος τ’ εἶχον Τίρυνθά τε τειχιόεσσαν<br>Ἑρμιόνην τ’ Ἀσίνην τε, [βαθὺ]ν κατὰ κόλπον ἐχούσας,<br>Τροιζῆν’ Ἠιόνας τε καὶ ἀμπελόεντ’ Ἐπίδαυρον,<br>οἵ τ’ ἔχον Αἴγιναν Μάσητά τε, κοῦροι Ἀχαιῶν.<br>τούτων δὲ περὶ μὲν τοῦ Ἄργους εἴρηται, περὶ δὲ τῶν ἄλλων λεκτέον.", "st": "8.6.10"}, {"sp": "N", "t": "τῇ μὲν οὖν Τίρυνθι ὁρμητηρίῳ χρήσασθαι δοκεῖ Προῖτος καὶ τειχίσαι διὰ Κυκλώπων, οὓς ἑπτὰ μὲν εἶναι καλεῖσθαι δὲ γαστερόχειρας τρεφομένους ἐκ τῆς τέχνης, ἥκειν δὲ μεταπέμπτους ἐκ Λυκίας· καὶ ἴσως τὰ σπήλαια τὰ περὶ τὴν Ναυπλίαν καὶ τὰ ἐν αὐτοῖς ἔργα τούτων ἐπώνυμά ἐστιν. ἡ δὲ ἀκρόπολις Λίκυμνα ἐπώνυμος Λικυμνίου, διέχει δὲ τῆς Ναυπλίας περὶ δώδεκα σταδίους· ἔρημος δ’ ἐστὶ κἀκείνη καὶ ἡ πλησίον Μιδέα, ἑτέρα οὖσα τῆς Βοιωτικῆς· ἐκείνη γὰρ ἔστι Μίδεια ὡς πρόνοια, αὕτη δὲ Μιδέα ὡς Τεγέα· ταύτῃ δ’ ὅμορος Πρόσυμνα … αὕτη ἱερὸν ἔχουσα Ἥρας· ἠρήμωσαν δὲ τὰς πλείστας οἱ Ἀργεῖοι ἀπειθούσας. οἱ δ’ οἰκήτορες οἱ μὲν ἐκ [τῆς] Τίρυνθος ἀπῆλθον εἰς Ἐπίδαυρον, οἱ δὲ ἐ[κ τῆς …] εἰς τοὺς Ἁλιεῖς καλουμένους, οἱ δ’ ἐκ τῆς Ἀ[σίνης (ἔστι δ’] αὕτη κώμη τῆς Ἀργείας πλησίον Ναυπλίας) ὑπὸ Λακεδαιμονίων εἰς τὴν Μεσσηνίαν μετῳκίσθ[ησαν, ὅπου] καὶ ἡ ὁμώνυμος τῇ Ἀργολικῇ Ἀσίνῃ πολίχ[νη]. οἱ γὰρ Λακεδαιμόνιοι, φησὶν ὁ Θεόπομπος, πολλὴν κατακτησάμενοι τῆς ἀλλοτρίας εἰς ταύτην κατῴκιζον οὓς ἂν ὑποδέξαιντο τῶν φυγόντων ἐπ’ αὐτο[ύς· καὶ οἱ] ἐκ τῆς Ναυπλίας ἐκεῖσε ἀνεχώρησαν.", "st": "8.6.11"}, {"sp": "N", "t": "Ἑρμιόνη δ’ ἐστὶ τῶν οὐκ ἀσήμων πόλεων, ἧς τὴν παραλίαν ἔχουσιν Ἁλιεῖς λεγόμενοι θαλαττουργοί τινες ἄνδρες. παρ’ Ἑρμιονεῦσι δὲ τεθρύληται τὴν εἰς Ἅιδου κατάβασιν σύντομον εἶναι· διόπερ οὐκ ἐντιθέασιν ἐνταῦθα τοῖς νεκροῖς ναῦλον.", "st": "8.6.12"}, {"sp": "N", "t": "Δρυόπων δ’ οἰκητήριόν φασι καὶ τὴν Ἀσίνην, εἴτ’ ἐκ τῶν περὶ Σπερχειὸν τόπων ὄντας αὐτοὺς Δρύοπος τοῦ Ἀρκάδος κατοικίσαντος ἐνταῦθα, ὡς Ἀριστοτέλης φησίν, εἴθ’ Ἡρακλέους ἐκ τῆς περὶ τὸν Παρνασσὸν Δωρίδος ἐξελάσαντος αὐτούς. τὸ δὲ Σκύλλαιον τὸ ἐν Ἑρμιόνῃ ὠνομάσθαι φασὶν ἀπὸ Σκύλλης τῆς Νίσου θυγατρός, ἣν ἐξ ἔρωτος προδοῦσαν Μίνῳ τὴν Νίσαιαν καταποντωθῆναί φασιν ὑπ’ αὐτοῦ, δεῦρο δ’ ἐκκυμανθεῖσαν ταφῆς τυχεῖν. ἠιόνες δὲ κώμη τις ἦν, ἣν ἐρημώσαντες Μυκηναῖοι ναύσταθμον ἐποίησαν, ἀφαν[ισθεῖσα δ’ ὕστερον] οὐδὲ ναύσταθμόν ἐστιν.", "st": "8.6.13"}, {"sp": "N", "t": "Τροιζὴν δὲ ἱερά ἐστι Ποσειδῶνος, ἀφ’ οὗ καὶ Ποσειδωνία ποτὲ ἐλέγετο· ὑπέρκειται δὲ τῆς θαλάττης εἰς πεντεκαίδεκα σταδίους, οὐδ’ αὕτη ἄσημος πόλις. πρόκειται δὲ τοῦ λιμένος αὐτῆς Πώγωνος τοὔνομα Καλαυρία νησίδιον ὅσον τριάκοντα σταδίων ἔχον τὸν κύκλον· ἐνταῦθα ἦν ἄσυλον Ποσειδῶνος ἱερόν, καί φασι τὸν θεὸν τοῦτον ἀλλάξασθαι πρὸς μὲν Λητὼ τὴν Καλαυρίαν ἀντιδόντα Δῆλον, πρὸς Ἀπόλλωνα δὲ Ταίναρον ἀντιδόντα Πυθώ. Ἔφορος δὲ καὶ τὸν χρησμὸν λέγει<br>ἶσόν τοι Δῆλόν τε Καλαύρειάν τε νέμεσθαι,<br>Πυθώ τ’ ἠγαθέην καὶ Ταίναρον ἠνεμόεντα.<br>ἦν δὲ καὶ Ἀμφικτυονία τις περὶ τὸ ἱερὸν τοῦτο ἑπτὰ πόλεων αἳ μετεῖχον τῆς θυσίας· ἦσαν δὲ Ἑρμιὼν Ἐπίδαυρος Αἴγινα Ἀθῆναι Πρασιεῖς Ναυπλιεῖς Ὀρχομενὸς ὁ Μινύειος· ὑπὲρ μὲν οὖν Ναυπλιέων Ἀργεῖοι συνετέλουν, ὑπὲρ Πρασιέων δὲ Λακεδαιμόνιοι. οὕτω δ’ ἐπεκράτησεν ἡ τιμὴ τοῦ θεοῦ τούτου παρὰ τοῖς Ἕλλησιν ὥστε καὶ Μακεδόνες δυναστεύοντες ἤδη μέχρι δεῦρο ἐφύλαττόν πως τὴν ἀσυλίαν, καὶ τοὺς ἱκέτας ἀποσπᾶν ᾐδοῦντο τοὺς εἰς Καλαυρίαν καταφυγόντας· ὅπου γε οὐδὲ Δημοσθένη ἐθάρρησεν Ἀρχίας βιάσασθαι στρατιώτας ἔχων, ᾧ προσετέτακτο ὑπὸ Ἀντιπάτρου ζῶντα ἀγαγεῖν κἀκεῖνον καὶ τῶν ἄλλων ῥητόρων ὃν ἂν εὕρῃ τῶν ἐν ταῖς αἰτίαις ὄντων ταῖς παραπλησίοις, ἀλλὰ πείθειν ἐπειρᾶτο· οὐ μὴν ἔπεισέ γε, ἀλλ’ ἔφθη φαρμάκῳ παραλύσας ἑαυτὸν τοῦ ζῆν. Τροιζὴν δὲ καὶ Πιτθεὺς οἱ Πέλοπος ὁρμηθέντες ἐκ τῆς Πισάτιδος ὁ μὲν τὴν πόλιν ὁμώνυμον ἑαυτοῦ κατέλιπεν, ὁ δὲ Πιτθεὺς ἐβασίλευσεν ἐκεῖνον διαδεξάμενος. Ἄνθης δ’ ὁ προκατέχων πλεύσας Ἁλικαρνασὸν ἔκτισεν· ἐροῦμεν δ’ ἐν τοῖς Καρικοῖς … ον καὶ τοῖς Τρωικοῖς.", "st": "8.6.14"}, {"sp": "N", "t": "ἡ Ἐπίδαυρος δ’ ἐκαλεῖτο Ἐπίταυρος· φησὶ δὲ Ἀριστοτέλης κατασχεῖν αὐτὴν Κᾶρας, ὥσπερ καὶ Ἑρμιόνα, τῶν δὲ Ἡρακλειδῶν κατελθόντων Ἴωνας αὐτοῖς συνοικῆσαι τοὺς ἐκ τῆς Ἀττικῆς τετραπόλεως συνεπομένους εἰς Ἄργος. καὶ αὕτη δ’ οὐκ ἄσημος ἡ πόλις καὶ μάλιστα διὰ τὴν ἐπιφάνειαν τοῦ Ἀσκληπιοῦ θεραπεύειν νόσους παντοδαπὰς πεπιστευμένου, καὶ τὸ ἱερὸν πλῆρες ἔχοντος ἀεὶ τῶν τε καμνόντων καὶ τῶν ἀνακειμένων πινάκων, ἐν οἷς ἀναγεγραμμέναι τυγχάνουσιν αἱ θεραπεῖαι, καθάπερ ἐν Κῷ τε καὶ Τρίκκῃ. κεῖται δ’ ἡ πόλις ἐν μυχῷ τοῦ Σαρωνικοῦ κόλπου, τὸν περίπλουν ἔχουσα σταδίων πεντεκαίδεκα, βλέπουσα πρὸς ἀνατολὰς θερινάς· περικλείεται δ’ ὄρεσιν ὑψηλοῖς μέχρι πρὸς τὴν θάλατταν, ὥστ’ ἐρυμνὴ κατεσκεύασται φυσικῶς πανταχόθεν. μεταξὺ δὲ Τροιζῆνος καὶ Ἐπιδαύρου χωρίον ἦν ἐρυμνὸν Μέθανα καὶ χερρόνησος ὁμώνυμος τούτῳ· παρὰ Θουκυδίδῃ δὲ ἔν τισιν ἀντιγράφοις Μεθώνη φέρεται ὁμωνύμως τῇ Μακεδονικῇ, ἐν ᾗ Φίλιππος ἐξεκόπη τὸν ὀφθαλμὸν πολιορκῶν· διόπερ οἴεταί τινας ἐξαπατηθέντας ὁ Σκήψιος Δημήτριος τὴν ἐν τῇ Τροιζηνίᾳ Μεθώνην ὑπονοεῖν, καθ’ ἧς ἀράσασθαι λέγεται τοὺς ὑπ’ Ἀγαμέμνονος πεμφθέντας ναυτολόγους μηδέποτε παύσασθαι [τοῦ] τειχοδομεῖν, οὐ τούτων ἀλλὰ τῶν Μακεδόνων ἀνανευσάντων, ὥς φησι Θεόπομπος· τούτους δ’ οὐκ εἰκὸς ἐγγὺς ὄντας ἀπειθῆσαι.", "st": "8.6.15"}, {"sp": "N", "t": "Αἴγινα δ’ ἔστι μὲν καὶ τόπος τις τῆς Ἐπιδαυρίας, ἔστι δὲ καὶ νῆσος πρὸ τῆς ἠπείρου ταύτης, ἣν ἐν τοῖς ἀρτίως παρατεθεῖσιν ἔπεσι βούλεται φράζειν ὁ ποιητής· διὸ καὶ γράφουσί τινες “νῆσόν τ’ Αἴγιναν” ἀντὶ τοῦ “οἵ τ’ ἔχον Αἴγιναν,” διαστελλόμενοι τὴν ὁμωνυμίαν. ὅτι μὲν οὖν τῶν σφόδρα γνωρίμων ἐστὶν ἡ νῆσος, τί δεῖ λέγειν; ἐντεῦθεν γὰρ Αἰακός τε λέγεται καὶ οἱ ἀπ’ αὐτοῦ. αὕτη δ’ ἐστὶν ἡ καὶ θαλαττοκρατήσασά ποτε καὶ περὶ πρωτείων ἀμφισβητήσασα πρὸς Ἀθηναίους ἐν τῇ περὶ Σαλαμῖνα ναυμαχίᾳ κατὰ τὰ Περσικά. λέγεται δὲ σταδίων ἑκατὸν ὀγδοήκοντα ὁ κύκλος τῆς νήσου, πόλιν δ’ ὁμώνυμον ἔχει τετραμμένην πρὸς λίβα· περιέχουσι δ’ αὐτὴν ἥ τε Ἀττικὴ καὶ ἡ Μεγαρὶς καὶ τῆς Πελοποννήσου τὰ μέχρι Ἐπιδαύρου, σχεδόν τι ἑκατὸν σταδίους ἑκάστη διέχουσα· τὸ δὲ ἑωθινὸν μέρος καὶ τὸ νότιον πελάγει κλύζεται τῷ τε Μυρτῴῳ καὶ τῷ Κρητικῷ· νησίδια δὲ περίκειται πολλὰ μὲν πρὸς τῇ ἠπείρῳ, Βέλβινα δὲ πρὸς τὸ πέλαγος ἀνατείνουσα. ἡ δὲ χώρα αὐτῆς κατὰ βάθους μὲν γεώδης ἐστί, πετρώδης δ’ ἐπιπολῆς καὶ μάλιστα ἡ πεδιάς· διόπερ ψιλὴ πᾶσά ἐστι, κριθοφόρος δὲ ἱκανῶς. Μυρμιδόνας δὲ κληθῆναί φασιν οὐχ ὡς ὁ μῦθος τοὺς Αἰγινήτας, ὅτι λοιμοῦ μεγάλου συμπεσόντος οἱ μύρμηκες ἄνθρωποι γένοιντο κατ’ εὐχὴν Αἰακοῦ, ἀλλ’ ὅτι μυρμήκων τρόπον ὀρύττοντες τὴν γῆν ἐπισπείροιεν ἐπὶ τὰς πέτρας, ὥστ’ ἔχειν γεωργεῖν, ἐν δὲ τοῖς ὀρύγμασιν οἰκεῖν φειδόμενοι πλίνθων. ὠνομάζετο δ’ Οἰνώνη πάλαι ἐπῴκησαν δ’ αὐτὴν Ἀργεῖοι καὶ Κρῆτες καὶ Ἐπιδαύριοι καὶ Δωριεῖς, ὕστερον δὲ κατεκληρούχησαν τὴν νῆσον Ἀθηναῖοι· ἀφελόμενοι δὲ Λακεδαιμόνιοι τοὺς Ἀθηναίους τὴν νῆσον ἀπέδοσαν τοῖς ἀρχαίοις οἰκήτορσιν. ἀποίκους δ’ ἔστειλαν Αἰγινῆται εἴς τε Κυδωνίαν τὴν ἐν Κρήτῃ καὶ εἰς Ὀμβρικούς. Ἔφορος δ’ ἐν Αἰγίνῃ ἄργυρον πρῶτον κοπῆναί φησιν ὑπὸ Φείδωνος· ἐμπόριον γὰρ γενέσθαι, διὰ τὴν λυπρότητα τῆς χώρας τῶν ἀνθρώπων θαλαττουργούντων ἐμπορικῶς, ἀφ’ οὗ τὸν ῥῶπον Αἰγιναίαν ἐμπολὴν λέγεσθαι.", "st": "8.6.16"}, {"sp": "N", "t": "ὁ δὲ ποιητὴς ἔνια μὲν χωρία λέγει συνεχῶς ὥσπερ καὶ κεῖται<br>οἵ θ’ Ὑρίην ἐνέμοντο καὶ Αὐλίδα<br>οἳ δ’ Ἄργος τ’ εἶχον Τίρυνθά τε<br>Ἑρμιόνην τ’ Ἀσίνην τε<br>Τροιζῆν’ Ἠιόνας τε.<br>ἄλλοτε δ’ οὐχ ὡς ἔστι τῇ τάξει<br>σχοῖνόν τε Σκῶλόν τε<br>Θέσπειαν Γραῖάν τε.<br>τά τ’ ἐν ἠπείρῳ ταῖς νήσοις συμφράζει<br>οἵ ῥ’ Ἰθάκην εἶχον,<br>καὶ Κροκύλει’ ἐνέμοντο.<br>τὰ γὰρ Κροκύλεια ἐν τοῖς Ἀκαρνᾶσιν. οὕτω δὲ καὶ νῦν τῇ Αἰγίνῃ τὸν Μάσητα συνῆψεν ὄντα τῆς Ἀργολικῆς ἠπείρου. Θυρέας δὲ Ὅμηρος μὲν οὐκ ὠνόμασεν, οἱ δ’ ἄλλοι θρυλοῦσι· περὶ ὧν Ἀργείοις καὶ Λακεδαιμονίοις συνέστη ἀγὼν τριακοσίοις πρὸς τριακοσίους· ἐνίκων δὲ Λακεδαιμόνιοι στρατηγοῦντος Ὀθρυάδα· εἶναι δέ φησι τὸ χωρίον τοῦτο Θουκυδίδης ἐν τῇ Κυνουρίᾳ κατὰ τὴν μεθορίαν τῆς Ἀργείας καὶ τῆς Λακωνικῆς. εἰσὶ δὲ καὶ Ὑσίαι τόπος γνώριμος τῆς Ἀργολικῆς καὶ Κεγχρεαί, αἳ κεῖνται ἐπὶ τῇ ὁδῷ τῇ ἐκ Τεγέας εἰς Ἄργος διὰ τοῦ Παρθενίου ὄρους. Ὅμηρος δ’ αὐτὰς οὐκ οἶδεν.", "st": "8.6.17"}, {"sp": "N", "t": "τῶν [δὴ] κατὰ Πελοπόννησον πόλεων ἐνδοξόταται γεγόνασι καὶ μέχρι νῦν εἰσιν Ἄργος τε Σπάρτη τε, διὰ δὲ τὸ πολυθρύλητον ἥκιστα δεῖ μακρολογεῖν περὶ αὐτῶν· τὰ γὰρ ὑπὸ πάντων εἰρημένα λέγειν δόξομεν. τὸ παλαιὸν μὲν οὖν ηὐδοκίμει τὸ Ἄργος μᾶλλον, ὕστερον δὲ καὶ μέχρι παντὸς ὑπερεβάλοντο Λακεδαιμόνιοι καὶ διετέλεσαν τὴν αὐτονομίαν φυλάττοντες, πλὴν εἴ τί που μικρὸν προσπταίειν αὐτοὺς συνέβαινεν. Ἀργεῖοι δὲ Πύρρον μὲν οὐκ ἐδέξαντο (ἀλλὰ καὶ πρὸ τοῦ τείχους ἔπεσε γρᾳδίου τινός, ὡς ἔοικε, κεραμίδα ἀφέντος ἄνωθεν ἐπὶ τὴν κεφαλήν) ὑπ’ ἄλλοις δ’ ἐγένοντο βασιλεῦσι, μετασχόντες δὲ τοῦ τῶν Ἀχαιῶν συστήματος σὺν ἐκείνοις εἰς τὴν τῶν Ῥωμαίων ἐξουσίαν ἦλθον, καὶ νῦν συνέστηκεν ἡ πόλις δευτερεύουσα τῇ τάξει μετὰ τὴν Σπάρτην.", "st": "8.6.18"}, {"sp": "N", "t": "ἑξῆς δὲ λέγωμεν περὶ τῶν ὑπὸ Μυκήναις καὶ τῷ Ἀγαμέμνονι τεταγμένων τόπων ἐν τῷ καταλόγῳ τῶν νεῶν· ἔχει δ’ οὕτω τὰ ἔπη<br>οἳ δὲ Μυκήνας εἶχον, ἐυκτίμενον πτολίεθρον,<br>ἀφνειόν τε Κόρινθον ἐυκτιμένας τε Κλεωνάς,<br>Ὀρνειάς τ’ ἐνέμοντο Ἀραιθυρέην τ’ ἐρατεινὴν<br>καὶ Σικυῶν’, ὅθ’ ἄρ’ Ἄδρηστος πρῶτ’ ἐμβασίλευεν,<br>οἵ θ’ Ὑπερησίην τε καὶ αἰπεινὴν Γονόεσσαν<br>Πελλήνην τ’ εἶχον, ἠδ’ Αἴγιον ἀμφενέμοντο,<br>αἰγιαλόν τ’ ἀνὰ πάντα καὶ ἀμφ’ Ἑλίκην εὐρεῖαν.<br>αἱ μὲν οὖν Μυκῆναι νῦν οὐκέτ’ εἰσίν, ἔκτισε δ’ αὐτὰς Περσεύς, διεδέξατο δὲ Σθένελος, εἶτ’ Εὐρυσθεύς· οἱ δ’ αὐτοὶ καὶ τοῦ Ἄργους ἦρξαν. Εὐρυσθεὺς μὲν οὖν στρατεύσας εἰς Μαραθῶνα ἐπὶ τοὺς Ἡρακλέους παῖδας καὶ Ἰόλαον βοηθησάντων Ἀθηναίων ἱστορεῖται πεσεῖν ἐν τῇ μάχῃ, καὶ τὸ μὲν ἄλλο σῶμα Γαργηττοῖ ταφῆναι, τὴν δὲ κεφαλὴν χωρὶς ἐν Τρικορύνθῳ, ἀποκόψαντος αὐτὴν Ἰολάου περὶ τὴν κρήνην τὴν Μακαρίαν ὑπὸ ἁμαξιτόν· καὶ ὁ τόπος καλεῖται Εὐρυσθέως κεφαλή. αἱ δὲ Μυκῆναι μετέπεσον εἰς τοὺς Πελοπίδας ὁρμηθέντας ἐκ τῆς Πισάτιδος, εἶτ’ εἰς τοὺς Ἡρακλείδας καὶ τὸ Ἄργος ἔχοντας. μετὰ δὲ τὴν ἐν Σαλαμῖνι ναυμαχίαν Ἀργεῖοι μετὰ Κλεωναίων καὶ Τεγεατῶν ἐπελθόντες ἄρδην τὰς Μυκήνας ἀνεῖλον καὶ τὴν χώραν διενείμαντο. διὰ δὲ τὴν ἐγγύτητα τὰς δύο πόλεις ὡς μίαν οἱ τραγικοὶ συνωνύμως προσαγορεύουσιν, Εὐριπίδης δὲ καὶ ἐν τῷ αὐτῷ δράματι τοτὲ μὲν Μυκήνας καλῶν τοτὲ δ’ Ἄργος τὴν αὐτὴν πόλιν, καθάπερ ἐν Ἰφιγενείᾳ καὶ Ὀρέστῃ. Κλεωναὶ δ’ εἰσὶ πόλισμα ἐπὶ τῇ ὁδῷ κείμενον τῇ ἐξ Ἄργους εἰς Κόρινθον ἐπὶ λόφου περιοικουμένου πανταχόθεν καὶ τετειχισμένου καλῶς, ὥστ’ οἰκείως εἰρῆσθαί μοι δοκεῖ τὸ ἐυκτιμένας Κλεωνάς. ἐνταῦθα δὲ καὶ ἡ Νεμέα μεταξὺ Κλεωνῶν καὶ Φλιοῦντος καὶ τὸ ἄλσος, ἐν ᾧ καὶ τὰ Νέμεα συντελεῖν ἔθος τοῖς Ἀργείοις, καὶ τὰ περὶ τὸν Νεμεαῖον λέοντα μυθευόμενα, καὶ ἡ Βέμβινα κώμη· διέχουσι δ’ αἱ Κλεωναὶ τοῦ μὲν Ἄργους σταδίους ἑκατὸν εἴκοσι, Κορίνθου δὲ ὀγδοήκοντα. καὶ ἡμεῖς ἀπὸ τοῦ Ἀκροκορίνθου κατωπτεύσαμεν τὸ κτίσμα.", "st": "8.6.19"}, {"sp": "N", "t": "ὁ δὲ Κόρινθος ἀφνειὸς μὲν λέγεται διὰ τὸ ἐμπόριον, ἐπὶ τῷ Ἰσθμῷ κείμενος καὶ δυεῖν λιμένων [ὢν] κύριος, ὧν ὁ μὲν τῆς Ἀσίας ὁ δὲ τῆς Ἰταλίας ἐγγύς ἐστι … καὶ ῥᾳδίας ποιεῖ τὰς ἑκατέρωθεν ἀμοιβὰς τῶν φορτίων πρὸς ἀλλήλους τοῖς τοσοῦτον ἀφεστῶσιν. ἦν δ’ ὥσπερ ὁ πορθμὸς οὐκ εὔπλους ὁ κατὰ τὴν Σικελίαν τὸ παλαιόν, οὕτω καὶ τὰ πελάγη καὶ μάλιστα τὸ ὑπὲρ Μαλεῶν διὰ τὰς ἀντιπνοίας· ἀφ’ οὗ καὶ παροιμιάζονται Μαλέας δὲ κάμψας ἐπιλάθου τῶν οἴκαδε. ἀγαπητὸν οὖν ἑκατέροις ἦν τοῖς τε ἐκ τῆς Ἰταλίας καὶ ἐκ τῆς Ἀσίας ἐμπόροις, ἀφεῖσι τὸν περὶ Μαλέας πλοῦν, κατάγεσθαι τὸν φόρτον αὐτόθι· καὶ πεζῇ δὲ τῶν ἐκκομιζομένων ἐκ τῆς Πελοποννήσου καὶ τῶν εἰσαγομένων ἔπιπτε τὰ τέλη τοῖς τὰ κλεῖθρα ἔχουσι. διέμεινε δὲ τοῦτο καὶ εἰς ὕστερον μέχρι παντός· τοῖς δ’ ὕστερον καὶ πλείω προσεγίνετο πλεονεκτήματα· καὶ γὰρ ὁ Ἰσθμικὸς ἀγὼν ἐκεῖ συντελούμενος ὄχλους ἐπήγετο, καὶ οἱ Βακχιάδαι τυραννήσαντες, πλούσιοι καὶ πολλοὶ καὶ γένος λαμπροί, διακόσια ἔτη σχεδόν τι κατέσχον τὴν ἀρχὴν καὶ τὸ ἐμπόριον ἀδεῶς ἐκαρπώσαντο· τούτους δὲ Κύψελος καταλύσας αὐτὸς ἐτυράννησε, καὶ μέχρι τριγονίας ὁ οἶκος αὐτοῦ συνέμεινε· τοῦ δὲ περὶ τὸν οἶκον τοῦτον πλούτου μαρτύριον τὸ Ὀλυμπίασιν ἀνάθημα Κυψέλου, σφυρήλατος χρυσοῦς ἀνδριὰς εὐμεγέθης [Διός]. Δημάρατός τε, εἷς τῶν ἐν Κορίνθῳ δυναστευσάντων, φεύγων τὰς ἐκεῖ στάσεις τοσοῦτον ἠνέγκατο πλοῦτον οἴκοθεν εἰς τὴν Τυρρηνίαν ὥστε αὐτὸς μὲν ἦρξε τῆς δεξαμένης αὐτὸν πόλεως, ὁ δ’ υἱὸς αὐτοῦ καὶ Ῥωμαίων κατέστη βασιλεύς. τό τε τῆς Ἀφροδίτης ἱερὸν οὕτω πλούσιον ὑπῆρξεν ὥστε πλείους ἢ χιλίας ἱεροδούλους ἐκέκτητο ἑταίρας, ἃς ἀνετίθεσαν τῇ θεῷ καὶ ἄνδρες καὶ γυναῖκες. καὶ διὰ ταύτας οὖν πολυωχλεῖτο ἡ πόλις καὶ ἐπλουτίζετο· οἱ γὰρ ναύκληροι ῥᾳδίως ἐξανηλίσκοντο, καὶ διὰ τοῦτο ἡ παροιμία φησίν οὐ παντὸς ἀνδρὸς ἐς Κόρινθόν ἐσθ’ ὁ πλοῦς. καὶ δὴ καὶ μνημονεύεταί τις ἑταίρα πρὸς τὴν ὀνειδίζουσαν, ὅτι οὐ φιλεργὸς εἴη οὐδ’ ἐρίων ἅπτοιτο, εἰπεῖν “ἐγὼ μέντοι ἡ τοιαύτη τρεῖς ἤδη καθεῖλον ἱστοὺς ἐν βραχεῖ χρόνῳ τούτῳ.”", "st": "8.6.20"}, {"sp": "N", "t": "τὴν δὲ τοποθεσίαν τῆς πόλεως, ἐξ ὧν Ἱερώνυμός τε εἴρηκε καὶ Εὔδοξος καὶ ἄλλοι καὶ αὐτοὶ δὲ εἴδομεν νεωστὶ ἀναληφθείσης ὑπὸ τῶν Ῥωμαίων, τοιάνδε εἶναι συμβαίνει. ὄρος ὑψηλὸν ὅσον τριῶν ἥμισυ σταδίων ἔχον τὴν κάθετον, τὴν δ’ ἀνάβασιν καὶ τριάκοντα σταδίων, εἰς ὀξεῖαν τελευτᾷ κορυφήν· καλεῖται δὲ Ἀκροκόρινθος, οὗ τὸ μὲν πρὸς ἄρκτον μέρος ἐστὶ τὸ μάλιστα ὄρθιον, ὑφ’ ᾧ κεῖται ἡ πόλις ἐπὶ τραπεζώδους ἐπιπέδου χωρίου πρὸς αὐτῇ τῇ ῥίζῃ τοῦ Ἀκροκορίνθου. αὐτῆς μὲν οὖν τῆς πόλεως ὁ κύκλος καὶ τετταράκοντα σταδίων ὑπῆρχεν· ἐτετείχιστο δ’ ὅσον τῆς πόλεως γυμνὸν ἦν τοῦ ὄρους· συμπεριείληπτο δὲ τῷ περιβόλῳ τούτῳ καὶ τὸ ὄρος αὐτὸ ὁ Ἀκροκόρινθος ᾗ δυνατὸν ἦν τειχισμὸν δέξασθαι, καὶ ἡμῖν ἀναβαίνουσιν ἦν δῆλα τὰ ἐρείπια τῆς σχοινίας· ὥσθ’ ἡ πᾶσα περίμετρος ἐγίνετο περὶ πέντε καὶ ὀγδοήκοντα σταδίων. ἀπὸ δὲ τῶν ἄλλων μερῶν ἧττον ὄρθιόν ἐστι τὸ ὄρος, ἀνατέταται μέντοι ἐνθένδε ἱκανῶς καὶ περίοπτόν ἐστιν. ἡ μὲν οὖν κορυφὴ ναΐδιον ἔχει Ἀφροδίτης, ὑπὸ δὲ τῇ κορυφῇ τὴν Πειρήνην εἶναι συμβαίνει κρήνην, ἔκρυσιν μὲν οὐκ ἔχουσαν μεστὴν δ’ ἀεὶ διαυγοῦς καὶ ποτίμου ὕδατος. φασὶ δὲ καὶ ἐνθένδε καὶ ἐξ ἄλλων ὑπονόμων τινῶν φλεβίων συνθλίβεσθαι τὴν πρὸς τῇ ῥίζῃ τοῦ ὄρους κρήνην ἐκρέουσαν εἰς τὴν πόλιν ὥσθ’ ἱκανῶς ἀπ’ αὐτῆς ὑδρεύεσθαι. ἔστι δὲ καὶ φρεάτων εὐπορία κατὰ τὴν πόλιν, λέγουσι δὲ καὶ κατὰ τὸν Ἀκροκόρινθον· οὐ μὴν ἡμεῖς γε εἴδομεν. τοῦ δ’ οὖν Εὐριπίδου φήσαντος οὕτως<br>ἥκω περίκλυστον προλιποῦσ’ Ἀκροκόρινθον,<br>ἱερὸν ὄχθον, πόλιν Ἀφροδίτας,<br>τὸ περίκλυστον ἤτοι κατὰ βάθους δεκτέον, ἐπεὶ καὶ φρέατα καὶ ὑπόνομοι λιβάδες διήκουσι δι’ αὐτοῦ, ἢ τὸ παλαιὸν ὑποληπτέον τὴν Πειρήνην ἐπιπολάζειν καὶ κατάρρυτον ποιεῖν τὸ ὄρος. ἐνταῦθα δέ φασι πίνοντα τὸν Πήγασον ἁλῶναι ὑπὸ Βελλεροφόντου, πτηνὸν ἵππον ἐκ τοῦ τραχήλου τοῦ Μεδούσης ἀναπαλέντα κατὰ τὴν γοργοτομίαν· τὸν δ’ αὐτόν φασι καὶ τὴν Ἵππου κρήνην ἀναβαλεῖν ἐν τῷ Ἑλικῶνι πλήξαντα τῷ ὄνυχι τὴν ὑποῦσαν πέτραν. ὑπὸ δὲ τῇ Πειρήνῃ τὸ Σισύφειόν ἐστιν, ἱεροῦ τινος ἢ βασιλείου λευκῶν λίθων πεποιημένου διασῶζον ἐρείπια οὐκ ὀλίγα. ἀπὸ δὲ τῆς κορυφῆς πρὸς ἄρκτον μὲν ἀφορᾶται ὅ τε Παρνασσὸς καὶ ὁ Ἑλικών, ὄρη ὑψηλὰ καὶ νιφόβολα, καὶ ὁ Κρισαῖος κόλπος ὑποπεπτωκὼς ἀμφοτέροις, περιεχόμενος ὑπὸ τῆς Φωκίδος καὶ τῆς Βοιωτίας καὶ τῆς Μεγαρίδος καὶ τῆς ἀντιπόρθμου τῇ Φωκίδι Κορινθίας καὶ Σικυωνίας· πρὸς ἑσπέραν δὲ … ὑπέρκειται δὲ τούτων ἁπάντων τὰ καλούμενα Ὄνεια ὄρη διατείνοντα μέχρι Βοιωτίας καὶ Κιθαιρῶνος ἀπὸ τῶν Σκιρωνίδων πετρῶν, ἀπὸ τῆς παρὰ ταύτας ὁδοῦ πρὸς τὴν Ἀττικήν.", "st": "8.6.21"}, {"sp": "N", "t": "ἀρχὴ δὲ τῆς παραλίας ἑκατέρας τῆς μὲν τὸ Λέχαιον τῆς δὲ Κεγχρεαὶ κώμη καὶ λιμὴν ἀπέχων τῆς πόλεως ὅσον ἑβδομήκοντα σταδίους· τούτῳ μὲν οὖν χρῶνται πρὸς τοὺς ἐκ τῆς Ἀσίας πρὸς δὲ τοὺς ἐκ τῆς Ἰταλίας τῷ Λεχαίῳ. τὸ δὲ Λέχαιον ὑποπέπτωκε τῇ πόλει κατοικίαν ἔχον οὐ πολλήν· σκέλη δὲ καθείλκυσται σταδίων περὶ δώδεκα ἑκατέρωθεν τῆς ὁδοῦ τῆς ἐπὶ τὸ Λέχαιον. ἐντεῦθεν δὲ παρεκτείνουσα ἡ ᾐὼν μέχρι Παγῶν τῆς Μεγαρίδος κλύζεται μὲν ὑπὸ τοῦ Κορινθιακοῦ κόλπου, κοίλη δ’ ἐστὶ καὶ ποιεῖ τὸν δίολκον πρὸς τὴν ἑτέραν ᾐόνα τὴν κατὰ Σχοινοῦντα πλησίον ὄντα τῶν Κεγχρεῶν. ἐν δὲ τῷ μεταξὺ τοῦ Λεχαίου καὶ Παγῶν τὸ τῆς Ἀκραίας μαντεῖον Ἥρας ὑπῆρχε τὸ παλαιόν, καὶ αἱ Ὀλμιαὶ τὸ ποιοῦν ἀκρωτήριον τὸν κόλπον ἐν ᾧ ἥ τε Οἰνόη καὶ Παγαί, τὸ μὲν τῶν Μεγαρέων φρούριον ἡ δὲ Οἰνόη τῶν Κορινθίων. ἀπὸ [δὲ] τῶν Κεγχρεῶν ὁ Σχοινοῦς, καθ’ ὃν τὸ στενὸν τοῦ διόλκου· ἔπειθ’ ἡ Κρομμυωνία. πρόκειται δὲ τῆς ᾐόνος ταύτης ὅ τε Σαρωνικὸς κόλπος καὶ ὁ Ἐλευσινιακός, τρόπον τινὰ ὁ αὐτὸς ὤν, συνεχὴς τῷ Ἑρμιονικῷ. ἐπὶ δὲ τῷ Ἰσθμῷ καὶ τὸ τοῦ Ἰσθμίου Ποσειδῶνος ἱερὸν ἄλσει πιτυώδει συνηρεφές, ὅπου τὸν ἀγῶνα τῶν Ἰσθμίων Κορίνθιοι συνετέλουν. ἡ δὲ Κρομμυὼν ἔστι κώμη τῆς Κορινθίας, πρότερον δὲ τῆς Μεγαρίδος, ἐν ᾗ μυθεύουσι τὰ περὶ τὴν Κρομμυωνίαν ὗν, ἣν μητέρα τοῦ Καλυδωνίου κάπρου φασί· καὶ τῶν Θησέως ἄθλων ἕνα τοῦτον παραδιδόασι τὴν τῆς ὑὸς ταύτης ἐξαίρεσιν. καὶ ἡ Τενέα δ’ ἐστὶ κώμη τῆς Κορινθίας, ἐν ᾗ τοῦ Τενεάτου Ἀπόλλωνος ἱερόν· λέγεται δὲ καὶ Ἀρχίᾳ τῷ στείλαντι τὴν εἰς Συρακούσας ἀποικίαν τοὺς πλείστους τῶν ἐποίκων ἐντεῦθεν συνεπακολουθῆσαι, καὶ μετὰ ταῦτα εὐθηνεῖν μάλιστα τῶν ἄλλων τὴν κατοικίαν ταύτην, τὰ δ’ ὕστατα καὶ καθ’ αὑτοὺς πολιτεύεσθαι, προσθέσθαι τε τοῖς Ῥωμαίοις ἀποστάντας Κορινθίων καὶ κατασκαφείσης τῆς πόλεως συμμεῖναι. φέρεται δὲ καὶ χρησμὸς ὁ δοθείς τινι τῶν ἐκ τῆς Ἀσίας ἐρωτῶντι εἰ λῷον εἴη μετοικεῖν εἰς Κόρινθον<br>εὐδαίμων ὁ Κόρινθος, ἐγὼ δ’ εἴην Τενεάτης.<br>ὅπερ κατ’ ἄγνοιάν τινες παρατρέπουσιν “ἐγὼ δ’ εἴην Τεγεάτης.” λέγεται δ’ ἐνταῦθα ἐκθρέψαι Πόλυβος τὸν Οἰδίπουν. δοκεῖ δὲ καὶ συγγένειά τις εἶναι Τενεδίοις πρὸς τούτους ἀπὸ Τέννου τοῦ Κύκνου, καθάπερ εἴρηκεν Ἀριστοτέλης· καὶ ἡ τοῦ Ἀπόλλωνος δὲ τιμὴ παρ’ ἀμφοτέροις ὁμοία οὖσα δίδωσιν οὐ μικρὰ σημεῖα.", "st": "8.6.22"}, {"sp": "N", "t": "Κορίνθιοι δ’ ὑπὸ Φιλίππῳ ὄντες ἐκείνῳ τε συνεφιλονείκησαν καὶ ἰδίᾳ πρὸς Ῥωμαίους ὑπεροπτικῶς εἶχον, ὥστε τινὲς καὶ τῶν πρέσβεων παριόντων τὴν οἰκίαν αὐτῶν ἐθάρρησαν καταντλῆσαι βόρβορον. ἀντὶ τούτων μὲν οὖν καὶ ἄλλων ὧν ἐξήμαρτον ἔτισαν δίκας αὐτίκα· πεμφθείσης γὰρ ἀξιολόγου στρατιᾶς, αὐτή τε κατέσκαπτο ὑπὸ Λευκίου Μομμίου καὶ τἆλλα μέχρι Μακεδονίας ὑπὸ Ῥωμαίοις ἐγένετο, ἐν ἄλλοις ἄλλων πεμπομένων στρατηγῶν· τὴν δὲ χώραν ἔσχον Σικυώνιοι τὴν πλείστην τῆς Κορινθίας. Πολύβιος δὲ τὰ συμβάντα περὶ τὴν ἅλωσιν ἐν οἴκτου μέρει λέγων προστίθησι καὶ τὴν στρατιωτικὴν ὀλιγωρίαν τὴν περὶ τὰ τῶν τεχνῶν ἔργα καὶ τὰ ἀναθήματα. φησὶ γὰρ ἰδεῖν παρὼν ἐρριμμένους πίνακας ἐπ’ ἐδάφους, πεττεύοντας δὲ τοὺς στρατιώτας ἐπὶ τούτων. ὀνομάζει δ’ αὐτῶν Ἀριστείδου γραφὴν τοῦ Διονύσου, ἐφ’ οὗ τινες εἰρῆσθαί φασι τὸ “οὐδὲν πρὸς τὸν Διόνυσον,” καὶ τὸν Ἡρακλέα τὸν καταπονούμενον τῷ τῆς Δηιανείρας χιτῶνι. τοῦτον μὲν οὖν οὐχ ἑωράκαμεν ἡμεῖς, τὸν δὲ Διόνυσον ἀνακείμενον ἐν τῷ Δημητρείῳ τῷ ἐν Ῥώμῃ κάλλιστον ἔργον ἑωρῶμεν· ἐμπρησθέντος δὲ τοῦ νεὼ συνηφανίσθη καὶ ἡ γραφὴ νεωστί. σχεδὸν δέ τι καὶ τῶν ἄλλων ἀναθημάτων τῶν ἐν Ῥώμῃ τὰ πλεῖστα καὶ ἄριστα ἐντεῦθεν ἀφῖχθαι· τινὰ δὲ καὶ αἱ κύκλῳ τῆς Ῥώμης πόλεις ἔσχον. μεγαλόφρων γὰρ ὢν μᾶλλον ἢ φιλότεχνος ὁ Μόμμιος, ὥς φασι, μετεδίδου ῥᾳδίως τοῖς δεηθεῖσι. Λεύκολλος δὲ κατασκευάσας τὸ τῆς Εὐτυχίας ἱερὸν καὶ στοάν τινα χρῆσιν ᾐτήσατο ὧν εἶχεν ἀνδριάντων ὁ Μόμμιος, ὡς κοσμήσων τὸ ἱερὸν μέχρι ἀναδείξεως, εἶτ’ ἀποδώσων· οὐκ ἀπέδωκε δέ, ἀλλ’ ἀνέθηκε κελεύσας αἴρειν εἰ βούλεται· πράως δ’ ἤνεγκεν ἐκεῖνος οὐ φροντίσας οὐδέν, ὥστ’ ηὐδοκίμει τοῦ ἀναθέντος μᾶλλον. πολὺν δὲ χρόνον ἐρήμη μείνασα ἡ Κόρινθος ἀνελήφθη πάλιν ὑπὸ Καίσαρος τοῦ θεοῦ διὰ τὴν εὐφυΐαν, ἐποίκους πέμψαντος τοῦ ἀπελευθερικοῦ γένους πλείστους· οἳ τὰ ἐρείπια κινοῦντες καὶ τοὺς τάφους συνανασκάπτοντες εὕρισκον ὀστρακίνων τορευμάτων πλήθη, πολλὰ δὲ καὶ χαλκώματα· θαυμάζοντες δὲ τὴν κατασκευὴν οὐδένα τάφον ἀσκευώρητον εἴασαν, ὥστε εὐπορήσαντες τῶν τοιούτων καὶ διατιθέμενοι πολλοῦ νεκροκορινθίων ἐπλήρωσαν τὴν Ῥώμην· οὕτω γὰρ ἐκάλουν τὰ ἐκ τῶν τάφων ληφθέντα, καὶ μάλιστα τὰ ὀστράκινα. κατ’ ἀρχὰς μὲν οὖν ἐτιμήθη σφόδρα ὁμοίως τοῖς χαλκώμασι τοῖς κορινθιουργέσιν, εἶτ’ ἐπαύσαντο τῆς σπουδῆς, ἐκλιπόντων τῶν ὀστράκων καὶ οὐδὲ κατωρθωμένων τῶν πλείστων. ἡ μὲν δὴ πόλις ἡ τῶν Κορινθίων μεγάλη τε καὶ πλουσία διὰ παντὸς ὑπῆρξεν, ἀνδρῶν τε ηὐπόρησεν ἀγαθῶν εἴς τε τὰ πολιτικὰ καὶ εἰς τὰς τέχνας τὰς δημιουργικάς· μάλιστα γὰρ καὶ ἐνταῦθα καὶ ἐν Σικυῶνι ηὐξήθη γραφική τε καὶ πλαστικὴ καὶ πᾶσα ἡ τοιαύτη δημιουργία. χώραν δ’ ἔσχεν οὐκ εὔγεων σφόδρα, ἀλλὰ σκολιάν τε καὶ τραχεῖαν, ἀφ’ οὗ πάντες ὀφρυόεντα Κόρινθον εἰρήκασι καὶ παροιμιάζονται Κόρινθος ὀφρυᾷ τε καὶ κοιλαίνεται.", "st": "8.6.23"}, {"sp": "N", "t": "Ὀρνεαὶ δ’ εἰσὶν ἐπώνυμοι τῷ παραρρέοντι ποταμῷ, νῦν μὲν ἔρημοι πρότερον δ’ οἰκούμεναι καλῶς, ἱερὸν ἔχουσαι Πριάπου τιμώμενον, ἀφ’ ὧν καὶ ὁ τὰ Πριάπεια ποιήσας Εὐφορίων Ὀρνεάτην καλεῖ τὸν θεόν· κεῖνται δ’ ὑπὲρ τοῦ πεδίου τοῦ Σικυωνίων, τὴν δὲ χώραν ἔσχον Ἀργεῖοι. Ἀραιθυρέα δ’ ἐστὶν ἡ νῦν Φλιασία καλουμένη, πόλιν δ’ εἶχεν ὁμώνυμον τῇ χώρᾳ πρὸς ὄρει Κηλώσσῃ· οἱ δ’ ὕστερον ἀναστάντες ἐκεῖθεν πρὸ τριάκοντα σταδίων ἔκτισαν πόλιν, ἣν ἐκάλεσαν Φλιοῦντα· τῆς δὲ Κηλώσσης μέρος ὁ Καρνεάτης, ὅθεν λαμβάνει τὴν ἀρχὴν Ἀσωπὸς ὁ παραρρέων τὴν Σικυῶνα καὶ ποιῶν τὴν Ἀσωπίαν χώραν, μέρος οὖσαν τῆς Σικυωνίας. ἔστι δ’ Ἀσωπὸς καὶ ὁ παρὰ Θήβας ῥέων καὶ Πλαταιὰς καὶ Τάναγραν, ἄλλος δ’ ἔστιν ἐν Ἡρακλείᾳ τῇ Τραχινίᾳ παρὰ κώμην ῥέων ἣν Παρασωπίους ὀνομάζουσι, τέταρτος δ’ ὁ ἐν Πάρῳ. κεῖται δ’ ὁ Φλιοῦς ἐν μέσῳ Σικυωνίας Ἀργείας Κλεωνῶν καὶ Στυμφάλου κύκλῳ περιεχόμενος· τιμᾶται δ’ ἐν Φλιοῦντι καὶ Σικυῶνι τὸ τῆς Δίας ἱερόν· καλοῦσι δ’ οὕτω τὴν Ἥβην.", "st": "8.6.24"}, {"sp": "N", "t": "τὴν δὲ Σικυῶνα πρότερον Μηκώνην ἐκάλουν, ἔτι δὲ πρότερον Αἰγιαλεῖς· ἀνῴκισε δ’ αὐτὴν ἀπὸ θαλάττης ὅσον εἴκοσι σταδίοις (οἱ δὲ δώδεκά φασιν) ἐπὶ λόφον ἐρυμνὸν Δημήτριος· τὸ δὲ παλαιὸν κτίσμα ἐπίνειόν ἐστιν ἔχον λιμένα. ὁρίζει δὲ τὴν Σικυωνίαν καὶ τὴν Κορινθίαν ποταμὸς Νεμέα· ἐτυραννήθη δὲ πλεῖστον χρόνον, ἀλλ’ ἀεὶ τοὺς τυράννους ἐπιεικεῖς ἄνδρας ἔσχεν, Ἄρατον δ’ ἐπιφανέστατον, ὃς καὶ τὴν πόλιν ἠλευθέρωσε, καὶ Ἀχαιῶν ἦρξε παρ’ ἑκόντων λαβὼν τὴν ἐξουσίαν, καὶ τὸ σύστημα ηὔξησε προσθεὶς αὐτῷ τήν τε πατρίδα καὶ τὰς ἄλλας πόλεις τὰς ἐγγύς. Ὑπερησίην δὲ καὶ τὰς ἑξῆς πόλεις ἃς ὁ ποιητὴς λέγει, καὶ τὸν Αἰγιαλὸν τῶν Ἀχαιῶν ἤδη συμβέβηκεν εἶναι μέχρι Δύμης καὶ τῶν ὅρων τῆς Ἠλείας.", "st": "8.6.25"}, {"sp": "N", "t": "ταύτης δὲ τῆς χώρας τὸ μὲν παλαιὸν Ἴωνες ἐκράτουν, ἐξ Ἀθηναίων τὸ γένος ὄντες, ἐκαλεῖτο δὲ τὸ μὲν παλαιὸν Αἰγιάλεια καὶ οἱ ἐνοικοῦντες Αἰγιαλεῖς, ὕστερον δ’ ἀπ’ ἐκείνων Ἰωνία, καθάπερ καὶ ἡ Ἀττική, ἀπὸ Ἴωνος τοῦ Ξούθου. φασὶ δὲ Δευκαλίωνος μὲν Ἕλληνα εἶναι, τοῦτον δὲ περὶ τὴν Φθίαν τῶν μεταξὺ Πηνειοῦ καὶ Ἀσωποῦ δυναστεύοντα τῷ πρεσβυτάτῳ τῶν παίδων παραδοῦναι τὴν ἀρχήν, τοὺς δ’ ἄλλους ἔξω διαπέμψαι ζητήσοντας ἵδρυσιν ἕκαστον αὑτῷ· ὧν Δῶρος μὲν τοὺς περὶ Παρνασσὸν Δωριέας συνοικίσας κατέλιπεν ἐπωνύμους αὑτοῦ, Ξοῦθος δὲ τὴν Ἐρεχθέως θυγατέρα γήμας ᾤκισε τὴν τετράπολιν τῆς Ἀττικῆς, Οἰνόην Μαραθῶνα Προβάλινθον καὶ Τρικόρυνθον. τῶν δὲ τούτου παίδων Ἀχαιὸς μὲν φόνον ἀκούσιον πράξας ἔφυγεν εἰς Λακεδαίμονα καὶ Ἀχαιοὺς τοὺς ἐκεῖ κληθῆναι παρεσκεύασεν, Ἴων δὲ τοὺς μετ’ Εὐμόλπου νικήσας Θρᾷκας οὕτως ηὐδοκίμησεν ὥστ’ ἐπέτρεψαν αὐτῷ τὴν πολιτείαν Ἀθηναῖοι. ὁ δὲ πρῶτον μὲν εἰς τέτταρας φυλὰς διεῖλε τὸ πλῆθος, εἶτα εἰς τέτταρας βίους· τοὺς μὲν γὰρ γεωργοὺς ἀπέδειξε τοὺς δὲ δημιουργοὺς τοὺς δὲ ἱεροποιούς, τετάρτους δὲ τοὺς φύλακας· τοιαῦτα δὲ πλείω διατάξας τὴν χώραν ἐπώνυμον ἑαυτοῦ κατέλιπεν. οὕτω δὲ πολυανδρῆσαι τὴν χώραν τότε συνέπεσεν ὥστε καὶ ἀποικίαν τῶν Ἰώνων ἔστειλαν εἰς Πελοπόννησον Ἀθηναῖοι, καὶ τὴν χώραν ἣν κατέσχον ἐπώνυμον ἑαυτῶν ἐποίησαν Ἰωνίαν ἀντ’ Αἰγιάλου κληθεῖσαν, οἵ τε ἄνδρες ἀντὶ Αἰγιαλέων Ἴωνες προσηγορεύθησαν εἰς δώδεκα πόλεις μερισθέντες. μετὰ δὲ τὴν Ἡρακλειδῶν κάθοδον ὑπ’ Ἀχαιῶν ἐξελαθέντες ἐπανῆλθον πάλιν εἰς Ἀθήνας· ἐκεῖθεν δὲ μετὰ τῶν Κοδριδῶν ἔστειλαν τὴν Ἰωνικὴν ἀποικίαν εἰς τὴν Ἀσίαν· ἔκτισαν δὲ δώδεκα πόλεις ἐν τῇ παραλίᾳ τῆς Καρίας καὶ τῆς Λυδίας, εἰς τοσαῦτα μέρη διελόντες σφᾶς ὅσα καὶ ἐν τῇ Πελοποννήσῳ κατεῖχον. οἱ δ’ Ἀχαιοὶ Φθιῶται μὲν ἦσαν τὸ γένος, ᾤκησαν δ’ ἐν Λακεδαίμονι, τῶν δ’ Ἡρακλειδῶν ἐπικρατησάντων ἀναληφθέντες ὑπὸ Τισαμενοῦ τοῦ Ὀρέστου παιδός, ὡς προειρήκαμεν, τοῖς Ἴωσιν ἐπέθεντο, καὶ γενόμενοι κρείττους τοὺς μὲν ἐξέβαλον, αὐτοὶ δὲ κατέσχον τὴν γῆν, καὶ διεφύλαξαν τὸν αὐτὸν τῆς χώρας μερισμὸν ὅνπερ καὶ παρέλαβον. οὕτω δ’ ἴσχυσαν ὥστε τὴν ἄλλην Πελοπόννησον ἐχόντων τῶν Ἡρακλειδῶν ὧν ἀπέστησαν, ἀντεῖχον ὅμως πρὸς ἅπαντας Ἀχαΐαν ὀνομάσαντες τὴν χώραν. ἀπὸ μὲν οὖν Τισαμενοῦ μέχρι Ὠγύγου βασιλευόμενοι διετέλουν· εἶτα δημοκρατηθέντες τοσοῦτον ηὐδοκίμησαν περὶ τὰς πολιτείας ὥστε τοὺς Ἰταλιώτας μετὰ τὴν στάσιν τὴν πρὸς τοὺς Πυθαγορείους τὰ πλεῖστα τῶν νομίμων μετενέγκασθαι παρὰ τούτων συνέβη· μετὰ δὲ τὴν ἐν Λεύκτροις μάχην ἐπέτρεψαν Θηβαῖοι τούτοις τὴν δίαιταν περὶ τῶν ἀντιλεγομένων ταῖς πόλεσι πρὸς ἀλλήλας· ὕστερον δ’ ὑπὸ Μακεδόνων λυθείσης τῆς κοινωνίας ἀνέλαβον σφᾶς πάλιν κατὰ μικρόν· ἦρξαν δὲ Πύρρου στρατεύσαντος εἰς Ἰταλίαν τέτταρες συνιοῦσαι πόλεις, ὧν ἦσαν Πάτραι καὶ Δύμη· εἶτα προσελάμβανόν τινας τῶν δώδεκα πλὴν Ὠλένου καὶ Ἑλίκης, τῆς μὲν οὐ συνελθούσης τῆς δ’ ἀφανισθείσης ὑπὸ κύματος.", "st": "8.7.1"}, {"sp": "N", "t": "ἐξαρθὲν γὰρ ὑπὸ σεισμοῦ τὸ πέλαγος κατέκλυσε καὶ αὐτὴν καὶ τὸ ἱερὸν τοῦ Ἑλικωνίου Ποσειδῶνος, ὃν καὶ νῦν ἔτι τιμῶσιν Ἴωνες, καὶ θύουσιν ἐκεῖ τὰ Πανιώνια. μέμνηται δ’, ὡς ὑπονοοῦσί τινες, ταύτης τῆς θυσίας Ὅμηρος ὅταν φῇ<br>αὐτὰρ ὁ θυμὸν ἄισθε καὶ ἤρυγεν, ὡς ὅτε ταῦρος<br>ἤρυγεν ἑλκόμενος Ἑλικώνιον ἀμφὶ ἄνακτα.<br>τεκμαίρονταί τε νεώτερον εἶναι τῆς Ἰωνικῆς ἀποικίας τὸν ποιητήν, μεμνημένον γε τῆς Πανιωνικῆς θυσίας ἣν ἐν τῇ Πριηνέων χώρᾳ συντελοῦσιν Ἴωνες τῷ Ἑλικωνίῳ Ποσειδῶνι, ἐπεὶ καὶ αὐτοὶ οἱ Πριηνεῖς ἐξ Ἑλίκης εἶναι λέγονται· καὶ δὴ πρὸς τὴν θυσίαν ταύτην καθιστᾶσιν ἄνδρα νέον Πριηνέα τὸν τῶν ἱερῶν ἐπιμελησόμενον. τεκμηριοῦνται δ’ ἔτι μᾶλλον τὸ προκείμενον ἐκ τῶν περὶ τοῦ ταύρου πεφρασμένων· τότε γὰρ νομίζουσι καλλιερεῖν περὶ τὴν θυσίαν ταύτην Ἴωνες, ὅταν θυόμενος ὁ ταῦρος μυκήσηται. οἱ δ’ ἀντιλέγοντες μεταφέρουσιν εἰς τὴν Ἑλίκην τὰ λεχθέντα τεκμήρια περὶ τοῦ ταύρου καὶ τῆς θυσίας, ὡς ἐκεῖ νενομισμένων τούτων καὶ τοῦ ποιητοῦ παραβάλλοντος τὰ ἐκεῖ συντελούμενα. κατεκλύσθη δ’ ἡ Ἑλίκη δυσὶν ἔτεσι πρὸ τῶν Λευκτρικῶν. Ἐρατοσθένης δὲ καὶ αὐτὸς ἰδεῖν φησι τὸν τόπον, καὶ τοὺς πορθμέας λέγειν ὡς ἐν τῷ πόρῳ ὀρθὸς ἑστήκει Ποσειδῶν χάλκεος, ἔχων ἱππόκαμπον ἐν τῇ χειρὶ κίνδυνον φέροντα τοῖς δικτυεῦσιν. Ἡρακλείδης δέ φησι κατ’ αὐτὸν γενέσθαι τὸ πάθος νύκτωρ, δώδεκα σταδίους διεχούσης τῆς πόλεως ἀπὸ θαλάττης καὶ τούτου τοῦ χωρίου παντὸς σὺν τῇ πόλει καλυφθέντος, δισχιλίους δὲ παρὰ τῶν Ἀχαιῶν πεμφθέντας ἀνελέσθαι μὲν τοὺς νεκροὺς μὴ δύνασθαι, τοῖς δ’ ὁμόροις νεῖμαι τὴν χώραν. συμβῆναι δὲ τὸ πάθος κατὰ μῆνιν Ποσειδῶνος· τοὺς γὰρ ἐκ τῆς Ἑλίκης ἐκπεσόντας Ἴωνας αἰτεῖν πέμψαντας παρὰ τῶν Ἑλικέων μάλιστα μὲν τὸ βρέτας τοῦ Ποσειδῶνος, εἰ δὲ μή, τοῦ γε ἱεροῦ τὴν ἀφίδρυσιν· οὐ δόντων δὲ πέμψαι πρὸς τὸ κοινὸν τῶν Ἀχαιῶν· τῶν δὲ ψηφισαμένων οὐδ’ ὣς ὑπακοῦσαι· τῷ δ’ ἑξῆς χειμῶνι συμβῆναι τὸ πάθος, τοὺς δ’ Ἀχαιοὺς ὕστερον δοῦναι τὴν ἀφίδρυσιν τοῖς Ἴωσιν. Ἡσίοδος δὲ καὶ ἄλλης Ἑλίκης μέμνηται Θετταλικῆς.", "st": "8.7.2"}, {"sp": "N", "t": "εἴκοσι μὲν δὴ ἔτη διετέλεσαν γραμματέα κοινὸν ἔχοντες καὶ στρατηγοὺς δύο κατ’ ἐνιαυτὸν οἱ Ἀχαιοί, καὶ κοινοβούλιον εἰς ἕνα τόπον συνήγετο αὐτοῖς (ἐκαλεῖτο δὲ Ἁμάριον) ἐν ᾧ τὰ κοινὰ ἐχρημάτιζον καὶ οὗτοι καὶ Ἴωνες πρότερον· εἶτα ἔδοξεν ἕνα χειροτονεῖσθαι στρατηγόν. Ἄρατος δὲ στρατηγήσας ἀφείλετο Ἀντίγονον τὸν Ἀκροκόρινθον, καὶ τὴν πόλιν τοῖς Ἀχαιοῖς προσέθηκε καθάπερ καὶ τὴν πατρίδα· προσελάβετο δὲ καὶ Μεγαρέας· καὶ τὰς παρ’ ἑκάστοις τυραννίδας καταλύων Ἀχαιοὺς ἐποίει τοὺς ἐλευθερωθέντας … τὴν δὲ Πελοπόννησον ἠλευθέρωσε τῶν τυραννίδων, ὥστε καὶ Ἄργος καὶ Ἑρμιὼν καὶ Φλιοῦς καὶ Μεγάλη πόλις, ἡ μεγίστη τῶν ἐν Ἀρκαδίᾳ, προσετέθη τοῖς Ἀχαιοῖς, ὅτε δὴ καὶ πλεῖστον ηὔξηντο. ἦν δ’ ὁ καιρὸς ἡνίκα Ῥωμαῖοι Καρχηδονίους ἐκ τῆς Σικελίας ἐκβαλόντες ἐστράτευσαν ἐπὶ τοὺς περὶ τὸν Πάδον Γαλάτας. μέχρι δὲ τῆς Φιλοποίμενος στρατηγίας συμμείναντες ἱκανῶς οἱ Ἀχαιοὶ διελύθησαν κατ’ ὀλίγον, ἤδη Ῥωμαίων ἐχόντων τὴν Ἑλλάδα σύμπασαν καὶ οὐ τὸν αὐτὸν τρόπον ἑκάστοις χρωμένων, ἀλλὰ τοὺς μὲν συνέχειν τοὺς δὲ καταλύειν βουλομένων …", "st": "8.7.3"}, {"sp": "N", "t": "ἡ δὲ τάξις τῶν τόπων, οὓς κατῴκουν εἰς δώδεκα μέρη διῃρημένοι, τοιαύτη τίς ἐστι· μετὰ Σικυῶνα Πελλήνη κεῖται· εἶτα Αἴγειρα δευτέρα· τρίτη Αἰγαί, Ποσειδῶνος ἱερὸν ἔχουσα· τετάρτη Βοῦρα· μετ’ αὐτὴν Ἑλίκη, εἰς ἣν καταπεφεύγεισαν Ἴωνες, μάχῃ κρατηθέντες ὑπ’ Ἀχαιῶν, καὶ τὸ τελευταῖον ἐξέπεσον ἐνθένδε· μετὰ δὲ Ἑλίκην Αἴγιον καὶ Ῥύπες καὶ Πατρεῖς καὶ Φαρεῖς· εἶτ’ Ὤλενος, παρ’ ὃν Πεῖρος ποταμὸς μέγας· εἶτα Δύμη καὶ Τριταιεῖς. οἱ μὲν οὖν Ἴωνες κωμηδὸν ᾤκουν, οἱ δ’ Ἀχαιοὶ πόλεις ἔκτισαν, ὧν εἴς τινας ὕστερον συνῴκισαν καὶ ἐκ τῶν ἄλλων μερίδων ἐνίας, καθάπερ τὰς Αἰγὰς εἰς Αἴγειραν (Αἰγαῖοι δ’ ἐλέγοντο οἱ ἐνοικοῦντες), Ὤλενον δὲ εἰς Δύμην. δείκνυται δ’ ἴχνη μεταξὺ Πατρῶν καὶ Δύμης τοῦ παλαιοῦ τῶν Ὠλενίων κτίσματος· αὐτοῦ δὲ καὶ τὸ τοῦ Ἀσκληπιοῦ ἱερὸν ἐπίσημον, [ὃ] Δύμης μὲν ἀπέχει τετταράκοντα σταδίους, Πατρῶν δὲ ὀγδοήκοντα. ὁμώνυμοι δ’ εἰσὶ ταῖς μὲν Αἰγαῖς ταύταις αἱ ἐν Εὐβοίᾳ, τῷ δὲ Ὠλένῳ τὸ ἐν Αἰτωλίᾳ κτίσμα καὶ αὐτὸ ἴχνη σῶζον μόνον. ὁ δὲ ποιητὴς τοῦ μὲν ἐν Ἀχαΐᾳ Ὠλένου οὐ μέμνηται, ὥσπερ οὐδ’ ἄλλων πλειόνων τῶν περὶ τὸν Αἰγιαλὸν οἰκούντων, ἀλλὰ κοινότερον λέγει<br>αἰγιαλόν τ’ ἀνὰ πάντα καὶ ἀμφ’ Ἑλίκην εὐρεῖαν.<br>τοῦ δ’ Αἰτωλικοῦ μέμνηται ὅταν φῇ<br>οἳ Πλευρῶν’ ἐνέμοντο καὶ Ὤλενον.<br>τὰς δ’ Αἰγὰς ἀμφοτέρας λέγει, τὴν μὲν Ἀχαϊκήν<br>οἱ δέ τοι εἰς Ἑλίκην τε καὶ Αἰγὰς δῶρ’ ἀνάγουσι.<br>ὅταν δὲ φῇ<br>Αἰγάς, ἔνθα τέ οἱ κλυτὰ δώματα βένθεσι λίμνης·<br>ἔνθ’ ἵππους ἔστησε Ποσειδάων,<br>βέλτιον δέχεσθαι τὰς ἐν Εὐβοίᾳ, ἀφ’ ὧν εἰκὸς καὶ τὸ πέλαγος Αἰγαῖον λεχθῆναι· ἐκεῖ δὲ καὶ τῷ Ποσειδῶνι ἡ πραγματεία πεποίηται ἡ περὶ τὸν Τρωικὸν πόλεμον. πρὸς δὲ ταῖς Ἀχαϊκαῖς Αἰγαῖς ὁ Κρᾶθις ῥεῖ ποταμὸς ἐκ δυεῖν ποταμῶν αὐξόμενος, ἀπὸ τοῦ κίρνασθαι τὴν ὀνομασίαν ἔχων· ἀφ’ οὗ καὶ ὁ ἐν Ἰταλίᾳ Κρᾶθις.", "st": "8.7.4"}, {"sp": "N", "t": "ἑκάστη δὲ τῶν δώδεκα μερίδων ἐκ δήμων συνειστήκει ἑπτὰ καὶ ὀκτώ· τοσοῦτον εὐανδρεῖν τὴν χώραν συνέβαινεν. ἔστι δ’ ἡ Πελλήνη στάδια ἑξήκοντα τῆς θαλάττης ὑπερκειμένη, φρούριον ἐρυμνόν. ἔστι δὲ καὶ κώμη Πελλήνη, ὅθεν καὶ αἱ Πελληνικαὶ χλαῖναι, ἃς καὶ ἆθλα ἐτίθεσαν ἐν τοῖς ἀγῶσι· κεῖται δὲ μεταξὺ Αἰγίου καὶ Πελλήνης· τὰ δὲ Πέλλανα ἕτερα τούτων ἐστί, Λακωνικὸν χωρίον, ὡς πρὸς τὴν Μεγαλοπολῖτιν νεῦον. Αἴγειρα δὲ ἐπὶ βουνοῦ κεῖται. Βοῦρα δ’ ὑπέρκειται τῆς θαλάττης ἐν τετταράκοντά πως σταδίοις, ἣν ὑπὸ σεισμοῦ καταποθῆναι συνέβη. ἀπὸ δὲ τῆς ἐνταῦθα κρήνης Συβάριδος τὸν κατὰ τὴν Ἰταλίαν ποταμὸν ὀνομασθῆναί φασιν. ἡ δ’ Αἰγὰ (καὶ γὰρ οὕτω λέγουσι τὰς Αἰγὰς) νῦν μὲν οὐκ οἰκεῖται, τὴν δὲ χώραν ἔχουσιν Αἰγιεῖς. Αἴγιον δὲ ἱκανῶς οἰκεῖται· ἱστοροῦσι δ’ ἐνταῦθα τὸν Δία ὑπ’ αἰγὸς ἀνατραφῆναι, καθάπερ φησὶ καὶ Ἄρατος<br>αἲξ ἱερή, τὴν μέν τε λόγος Διὶ μαζὸν ἐπισχεῖν.<br>ἐπιλέγει δὲ καὶ ὅτι<br>Ὠλενίην δέ μιν αἶγα Διὸς καλέουσ’ ὑποφῆται<br>δηλῶν τὸν τόπον διότι πλησίον Ὠλένη. αὐτοῦ δὲ καὶ ἡ Κερύνεια ἐπὶ πέτρας ὑψηλῆς ἱδρυμένη. Αἰγιέων δ’ ἐστὶ καὶ ταῦτα καὶ Ἑλίκη καὶ τὸ τοῦ Διὸς ἄλσος τὸ Ἁμάριον, ὅπου συνῄεσαν οἱ Ἀχαιοὶ βουλευσόμενοι περὶ τῶν κοινῶν. ῥεῖ δὲ διὰ τῆς Αἰγιέων ὁ Σελινοῦς ποταμός, ὁμώνυμος τῷ τε ἐν Ἐφέσῳ παρὰ τὸ Ἀρτεμίσιον ῥέοντι, καὶ τῷ ἐν τῇ νῦν Ἠλείᾳ τῷ παραρρέοντι τὸ χωρίον ὅ φησιν ὠνήσασθαι τῇ Ἀρτέμιδι Ξενοφῶν κατὰ χρησμόν· ἄλλος δὲ Σελινοῦς ὁ παρὰ τοῖς Ὑβλαίοις Μεγαρεῦσιν, οὓς ἀνέστησαν Καρχηδόνιοι. τῶν δὲ λοιπῶν πόλεων τῶν Ἀχαϊκῶν εἴτε μερίδων Ῥύπες μὲν οὐκ οἰκοῦνται, τὴν δὲ χώραν Ῥυπίδα καλουμένην ἔσχον Αἰγιεῖς καὶ Φαριεῖς· ἐκ δὲ τῶν Ῥυπῶν ἦν ὁ Μύσκελλος ὁ Κρότωνος οἰκιστής· τῆς δὲ Ῥυπίδος καὶ τὸ Λεῦκτρον ἦν, δῆμος τῶν Ῥυπῶν. μετὰ δὲ τούτους Πάτραι πόλις ἀξιόλογος· μεταξὺ δὲ τὸ Ῥίον ἀπέχον Πατρῶν στάδια τετταράκοντα. Ῥωμαῖοι δὲ νεωστὶ μετὰ τὴν Ἀκτιακὴν νίκην ἵδρυσαν αὐτόθι τῆς στρατιᾶς μέρος ἀξιόλογον, καὶ διαφερόντως εὐανδρεῖ νῦν ἀποικία Ῥωμαίων οὖσα· ἔχει δὲ ὕφορμον μέτριον. ἐφεξῆς δ’ ἐστὶν ἡ Δύμη, πόλις ἀλίμενος, πασῶν δυσμικωτάτη, ἀφ’ οὗ καὶ τοὔνομα· πρότερον δ’ ἐκαλεῖτο Στράτος· διαιρεῖ δ’ αὐτὴν ἀπὸ τῆς Ἠλείας κατὰ Βουπράσιον ὁ Λάρισος ποταμός, ῥέων ἐξ ὄρους· τοῦτο δ’ οἱ μὲν Σκόλλιν καλοῦσιν, Ὅμηρος δὲ πέτρην Ὠλενίην. τοῦ δ’ Ἀντιμάχου Καυκωνίδα τὴν Δύμην εἰπόντος, οἱ μὲν ἐδέξαντο ἀπὸ τῶν Καυκώνων ἐπιθέτως εἰρῆσθαι αὐτὸ μέχρι δεῦρο καθηκόντων, καθάπερ ἐπάνω προείπομεν· οἱ δ’ ἀπὸ Καύκωνος ποταμοῦ τινος, ὡς αἱ Θῆβαι Διρκαῖαι καὶ Ἀσωπίδες, Ἄργος δ’ Ἰνάχειον, Τροία δὲ Σιμουντίς. δέδεκται δ’ οἰκήτορας καὶ ἡ Δύμη μικρὸν πρὸ ἡμῶν ἀνθρώπους μιγάδας, οὓς ἀπὸ τοῦ πειρατικοῦ πλήθους περιλιπεῖς ἔσχε Πομπήιος, καταλύσας τὰ λῃστήρια καὶ ἱδρύσας τοὺς μὲν ἐν Σόλοις τοῖς Κιλικίοις τοὺς δ’ ἄλλοθι καὶ δὴ καὶ ἐνταῦθα. ἡ δὲ Φάρα συνορεῖ μὲν τῇ Δυμαίᾳ. καλοῦνται δὲ οἱ μὲν ἐκ ταύτης τῆς Φάρας Φαρεῖς, οἱ δ’ ἐκ τῆς Μεσσηνιακῆς Φαραιᾶται· ἔστι δ’ ἐν τῇ Φαραϊκῇ Δίρκη κρήνη ὁμώνυμος τῇ ἐν Θήβαις. ἡ δ’ Ὤλενος ἔστι μὲν ἔρημος, κεῖται δὲ μεταξὺ Πατρῶν καὶ Δύμης· ἔχουσι δὲ Δυμαῖοι τὴν χώραν. εἶτ’ Ἄραξος, τὸ ἀκρωτήριον τῆς Ἠλείας, ἀπὸ Ἰσθμοῦ στάδιοι χίλιοι [τριάκοντα].", "st": "8.7.5"}, {"sp": "N", "t": "Ἀρκαδία δ’ ἐστὶν ἐν μέσῳ μὲν τῆς Πελοποννήσου, πλείστην δὲ χώραν ὀρεινὴν ἀποτέμνεται. μέγιστον δ’ ὄρος ἐν αὐτῇ Κυλλήνη· τὴν γοῦν κάθετον οἱ μὲν εἴκοσι σταδίων φασὶν οἱ δ’ ὅσον πεντεκαίδεκα. δοκεῖ δὲ παλαιότατα ἔθνη τῶν Ἑλλήνων εἶναι τὰ Ἀρκαδικά, Ἀζᾶνές τε καὶ Παρράσιοι καὶ ἄλλοι τοιοῦτοι. διὰ δὲ τὴν τῆς χώρας παντελῆ κάκωσιν οὐκ ἂν προσήκοι μακρολογεῖν περὶ αὐτῶν· αἵ τε γὰρ πόλεις ὑπὸ τῶν συνεχῶν πολέμων ἠφανίσθησαν ἔνδοξοι γενόμεναι πρότερον, τήν τε χώραν οἱ γεωργήσαντες ἐκλελοίπασιν ἐξ ἐκείνων ἔτι τῶν χρόνων ἐξ ὧν εἰς τὴν προσαγορευθεῖσαν Μεγάλην πόλιν αἱ πλεῖσται συνῳκίσθησαν. νυνὶ δὲ καὶ αὐτὴ ἡ Μεγάλη πόλις τὸ τοῦ κωμικοῦ πέπονθε καὶ<br>ἐρημία μεγάλη ’στὶν ἡ Μεγάλη πόλις.<br>βοσκήμασι δ’ εἰσὶ νομαὶ δαψιλεῖς, καὶ μάλιστα ἵπποις καὶ ὄνοις τοῖς ἱπποβάταις· ἔστι δὲ καὶ τὸ γένος τῶν ἵππων ἄριστον τὸ Ἀρκαδικόν, καθάπερ καὶ τὸ Ἀργολικὸν καὶ τὸ Ἐπιδαύριον. καὶ ἡ τῶν Αἰτωλῶν δὲ καὶ Ἀκαρνάνων ἐρημία πρὸς ἱπποτροφίαν εὐφυὴς γέγονεν οὐχ ἧττον τῆς Θετταλίας.", "st": "8.8.1"}, {"sp": "N", "t": "Μαντίνειαν μὲν οὖν ἐποίησεν ἔνδοξον Ἐπαμεινώνδας, τῇ δευτέρᾳ νικήσας μάχῃ Λακεδαιμονίους ἐν ᾗ καὶ αὐτὸς ἐτελεύτα. καὶ αὕτη δὲ καὶ Ὀρχομενὸς καὶ Ἡραία καὶ Κλείτωρ καὶ Φενεὸς καὶ Στύμφαλος καὶ Μαίναλος καὶ Μεθύδριον καὶ Καφυεῖς καὶ Κύναιθα ἢ οὐκέτ’ εἰσὶν ἢ μόλις αὐτῶν ἴχνη φαίνεται καὶ σημεῖα. Τεγέα δ’ ἔτι μετρίως συμμένει καὶ τὸ ἱερὸν τῆς Ἀλέας Ἀθηνᾶς· τιμᾶται δ’ ἐπὶ μικρὸν καὶ τὸ τοῦ Λυκαίου Διὸς ἱερὸν κατὰ τὸ Λύκαιον [μέγιστον] ὄρος. τῶν δ’ ὑπὸ τοῦ ποιητοῦ λεγομένων<br>Ῥίπην τε Στρατίην τε καὶ ἠνεμόεσσαν Ἐνίσπην<br>εὑρεῖν τε χαλεπὸν καὶ εὑροῦσιν οὐδὲν ὄφελος διὰ τὴν ἐρημίαν.", "st": "8.8.2"}, {"sp": "N", "t": "ὄρη δ’ ἐπιφανῆ πρὸς τῇ Κυλλήνῃ Φολόη τε καὶ Λύκαιον καὶ Μαίναλος καὶ τὸ Παρθένιον καλούμενον καθῆκον ἐπὶ τὴν Ἀργείαν ἀπὸ τῆς Τεγεάτιδος.", "st": "8.8.3"}, {"sp": "N", "t": "περὶ δὲ τοῦ Ἀλφειοῦ καὶ τοῦ Εὐρώτα τὸ συμβεβηκὸς παράδοξον εἴρηται καὶ τὸ περὶ Ἐρασῖνον τὸν ἐκδιδόντα ἐκ τῆς Στυμφαλίδος λίμνης εἰς τὴν Ἀργείαν νυνί, πρότερον δ’ οὐκ ἔχοντα ἔκρυσιν, τῶν βερέθρων, ἃ καλοῦσιν οἱ Ἀρκάδες ζέρεθρα, τυφλῶν ὄντων καὶ μὴ δεχομένων ἀπέρασιν ὥστε τὴν τῶν Στυμφαλίων πόλιν νῦν μὲν καὶ πεντήκοντα διέχειν σταδίους ἀπὸ τῆς λίμνης, τότε δ’ ἐπ’ αὐτῆς κεῖσθαι. τἀναντία δ’ ὁ Λάδων ἔπαθε τοῦ ῥεύματος ἐπισχεθέντος ποτὲ διὰ τὴν ἔμφραξιν τῶν πηγῶν· συμπεσόντα γὰρ τὰ περὶ Φενεὸν βέρεθρα ὑπὸ σεισμοῦ, δι’ ὧν ἦν ἡ φορά, μονὴν ἐποίησε τοῦ ῥεύματος μέχρι τῶν κατὰ βάθους φλεβῶν τῆς πηγῆς. καὶ οἱ μὲν οὕτω λέγουσιν· Ἐρατοσθένης δέ φησι περὶ Φενεὸν μὲν τὸν Ἀνίαν καλούμενον ποταμὸν λιμνάζειν τὰ πρὸ τῆς πόλεως, καταδύεσθαι δ’ εἴς τινας ἠθμοὺς οὓς καλεῖσθαι ζέρεθρα· τούτων δ’ ἐμφραχθέντων ἔσθ’ ὅτε ὑπερχεῖσθαι τὸ ὕδωρ εἰς τὰ πεδία, πάλιν δ’ ἀναστομουμένων ἄθρουν ἐκ τῶν πεδίων ἐκπεσὸν εἰς τὸν Λάδωνα καὶ τὸν Ἀλφειὸν ἐμβάλλειν, ὥστε καὶ τῆς Ὀλυμπίας κλυσθῆναί ποτε τὴν περὶ τὸ ἱερὸν γῆν, τὴν δὲ λίμνην συσταλῆναι· τὸν Ἐρασῖνον δὲ παρὰ Στυμφάλου ῥέοντα ὑποδύντα ὑπὸ τὸ ὄρος ἐν τῇ Ἀργείᾳ πάλιν ἀναφανῆναι· διὸ δὴ καὶ Ἰφικράτη πολιορκοῦντα τὸν Στύμφαλον καὶ μηδὲν περαίνοντα ἐπιχειρῆσαι τὴν κατάδυσιν ἀποφράξαι σπόγγους πορισάμενον πολλούς, παύσασθαι δὲ διοσημίας γενομένης. περὶ Φενεὸν δ’ ἔστι καὶ τὸ καλούμενον Στυγὸς ὕδωρ, λιβάδιον ὀλεθρίου ὕδατος νομιζόμενον ἱερόν. τοσαῦτα καὶ περὶ Ἀρκαδίας εἰρήσθω.", "st": "8.8.4"}, {"sp": "N", "t": "Πολυβίου δ’ εἰρηκότος τὸ ἀπὸ Μαλεῶν ἐπὶ τὰς ἄρκτους μέχρι τοῦ Ἴστρου διάστημα περὶ μυρίους σταδίους, εὐθύνει τοῦτο ὁ Ἀρτεμίδωρος οὐκ ἀτόπως, ἐπὶ μὲν Αἴγιον χιλίους καὶ [τετρακος]ίους εἶναι λέγων ἐκ Μαλεῶν ὁδόν, ἐνθένδε εἰς [Κίρραν πλοῦν] διακοσίων, ἐνθένδε διὰ Ἡρακλείας [εἰς Θαυμακοὺς] πεντακοσίων ὁδόν, εἶτα εἰς Λάρισαν [καὶ τὸν Πηνειὸν] τριακοσίων τετταράκοντα, εἶτα διὰ [τῶν Τεμπῶν ἐπὶ τὰς Πη]νειοῦ ἐκβολὰς διακοσίων τετταράκον[τα, εἶτα εἰς τὴν Θεσσα]λονίκειαν ἑξακοσίων ἑξήκοντα, ἐντεῦ[θεν ἐπ’ Ἴστρον δι’ Εἰδομ]ένης καὶ Στόβων καὶ Δαρδανίων τρισχι[λίους καὶ διακοσίο]υς. κατ’ ἐκεῖνον δὴ συμβαίνει τὸ ἐκ [τοῦ Ἴστρου ἐπὶ τὰς Μαλ]έας ἑξακισχιλίων πεντακοσίων. αἴτιον δὲ τούτου τὸ μὴ τὴν σύντομον καταμετρεῖν, ἀλλὰ τὴν τυχοῦσαν ἣν ἐπορεύθη τῶν στρατηγῶν τις. οὐκ ἄτοπον δ’ ἴσως καὶ τοὺς οἰκιστὰς προσθεῖναι τῶν τὴν Πελοπόννησον οἰκούντων, οὓς εἶπεν Ἔφορος, τοὺς μετὰ τὴν Ἡρακλειδῶν κάθοδον· Κορίνθου μὲν Ἀλήτην, Σικυῶνος δὲ Φάλκην, Ἀχαΐας δὲ Τισαμενόν, Ἤλιδος δ’ Ὄξυλον, Μεσσήνης δὲ Κρεσφόντην, Λακεδαίμονος δ’ Εὐρυσθένη καὶ Προκλῆ, Ἄργους δὲ Τήμενον κ[αὶ Κισσόν, τῶν δὲ] περὶ τὴν Ἀκτὴν Ἀγραῖον καὶ Δηιφόντην.", "st": "8.8.5"}, {"sp": "HDR", "t": "Βιβλίον Θʹ", "st": "9"}, {"sp": "N", "t": "περιωδευκόσι δὲ τὴν Πελοπόννησον, ἣν πρώτην ἔφαμεν καὶ ἐλαχίστην τῶν συντιθεισῶν τὴν Ἑλλάδα χερρονήσων, ἐφεξῆς ἂν εἴη τὰς συνεχεῖς ἐπελθεῖν. ἦν δὲ δευτέρα μὲν ἡ προστιθεῖσα τῇ Πελοποννήσῳ τὴν Μεγαρίδα, ὥστε τὸν Κρομμυῶνα Μεγαρέων εἶναι καὶ μὴ Κορινθίων· τρίτη δὲ ἡ πρὸς ταύτῃ προσλαμβάνουσα τὴν Ἀττικὴν καὶ τὴν Βοιωτίαν καὶ τῆς Φωκίδος τι μέρος καὶ τῶν Ἐπικνημιδίων Λοκρῶν. περὶ τούτων οὖν [λεκτέον]. φησὶ δ’ Εὔδοξος, εἴ τις νοήσειεν ἀπὸ τῶν Κεραυνίων ὀρῶν ἐπὶ Σούνιον τὸ τῆς Ἀττικῆς ἄκρον ἐπὶ τὰ πρὸς ἕω μέρη τεταμένην εὐθεῖαν, ἐν δεξιᾷ μὲν ἀπολείψειν τὴν Πελοπόννησον ὅλην πρὸς νότον, ἐν ἀριστερᾷ δὲ καὶ πρὸς τὴν ἄρκτον τὴν ἀπὸ τῶν Κεραυνίων ὀρῶν συνεχῆ παραλίαν μέχρι τοῦ Κρισαίου κόλπου καὶ τῆς Μεγαρίδος καὶ συμπάσης τῆς Ἀττικῆς· νομίζει δ’ οὐδ’ ἂν κ[οιλαίνεσθαι οὕτως] τὴν ᾐόνα τὴν ἀπὸ Σουνίου μέχρι [τοῦ Ἰσθμοῦ ὥστε μεγάλην] ἔχειν ἐπιστροφήν, εἰ μὴ προσῆν τῇ [ᾐόνι ταύτῃ καὶ] τὰ συνεχῆ τῷ Ἰσθμῷ χωρία τὰ [ποιοῦντα τὸν κόλπον τὸν] Ἑρμιονικὸν καὶ τὴν Ἀκτήν· ὡς δ’ αὕ[τως οὐδ’ ἂν τὴν ἀπὸ τῶν Κεραυν]ίων ἐπὶ τὸν Κορινθιακὸν κόλπον ἔχειν τινὰ τοσαύ[την ἐπιστρο]φὴν ὥστε κοιλαίνεσθαι κολποειδῶς καθ’ αὑ[τήν, εἰ μὴ τὸ] Ῥίον καὶ τὸ Ἀντίρριον συναγόμενα εἰς στενὸν [ἐποίει τὴν] ἔμφασιν ταύτην· ὁμοίως δὲ καὶ τὰ περι[έχοντα] τὸν μυχόν, εἰς ἃ καταλήγειν συμβαίνει τὴν [ταύτῃ] θάλατταν.", "st": "9.1.1"}, {"sp": "N", "t": "οὕτω δ’ εἰρηκότος Εὐδόξου, μαθηματικοῦ ἀνδρὸς καὶ σχημάτων ἐμπείρου καὶ κλιμάτων καὶ τοὺς τόπους τούτους εἰδότος, δεῖ νοεῖν τήνδε τὴν πλευρὰν τῆς Ἀττικῆς σὺν τῇ Μεγαρίδι τὴν ἀπὸ Σουνίου μέχρι Ἰσθμοῦ κοίλην μὲν ἀλλ’ ἐπὶ μικρόν. ἐνταῦθα δ’ ἐστὶ κατὰ μέσην που τὴν λεχθεῖσαν γραμμὴν ὁ Πειραιεὺς τὸ τῶν Ἀθηνῶν ἐπίνειον. διέχει γὰρ τοῦ μὲν Σχοινοῦντος τοῦ κατὰ τὸν Ἰσθμὸν περὶ τριακοσίους πεντήκοντα σταδίους, τοῦ δὲ Σουνίου τριάκοντα καὶ τριακοσίους· [τός]ον πώς ἐστι διάστημα καὶ τὸ ἐπὶ Πηγὰς ἀπὸ τοῦ Πει[ραιῶς], ὅσονπερ καὶ ἐπὶ Σχοινοῦντα· δέκα δ’ ὅμως στα[δίοις] πλεονάζειν φασί. κάμψαντι δὲ τὸ Σούνιον πρὸς ἄρκτον μὲν ὁ πλοῦς, ἐκκλίνων [δὲ] πρὸς δύσιν.", "st": "9.1.2"}, {"sp": "N", "t": "ἀκτὴ δ’ ἐστὶν [ἡ Ἀττικὴ] ἀμφιθάλαττος, στενὴ τὸ πρῶτον, εἶτ’ εἰς τὴν μεσόγαιαν πλατύνεται, μηνοειδῆ δ’ οὐδὲν ἧττον ἐπιστροφὴν λαμβάνει πρὸς Ὠρωπὸν τῆς Βοιωτίας τὸ κυρτὸν ἔχουσαν πρὸς θαλάττῃ· τοῦτο δ’ ἐστὶ τὸ δεύτερον πλευρὸν ἑῷον τῆς Ἀττικῆς. τὸ δὲ λοιπὸν ἤδη τὸ προσάρκτιόν ἐστι πλευρὸν ἀπὸ τῆς Ὠρωπίας ἐπὶ δύσιν παρατεῖνον μέχρι τῆς Μεγαρίδος, ἡ Ἀττικὴ ὀρεινή, πολυώνυμός τις, διείργουσα τὴν Βοιωτίαν ἀπὸ τῆς Ἀττικῆς· ὥσθ’, ὅπερ εἶπον ἐν τοῖς πρόσθεν, ἰσθμὸν γίνεσθαι τὴν Βοιωτίαν ἀμφιθάλαττον οὖσαν τῆς τρίτης χερρονήσου τῆς λεχθείσης, ἀπολαμβάνοντα ἐντὸς τὰ πρὸς τῇ Πελοποννήσῳ τήν τε Μεγαρίδα καὶ τὴν Ἀττικήν. διὰ δὲ τοῦτο καὶ Ἀκτήν φασι λεχθῆναι τὸ παλαιὸν καὶ Ἀκτικὴν τὴν νῦν Ἀττικὴν παρονομασθεῖσαν, ὅτι τοῖς ὄρεσιν ὑποπέπτωκε τὸ πλεῖστον μέρος αὐτῆς ἁλιτενὲς καὶ στενόν, μήκει δ’ ἀξιολόγῳ κεχρημένον, προπεπτωκὸς μέχρι Σουνίου. ταύτας οὖν διέξιμεν ἀναλα[βόντες πάλιν ἀπὸ τῆς π]αραλίας ἀφ’ ἧσπερ ἀπελίπομεν.", "st": "9.1.3"}, {"sp": "N", "t": "μετὰ δὴ Κρομμυῶνα ὑπέρκεινται τῆς Ἀττικῆς αἱ Σκιρωνίδες πέτραι πάροδον οὐκ ἀπολείπουσαι πρὸς θαλάττῃ· ὑπὲρ αὐτῶν δ’ ἐστὶν ἡ ὁδὸς ἡ ἐπὶ Μεγάρων καὶ τῆς Ἀττικῆς ἀπὸ τοῦ Ἰσθμοῦ· οὕτω δὲ σφόδρα πλησιάζει ταῖς πέτραις ἡ ὁδὸς ὥστε πολλαχοῦ καὶ παράκρημνός ἐστι διὰ τὸ ὑπερκείμενον ὄρος δύσβατόν τε καὶ ὑψηλὸν ὄν· ἐνταῦθα δὲ μυθεύεται τὰ περὶ τοῦ Σκείρωνος καὶ τοῦ Πιτυοκάμπτου τῶν λῃζομένων τὴν λεχθεῖσαν ὀρεινήν, οὓς καθεῖλε Θησεύς. ἀπὸ δὲ τῶν ἄκρων τούτων καταιγίζοντα σκαιὸν τὸν ἀργέστην σκίρωνα προσηγορεύκασιν Ἀθηναῖοι. μετὰ δὲ τὰς Σκιρωνίδας πέτρας ἄκρα πρόκειται Μινῴα ποιοῦσα τὸν ἐν τῇ Νισαίᾳ λιμένα. ἡ δὲ Νίσαια ἐπίνειόν ἐστιν τῶν Μεγάρων δεκαοκτὼ σταδίους τῆς πόλεως διέχον, σκέλεσιν ἑκατέρωθεν συναπτόμενον πρὸς αὐτήν· ἐκαλεῖτο δὲ καὶ τοῦτο Μινῴα.", "st": "9.1.4"}, {"sp": "N", "t": "τὸ παλαιὸν μὲν οὖν Ἴωνες εἶχον τὴν χώραν ταύτην οἵπερ καὶ τὴν Ἀττικήν, οὔπω τῶν Μεγάρων ἐκτισμένων· διόπερ οὐδ’ ὁ ποιητὴς μέμνηται τῶν τόπων τούτων ἰδίως, ἀλλ’ Ἀθηναίους καλῶν τοὺς ἐν τῇ Ἀττικῇ πάντας συμπεριείληφε καὶ τούτους τῷ κοινῷ ὀνόματι Ἀθηναίους νομίζων, ὡς ὅταν φῇ ἐν τῷ καταλόγῳ<br>οἳ δ’ ἄρ’ Ἀθήνας εἶχον, ἐυκτίμενον πτολίεθρον<br>δέχεσθαι δεῖ καὶ τοὺς νῦν Μεγαρέας, ὡς καὶ τούτους μετασχόντας τῆς στρατείας. σημεῖον δέ· ἡ γὰρ Ἀττικὴ τὸ παλαιὸν Ἰωνία καὶ Ἰὰς ἐκαλεῖτο, καὶ ὁ ποιητὴς ὅταν φῇ<br>ἔνθα δὲ Βοιωτοὶ καὶ Ἰάονες<br>τοὺς Ἀθηναίους λέγει· ταύτης δ’ ἦν μερὶς καὶ ἡ Μεγαρίς.", "st": "9.1.5"}, {"sp": "N", "t": "καὶ δὴ καὶ τῶν ὁρίων ἀμφισβητοῦντες πολλάκις οἵ τε Πελοποννήσιοι καὶ Ἴωνες, ἐν οἷς ἦν καὶ ἡ Κρομμυωνία, συνέβησαν καὶ στήλην ἔστησαν ἐπὶ τοῦ συνομολογηθέντος τόπου περὶ αὐτὸν τὸν Ἰσθμόν, ἐπιγραφὴν ἔχουσαν ἐπὶ μὲν τοῦ πρὸς τὴν Πελοπόννησον μέρους<br>τάδ’ ἐστὶ Πελοπόννησος οὐκ Ἰωνία,<br>ἐπὶ δὲ τοῦ πρὸς Μέγαρα<br>τάδ’ οὐχὶ Πελοπόννησος ἀλλ’ Ἰωνία.<br>οἵ τε δὴ τὴν Ἀτθίδα συγγράψαντες πολλὰ διαφωνοῦντες τοῦτό γε ὁμολογοῦσιν οἵ γε λόγου ἄξιοι, διότι τῶν Πανδιονιδῶν τεττάρων ὄντων, Αἰγέως τε καὶ Λύκου καὶ Πάλλαντος καὶ τετάρτου Νίσου, καὶ τῆς Ἀττικῆς εἰς τέτταρα μέρη διαιρεθείσης, ὁ Νῖσος τὴν Μεγαρίδα λάχοι καὶ κτίσαι τὴν Νίσαιαν. Φιλόχορος μὲν οὖν ἀπὸ Ἰσθμοῦ μέχρι τοῦ Πυθίου διήκειν αὐτοῦ φησι τὴν ἀρχήν, Ἄνδρων δὲ μέχρι Ἐλευσῖνος καὶ τοῦ Θριασίου πεδίου. τὴν δ’ εἰς τέτταρα μέρη διανομὴν ἄλλων ἄλλως εἰρηκότων ἀρκεῖ ταῦτα παρὰ Σοφοκλέους λαβεῖν· φησὶ δ’ ὁ Αἰγεὺς ὅτι ὁ πατὴρ ὥρισεν ἐμοὶ μὲν ἀ[πελθεῖ]ν εἰς ἀκτὰς τῆσδε γῆς πρεσβεῖα νείμας· [εἶτ]α Λύκῳ<br>τὸν ἀντίπλευρον κῆπον Εὐβοίας νέμει,<br>Νίσῳ δὲ τὴν ὅμαυλον ἐξαιρεῖ χθόνα<br>Σκείρωνος ἀκτῆς, τῆς δὲ γῆς τὸ πρὸς νότον<br>ὁ σκληρὸς οὗτος καὶ γίγαντας ἐκτρέφων<br>εἴληχε Πάλλας.<br>ὅτι μὲν οὖν ἡ Μεγαρὶς τῆς Ἀττικῆς μέρος ἦν, τούτοις χρῶνται τεκμηρίοις.", "st": "9.1.6"}, {"sp": "N", "t": "μετὰ δὲ τὴν τῶν Ἡρακλειδῶν κάθοδον καὶ τὸν τῆς χώρας μερισμὸν ὑπ’ αὐτῶν καὶ τῶν συγκατελθόντων αὐτοῖς Δωριέων ἐκπεσεῖν τῆς οἰκείας συνέβη πολλοὺς εἰς τὴν Ἀττικήν, ὧν ἦν καὶ ὁ τῆς Μεσσήνης βασιλεὺς Μέλανθος· οὗτος δὲ καὶ τῶν Ἀθηναίων ἐβασίλευσεν ἑκόντων, νικήσας ἐκ μονομαχίας τὸν τῶν Βοιωτῶν βασιλέα Ξάνθον. εὐανδρούσης δὲ τῆς Ἀττικῆς διὰ τοὺς φυγάδας φοβηθέντες οἱ Ἡρακλεῖδαι, παροξυνόντων αὐτοὺς μάλιστα τῶν ἐν Κορίνθῳ καὶ τῶν ἐν Μεσσήνῃ, τῶν μὲν διὰ τὴν γειτνίασιν, τῶν δὲ ὅτι Κόδρος τῆς Ἀττικῆς ἐβασίλευε τότε ὁ τοῦ Μελάνθου παῖς, ἐστράτευσαν ἐπὶ τὴν Ἀττικήν· ἡττηθέντες δὲ μάχῃ τῆς μὲν ἄλλης ἐξέστησαν γῆς, τὴν Μεγαρικὴν δὲ κατέσχον καὶ τήν τε πόλιν ἔκτισαν τὰ Μέγαρα καὶ τοὺς ἀνθρώπους Δωριέας ἀντὶ Ἰώνων ἐποίησαν· ἠφάνισαν δὲ καὶ τὴν στήλην τὴν ὁρίζουσαν τούς τε Ἴωνας καὶ τοὺς Πελοποννησίους.", "st": "9.1.7"}, {"sp": "N", "t": "πολλαῖς δὲ κέχρηται μεταβολαῖς ἡ τῶν Μεγαρέων πόλις, συμμένει δ’ ὅμως μέχρι νῦν. ἔσχε δέ ποτε καὶ φιλοσόφων διατριβὰς τῶν προσαγορευθέντων Μεγαρικῶν, Εὐκλείδην διαδεξαμένων ἄνδρα Σωκρατικόν, Μεγαρέα τὸ γένος· καθάπερ καὶ Φαίδωνα μὲν τὸν Ἠλεῖον οἱ Ἠλειακοὶ διεδέξαντο, καὶ τοῦτον Σωκρατικόν, ὧν ἦν καὶ Πύρρων, Μενέδημον δὲ τὸν Ἐρετριέα οἱ Ἐρετρικοί. ἔστι δ’ ἡ χώρα τῶν Μεγαρέων παράλυπρος καθάπερ καὶ ἡ Ἀττική, καὶ τὸ πλέον αὐτῆς ἐπέχει τὰ καλούμενα Ὄνεια ὄρη, ῥάχις τις μηκυνομένη μὲν ἀπὸ τῶν Σκιρωνίδων πετρῶν ἐπὶ τὴν Βοιωτίαν καὶ τὸν Κιθαιρῶνα, διείργουσα δὲ τὴν κατὰ Νίσαιαν θάλατταν ἀπὸ τῆς κατ[ὰ τὰς Παγὰς] Ἀλκυονίδος προσαγορευομένης.", "st": "9.1.8"}, {"sp": "N", "t": "πρόκειται δ’ ἀπὸ Νισαίας πλέοντι εἰς τὴν Ἀττικὴν πέντε νησία. εἶτα Σαλαμὶς ἑβδομήκοντά που σταδίων οὖσα τὸ μῆκος, οἱ δ’ ὀγδοήκοντά φασιν· ἔχει δ’ ὁμώνυμον πόλιν τὴν μὲν ἀρχαίαν ἔρημον πρὸς Αἴγιναν τετραμμένην καὶ πρὸς νότον (καθάπερ καὶ Αἰσχύλος εἴρηκεν<br>Αἴγινα δ’ αὕτη πρὸς νότου κεῖται πνοάς<br>), τὴν δὲ νῦν ἐν κόλπῳ κειμένην ἐπὶ χερρονησοειδοῦς τόπου συνάπτοντος πρὸς τὴν Ἀττικήν. ἐκαλεῖτο δ’ ἑτέροις ὀνόμασι τὸ παλαιόν· καὶ γὰρ Σκιρὰς καὶ Κύχρεια ἀπό τινων ἡρώων, ἀφ’ οὗ μὲν Ἀθηνᾶ τε λέγεται Σκιρὰς καὶ τόπος Σκίρα ἐν τῇ Ἀττικῇ καὶ ἐπὶ Σκίρῳ ἱεροποιία τις καὶ ὁ μὴν ὁ Σκιροφοριών, ἀφ’ οὗ δὲ καὶ Κυχρείδης ὄφις, ὅν φησιν Ἡσίοδος τραφέντα ὑπὸ Κυχρέως ἐξελαθῆναι ὑπὸ Εὐρυλόχου λυμαινόμενον τὴν νῆσον, ὑποδέξασθαι δὲ αὐτὸν τὴν Δήμητρα εἰς Ἐλευσῖνα καὶ γενέσθαι ταύτης ἀμφίπολον. ὠνομάσθη δὲ καὶ Πιτυοῦσσα ἀπὸ τοῦ φυτοῦ· ἐπιφανὴς δὲ ἡ νῆσος ὑπῆρξε διά τε τοὺς Αἰακίδας ἐπάρξαντας αὐτῆς, καὶ μάλιστα δι’ Αἴαντα τὸν Τελαμώνιον, καὶ διὰ τὸ περὶ τὴν νῆσον ταύτην καταναυμαχηθῆναι Ξέρξην ὑπὸ τῶν Ἑλλήνων καὶ φυγεῖν εἰς τὴν οἰκείαν. συναπέλαυσαν δὲ καὶ Αἰγινῆται τῆς περὶ τὸν ἀγῶνα τοῦτον δόξης, γείτονές τε ὄντες καὶ ναυτικὸν ἀξιόλογον παρασχόμενοι. Βώκαρος δ’ ἐστὶν ἐν Σαλαμῖνι ποταμός, ὁ νῦν Βωκαλία καλούμενος.", "st": "9.1.9"}, {"sp": "N", "t": "καὶ νῦν μὲν ἔχουσιν Ἀθηναῖοι τὴν νῆσον, τὸ δὲ παλαιὸν πρὸς Μεγαρέας ὑπῆρξεν αὐτοῖς ἔρις περὶ αὐτῆς· καί φασιν οἱ μὲν Πεισίστρατον οἱ δὲ Σόλωνα παρεγγράψαντα ἐν τῷ νεῶν καταλόγῳ μετὰ τὸ ἔπος τοῦτο<br>Αἴας δ’ ἐκ Σαλαμῖνος ἄγεν δυοκαίδεκα νῆας<br>ἑξῆς τοῦτο<br>στῆσε δ’ ἄγων, ἵν’ Ἀθηναίων ἵσταντο φάλαγγες,<br>μάρτυρι χρήσασθαι τῷ ποιητῇ τοῦ τὴν νῆσον ἐξ ἀρχῆς Ἀθηναίων ὑπάρξαι. οὐ παραδέχονται δὲ τοῦθ’ οἱ κριτικοὶ διὰ τὸ πολλὰ τῶν ἐπῶν ἀντιμαρτυρεῖν αὐτοῖς. διὰ τί γὰρ ναυλοχῶν ἔσχατος φαίνεται ὁ Αἴας, οὐ μετ’ Ἀθηναίων ἀλλὰ μετὰ τῶν ὑπὸ Πρωτεσιλάῳ Θετταλῶν;<br>ἔνθ’ ἔσαν Αἴαντός τε νέες καὶ Πρωτεσιλάου<br>καὶ ἐν τῇ ἐπιπωλήσει ὁ Ἀγαμέμνων<br>εὗρ’ υἱὸν Πετεῶο Μενεσθῆα πλή⟨ξιππον⟩<br>⟨ἑστα⟩ότ’, ἀμφὶ δ’ Ἀθηναῖοι, μήστωρες ἀυτῆς.<br>αὐτὰρ ὁ πλησίον ἑστήκει πολύμητις Ὀδυσσεύς,<br>πὰρ δὲ Κεφαλλήνων ἀμφὶ στίχες.<br>ἐπὶ δὲ τὸν Αἴαντα καὶ τοὺς Σαλαμινίους πάλιν<br>ἦλθε δ’ ἐπ’ Αἰάντεσσι,<br>καὶ παρ’ αὐτούς<br>Ἰδομενεὺς δ’ ἑτέρωθεν,<br>οὐ Μενεσθεύς. οἱ μὲν δὴ Ἀθηναῖοι τοιαύτην τινὰ σκήψασθαι μαρτυρίαν παρ’ Ὁμήρου δοκοῦσιν, οἱ δὲ Μεγαρεῖς ἀντιπαρῳδῆσαι οὕτως<br>Αἴας δ’ ἐκ Σαλαμῖνος ἄγεν νέας, ἔκ τε Πολίχνης,<br>ἔκ τ’ Αἰγειρούσσης Νισαίης τε Τριπόδων τε.<br>ἅ ἐστι χωρία Μεγαρικά, ὧν οἱ Τρίποδες Τριποδίσκιον λέγονται, καθ’ ὃ ἡ νῦν ἀγορὰ τῶν Μεγάρων κεῖται.", "st": "9.1.10"}, {"sp": "N", "t": "τινὲς δ’ ἀπὸ τοῦ τὴν ἱέρειαν τῆς Πολιάδος Ἀθηνᾶς χλωροῦ τυροῦ τοῦ μὲν ἐπιχωρίου μὴ ἅπτεσθαι, ξενικὸν δὲ μόνον προσφέρεσθαι, χρῆσθαι δὲ καὶ τῷ Σαλαμινίῳ, ξένην φασὶ τῆς Ἀττικῆς τὴν Σαλαμῖνα οὐκ εὖ· καὶ γὰρ τὸν ἀπὸ τῶν ἄλλων νήσων τῶν ὁμολογουμένως τῇ Ἀττικῇ προσχώρων προσφέρεται, ξενικὸν πάντα τὸν διαπόντιον νοησάντων τῶν ἀρξάντων τοῦ ἔθους τούτου. ἔοικε δὴ τὸ παλαιὸν ἡ νῦν Σαλαμὶς καθ’ αὑτὴν τάττεσθαι, τὰ δὲ Μέγαρα τῆς Ἀττικῆς ὑπάρξαι μέρος. ἐν δὲ τῇ παραλίᾳ τῇ κατὰ Σαλαμῖνα κεῖσθαι συμβαίνει τὰ ὅρια τῆς τε Μεγαρικῆς καὶ τῆς Ἀτθίδος, ὄρη δύο ἃ καλοῦσι Κέρατα.", "st": "9.1.11"}, {"sp": "N", "t": "εἶτ’ Ἐλευσὶς πόλις, ἐν ᾗ τὸ τῆς Δήμητρος ἱερὸν τῆς Ἐλευσινίας καὶ ὁ μυστικὸς σηκός, ὃν κατεσκεύασεν Ἰκτῖνος ὄχλον θεάτρου δέξασθαι δυνάμενον, ὃς καὶ τὸν παρθενῶνα ἐποίησε τὸν ἐν ἀκροπόλει τῇ Ἀθηνᾷ, Περικλέους ἐπιστατοῦντος τῶν ἔργων· ἐν δὲ τοῖς δήμοις καταριθμεῖται ἡ πόλις.", "st": "9.1.12"}, {"sp": "N", "t": "εἶτα τὸ Θριάσιον πεδίον καὶ ὁμώνυμος αἰγιαλὸς καὶ δῆμος· εἶθ’ ἡ ἄκρα ἡ Ἀμφιάλη καὶ τὸ ὑπερκείμενον λατόμιον καὶ ὁ εἰς Σαλαμῖνα πορθμὸς ὅσον διστάδιος, ὃν διαχοῦν ἐπειρᾶτο Ξέρξης, ἔφθη δὲ ἡ ναυμαχία γενομένη καὶ φυγὴ τῶν Περσῶν. ἐνταῦθα δὲ καὶ αἱ Φαρμακοῦσσαι, δύο νησία ὧν ἐν τῷ μείζονι Κίρκης τάφος δείκνυται.", "st": "9.1.13"}, {"sp": "N", "t": "ὑπὲρ δὲ τῆς ἀκτῆς ταύτης ὄρος ἐστὶν ὃ καλεῖται Κορυδαλλός, καὶ ὁ δῆμος οἱ Κορυδαλλεῖς· εἶθ’ ὁ Φώρων λιμὴν καὶ ἡ Ψυττάλεια, νησίον ἔρημον πετρῶδες ὅ τινες εἶπον λήμην τοῦ Πειραιῶς· πλησίον δὲ καὶ ἡ Ἀταλάντη ὁμώνυμος τῇ περὶ Εὔβοιαν καὶ Λοκρούς, καὶ ἄλλο νησίον ὅμοιον τῇ Ψυτταλείᾳ καὶ τοῦτο· εἶθ’ ὁ Πειραιεὺς καὶ αὐτὸς ἐν τοῖς δήμοις ταττόμενος καὶ ἡ Μουνυχία.", "st": "9.1.14"}, {"sp": "N", "t": "λόφος δ’ ἐστὶν ἡ Μουνυχία χερρονησιάζων καὶ κοῖλος καὶ ὑπόνομος πολὺ μέρος φύσει τε καὶ ἐπίτηδες ὥστ’ οἰκήσεις δέχεσθαι, στομίῳ δὲ μικρῷ τὴν εἴσοδον ἔχων. ὑποπίπτουσι δ’ αὐτῷ λιμένες τρεῖς. τὸ μὲν οὖν παλαιὸν ἐτετείχιστο καὶ συνῴκιστο ἡ Μουνυχία παραπλησίως ὥσπερ ἡ τῶν Ῥοδίων πόλις, προσειληφυῖα τῷ περιβόλῳ τόν τε Πειραιᾶ καὶ τοὺς λιμένας πλήρεις νεωρίων, ἐν οἷς καὶ ἡ ὁπλοθήκη Φίλωνος ἔργον· ἄξιόν τε ἦν ναύσταθμον ταῖς τετρακοσίαις ναυσίν, ὧν οὐκ ἐλάττους ἔστελλον Ἀθηναῖοι. τῷ δὲ τείχει τούτῳ συνῆπτε τὰ καθειλκυσμένα ἐκ τοῦ ἄστεος σκέλη· ταῦτα δ’ ἦν μακρὰ τείχη τετταράκοντα σταδίων τὸ μῆκος, συνάπτοντα τὸ ἄστυ τῷ Πειραιεῖ. οἱ δὲ πολλοὶ πόλεμοι τὸ τεῖχος κατήρειψαν καὶ τὸ τῆς Μουνυχίας ἔρυμα, τόν τε Πειραιᾶ συνέστειλαν εἰς ὀλίγην κατοικίαν τὴν περὶ τοὺς λιμένας καὶ τὸ ἱερὸν τοῦ Διὸς τοῦ σωτῆρος· τοῦ δὲ ἱεροῦ τὰ μὲν στοΐδια ἔχει πίνακας θαυμαστούς, ἔργα τῶν ἐπιφανῶν τεχνιτῶν, τὸ δ’ ὕπαιθρον ἀνδριάντας. κατέσπασται δὲ καὶ τὰ μακρὰ τείχη, Λακεδαιμονίων μὲν καθελόντων πρότερον Ῥωμαίων δ’ ὕστερον, ἡνίκα Σύλλας ἐκ πολιορκίας εἷλε καὶ τὸν Πειραιᾶ καὶ τὸ ἄστυ.", "st": "9.1.15"}, {"sp": "N", "t": "τὸ δ’ ἄστυ αὐτὸ πέτρα ἐστὶν ἐν πεδίῳ περιοικουμένη κύκλῳ· ἐπὶ δὲ τῇ πέτρᾳ τὸ τῆς Ἀθηνᾶς ἱερὸν ὅ τε ἀρχαῖος νεὼς ὁ τῆς Πολιάδος ἐν ᾧ ὁ ἄσβεστος λύχνος, καὶ ὁ παρθενὼν ὃν ἐποίησεν Ἰκτῖνος, ἐν ᾧ τὸ τοῦ Φειδίου ἔργον ἐλεφάντινον ἡ Ἀθηνᾶ. ἀλλὰ γὰρ εἰς πλῆθος ἐμπίπτων τῶν περὶ τῆς πόλεως ταύτης ὑμνουμένων τε καὶ διαβοωμένων ὀκνῶ πλεονάζειν, μὴ συμβῇ τῆς προθέσεως ἐκπεσεῖν τὴν γραφήν. ἔπεισι γὰρ ὅ φησιν Ἡγησίας “ὁρῶ τὴν ἀκρόπολιν καὶ τὸ περιττῆς τριαίνης ἐκεῖθι σημεῖον, ὁρῶ τὴν Ἐλευσῖνα, καὶ τῶν ἱερῶν γέγονα μύστης· ἐκεῖνο Λεωκόριον, τοῦτο Θησεῖον· οὐ δύναμαι δηλῶσαι καθ’ ἓν ἕκαστον· ἡ γὰρ Ἀττικὴ θεῶν αὐτοῖς … καταλαβόντων καὶ τῶν προγόνων ἡρώων …” οὗτος μὲν οὖν ἑνὸς ἐμνήσθη τῶν ἐν ἀκροπόλει σημείων, Πολέμων δ’ ὁ περιηγητὴς τέτταρα βιβλία συνέγραψε περὶ τῶν ἀναθημάτων τῶν ἐν ἀκροπόλει· τὸ δ’ ἀνάλογον συμβαίνει καὶ ἐπὶ τῶν ἄλλων τῆς πόλεως μερῶν καὶ τῆς χώρας· Ἐλευσῖνά τε εἰπὼν ἕνα τῶν ἑκατὸν ἑβδομήκοντα δήμων πρὸς δὲ καὶ τεττάρων, ὥς φασιν, οὐδένα τῶν ἄλλων ὠνόμακεν.", "st": "9.1.16"}, {"sp": "N", "t": "ἔχουσι δὲ κἂν εἰ μὴ πάντες οἵ γε πολλοὶ μυθοποιίας συχνὰς καὶ ἱστορίας· καθάπερ Ἄφιδνα μὲν τὴν τῆς Ἑλένης ἁρπαγὴν ὑπὸ Θησέως καὶ τὴν ὑπὸ τῶν Διοσκούρων ἐκπόρθησιν αὐτῆς καὶ ἀνακομιδὴν τῆς ἀδελφῆς, Μαραθὼν δὲ τὸν Περσικὸν ἀγῶνα, Ῥαμνοῦς δὲ τὸ τῆς Νεμέσεως ξόανον, ὅ τινες μὲν Διοδότου φασὶν ἔργον τινὲς δὲ Ἀγορακρίτου τοῦ Παρίου, καὶ μεγέθει καὶ κάλλει σφόδρα κατωρθωμένον καὶ ἐνάμιλλον τοῖς Φειδίου ἔργοις. οὕτω δὲ καὶ Δεκέλεια μὲν τὸ ὁρμητήριον τῶν Πελοποννησίων κατὰ τὸν Δεκελεικὸν πόλεμον, Φυλὴ δὲ ὅθεν ἐπήγαγε τὸν δῆμον Θρασύβουλος εἰς Πειραιᾶ κἀκεῖθεν εἰς ἄστυ. οὕτω δὲ καὶ ἐπ’ ἄλλων πλειόνων ἔστιν ἱστορεῖν πολλά· καὶ ἔτι τὸ Λεωκόριον καὶ τὸ Θη[σεῖον μύθο]υς ἔχει, καὶ τὸ Λύκειον καὶ τὸ Ὀλυμπικὸν … ὸ τὸ Ὀλύμπιον, ὅπερ ἡμιτελὲς κατέλιπε τελευτῶν ὁ ἀναθεὶς βασιλεύς· ὁμοίως δὲ καὶ ἡ Ἀκαδημία καὶ οἱ κῆποι τῶν φιλοσόφων καὶ τὸ Ὠιδεῖον καὶ ἡ ποικίλη στοὰ καὶ τὰ ἱερὰ τὰ ἐν τῇ πό[λει πλεῖστα] ἔχοντα τεχνιτῶν ἔργα.", "st": "9.1.17"}, {"sp": "N", "t": "πολὺ δ’ ἂν πλείων εἴη λόγος, εἰ τοὺς ἀρχηγέτας τοῦ κτίσματος ἐξετάζοι τις ἀρξάμενος ἀπὸ Κέκροπος· οὐδὲ γὰρ ὁμοίως λέγουσιν ἅπαντες. τοῦτο δὲ καὶ ἀπὸ τῶν ὀνομάτων δῆλον· ἀκτὴν μὲν γὰρ ἀπὸ Ἀκταίωνος φασίν, Ἀτθίδα δὲ καὶ Ἀττικὴν ἀπὸ Ἀτθίδος τῆς Κραναοῦ, ἀφ’ οὗ καὶ Κραναοὶ οἱ ἔνοικοι, Μοψοπίαν δὲ ἀπὸ Μοψόπου, Ἰωνίαν δὲ ἀπὸ Ἴωνος τοῦ Ξούθου, Ποσειδωνίαν δὲ καὶ Ἀθήνας ἀπὸ τῶν ἐπωνύμων θεῶν. εἴρηται δ’ ὅτι κἀνταῦθα φαίνεται τὸ τῶν Πελασγῶν ἔθνος ἐπιδημῆσαν, καὶ διότι ὑπὸ τῶν Ἀττικῶν Πελαργοὶ προσηγορεύθησαν διὰ τὴν πλάνην.", "st": "9.1.18"}, {"sp": "N", "t": "ὅσῳ δὲ πλέον ἐστὶ τὸ φιλότιμον περὶ τὰ ἔνδοξα καὶ πλείους οἱ λαλήσαντές τι περὶ αὐτῶν, τοσῷδε μείζων ὁ ἔλεγχος, ἐὰν μὴ κρατῇ τις τῆς ἱστορίας· οἷον ἐν τῇ συναγωγῇ τῶν ποταμῶν ὁ Καλλίμαχος γελᾶν φησιν, εἴ τις θαρρεῖ γράφειν τὰς τῶν Ἀθηναίων παρθένους “ἀφύσσεσθαι καθαρὸν γάνος Ἠριδανοῖο,” οὗ καὶ τὰ βοσκήματα ἀπόσχοιτ’ ἄν. εἰσὶ μὲν νῦν αἱ πηγαὶ καθαροῦ καὶ ποτίμου ὕδατος, ὥς φασιν, ἐκτὸς τῶν Διοχάρους καλουμένων πυλῶν πλησίον τοῦ Λυκείου· πρότερον δὲ καὶ κρήνη κατεσκεύαστό τις πλησίον πολλοῦ καὶ καλοῦ ὕδατος· εἰ δὲ μὴ νῦν, τί ἂν εἴη θαυμαστόν, εἰ πάλαι πολὺ καὶ καθαρὸν ἦν ὥστε καὶ πότιμον εἶναι, μετέβαλε δὲ ὕστερον; ἐν μὲν οὖν τοῖς καθ’ ἕκαστα τοσούτοις οὖσιν οὐκ ἐνδέχεται διατρίβειν, οὐ μὴν οὐδὲ σιγῇ παρελθεῖν ὥστε μηδ’ ἐν κεφαλαίῳ μνησθῆναί τινων.", "st": "9.1.19"}, {"sp": "N", "t": "τοσαῦτ’ οὖν ἀπόχρη προσθεῖσιν ὅτι φησὶ Φιλόχορος πορθουμένης τῆς χώρας ἐκ θαλάττης μὲν ὑπὸ Καρῶν ἐκ γῆς δὲ ὑπὸ Βοιωτῶν, οὓς ἐκάλουν Ἄονας, Κέκροπα πρῶτον εἰς δώδεκα πόλεις συνοικίσαι τὸ πλῆθος, ὧν ὀνόματα Κεκροπία Τετράπολις Ἐπακρία Δεκέλεια Ἐλευσὶς Ἄφιδνα (λέγουσι δὲ καὶ πληθυντικῶς Ἀφίδνας) Θόρικος Βραυρὼν Κύθηρος Σφηττὸς Κηφισιά … πάλιν δ’ ὕστερον εἰς μίαν πόλιν συναγαγεῖν λέγεται τὴν νῦν τὰς δώδεκα Θησεύς. ἐβασιλεύοντο μὲν [οὖν οἱ Ἀθηναῖοι] πρότερον, εἶτ’ εἰς δημοκρατίαν μετέστησαν· τυράννων δ’ ἐπιθεμένων αὐτοῖς, Πεισιστράτου καὶ τῶν παίδων, ὕστερόν τε ὀλιγαρχίας γενομένης τῆς τε τῶν τετρακοσίων καὶ τῆς τῶν τριάκοντα τυράννων, οὓς ἐπέστησαν Λακεδαιμόνιοι, τούτους μὲν διεκρούσαντο ῥᾳδίως, ἐφύλαξαν δὲ τὴν δημοκρατίαν μέχρι τῆς Ῥωμαίων ἐπικρατείας. καὶ γὰρ εἴ τι μικρὸν ὑπὸ τῶν Μακεδονικῶν βασιλέων παρελυπήθησαν ὥσθ’ ὑπακούειν αὐτῶν ἀναγκασθῆναι, τόν γε ὁλοσχερῆ τύπον τῆς πολιτείας τὸν αὐτὸν διετήρουν. ἔνιοι δέ φασι καὶ βέλτιστα τότε αὐτοὺς πολιτεύσασθαι δεκαετῆ χρόνον ὃν ἦρχε Μακεδόνων Κάσανδρος. οὗτος γὰρ ὁ ἀνὴρ πρὸς μὲν τὰ ἄλλα δοκεῖ τυραννικώτερος γενέσθαι, πρὸς Ἀθηναίους δὲ εὐγνωμόνησε λαβὼν ὑπήκοον τὴν πόλιν· ἐπέστησε γὰρ τῶν πολιτῶν Δημήτριον τὸν Φαληρέα τῶν Θεοφράστου τοῦ φιλοσόφου γνωρίμων, ὃς οὐ μόνον οὐ κατέλυσε τὴν δημοκρατίαν ἀλλὰ καὶ ἐπηνώρθωσε. δηλοῖ δὲ τὰ ὑπομνήματα ἃ συνέγραψε περὶ τῆς πολιτείας ταύτης ἐκεῖνος. ἀλλ’ οὕτως ὁ φθόνος ἴσχυσε καὶ ἡ πρὸς ὀλίγους ἀπέχθεια ὥστε μετὰ τὴν Κασάνδρου τελευτὴν ἠναγκάσθη φυγεῖν εἰς Αἴγυπτον· τὰς δ’ εἰκόνας αὐτοῦ πλείους ἢ τριακοσίας κατέσπασαν οἱ ἐπαναστάντες καὶ κατεχώνευσαν, ἔνιοι δὲ καὶ προστιθέασιν ὅτι καὶ εἰς ἀμίδας. Ῥωμαῖοι δ’ οὖν παραλαβόντες αὐτοὺς δημοκρατουμένους ἐφύλαξαν τὴν αὐτονομίαν αὐτοῖς καὶ τὴν ἐλευθερίαν. ἐπιπεσὼν δ’ ὁ Μιθριδατικὸς πόλεμος τυράννους αὐτοῖς κατέστησεν οὓς ὁ βασιλεὺς ἐβούλετο· τὸν δ’ ἰσχύσαντα μάλιστα τὸν Ἀριστίωνα καὶ ταύτην βιασάμενον τὴν πόλιν ἐκ πολιορκίας ἑλὼν Σύλλας ὁ τῶν Ῥωμαίων ἡγεμὼν ἐκόλασε, τῇ δὲ πόλει συγγνώμην ἔνειμε· καὶ μέχρι νῦν ἐν ἐλευθερίᾳ τέ ἐστι καὶ τιμῇ παρὰ τοῖς Ῥωμαίοις.", "st": "9.1.20"}, {"sp": "N", "t": "μετὰ δὲ τὸν Πειραιᾶ Φαληρεῖς δῆμος ἐν τῇ ἐφεξῆς παραλίᾳ· εἶθ’ Ἁλιμούσιοι Αἰξωνεῖς Ἁλαιεῖς οἱ Αἰξωνικοὶ Ἀναγυράσιοι· εἶτα Θοραιεῖς Λαμπτρεῖς Αἰγιλιεῖς Ἀναφλύστιοι Ἀζηνιεῖς· οὗτοι μὲν οἱ μέχρι τῆς ἄκρας τοῦ Σουνίου. μεταξὺ δὲ τῶν λεχθέντων δήμων μακρὰ ἄκρα, πρώτη μετὰ τοὺς Αἰξωνέας Ζωστήρ, εἶτ’ ἄλλη μετὰ Θοραιέας Ἀστυπάλαια· ὧν τῆς μὲν πρόκειται νῆσος Φάβρα τῆς δ’ Ἐλαιοῦσσα· καὶ κατὰ τοὺς Αἰξωνέας δ’ ἔστιν Ὑδροῦσσα· περὶ δὲ Ἀνάφλυστόν ἐστι καὶ τὸ Πανεῖον καὶ τὸ τῆς Κωλιάδος Ἀφροδίτης ἱερόν, εἰς ὃν τόπον ἐκκυμανθῆναι τὰ τελευταῖα τὰ ἐκ τῆς περὶ Σαλαμῖνα ναυμαχίας τῆς Περσικῆς ναυάγιά φασι, περὶ ὧν καὶ τὸν Ἀπόλλω προειπεῖν “Κωλιάδες δὲ γυναῖκες ἐρετμοῖσι φρύξουσι.” πρόκειται δὲ καὶ τούτων τῶν τόπων Βέλβινα νῆσος οὐ πολὺ ἄπωθεν καὶ ὁ Πατρόκλου χάραξ· ἔρημοι δ’ αἱ πλεῖσται τούτων.", "st": "9.1.21"}, {"sp": "N", "t": "κάμψαντι δὲ τὴν κατὰ τὸ Σούνιον ἄκραν ἀξιόλογος δῆμος Σούνιον, εἶτα Θόρικος, εἶτα Ποταμὸς δῆμος οὕτω καλούμενος, ἐξ οὗ οἱ ἄνδρες Ποτάμιοι, εἶτα Πρασιὰ Στειριὰ Βραυρών, ὅπου τὸ τῆς Βραυρωνίας Ἀρτέμιδος ἱερόν, [Ἁλαὶ Ἀραφη]νίδες, ὅπου τὸ τῆς Ταυροπόλου, Μυρρινοῦς Προβάλινθος Μαραθών, ὅπου Μιλτιάδης τὰς μετὰ Δάτιος τοῦ Πέρσου δυνάμεις ἄρδην διέφθειρεν οὐ περιμείνας ὑστερίζοντας Λακεδαιμονίους διὰ τὴν πανσέληνον· ἐνταῦθα μεμυθεύκασι καὶ τὸν Μαραθώνιον ταῦρον ὃν ἀνεῖλε Θησεύς. μετὰ δὲ Μαραθῶνα Τρικόρυνθος, εἶτα Ῥαμνοῦς, [ὅπου] τὸ τῆς Νεμέσεως ἱερόν, εἶτα Ψαφὶς ἡ τῶν Ὠρωπίων· ἐνταῦθα δέ που καὶ τὸ Ἀμφιαράειόν ἐστι τετιμημένον ποτὲ μαντεῖον, ὅπου φυγόντα τὸν Ἀμφιάρεων, ὥς φησι Σοφοκλῆς, “ἐδέξατο ῥαγεῖσα Θηβαία κόνις αὐτοῖσιν ὅπλοις καὶ τετρωρίστῳ δίφρῳ.” Ὠρωπὸς δ’ ἐν ἀμφισβητησίμῳ γεγένηται πολλάκις· ἵδρυται γὰρ ἐν μεθορίῳ τῆς τε Ἀττικῆς καὶ τῆς Βοιωτίας. πρόκειται δὲ τῆς παραλίας ταύτης πρὸ μὲν τοῦ Θορίκου καὶ τοῦ Σουνίου νῆσος Ἑλένη τραχεῖα καὶ ἔρημος, παραμήκης ὅσον ἑξήκοντα σταδίων τὸ μῆκος, ἧς φασι μεμνῆσθαι τὸν ποιητὴν ἐν οἷς Ἀλέξανδρος λέγει πρὸς τὴν Ἑλένην “οὐδ’ ὅτε σε πρῶτον Λακεδαίμονος ἐξ ἐρατεινῆς [ἔπλεον]ἁρπάξας ἐν ποντοπόροισι νέεσσι, νήσῳ δ’ ἐν Κρανάῃ ἐμίγην φιλότητι καὶ εὐνῇ.” ταύτην γὰρ λέγει Κρανάην τὴν νῦν Ἑλένην ἀπὸ τοῦ ἐκεῖ γενέσθαι τὴν μῖξιν. μετὰ δὲ τὴν Ἑλένην ἡ Εὔβοια πρόκειται τῆς ἑξῆς παραλίας, ὁμοίως στενὴ καὶ μακρὰ καὶ κατὰ μῆκος τῇ ἠπείρῳ παραβεβλημένη καθάπερ ἡ Ἑλένη. ἔστι δ’ ἀπὸ τοῦ Σουνίου πρὸς τὸ νότιον τῆς Εὐβοίας ἄκρον, ὃ καλοῦσι Λευκὴν ἀκτήν, σταδίων τριακοσίων πλοῦς· ἀλλὰ περὶ Εὐβοίας μὲ[ν λέξομεν ὕστερον], τοὺς δ’ ἐν τῇ μεσογαίᾳ δήμους τῆς Ἀττικῆς μακρὸν εἰπεῖν διὰ τὸ πλῆθος.", "st": "9.1.22"}, {"sp": "N", "t": "τῶν δ’ ὀρῶν τὰ μὲν ἐν ὀνόματι μάλιστά ἐστιν ὅ τε Ὑμηττὸς καὶ Βριλησσὸς καὶ Λυκαβηττός, ἔτι δὲ Πάρνης καὶ Κορυδαλλός. μαρμάρου δ’ ἐστὶ τῆς τε Ὑμηττίας καὶ τῆς Πεντελικῆς κάλλιστα μέταλλα πλησίον τῆς πόλεως· ὁ δ’ Ὑμηττὸς καὶ μέλι ἄριστον ποιεῖ. τὰ δ’ ἀργυρεῖα τὰ ἐν τῇ Ἀττικῇ κατ’ ἀρχὰς μὲν ἦν ἀξιόλογα, νυνὶ δ’ ἐκλείπει· καὶ δὴ καὶ οἱ ἐργαζόμενοι, τῆς μεταλλείας ἀσθενῶς ὑπακουούσης, τὴν παλαιὰν ἐκβολάδα καὶ σκωρίαν ἀναχωνεύοντες εὕρισκον ἔτι ἐξ αὐτῆς ἀποκαθαιρόμενον ἀργύριον, τῶν ἀρχαίων ἀπείρως καμινευόντων. τοῦ δὲ μέλιτος ἀρίστου τῶν πάντων ὄντος τοῦ Ἀττικοῦ πολὺ βέλτιστόν φασι τὸ ἐν τοῖς ἀργυρείοις, ὃ καὶ ἀκάπνιστον καλοῦσιν ἀπὸ τοῦ τρόπου τῆς σκευασίας.", "st": "9.1.23"}, {"sp": "N", "t": "ποταμοὶ δ’ εἰσὶν ὁ μὲν Κηφισσὸς ἐκ Τρινεμέων τὰς ἀρχὰς ἔχων ῥέων δὲ διὰ τοῦ πεδίου, ἐφ’ οὗ καὶ ἡ γέφυρα καὶ οἱ γεφυρισμοί, διὰ δὲ τῶν σκελῶν τῶν ἀπὸ τοῦ ἄστεος εἰς τὸν Πειραιᾶ καθηκόντων ἐκδίδωσιν εἰς τὸ Φαληρικόν, χειμαρρώδης τὸ πλέον, θέρους δὲ μειοῦται τελέως. ἔστι δὲ τοιοῦτος μᾶλλον ὁ Ἰλισσός, ἐκ θατέρου μέρους τοῦ ἄστεος ῥέων εἰς τὴν αὐτὴν παραλίαν ἐκ τῶν ὑπὲρ τῆς Ἄγρας καὶ τοῦ Λυκείου μερῶν καὶ τῆς πηγῆς ἣν ὕμνηκεν ἐν Φαίδρῳ Πλάτων. περὶ μὲν τῆς Ἀττικῆς ταῦτα.", "st": "9.1.24"}, {"sp": "N", "t": "ἑξῆς δ’ ἐστὶν ἡ Βοιωτία, περὶ ἧς λέγοντα καὶ περὶ τῶν συνεχῶν ἐθνῶν ἀνάμνησιν ποιήσασθαι χρὴ τοῦ σαφοῦς χάριν ὧν εἴπομεν πρότερον. [ἐλέγομ]εν δὲ τὴν ἀπὸ Σουνίου παραλίαν μέχρι Θετταλο[νικείας] ἐπὶ τὰς ἄρκτους τετάσθαι, μικρὸν ἐκκλίνουσαν [πρὸς δύσιν καὶ] ἔχουσαν τὴν θάλατταν πρὸς ἕω, τὰ δ’ ὑπερ[κείμενα μέρ]η πρὸς δύσιν ὡς ἂν ταινίας τινὰς διὰ τῆς [πάσης χώρας] τεταμένας παραλλήλους· ὧν πρώτη ἐστὶν [ἡ Ἀττικὴ σὺν τῇ] Μεγαρίδι ὡς ἂν ταινία τις, τὸ μὲν ἑωθι[νὸν πλευρὸν ἔχου]σα τὴν ἀπὸ Σουνίου μέχρι Ὠρωποῦ καὶ … ίας, τὸ δ’ ἑσπέριον τόν τε Ἰσθμὸν καὶ τὴν [Ἀλκυονίδα θάλ]ατταν τὴν κατὰ Παγὰς μέχρι τῶν [τόπων τῆς Βοιωτί]ας τῶν περὶ Κρέουσαν· τὰ δὲ λοιπὰ [τὴν ἀπὸ Σουνίου] μέχρι Ἰσθμοῦ παραλίαν καὶ τὴν ὡς ἂν … ς ὀρεινὴν τὴν διείργουσαν ἀπὸ τῆς [Βοιωτίας τὴν Ἀ]ττικήν. δευτέρα δ’ ἐστὶν ἡ Βοιωτία ἀπὸ τῆς ἕω ἐπὶ δύσιν τεταμένη ταινία τις ἀπὸ τῆς κατ’ Εὔβοιαν θαλάττης ἐπὶ θάλατταν τὴν κατὰ τὸν Κρισαῖον κόλπον, ἰσομήκης πως τῇ Ἀττικῇ ἢ καὶ ἐλάττων κατὰ μῆκος· ἀρετῇ μέντοι τῆς χώρας πάμπολυ διαφέρει.", "st": "9.2.1"}, {"sp": "N", "t": "Ἔφορος δὲ καὶ ταύτῃ κρείττω τὴν Βοιωτίαν ἀποφαίνει τῶν ὁμόρων ἐθνῶν καὶ ὅτι μόνη τριθάλαττός ἐστι καὶ λιμένων εὐπορεῖ πλειόνων, ἐπὶ μὲν τῷ Κρισαίῳ κόλπῳ καὶ τῷ Κορινθιακῷ τὰ ἐκ τῆς Ἰταλίας καὶ Σικελίας καὶ Λιβύης δεχομένη, ἐπὶ δὲ τῶν πρὸς Εὔβοιαν μερῶν ἐφ’ ἑκάτερα τοῦ Εὐρίπου σχιζομένης τῆς παραλίας τῇ μὲν ἐπὶ τὴν Αὐλίδα καὶ τὴν Ταναγρικὴν τῇ δ’ ἐπὶ τὸν Σαλγανέα καὶ τὴν Ἀνθηδόνα, τῇ μὲν εἶναι συνεχῆ τὴν κατ’ Αἴγυπτον καὶ Κύπρον καὶ τὰς νήσους θάλατταν τῇ δὲ τὴν κατὰ Μακεδόνας καὶ τὴν Προποντίδα καὶ τὸν Ἑλλήσποντον. προστίθησι δὲ ὅτι καὶ τὴν Εὔβοιαν τρόπον τινὰ μέρος αὐτῆς πεποίηκεν ὁ Εὔριπος οὕτω στενὸς ὢν καὶ γεφύρᾳ συνεζευγμένος πρὸς αὐτὴν διπλέθρῳ. τὴν μὲν οὖν χώραν ἐπαινεῖ διὰ ταῦτα, καί φησι πρὸς ἡγεμονίαν εὐφυῶς ἔχειν, ἀγωγῇ δὲ καὶ παιδείᾳ μὴ χρησαμένους ἐπιμελεῖ τοὺς ἀεὶ προϊσταμένους αὐτῆς, εἰ καί [τί] ποτε κατώρθωσαν, ἐπὶ μικρὸν τὸν χρόνον συμμεῖναι, καθάπερ Ἐπαμεινώνδας ἔδειξε· τελευτήσαντος γὰρ ἐκείνου τὴν ἡγεμονίαν ἀποβαλεῖν εὐθὺς τοὺς Θηβαίους γευσαμένους αὐτῆς μόνον· αἴτιον δὲ εἶναι τὸ λόγων καὶ ὁμιλίας τῆς πρὸς ἀνθρώπους ὀλιγωρῆσαι, μόνης δ’ ἐπιμεληθῆναι τῆς κατὰ πόλεμον ἀρετῆς. ἔδει δὲ προσθεῖναι διότι τοῦτο πρὸς Ἕλληνας μάλιστα χρήσιμόν ἐστιν, ἐπεὶ πρός γε τοὺς βαρβάρους βία λόγου κρείττων ἐστί. καὶ Ῥωμαῖοι δὲ τὸ παλαιὸν μὲν ἀγριωτέροις ἔθνεσι πολεμοῦντες οὐδὲν ἐδέοντο τῶν τοιούτων παιδευμάτων, ἀφ’ οὗ δὲ ἤρξαντο πρὸς ἡμερώτερα ἔθνη καὶ φῦλα τὴν πραγματείαν ἔχειν, ἐπέθεντο καὶ ταύτῃ τῇ ἀγωγῇ καὶ κατέστησαν πάντων κύριοι.", "st": "9.2.2"}, {"sp": "N", "t": "ἡ δ’ οὖν Βοιωτία πρότερον μὲν ὑπὸ βαρβάρων ᾠκεῖτο Ἀόνων καὶ Τεμμίκων ἐκ τοῦ Σουνίου πεπλανημένων καὶ Λελέγων καὶ Ὑάντων· εἶτα Φοίνικες ἔσχον οἱ μετὰ Κάδμου, ὃς τήν τε Καδμείαν ἐτείχισε καὶ τὴν ἀρχὴν τοῖς ἐκγόνοις ἀπέλιπεν. ἐκεῖνοι δὲ τὰς Θήβας τῇ Καδμείᾳ προσέκτισαν, καὶ συνεφύλαξαν τὴν ἀρχὴν ἡγούμενοι τῶν πλείστων Βοιωτῶν ἕως τῆς τῶν Ἐπιγόνων στρατείας. κατὰ δὲ τούτους ὀλίγον χρόνον ἐκλιπόντες τὰς Θήβας ἐπανῆλθον πάλιν· ὡς δ’ αὕτως ὑπὸ Θρᾳκῶν καὶ Πελασγῶν ἐκπεσόντες ἐν Θετταλίᾳ συνεστήσαντο τὴν ἀρχὴν μετὰ Ἀρναίων ἐπὶ πολὺν χρόνον, ὥστε καὶ Βοιωτοὺς κληθῆναι πάντας. εἶτ’ ἀνέστρεψαν εἰς τὴν οἰκείαν, ἤδη τοῦ Αἰολικοῦ στόλου παρεσκευασμένου περὶ Αὐλίδα τῆς Βοιωτίας, ὃν ἔστελλον εἰς τὴν Ἀσίαν οἱ Ὀρέστου παῖδες. προσθέντες δὲ τῇ Βοιωτίᾳ τὴν Ὀρχομενίαν (οὐ γὰρ ἦσαν κοινῇ πρότερον, οὐδ’ Ὅμηρος μετὰ Βοιωτῶν αὐτοὺς κατέλεξεν ἀλλ’ ἰδίᾳ, Μινύας προσαγορεύσας) μετ’ ἐκείνων ἐξέβαλον τοὺς μὲν Πελασγοὺς εἰς Ἀθήνας, ἀφ’ ὧν ἐκλήθη μέρος τι τῆς πόλεως Πελασγικόν (ᾤκησαν δὲ ὑπὸ τῷ Ὑμηττῷ), τοὺς δὲ Θρᾷκας ἐπὶ τὸν Παρνασσόν. Ὕαντες δὲ τῆς Φωκίδος Ὕαν πόλιν ᾤκισαν.", "st": "9.2.3"}, {"sp": "N", "t": "φησὶ δ’ Ἔφορος τοὺς μὲν Θρᾷκας ποιησαμένους σπονδὰς πρὸς τοὺς Βοιωτοὺς ἐπιθέσθαι νύκτωρ στρατοπεδεύουσιν ὀλιγωρότερον ὡς εἰρήνης γεγονυίας· διακρουσαμένων [δ’] αὐτοὺς αἰτιωμένων τε ἅμα ὅτι τὰς σπονδὰς παρέβαινον, μὴ παραβῆναι φάσκειν ἐκείνους· συνθέσθαι γὰρ ἡμέρας, νύκτωρ δ’ ἐπιθέσθαι· ἀφ’ οὗ δὴ καὶ τὴν παροιμίαν εἰρῆσθαι “Θρᾳκία παρεύρεσις.” τοὺς δὲ Πελασγοὺς μένοντος ἔτι τοῦ πολέμου χρηστηριασομένους ἀπελθεῖν, ἀπελθεῖν δὲ καὶ τοὺς Βοιωτούς· τὸν μὲν οὖν τοῖς Πελασγοῖς δοθέντα χρησμὸν ἔφη μὴ ἔχειν εἰπεῖν, τοῖς δὲ Βοιωτοῖς ἀνελεῖν τὴν προφῆτιν ἀσεβήσαντας εὖ πράξειν· τοὺς δὲ θεωροὺς ὑπονοήσαντας χαριζομένην τοῖς Πελασγοῖς τὴν προφῆτιν κατὰ τὸ συγγενὲς (ἐπειδὴ καὶ τὸ ἱερὸν Πελασγικὸν ἐξ ἀρχῆς ὑπῆρξεν) οὕτως ἀνελεῖν, ἁρπάσαντας τὴν ἄνθρωπον εἰς πυρὰν ἐμβαλεῖν ἐνθυμηθέντας, εἴτε κακουργήσασαν εἴτε μή, πρὸς ἀμφότερα ὀρθῶς ἔχειν, εἰ μὲν παρεχρηστηρίασε, κολασθείσης αὐτῆς, εἰ δ’ οὐδὲν ἐκακούργησε, τὸ προσταχθὲν αὐτῶν πραξάντων. τοὺς δὲ περὶ τὸ ἱερὸν τὸ μὲν ἀκρίτους κτείνειν τοὺς πράξαντας, καὶ ταῦτ’ ἐν ἱερῷ, μὴ δοκιμάσαι, καθιστάναι δ’ εἰς κρίσιν, καλεῖν δ’ ἐπὶ τὰς ἱερείας, ταύτας δὲ εἶναι τὰς προφήτιδας αἳ λοιπαὶ τριῶν οὐσῶν περιῆσαν· λεγόντων δ’ ὡς οὐδαμοῦ νόμος εἴη δικάζειν γυναῖκας, προσελέσθαι καὶ ἄνδρας ἴσους ταῖς γυναιξὶ τὸν ἀριθμόν· τοὺς μὲν οὖν ἄνδρας ἀπογνῶναι, τὰς δὲ γυναῖκας καταγνῶναι, ἴσων δὲ τῶν ψήφων γενομένων τὰς ἀπολυούσας νικῆσαι· ἐκ δὲ τούτων Βοιωτοῖς μόνοις ἄνδρας προθεσπίζειν ἐν Δωδώνῃ. τὰς μέντοι προφήτιδας ἐξηγουμένας τὸ μαντεῖον εἰπεῖν, ὅτι προστάττοι ὁ θεὸς τοῖς Βοιωτοῖς τοὺς παρ’ αὐτοῖς τρίποδας συλήσαντας ἕνα εἰς Δωδώνην πέμπειν κατ’ ἔτος· καὶ δὴ καὶ ποιεῖν τοῦτο· ἀεὶ γάρ τινα τῶν ἀνακειμένων τριπόδων νύκτωρ καθαιροῦντας καὶ κατακαλύπτοντας ἱματίοις ὡς ἂν λάθρᾳ τριποδηφορεῖν εἰς Δωδώνην.", "st": "9.2.4"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τὴν Αἰολικὴν ἀποικίαν συνέπραξαν τοῖς περὶ Πενθίλον, πλείστους ἐξ ἑαυτῶν συμπέμψαντες, ὥστε καὶ Βοιωτικὴν προσαγορευθῆναι. ὕστερον δὲ χρόνοις πολλοῖς ὁ Περσικὸς πόλεμος περὶ Πλαταιὰς γενόμενος διελυμήνατο τὴν χώραν. εἶτ’ ἀνέλαβον σφᾶς πάλιν ἐπὶ τοσοῦτον ὥστε καὶ τῆς τῶν Ἑλλήνων ἀρχῆς ἀμφισβητῆσαι Θηβαίους δυσὶ μάχαις κρατήσαντας Λακεδαιμονίους. Ἐπαμεινώνδα δὲ πεσόντος ἐν τῇ μάχῃ ταύτης μὲν τῆς ἐλπίδος διεσφάλησαν, ὑπὲρ δὲ τῶν Ἑλλήνων ὅμως ἐπολέμησαν πρὸς Φωκέας τοὺς τὸ ἱερὸν συλήσαντας τὸ κοινόν. κακωθέντες δ’ ὑπό τε τούτου τοῦ πολέμου καὶ τῶν Μακεδόνων ἐπιθεμένων τοῖς Ἕλλησιν, ὑπὸ τῶν αὐτῶν τούτων καὶ ἀπέβαλον τὴν πόλιν κατασκαφεῖσαν καὶ ἀνέλαβον ἀνακτισθεῖσαν. ἐξ ἐκείνου δ’ ἤδη πράττοντες ἐνδεέστερον ἀεὶ μέχρι εἰς ἡμᾶς οὐδὲ κώμης ἀξιολόγου τύπον σώζουσι· καὶ [αἱ] ἄλλαι δὲ πόλεις ἀνάλογον πλὴν Τανάγρας καὶ Θεσπιῶν· αὗται δ’ ἱκανῶς συμμένουσι πρὸς ἐκείνας κρινόμεναι.", "st": "9.2.5"}, {"sp": "N", "t": "ἑξῆς δὲ τὴν περιήγησιν τῆς χώρας ποιητέον ἀρξαμένους ἀπὸ τῆς πρὸς Εὔβοιαν παραλίας τῆς συνεχοῦς τῇ Ἀττικῇ. ἀρχὴ δ’ ὁ Ὠρωπὸς καὶ ὁ ἱερὸς λιμὴν ὃν καλοῦσι Δελφίνιον, καθ’ ὃν ἡ παλαιὰ Ἐρέτρια ἐν τῇ Εὐβοίᾳ, διάπλουν ἔχουσα ἑξήκοντα σταδίων. μετὰ δὲ τὸ Δελφίνιον ὁ Ὠρωπὸς ἐν εἴκοσι σταδίοις· κατὰ δὲ τοῦτόν ἐστιν ἡ νῦν Ἐρέτρια, διάπλους δ’ ἐπ’ αὐτὴν στάδιοι τετταράκοντα.", "st": "9.2.6"}, {"sp": "N", "t": "εἶτα Δήλιον τὸ ἱερὸν τοῦ Ἀπόλλωνος ἐκ Δήλου ἀφιδρυμένον, Ταναγραίων πολίχνιον Αὐλίδος διέχον σταδίους τριάκοντα, ὅπου μάχῃ λειφθέντες Ἀθηναῖοι προτροπάδην ἔφυγον· ἐν δὲ τῇ φυγῇ πεσόντα ἀφ’ ἵππου Ξενοφῶντα ἰδὼν κείμενον τὸν Γρύλλου Σωκράτης ὁ φιλόσοφος στρατεύων πεζὸς τοῦ ἵππου γεγονότος ἐκποδὼν ἀνέλαβε τοῖς ὤμοις αὐτόν, καὶ ἔσωσεν ἐπὶ πολλοὺς σταδίους ἕως ἐπαύσατο ἡ φυγή.", "st": "9.2.7"}, {"sp": "N", "t": "εἶτα λιμὴν μέγας ὃν καλοῦσι Βαθὺν λιμένα· εἶθ’ ἡ Αὐλὶς πετρῶδες χωρίον καὶ κώμη Ταναγραίων· λιμὴν δ’ ἐστὶ πεντήκοντα πλοίοις, ὥστ’ εἰκὸς τὸν ναύσταθμον τῶν Ἑλλήνων ἐν τῷ μεγάλῳ ὑπάρξαι λιμένι. καὶ ὁ Εὔριπος δ’ ἐστὶ πλησίον ὁ Χαλκίδος, εἰς ὃν ἀπὸ Σουνίου στάδιοι ἑξακόσιοι ἑβδομήκοντα· ἔστι δ’ ἐπ’ αὐτῷ γέφυρα δίπλεθρος, ὡς εἴρηκα· πύργος δ’ ἑκατέρωθεν ἐφέστηκεν ὁ μὲν ἐκ τῆς Χαλκίδος ὁ δ’ ἐκ τῆς Βοιωτίας· διῳκοδόμηται δ’ εἰς αὐτοὺς σῦριγξ. περὶ δὲ τῆς παλιρροίας τοῦ Εὐρίπου τοσοῦτον μόνον εἰπεῖν ἱκανόν, ὅτι ἑπτάκις μεταβάλλειν φασὶ καθ’ ἡμέραν ἑκάστην καὶ νύκτα· τὴν δ’ αἰτίαν ἐν ἄλλοις σκεπτέον.", "st": "9.2.8"}, {"sp": "N", "t": "πλησίον δ’ ἐστὶν ἐφ’ ὕψους κείμενον χωρίον Σαλγανεύς, ἐπώνυμον τοῦ ταφέντος ἐπ’ αὐτῷ Σαλγανέως ἀνδρὸς Βοιωτίου, καθηγησαμένου τοῖς Πέρσαις εἰσπλέουσιν εἰς τὸν διάπλουν τοῦτον ἐκ τοῦ Μαλιακοῦ κόλπου, ὅν φασιν ἀναιρεθῆναι πρὶν ἢ τῷ Εὐρίπῳ συνάπτειν ὑπὸ τοῦ ναυάρχου Μεγαβάτου νομισθέντα κακοῦργον, ὡς ἐξ ἀπάτης ἐμβαλόντα τὸν στόλον εἰς τυφλὸν τῆς θαλάττης στενωπόν· αἰσθόμενον δὲ τὸν βάρβαρον τὴν περὶ αὐτὸν ἀπάτην μεταγνῶναί τε καὶ ταφῆς ἀξιῶσαι τὸν ἀναιτίως ἀποθανόντα.", "st": "9.2.9"}, {"sp": "N", "t": "καὶ ἡ Γραῖα δ’ ἐστὶ τόπος Ὠρωποῦ πλησίον καὶ τὸ ἱερὸν τοῦ Ἀμφιαράου καὶ τὸ Ναρκίσσου τοῦ Ἐρετριέως μνῆμα ὃ καλεῖται Σιγηλοῦ, ἐπειδὴ σιγῶσι παριόντες· τινὲς δὲ τῇ Τανάγρᾳ τὴν αὐτήν φασιν· ἡ Ποιμανδρὶς δ’ ἐστὶν ἡ αὐτὴ τῇ Ταναγρικῇ· καλοῦνται δὲ καὶ Γεφυραῖοι οἱ Ταναγραῖοι. ἐκ Κνωπίας δὲ τῆς Θηβαϊκῆς μεθιδρύ[θη κατὰ χρησμὸν] δεῦρο τὸ Ἀμφιαράειον.", "st": "9.2.10"}, {"sp": "N", "t": "καὶ ὁ Μυκαλησσὸς δὲ κώμη τῆς Ταναγραϊκῆς· κεῖται δὲ παρ’ ὁδὸν [τὴν ἐκ] Θηβῶν εἰς Χαλκίδα· ὡς δ’ αὕτως καὶ τὸ Ἅρμα, τῆς Ταναγραϊκῆς κώμη ἔρημος περὶ τὴν Μυκαλησσόν, ἀπὸ τοῦ Ἀμφιαράου ἅρματος λαβοῦσα τοὔνομα, ἑτέρα οὖσα τοῦ Ἅρματος τοῦ κατὰ τὴν Ἀττικήν, ὅ ἐστι περὶ Φυλήν, δῆμον τῆς Ἀττικῆς ὅμορον τῇ Τανάγρᾳ. ἐντεῦθεν δὲ ἡ παροιμία τὴν ἀρχὴν ἔσχεν ἡ λέγουσα “ὁπόταν δι’ Ἅρματος ἀστράψῃ,” ἀστραπήν τινα σημειουμένων κατὰ χρησμὸν τῶν λεγομένων Πυθαϊστῶν, βλεπόντων ὡς ἐπὶ τὸ Ἅρμα καὶ τότε πεμπόντων τὴν θυσίαν εἰς Δελφοὺς ὅταν ἀστράψαντα ἴδωσιν· ἐτήρουν δ’ ἐπὶ τρεῖς μῆνας, καθ’ ἕκαστον μῆνα ἐπὶ τρεῖς ἡμέρας καὶ νύκτας, ἀπὸ τῆς ἐσχάρας τοῦ ἀστραπαίου Διός· ἔστι δ’ αὕτη ἐν τῷ τείχει μεταξὺ τοῦ Πυθίου καὶ τοῦ Ὀλυμπίου. περὶ δὲ τοῦ Ἅρματος τοῦ Βοιωτιακοῦ οἱ μέν φασιν ἐκπεσόντος ἐκ τοῦ ἅρματος ἐν τῇ μάχῃ τοῦ Ἀμφιαράου κατὰ τὸν τόπον, ὅπου νῦν ἐστὶ τὸ ἱερὸν αὐτοῦ, τὸ ἅρμα ἔρημον ἐνεχθῆναι ἐπὶ τὸν ὁμώνυμον τόπον· οἱ δὲ τοῦ Ἀδράστου συντριβῆναι τὸ ἅρμα φεύγοντός φασιν ἐνταῦθα, τὸν δὲ διὰ τοῦ Ἀρείονος σωθῆναι. Φιλόχορος δ’ ὑπὸ τῶν κωμητῶν σωθῆναί φησιν αὐτόν, καὶ διὰ τοῦτο ἰσοπολιτείαν αὐτοῖς παρὰ τῶν Ἀργείων ὑπάρξαι.", "st": "9.2.11"}, {"sp": "N", "t": "ἔστι δὲ τῷ ἐκ Θηβῶν εἰς Ἄργος ἀνιόντι ἐν ἀριστερᾷ ἡ Τάναγρα κ … ἐν δεξιᾷ κεῖται· καὶ ἡ Ὑρία δὲ τῆς Ταναγραίας νῦν ἐστί, πρότερον δὲ τῆς Θηβαΐδος· ὅπου ὁ Ὑριεὺς μεμύθευται καὶ ἡ τοῦ Ὠρίωνος γένεσις, ἥν φησι Πίνδαρος ἐν τοῖς διθυράμβοις· κεῖται δ’ ἐγγὺς Αὐλίδος. ἔνιοι δὲ τὰς Ὑσιὰς Ὑρίην λέγεσθαί φασι, τῆς Παρασωπίας οὖσαν ὑπὸ τῷ Κιθαιρῶνι πλησίον Ἐρυθρῶν ἐν τῇ μεσογαίᾳ, ἄποικον Ὑριέων, κτίσμα δὲ Νυκτέως τοῦ Ἀντιόπης πατρός. εἰσὶ δὲ καὶ ἐν τῇ Ἀργείᾳ Ὑσίαι κώ[μη], οἱ δ’ ἐξ αὐτῆς Ὑσιᾶται λέγονται. τῶν δ’ Ἐρυθρῶν τούτων ἄποικοι αἱ ἐν Ἰωνίᾳ Ἐρυθραί. καὶ ὁ Ἑλεὼν δ’ ἐστὶ κώμη Ταναγρική, ἀπὸ τῶν ἑλῶν ὠνομασμένη.", "st": "9.2.12"}, {"sp": "N", "t": "μετὰ δὲ Σαλγανέα Ἀνθηδὼν πόλις λιμένα ἔχουσα, ἐσχάτη τῆς Βοιωτιακῆς παραλίας τῆς πρὸς Εὐβοίᾳ, καθάπερ καὶ ὁ ποιητὴς εἴρηκεν “Ἀνθηδόνα τ’ ἐσχατόωσαν.” εἰσὶ μέντοι ἔτι προϊόντι μικρὸν πολίχναι δύο τῶν Βοιωτῶν, Λάρυμνά τε, παρ’ ἣν ὁ Κηφισσὸς ἐκδίδωσι, καὶ ἔτι ἐπέκεινα Ἁλαί, ὁμώνυμοι τοῖς Ἀττικοῖς δήμοις. κατὰ δὲ τὴν παραλίαν ταύτην κεῖσθαί φασιν Αἰγὰς τὰς ἐν Εὐβοίᾳ, ἐν αἷς τὸ τοῦ Ποσειδῶνος ἱερὸν τοῦ Αἰγαίου· ἐμνήσθημεν δ’ αὐτοῦ καὶ πρότερον. δίαρμα δ’ ἐστὶν ἀπὸ μὲν τῆς Ἀνθηδόνος εἰς Αἰγὰς ἑκατὸν εἴκοσι στάδιοι, ἀπὸ δὲ τῶν ἄλλων τόπων πολὺ ἐλάττους· κεῖται δ’ ἐπὶ ὄρους ὑψηλοῦ τὸ ἱερόν, ἦν δέ ποτε καὶ πόλις· ἐγγὺς δὲ τῶν [Αἰγῶν] καὶ αἱ Ὀρόβιαι. ἐν δὲ τῇ Ἀνθηδονίᾳ Μεσσάπιον ὄρος ἐστὶν ἀπὸ Μεσσάπου, ὃς εἰς τὴν Ἰαπυγίαν ἐλθὼν Μεσσαπίαν τὴν χώραν ἐκάλεσεν. ἐνταῦθα δὲ καὶ τὰ περὶ τὸν Γλαῦκον μυθεύεται τὸν Ἀνθηδόνιον, ὅν φασιν εἰς κῆτος μεταβαλεῖν.", "st": "9.2.13"}, {"sp": "N", "t": "πλησίον δ’ ἐστὶν Ἀνθηδόνος ἱεροπρεπὴς τόπος τῆς Βοιωτίας, ἴχνη πόλεως ἔχων, ὁ καλούμενος Ἴσος συστέλλοντι τὴν πρώτην συλλαβήν. οἴονται δέ τινες δεῖν γράφειν “ἶσόν τε ζαθέην Ἀνθηδόνα τ’ ἐσχατόωσαν” ἐκτείνοντες τὴν πρώτην συλλαβὴν ποιητικῶς διὰ τὸ μέτρον, ἀντὶ τοῦ “Νῖσάν τε ζαθέην.” ἡ γὰρ Νῖσα οὐδαμοῦ φαίνεται τῆς Βοιωτίας, ὥς φησιν Ἀπολλόδωρος ἐν τοῖς περὶ νεῶν … [ε]ἴη, εἰ μὴ τὴν Νῖσαν οὕτως εἴρηκεν· ἦν γὰρ ὁ … Μεγαρικῇ. ἐκεῖθεν ἀπῳκισμένη πρός[χωρος τοῦ Κιθα]ιρῶνος, ἐκλέλειπται δὲ νῦν. τινὲς δὲ γράφουσι “Κρεῦσάν τε ζαθέην,” τὴν νῦν Κρέουσαν δεχόμενοι, τὸ τῶν Θεσπιέων ἐπίνειον ἐν τῷ Κρισαίῳ κόλπῳ ἱδρυμένον· ἄλλοι δὲ “Φαράς τε ζαθέας.” ἔστι δὲ τῆς τετρακωμίας τῆς περὶ Τάναγραν, Ἑλεῶνος Ἅρματος Μυκαλησσοῦ Φαρῶν. γράφουσι δὲ καὶ τοῦτο “Νῦσάν τε ζαθέην.” κώμη δ’ ἐστὶ τοῦ Ἑλικῶνος ἡ Νῦσα. ἡ μὲν οὖν παραλία τοιαύτη τις ἡ πρὸς Εὔβοιαν.", "st": "9.2.14"}, {"sp": "N", "t": "τὰ δ’ ἑξῆς ἐν τῇ μεσογαίᾳ πεδία ἐστὶ κοῖλα πάντοθεν ἐκ τῶν ἄλλων μερῶν ὄρεσι περιεχόμενα, τοῖς Ἀττικοῖς μὲν πρὸς νότου, πρὸς ἄρκτου δὲ τοῖς Φωκικοῖς· ἀπὸ δὲ τῆς ἑσπέρας ὁ Κιθαιρὼν λοξὸς ἐμπίπτει μικρὸν ὑπὲρ τῆς Κρισαίας θαλάττης, ἔχων τὴν ἀρχὴν συνεχῆ τοῖς Μεγαρικοῖς καὶ τοῖς Ἀττικοῖς ὄρεσιν, εἶτ’ ἐπιστρέφων εἰς τὰ πεδία, παυόμενος δὲ περὶ τὴν Θηβαίαν.", "st": "9.2.15"}, {"sp": "N", "t": "τῶν δὲ πεδίων τούτων τὰ μὲν λιμνάζει, ποταμῶν ἀναχεομένων εἰς αὐτά, τῶν δ’ ἐμπιπτόντων, εἶτα ἐκρύσεις λαμβανόντων· τὰ δ’ ἀνέψυκται καὶ γεωργεῖται παντοδαπῶς διὰ τὴν εὐκαρπίαν. ὑπάντρου δὲ καὶ σηραγγώδους οὔσης κατὰ βάθους τῆς γῆς, σεισμοὶ γενόμενοι πολλάκις ἐξαίσιοι τοὺς μὲν ἔφραξαν τῶν πόρων τοὺς δὲ ἀνέῳξαν, τοὺς μὲν μέχρι τῆς ἐπιφανείας τοὺς δὲ δι’ ὑπονόμων· συμβαίνει δὴ καὶ τοῖς ὕδασι τοῖς μὲν δι’ ὑπονόμων φέρεσθαι τῶν ῥείθρων τοῖς δ’ ἐπιπολῆς, τοῖς τε λιμναίοις καὶ τοῖς ποταμίοις. ἐγχωσθέντων δὲ κατὰ βάθους τῶν πόρων αὔξεσθαι τὰς λίμνας συμβαίνει μέχρι τῶν οἰκουμένων τόπων ὥστε καὶ πόλεις καταπίνεσθαι καὶ χώρας, ἀνοιχθέντων δὲ τῶν αὐτῶν ἢ ἄλλων ἀνακαλύπτεσθαι, καὶ τοὺς αὐτοὺς τόπους ποτὲ μὲν πλεῖσθαι ποτὲ δὲ πεζεύεσθαι, καὶ τὰς αὐτὰς πόλεις ποτὲ μὲν ἐπὶ τῇ λίμνῃ ποτὲ δὲ ἄπωθεν κεῖσθαι.", "st": "9.2.16"}, {"sp": "N", "t": "διττῶς δὲ τοῦτο γίνεται· καὶ γὰρ μενουσῶν ἀκινήτων τῶν πόλεων, ὅταν ἡ αὔξησις τῶν ὑδάτων ἥττων ᾖ τῆς ὑπερχύσεως διὰ ὕψος τῶν οἰκήσεων ἢ διὰ ἀπόστασιν, καὶ διὰ ἀνοικισμόν, ὅταν τῷ πλησιασμῷ κινδυνεύσαντες πολλάκις ἀπαλλαγὴν πορίσωνται τοῦ φόβου τὴν μετάληψιν τῶν χωρίων τῶν ἄπωθεν ἢ τῶν ἐν ὕψει. παρακολουθεῖ δὲ τοῖς οὕτως ἀνοικισθεῖσι τὸ τὴν αὐτὴν προσηγορίαν φυλάττουσιν, ἐτύμως πρότερον λεγομένοις ἀπὸ τοῦ συμβεβηκότος τοπικῶς, νῦν μη[κέτι] λέγεσθαι ἐτύμως· Πλαταιὰς γὰρ ἀπὸ τῆς πλάτης τῶν κωπῶν εἰρῆσθαι πιθανὸν καὶ Πλαταιέας τοὺς ἀπὸ κωπηλασίας ζῶντας, ἀλλὰ νῦν ἄπωθεν τῆς λίμνης οἰκοῦντες οὐκέτ’ ἂν προσαγορεύοιντο ἐτύμως. ἕλος τε καὶ Ἑλεὼν καὶ Εἱλέσιον ἐκλήθη διὰ τὸ ἐπὶ τοῖς ἕλεσιν ἱδρῦσθαι· νῦν δὲ οὐχ ὁμοίως ἔχει ταῦτα, ἢ ἀνοικισθέντων ἢ τῆς λίμνης ἐπιπολὺ ταπεινωθείσης διὰ τὰς ὕστερον γενομένας ἐκρύσεις· καὶ γὰρ τοῦτο δυνατόν.", "st": "9.2.17"}, {"sp": "N", "t": "δηλοῖ δὲ καὶ ὁ Κηφισσὸς τοῦτο μάλιστα τὴν Κωπαΐδα λίμνην πληρῶν. αὐξομένης γὰρ αὐτῆς ὥστε κινδυνεύειν καταποθῆναι τὰς Κώπας, [ἃς] ὅ τε ποιητὴς ὀνομάζει, καὶ ἀπ’ αὐτῶν ἡ λίμνη τὴν ἐπωνυμίαν εἴληφε, χάσμα γενηθὲν πρὸς τῇ λίμνῃ πλησίον τῶν Κωπῶν ἀνέῳξεν ὑπὸ γῆς ῥεῖθρον ὅσον τριάκοντα σταδίων καὶ ἐδέξατο τὸν ποταμόν, εἶτα ἐξέρρηξεν εἰς τὴν ἐπιφάνειαν κατὰ Λάρυμναν τῆς Λοκρίδος τὴν ἄνω· καὶ γὰρ ἑτέρα ἐστίν, ἧς [ἐμνήσθη]μεν, [ἡ] Βοιωτιακή, ἐπὶ τῇ θαλάττῃ, ᾗ προσέθεσαν Ῥωμαῖοι τὴν ἄνω. καλεῖται δ’ ὁ τόπος Ἀγχόη· ἔστι δὲ καὶ λίμνη ὁμώνυμος· ἐντεῦθεν δ’ ἤδη ὁ Κηφισσὸς ἐκδίδωσιν ἐπὶ τὴν θάλατταν. τότε μὲν οὖν παυσαμένης τῆς πλημμυρίδος, παῦλα καὶ τοῦ κινδύνου τοῖς παροικοῦσιν ὑπῆρξε, πλὴν τῶν ἤδη καταποθεισῶν πόλεων. πάλιν δ’ ἐγχουμένων τῶν πόρων, ὁ μεταλλευτὴς Κράτης ἀνὴρ Χαλκιδεὺς ἀνακαθαίρειν τὰ ἐμφράγματα ἐπαύσατο στασιασάντων τῶν Βοιωτῶν, καίπερ, ὡς αὐτὸς ἐν τῇ πρὸς Ἀλέξανδρον ἐπιστολῇ φησιν, ἀνεψυγμένων ἤδη πολλῶν, ἐν οἷς οἱ μὲν τὸν Ὀρχομενὸν οἰκεῖσθαι τὸν ἀρχαῖον ὑπελάμβανον, οἱ δ’ Ἐλευσῖνα καὶ Ἀθήνας παρὰ τὸν Τρίτωνα ποταμόν· λέγεται [δ’ οἰκίσαι] Κέκροπα, ἡνίκα τῆς Βοιωτίας ἐπῆρξε καλουμένης τότε Ὠγυγίας, ἀφανισθῆναι δὲ ταύτας ἐπικλυσθείσας ὕστερον. γενέσθαι δέ φασιν καὶ κατὰ Ὀρχομενὸν χάσμα, καὶ δέξασθαι τὸν Μέλανα ποταμὸν τὸν ῥέοντα διὰ τῆς Ἁλιαρτίας καὶ ποιοῦντα ἐνταῦθα τὸ ἕλος τὸ φύον τὸν αὐλητικὸν κάλαμον. ἀλλ’ οὗτος ἠφάνισται τελέως, εἴτε τοῦ χάσματος διαχέοντος αὐτὸν εἰς ἀδήλους πόρους, εἴτε τῶν περὶ Ἁλίαρτον ἑλῶν καὶ λιμνῶν προαναλισκόντων αὐτόν, ἀφ’ ὧν ποιήεντα καλεῖ τὸν [τόπον] ὁ ποιητὴς “καὶ ποιήενθ’ Ἁλίαρτον” λέγων.", "st": "9.2.18"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ἐκ τῶν Φωκικῶν ὀρῶν οἱ ποταμοὶ καταφέρονται, ὧν ὁ Κηφισσὸς ἐκ Λιλαίας Φωκικῆς πόλεως τὴν ἀρχὴν λαμβάνει, καθάπερ καὶ Ὅμηρός φησιν “οἵ τε Λίλαιαν ἔχον πηγῇς ἔπι Κηφισσοῖο·” δι’ Ἐλατείας δὲ ῥυεὶς μεγίστης τῶν ἐν Φωκεῦσι πόλεων, καὶ διὰ Παραποταμίων καὶ Φανοτέων ὁμοίως Φωκικῶν πολισμάτων, εἰς Χαιρώνειαν τῆς Βοιωτίας πρόεισιν, εἶτα διὰ τῆς Ὀρχομενίας καὶ τῆς Κορωνειακῆς εἰς τὴν Κωπαΐδα λίμνην ἐξίησι· καὶ ὁ Περμησσὸς δὲ καὶ ὁ Ὀλμειός, ἐκ τοῦ Ἑλικῶνος συμβάλλοντες ἀλλήλοις, εἰς τὴν αὐτὴν ἐμπίπτουσι λίμνην τὴν Κωπαΐδα τοῦ Ἁλιάρτου πλη[σίον· καὶ ἄλλα] δὲ ῥεύματα εἰς αὐτὴν ἐμβάλλει. ἔστι μὲν οὖν μεγάλη, τὴν περίμετρον ἔχουσα ὀγδοήκοντα καὶ τριακοσίων σταδίων, αἱ δὲ ἐκρύσεις οὐδαμοῦ φαίνονται πλὴν τοῦ δεχομένου τὸν Κηφισσὸν χάσματος καὶ τῶν ἑλῶν.", "st": "9.2.19"}, {"sp": "N", "t": "[Τῶν δὲ περι]κειμένων λιμνῶν ἐστὶν ἥ τε Τρεφία καὶ ἡ Κ[ηφισσίς, ἧς] μέμνηται καὶ Ὅμηρος “ὅς ῥ’ ἐν Ὕλῃ ναίεσκε μέγα πλούτοιο μεμηλώς, λίμνῃ κεκλιμένος Κηφισσίδι.” οὐ γὰρ λίμνην τὴν Κωπαΐδα βούλεται λέγειν, ὡς οἴονταί τινες, ἀλλὰ τὴν Ὑλικὴν προσαγορευομένην ἀπὸ τῆς πλησίον κώμης ἣν καλοῦσιν Ὕλας, οὐδὲ Ὕδην, ὡς ἔνιοι γράφουσιν “ὅς ῥ’ ἐν Ὕδῃ ναίεσκεν.” ἡ μὲν γάρ ἐστιν ἐν Λυδίᾳ “Τμώλῳ ὑπὸ νιφόεντι, Ὕδης ἐν πίονι δήμῳ,” ἡ δὲ Βοιωτιακή· ἐπιφέρει γοῦν τῷ “λίμνῃ κεκλιμένος Κηφισσίδι” τὸ “πὰρ δὲ οἱ ἄλλοι ναῖον Βοιωτοί.” ἡ μὲν γάρ ἐστι μεγάλη καὶ οὐκ ἐν τῇ Θηβαΐδι, ἡ δὲ μικρά, ἐκεῖθεν δι’ ὑπονόμων πληρουμένη, κειμένη μεταξὺ Θηβῶν καὶ Ἀνθηδόνος. Ὅμηρος δ’ ἑνικῶς ἐκφέρει τοτὲ μὲν ἐκτείνων τὴν πρώτην συλλαβήν, ὡς ἐν τῷ καταλόγῳ “ἠδ’ Ὕλην καὶ Πετεῶνα,” ποιητικῶς, τοτὲ δὲ συστέλλων “ὅς ῥ’ ἐν Ὕλῃ ναίεσκε” “σκυτοτόμων ὄχ’ ἄριστος Ὕλῃ ἔνι οἰκία ναίων.” οὐδ’ ἐνταῦθα εὖ γραφόντων τινῶν Ὕδῃ ἔνι· οὐ γὰρ ὁ Αἴας ἐκ Λυδίας τὸ σάκος μετεπέμπετο.", "st": "9.2.20"}, {"sp": "N", "t": "[Αὗται δ’ αἱ] λίμναι τὴν τάξιν τῶν ἐφεξῆς τόπω[ν ὑπογράφουσιν ὥστε] λόγῳ περιληφθῆναι σαφῶς, ὅτι ὁ [ποιητὴς ἀτάκτως χρῆται] τοῖς ὀνόμασι τῶν τόπων τῶν τε ἀξ[ιολόγων καὶ τῶν μή· καὶ] χαλεπὸν ἐν τοσούτοις καὶ ἀσήμοις τοῖς πλείστοις καὶ ἐν μεσογαίᾳ μηδαμοῦ τῇ τάξει διαπεσεῖν· ἡ παραλία δ’ ἔχει τι πλεονέκτημα πρὸς τοῦτο· καὶ γνωριμώτεροι οἱ τόποι, καὶ ἡ θάλαττα τό γε ἑξῆς ὑπαγορεύει βέλτιον· διόπερ καὶ ἡμεῖς ἐκεῖθεν πειρώμ[εθα περιοδεύειν]· ἐνταῦθα δ’ ἐάσαντες τοῦτο τῷ π[οιητῇ ἀκολουθοῦντες ποιήσομεν τὴν] διαρίθμησιν, προστιθέντες ὅ τι ἂν χρήσιμον ᾖ [πρὸς τὴν ὑπόθεσι]ν ἡμῖν, ὑπ’ ἐκείνου δὲ παραλειφθέν. ἄρχεται [δ’ ἀπὸ τῆς Ὑρί]ης καὶ τῆς Αὐλίδος, περὶ ὧν εἰρήκαμεν.", "st": "9.2.21"}, {"sp": "N", "t": "σχοῖνος δ’ ἐστὶ χώρα τῆς Θηβαϊκῆς κατὰ τὴν ὁδὸν τὴν ἐπὶ Ἀνθηδόνος, διέχουσα τῶν Θηβῶν ὅσον πεντήκοντα σταδίους· ῥεῖ δὲ καὶ ποταμὸς δι’ αὐτῆς Σχοινοῦς.", "st": "9.2.22"}, {"sp": "N", "t": "Σκῶλος δ’ ἐστὶ κώμη τῆς Παρασωπίας ὑπὸ τῷ Κιθαιρῶνι, δυσοίκητος τόπος καὶ τραχύς, ἀφ’ οὗ καὶ ἡ παροιμία “εἰς Σκῶλον μήτ’ αὐτὸς ἴναι, μήτ’ ἄλλῳ ἕπεσθαι.” καὶ τὸν Πενθέα δὲ ἐνθένδε καταγόμενον διασπασθῆναί φασιν. ἦν δὲ καὶ τῶν περὶ Ὄλυνθον πόλεων ὁμώνυμος αὐτῇ Σκῶλος. εἴρηται δ’ ὅτι Παρασώπιοι καὶ κώμη τις καλεῖται ἐν Ἡρακλείᾳ τῇ Τραχινίᾳ, παρ’ ἣν ῥεῖ Ἀσωπὸς ποταμός, καὶ ὅτι ἐν Σικυωνίᾳ ἄλλος ἐστὶν Ἀσωπὸς καὶ ἡ χώρα Ἀσωπία, δι’ ἧς ῥεῖ.", "st": "9.2.23"}, {"sp": "N", "t": "ὁ Ἐτεωνὸς δὲ Σκάρφη μετωνομάσθη, καὶ αὕτη δὲ τῆς Παρασωπίας. ὁ γὰρ Ἀσωπὸς καὶ ὁ Ἰσμηνὸς διὰ τοῦ πεδίου ῥέουσι τοῦ πρὸ τῶν Θηβῶν· ἔστι δὲ καὶ ἡ Δίρκη κρήνη καὶ Πότνιαι, ἐφ’ ὧν μυθεύεται τὰ περὶ τὸν Ποτνιέα Γλαῦκον τὸν διασπασθέντα ὑπὸ τῶν Ποτνιάδων ἵππων τῆς πόλεως πλησίον, καὶ ὁ Κιθαιρὼν δὲ οὐκ ἄπωθεν τῶν Θηβῶν τελευτᾷ· παρ’ αὐτὸν δὲ ὁ Ἀσωπὸς ῥεῖ, τὴν ὑπώρειαν αὐτοῦ κλύζων καὶ ποιῶν τοὺς Παρασωπίους εἰς κατοικίας πλείους διῃρημένους, ἅπαντας δ’ ὑπὸ Θηβαίοις ὄντας (ἕτεροι δ’ ἐν τῇ Πλαταιέων φασὶ τόν τε Σκῶλον καὶ τὸν Ἐτεωνὸν καὶ τὰς Ἐρύθρας· καὶ γὰρ παρα[ρρεῖ] Πλαταιὰς καὶ παρὰ Τάναγραν ἐκδίδωσιν)· ἐν δὲ τῇ Θηβαίων εἰσὶ καὶ αἱ Θεράπναι καὶ ὁ Τευμησσός, ὃν ἐκόσμησεν Ἀντίμαχος διὰ πολλῶν ἐπῶν, τὰς μὴ προσούσας ἀρετὰς διαριθμούμενος “ἔστι τις ἠνεμόεις ὀλίγος λόφος.” γνώριμα δὲ τὰ ἔπη.", "st": "9.2.24"}, {"sp": "N", "t": "Θέσπειαν δὲ λέγει τὰς νῦν Θεσπιάς, πολλῶν ὀνομάτων τῶν μὲν ἀμφοτέρως λεγομένων καὶ ἑνικῶς καὶ πληθυντικῶς, καθάπερ καὶ ἀρρενικῶς καὶ θηλυκῶς, τῶν δ’ ὁποτέρως. ἔστι δὲ πόλις πρὸς τῷ Ἑλικῶνι νοτιωτέρα αὐτοῦ, ἐπικειμένη δὲ τῷ Κρισαίῳ κόλπῳ καὶ αὐτὴ καὶ ὁ Ἑλικών· ἐπίνειον δ’ ἔχουσιν αἱ Θεσπιαὶ Κρέουσαν, ἣν καὶ Κρεουσίδα καλοῦσιν. ἐν δὲ τῇ Θεσπιέων ἐστὶ καὶ ἡ Ἄσκρη κατὰ τὸ πρὸς Ἑλικῶνα μέρος, ἡ τοῦ Ἡσιόδου πατρίς· ἐν δεξιᾷ γάρ ἐστι τοῦ Ἑλικῶνος, ἐφ’ ὑψηλοῦ καὶ τραχέος τόπου κειμένη, ἀπέχουσα τῶν Θεσπιῶν ὅσον τετταράκοντα σταδίους, ἣν καὶ κεκωμῴδηκεν αὐτὸς ἐ[πιλαβόμενος] τοῦ πατρός, ὅτι ἐκ Κύμης τῆς Αἰολίδος μ[ετέστη, θρασύ]τερον λέγων “νάσσατο δ’ ἄγχ’ Ἑλικῶνος ὀιζυρῇ [ἐνὶ κώμῃ], Ἄσκρῃ χεῖμα κακῇ, θέρει ἀργαλέῃ, οὐδέ ποτ’ [ἐσθλῇ].” ὁ δὲ Ἑλικὼν συνεχής ἐστι τῇ Φωκίδι ἐκ τῶν πρὸς ἄρκτον αὐτοῦ μερῶν· μικρὰ δὲ καὶ ἐκ τῶν πρὸς ἑσπέραν κατὰ τὸν ὕστατον λιμένα τῆς Φωκίδος, ὃν καλοῦσιν ἀπὸ τοῦ συμβεβηκότος μυχόν· ὑπέρκειται γὰρ κατὰ τοῦτον μάλιστα τὸν λιμένα τοῦ Κρισαίου κόλπου καὶ ὁ Ἑλικὼν καὶ ἡ Ἄσκρη καὶ ἔτι αἱ Θεσπιαὶ καὶ τὸ ἐπίνειον αὐτῆς ἡ Κρέουσα. τοῦτο δὲ καὶ κοιλότατον νομίζεται τὸ μέρος τοῦ Κρισαίου κόλπου καὶ ἁπλῶς τοῦ Κορινθιακοῦ· στάδιοι δ’ εἰσὶ τῆς [παραλίας] τῆς ἀπὸ τοῦ μυχοῦ τοῦ λιμένος εἰς Κρέουσαν ἐνε[νήκοντα·] ἐντεῦθεν δὲ ἑκατὸν εἴκοσιν ἕως τῆς ἄκρας ἣν [Ὀλμιὰς] καλοῦσιν· ἐν δὲ τῷ κοιλοτάτῳ τοῦ κόλπου τοῦ [Κρισαίου συμ]βέβηκε τὰς Πηγὰς κεῖσθαι καὶ τὴν Οἰνόην, πε[ρὶ ὧν εἰ]ρήκαμεν. ὁ μὲν οὖν Ἑλικὼν οὐ πολὺ διεστηκὼς τοῦ Παρνασσοῦ ἐνάμιλλός ἐστιν ἐκείνῳ κατά τε ὕψος καὶ περίμετρον· ἄμφω γὰρ χιονόβολα τὰ ὄρη καὶ πετρώδη, περιγράφεται δ’ οὐ πολλῇ χώρᾳ. ἐνταῦθα δ’ ἐστὶ τό τε τῶν Μουσῶν ἱερὸν καὶ ἡ Ἵππου κρήνη καὶ τὸ τῶν Λειβηθρίδων νυμφῶν ἄντρον· ἐξ οὗ τεκμαίροιτ’ ἄν τις Θρᾷκας εἶναι τοὺς τὸν Ἑλικῶνα ταῖς Μούσαις καθιερώσαντας, οἳ καὶ τὴν Πιερίδα καὶ τὸ Λείβηθρον καὶ τὴν Πίμπλειαν ταῖς αὐταῖς θεαῖς ἀνέδειξαν· ἐκαλοῦντο δὲ Πίερες· ἐκλιπόντων δ’ ἐκείνων Μακεδόνες νῦν ἔχουσι τὰ χωρία ταῦτα. εἴρηται δ’ ὅτι τὴν Βοιωτίαν ταύτην ἐπῴκησάν ποτε Θρᾷκες βιασάμενοι τοὺς Βοιωτοὺς καὶ Πελασγοὶ καὶ ἄλλοι βάρβαροι. αἱ δὲ Θεσπιαὶ πρότερον μὲν ἐγνωρίζοντο διὰ τὸν Ἔρωτα τὸν Πραξιτέλους, ὃν ἔγλυψε μὲν ἐκεῖνος, ἀνέθηκε δὲ Γλυκέρα ἡ ἑταίρα Θεσπιεῦσιν ἐκεῖθεν οὖσα τὸ γένος, λαβοῦσα δῶρον παρὰ τοῦ τεχνίτου. πρότερον μὲν οὖν ὀψόμενοι τὸν Ἔρωτά τινες ἀνέβαινον ἐπὶ τὴν Θέσπειαν ἄλλως οὐκ οὖσαν ἀξιοθέατον, νυνὶ δὲ μόνη συνέστηκε τῶν Βοιωτιακῶν πόλεων καὶ Τάναγρα· τῶν δ’ ἄλλων ἐρείπια καὶ ὀνόματα λέλειπται.", "st": "9.2.25"}, {"sp": "N", "t": "[μετ]ὰ δὲ Θεσπιὰς καταλέγει Γραῖαν καὶ Μυκα[λησσόν, περ]ὶ ὧν εἰρήκαμεν· ὡς δ’ αὕτως καὶ περὶ τῶν [ἄλλων οἵ τ’] ἀμφ’ Ἅρμ’ ἐνέμοντο καὶ Εἰλέσιον “καὶ Ἐρύθρας, [οἵ τ’ Ἐλεῶν’] εἶχον ἠδ’ Ὕλην καὶ Πετεῶνα.” Πετεὼν δὲ κώμη τῆς Θηβαΐδος ἐγγὺς τῆς ἐπ’ Ἀνθηδόνα ὁδοῦ, ἡ δ’ Ὠκαλέη μέση Ἁλιάρτου καὶ Ἀλαλκομενίου ἑκατέρου τριάκοντα σταδίους ἀπέχουσα· παραρρεῖ δ’ αὐτὴν ποτάμιον ὁμώνυμον. Μεδεὼν δ’ ὁ μὲν Φωκικὸς ἐν τῷ Κρισαίῳ κόλπῳ, διέχων Βοιωτίας σταδίους ἑκατὸν ἑξήκοντα, ὁ δὲ Βοιωτιακὸς ἀπ’ ἐκείνου κέκληται, πλησίον δ’ ἐστὶν Ὀγχηστοῦ ὑπὸ τῷ Φοινικίῳ ὄρει, ἀφ’ οὗ καὶ μετωνόμασται Φοινικίς· τῆς δὲ Θηβαίας καὶ τοῦτο λέγεται, [ὑπ’ ἐνί]ων δὲ τῆς Ἁλιαρτίας καὶ Μεδεὼν καὶ Ὠκαλέα.", "st": "9.2.26"}, {"sp": "N", "t": "εἶτά φησι “κώπας Εὔτρησίν τε πολυτρήρωνά τε Θίσβην.” περὶ μὲν οὖν Κωπῶν εἴρηται· προσάρκτιος δέ ἐστιν ἐπὶ τῇ Κωπαΐδι λίμνῃ· αἱ δ’ ἄλλαι κύκλῳ εἰσὶν αἵδε, Ἀκραιφίαι Φοινικὶς Ὀγχηστὸς Ἁλίαρτος Ὠκαλέα Ἀλαλκομεναὶ Τιλφούσιον Κορώνεια. καὶ τό γε παλαιὸν οὐκ ἦν τῆς λίμνης κοινὸν ὄνομα, ἀλλὰ καθ’ ἑκάστην πρὸς αὐτῇ κατοικίαν ἐκείνης ἐπώνυμος ἐλέγετο, Κωπαῒς μὲν τῶν Κωπῶν, Ἁλιαρτὶς δὲ Ἁλιάρτου, καὶ οὕτως ἐπὶ τῶν ἄλλων, ὕστερον δ’ ἡ πᾶσα Κωπαῒς ἐλέχθη κατ’ ἐπικράτειαν· κοιλότατον γὰρ τοῦτο τὸ χωρίον. Πίνδαρος δὲ καὶ Κηφισσίδα καλεῖ ταύτην· παρατίθησι γοῦν τὴν Τιλφῶσσαν κρήνην ὑπὸ τῷ Τιλφωσσίῳ ὄρει ῥέουσαν πλησίον Ἁλιάρτου καὶ Ἀλαλκομενῶν, ἐφ’ ᾗ τὸ Τειρεσίου μνῆμα· αὐτοῦ δὲ καὶ τὸ τοῦ Τιλ[φωσσίου Ἀπόλλω]νος ἱερόν.", "st": "9.2.27"}, {"sp": "N", "t": "ὁ δὲ ποιητὴς ἐφεξῆς ταῖς Κώπαις Εὔτρησιν τίθησι κώμιον Θεσπιέων· ἐνταῦθά φασι Ζῆθον καὶ Ἀμφίονα οἰκῆσαι πρὶν βασιλεῦσαι Θηβῶν. ἡ δὲ Θίσβη Θίσβαι νῦν λέγονται, οἰκεῖται δὲ μικρὸν ὑπὲρ τῆς θαλάττης ὅμορον Θεσπιεῦσι τὸ χωρίον καὶ τῇ Κορωνειακῇ, ὑποπεπτωκὸς ἐκ τοῦ νοτίου μέρους τῷ Ἑλικῶνι καὶ αὐτό· ἐπίνειον δ’ ἔχει πετρῶδες περιστερῶν μεστόν, ἐφ’ οὗ φησιν ὁ ποιητὴς “πολυτρήρωνά τε Θίσβην.” πλοῦς δ’ ἐστὶν ἐνθένδε εἰς Σικυῶνα σταδίων ἑκατὸν ἑξήκοντα.", "st": "9.2.28"}, {"sp": "N", "t": "ἑξῆς δὲ Κορώνειαν καταλέγει καὶ Ἁλίαρτον καὶ Πλαταιὰς καὶ Γλίσσαντα. ἡ μὲν οὖν Κορώνεια ἐγγὺς τοῦ Ἑλικῶνός ἐστιν ἐφ’ ὕψους ἱδρυμένη, κατελάβοντο δ’ αὐτὴν ἐπανιόντες ἐκ τῆς Θετταλικῆς Ἄρνης οἱ Βοιωτοὶ μετὰ τὰ Τρωικά, ὅτε περ καὶ τὸν Ὀρχομενὸν ἔσχον· κρατήσαντες δὲ τῆς Κορωνείας ἐν τῷ πρὸ αὐτῆς πεδίῳ τὸ τῆς Ἰτωνίας Ἀθηνᾶς ἱερὸν ἱδρύσαντο ὁμώνυμον τῷ Θετταλικῷ, καὶ τὸν παραρρέοντα ποταμὸν Κουάριον προσηγόρευσαν ὁμοφώνως τῷ ἐκεῖ. Ἀλκαῖος δὲ καλεῖ Κωράλιον λέγων “[ὦ ’ν]ασσ’ Ἀθανάα πολε[μηδόκος], ἅ ποι Κορωνίας ἐπὶ λαΐω ναύω πάροιθεν ἀμφι[βαίνεις] Κωραλίω ποταμῶ παρ’ ὄχθαις.” ἐνταῦθα δὲ καὶ τὰ Παμβοιώτια συντέλουν· συγκαθίδρυται δὲ τῇ Ἀθηνᾷ ὁ Ἅιδης κατά τινα, ὥς φασι, μυστικὴν αἰτίαν. οἱ μὲν οὖν ἐν τῇ Κορωνείᾳ Κορώνιοι λέγονται, οἱ δ’ ἐν τῇ Μεσσηνιακῇ Κορωναεῖς.", "st": "9.2.29"}, {"sp": "N", "t": "Ἁλίαρτος δὲ νῦν οὐκέτι ἐστὶ κατασκαφεῖσα ἐν τῷ πρὸς Περσέα πολέμῳ, τὴν χώραν δ’ ἔχουσιν Ἀθηναῖοι δόντων Ῥωμαίων. ἔκειτο δὲ ἐν στενῷ χωρίῳ μεταξὺ ὑπερκειμένου ὄρους καὶ τῆς Κωπαΐδος λίμνης πλησίον τοῦ Περμησσοῦ καὶ τοῦ Ὀλμειοῦ καὶ τοῦ ἕλους τοῦ φύοντος τὸν αὐλητικὸν κάλαμον.", "st": "9.2.30"}, {"sp": "N", "t": "Πλαταιαὶ δέ, ἃς ἑνικῶς εἶπεν ὁ ποιητής, ὑπὸ τῷ Κιθαιρῶνί εἰσι μεταξὺ αὐτοῦ καὶ Θηβῶν κατὰ τὴν ὁδὸν τὴν εἰς Ἀθήνας καὶ Μέγαρα ἐπὶ τῶν ὅρων τῶν τῆς Ἀττικῆς καὶ τῆς Βοιωτίας. [αἱ] γὰρ Ἐλευθεραὶ πλησίον, ἃς οἱ μὲν [τῆς Ἀττικῆς, οἱ δὲ] τῆς Βοιωτίας φασίν. εἴρηται δ’ ὅτι παραρρεῖ τὰς Πλαταιὰς ὁ Ἀσωπός. ἐνταῦθα Μαρδόνιον καὶ τὰς τριάκοντα μυριάδας Περσῶν αἱ τῶν Ἑλλήνων δυνάμεις ἄρδην ἠφάνισαν· ἱδρύσαντό τε ἐλευθερίου Διὸς ἱερὸν καὶ ἀγῶνα γυμνικὸν στεφανίτην ἀπέδειξαν, Ἐλευθέρια προσαγορεύσαντες· ταφή τε δείκνυται δημοσία τῶν τελευτησάντων ἐν τῇ μάχῃ. ἔστι δὲ καὶ ἐν τῇ Σικυωνίᾳ δῆμος Πλαταιαί, ὅθενπερ ἦν Μνασάλκης ὁ ποιητής. Γλίσσαντα δὲ λέγει κατοικίαν ἐν τῷ Ὑπάτῳ ὄρει ὅ ἐστιν ἐν τῇ Θηβαϊκῇ πλησίον Τευμησσοῦ καὶ τῆς Καδμείας, ᾧ [ὑποπ]ίπτει τὸ Ἀόνιον καλούμενον πεδίον, ὃ διατείνει [εἰς τὴν Καδμεία]ν ἀπὸ τοῦ Ὑπάτου ὄρους.", "st": "9.2.31"}, {"sp": "N", "t": "τὸ δ’ οὕτω ῥηθέν “οἵ θ’ ὑπὸ Θήβας εἶχον” οἱ μὲν δέχονται πολείδιόν τι Ὑποθήβας καλούμενον, οἱ δὲ τὰς Ποτνίας· τὰς γὰρ Θήβας ἐκλελεῖφθαι διὰ τὴν τῶν Ἐπιγόνων στρατείαν καὶ μὴ μετασχεῖν τοῦ Τρωικοῦ πολέμου· οἱ δὲ μετασχεῖν μὲν οἰκεῖν δὲ ὑπὸ τῇ Καδμείᾳ τότε ἐν τοῖς ἐπιπέδοις χωρίοις μετὰ τὴν τῶν Ἐπιγόνων ἄφοδον, τὴν Καδμείαν ἀδυνατοῦντας ἀνακτίσαι· ἐπεὶ δὲ ἡ Καδμεία ἐκαλεῖτο Θῆβαι, ὑπὸ Θήβας εἰπεῖν ἀντὶ τοῦ ὑπὸ τῇ Καδμείᾳ οἰκοῦντας τὸν ποιητὴν τοὺς τότε Θηβαίους.", "st": "9.2.32"}, {"sp": "N", "t": "Ὀγχηστὸς δ’ ἐστίν, ὅπου τὸ Ἀμφικτυονικὸν συνήγετο ἐν τῇ Ἁλιαρτίᾳ πρὸς τῇ Κωπαΐδι λίμνῃ καὶ τῷ Τηνερικῷ πεδίῳ, ἐν ὕψει κείμενος ψιλός, ἔχων Ποσειδῶνος ἱερὸν καὶ αὐτὸ ψιλόν. οἱ δὲ ποιηταὶ κοσμοῦσιν, ἄλση καλοῦντες τὰ ἱερὰ πάντα κἂν ᾖ ψιλά· τοιοῦτόν ἐστι καὶ τὸ τοῦ Πινδάρου περὶ τοῦ Ἀπόλλωνος λεγόμενον<br>[δι]νηθεὶς ἐπῄει<br>γᾶν τε καὶ θάλασσαν, καὶ σκοπιαῖσιν [μεγάλαι]ς ὀρέων ὕπερ ἔστα,<br>καὶ μύλους δινάσατο βαλλό[μενος] κρηπῖδας ἀλσέων.<br>οὐκ εὖ δ’ ὁ Ἀλκαῖος, ὥσπερ τὸ τοῦ ποταμοῦ ὄνομα παρέτρεψε τοῦ Κουαρίου, οὕτω καὶ τοῦ Ὀγχηστοῦ κατέψευσται πρὸς ταῖς ἐσχατιαῖς τοῦ Ἑλικῶνος αὐτὸν τιθείς· ὁ δ’ ἐστὶν ἄπωθεν ἱκανῶς τούτου τοῦ ὄρους.", "st": "9.2.33"}, {"sp": "N", "t": "τὸ δὲ Τηνερικὸν πεδίον ἀπὸ Τηνέρου προσηγόρευται μυθεύεται δ’ Ἀπόλλωνος υἱὸς ἐκ Μελίας, προφήτης τοῦ μαντείου κατὰ τὸ Πτῷον ὄρος, ὅ φησιν εἶναι τρικόρυφον ὁ αὐτὸς ποιητής<br>καί ποτε τὸν τρικάρανον Πτωίου κευθμῶνα κατέσχεθε·<br>καὶ τὸν Τήνερον καλεῖ<br>ναοπόλον μάντιν δαπέδοισιν ὁμοκλέα.<br>ὑπέρκειται δὲ τὸ Πτῷον τοῦ Τηνερικοῦ πεδίου καὶ τῆς Κωπαΐδος λίμνης πρὸς Ἀκραιφίῳ· Θηβαίων δ’ ἦν τό τε μαντεῖον καὶ τὸ ὄρος· τὸ δ’ Ἀκραίφιον καὶ αὐτὸ κεῖται ἐν ὕψει. φασὶ δὲ τοῦτο καλεῖσθαι Ἄρνην ὑπὸ τοῦ ποιητοῦ, ὁμώνυμον τῇ Θετταλικῇ.", "st": "9.2.34"}, {"sp": "N", "t": "οἱ δέ φασι καὶ τὴν Ἄρνην ὑπὸ τῆς λίμνης καταποθῆναι καὶ τὴν Μίδειαν. Ζηνόδοτος δὲ γράφων “οἳ δὲ πολυστάφυλον Ἄσκρην ἔχον,” οὐκ ἔοικεν ἐντυχόντι τοῖς ὑπὸ Ἡσιόδου περὶ τῆς πατρίδος λεχθεῖσι καὶ τοῖς ὑπ’ Εὐδόξου πολὺ χείρω λέγοντος περὶ τῆς Ἄσκρης. πῶς γὰρ ἄν τις πολυστάφυλον τὴν τοιαύτην ὑπὸ τοῦ ποιητοῦ λέγεσθαι πιστεύσειεν; οὐκ εὖ δὲ οὐδὲ οἱ Τάρνην ἀντὶ τῆς Ἄρνης γράφοντες· οὐδὲ γὰρ μία δείκνυται Τάρνη παρὰ τοῖς Βοιωτοῖς, ἐν δὲ Λυδοῖς ἐστιν, ἧς καὶ Ὅμηρος μέμνηται “Ἰδομενεὺς δ’ ἄρα Φαῖστον ἐνήρατο Μῄονος υἱὸν Βώρου, ὃς ἐκ Τάρνης ἐριβώλακος εἰληλούθει.” λοιπαὶ δ’ εἰσὶ τῶν μὲν περικειμένων τῇ λίμνῃ αἵ τε Ἀλαλκομεναὶ καὶ τὸ Τιλφώσσιον, τῶν δ’ ἄλλων Χαιρώνεια καὶ Λεβάδεια καὶ Λεῦκτρα, περὶ ὧν ἄξιον μνησθῆναι.", "st": "9.2.35"}, {"sp": "N", "t": "Ἀλαλκομενῶν τοίνυν μέμνηται ὁ ποιητής, ἀλλ’ οὐκ ἐν καταλόγῳ “Ἥρη τ’ Ἀργείη καὶ Ἀλαλκομενηὶς Ἀθήνη.” ἔχει δ’ ἀρχαῖον ἱερὸν Ἀθηνᾶς σφόδρα τιμώμενον, καί φασί γε τὴν θεὸν γεγενῆσθαι ἐνθάδε, καθάπερ καὶ τὴν Ἥραν ἐν Ἄργει, καὶ διὰ τοῦτο τὸν ποιητὴν ὡς ἀπὸ πατρίδων τούτων ἀμφοτέρας οὕτως ὀνομάσαι. διὰ τοῦτο δ’ ἴσως οὐδ’ ἐν τῷ καταλόγῳ μέμνηται τῶν ἐνταῦθα ἀνδρῶν, ἐπειδὴ ἱεροὶ ὄντες παρεῖντο τῆς στρατείας. καὶ γὰρ καὶ ἀπόρθητος ἀεὶ διετέλεσεν ἡ πόλις, οὔτε μεγάλη οὖσα οὔτ’ ἐν εὐερκεῖ χωρίῳ κειμένη, ἀλλ’ ἐν πεδίῳ· τὴν δὲ θεὸν σεβόμενοι πάντες ἀπείχοντο πάσης βίας, ὥστε καὶ Θηβαῖοι κατὰ τὴν τῶν Ἐπιγόνων στρατείαν ἐκλιπόντες τὴν πόλιν ἐκεῖσε λέγονται καταφεύγειν καὶ εἰς τὸ ὑπερκείμενον ὄρος ἐρυμνὸν τὸ Τιλφώσσιον, ὑφ’ ᾧ Τιλφῶσσα κρήνη καὶ τὸ τοῦ Τειρεσίου μνῆμα ἐκεῖ τελευτήσαντος κατὰ τὴν φυγήν.", "st": "9.2.36"}, {"sp": "N", "t": "Χαιρώνεια δ’ ἐστὶν Ὀρχομενοῦ πλησίον, ὅπου Φίλιππος ὁ Ἀμύντου μάχῃ μεγάλῃ νικήσας Ἀθηναίους τε καὶ Βοιωτοὺς καὶ Κορινθίους κατέστη τῆς Ἑλλάδος κύριος· δείκνυται δὲ κἀνταῦθα ταφὴ τῶν πεσόντων ἐν τῇ μάχῃ δημοσία· περὶ δὲ τοὺς τόπους τοὺς αὐτοὺς καὶ Ῥωμαῖοι τὰς Μιθριδάτου δυνάμεις πολλῶν μυριάδων κατηγωνίσαντο, ὥστ’ ὀλίγους ἐπὶ θάλατταν σωθέντας φυγεῖν ἐν ταῖς ναυσί, τοὺς δ’ ἄλλους τοὺς μὲν ἀπολέσθαι τοὺς δὲ καὶ ἁλῶναι.", "st": "9.2.37"}, {"sp": "N", "t": "Λεβάδεια δ’ ἐστίν, ὅπου Διὸς Τροφωνίου μαντεῖον ἵδρυται, χάσματος ὑπονόμου κατάβασιν ἔχον, καταβαίνει δ’ αὐτὸς ὁ χρηστηριαζόμενος· κεῖται δὲ μεταξὺ τοῦ Ἑλικῶνος καὶ τῆς Χαιρωνείας, Κορωνείας πλησίον.", "st": "9.2.38"}, {"sp": "N", "t": "τὰ δὲ Λεῦκτρά ἐστιν, ὅπου Λακεδαιμονίους μεγάλῃ μάχῃ νικήσας Ἐπαμεινώνδας ἀρχὴν εὕρετο τῆς καταλύσεως αὐτῶν· οὐκέτι γὰρ ἐξ ἐκείνου τὴν τῶν Ἑλλήνων ἡγεμονίαν ἀναλαβεῖν ἴσχυσαν ἣν εἶχον πρότερον, καὶ μάλιστ’ ἐπειδὴ καὶ τῇ δευτέρᾳ συμβολῇ τῇ περὶ Μαντίνειαν κακῶς ἔπραξαν. τὸ μέντοι μὴ ὑφ’ ἑτέροις εἶναι καίπερ οὕτως ἐπταικόσι συνέμεινε μέχρι τῆς Ῥωμαίων ἐπικρατείας· καὶ παρὰ τούτοις δὲ τιμώμενοι διατελοῦσι διὰ τὴν τῆς πολιτείας ἀρετήν. δείκνυται δὲ ὁ τόπος οὗτος κατὰ τὴν ἐκ Πλαταιῶν εἰς Θεσπιὰς ὁδόν.", "st": "9.2.39"}, {"sp": "N", "t": "ἑξῆς δ’ ὁ ποιητὴς μέμνηται τοῦ τῶν Ὀρχομενίων καταλόγου, χωρίζων αὐτοὺς ἀπὸ τοῦ Βοιωτιακοῦ ἔθνους. καλεῖ δὲ Μινύειον τὸν Ὀρχομενὸν ἀπὸ ἔθνους τοῦ Μινυῶν· ἐντεῦθεν δὲ ἀποικῆσαί τινας τῶν Μινυῶν εἰς Ἰωλκόν φασιν, ὅθεν τοὺς Ἀργοναύτας Μινύας λεχθῆναι. φαίνεται δὲ τὸ παλαιὸν καὶ πλουσία τις γεγονυῖα πόλις καὶ δυναμένη μέγα· τοῦ μὲν οὖν πλούτου μάρτυς καὶ Ὅμηρος· διαριθμούμενος γὰρ τοὺς τόπους τοὺς πολυχρηματήσαντάς φησιν “οὐδ’ ὅσ’ ἐς Ὀρχομενὸν ποτινίσσεται, οὐδ’ ὅσα Θήβας Αἰγυπτίας.” τῆς δυνάμεως δέ, ὅτι Θηβαῖοι δασμὸν ἐτέλουν τοῖς Ὀρχομενίοις καὶ Ἐργίνῳ τῷ τυραννοῦντι αὐτῶν, ὃν ὑφ’ Ἡρακλέους καταλυθῆναί φασιν. Ἐτεοκλῆς δέ, τῶν βασιλευσάντων ἐν Ὀρχομενῷ τις, Χαρίτων ἱερὸν ἱδρυσάμενος πρῶτος ἀμφότερα ἐμφαίνει, καὶ πλοῦτον καὶ δύναμιν, ὃς εἴτ’ ἐν τῷ λαμβάνειν χάριτας εἴτ’ ἐν τῷ διδόναι κατορθῶν εἴτε καὶ ἀμφότερα, τὰς θεὰς ἐτίμησε ταύτας. λέγουσι δὲ τὸ χωρίον, ὅπερ ἡ λίμνη κατέχει νῦν ἡ Κωπαΐς, ἀνεψῦχθαι πρότερον καὶ γεωργεῖσθαι παντοδαπῶς ὑπὸ τοῖς Ὀρχομενίοις ὂν πλησίον οἰκοῦσι· καὶ τοῦτ’ οὖν τεκμήριον τοῦ πλούτου τιθέασι.", "st": "9.2.40"}, {"sp": "N", "t": "τὴν δ’ Ἀσπληδόνα χωρὶς τῆς πρώτης συλλαβῆς ἐκάλουν τινές· εἶτ’ Εὐδείελος μετωνομάσθη καὶ αὐτὴ καὶ ἡ χώρα, τάχα τι ἰδίωμα προσφερομένη ἐκ τοῦ δειλινοῦ κλίματος οἰκεῖον τοῖς κατοικοῦσι, καὶ μάλιστα τὸ εὐχείμερον. διέχει δὲ τοῦ Ὀρχομενοῦ στάδια εἴκοσι· μεταξὺ δ’ ὁ Μέλας ποταμός.", "st": "9.2.41"}, {"sp": "N", "t": "ὑπέρκειται δ’ Ὀρχομενίας ὁ Πανοπεύς, Φωκικὴ πόλις, καὶ Ὑάμπολις· τούτοις δ’ ὁμορεῖ Ὀποῦς, ἡ τῶν Λοκρῶν μητρόπολις τῶν Ἐπικνημιδίων. πρότερον μὲν οὖν οἰκεῖσθαι τὸν Ὀρχομενόν φασιν ἐπὶ πεδίῳ, ἐπιπολαζόντων δὲ τῶν ὑδάτων ἀνοικισθῆναι πρὸς τὸ Ἀκόντιον ὄρος, παρατεῖνον ἐπὶ ἑξήκοντα σταδίους μέχρι Παραποταμίων τῶν ἐν τῇ Φωκίδι. ἱστοροῦσι δὲ τοὺς ἐν τῷ Πόντῳ καλουμένους Ἀχαιοὺς ἀποίκους Ὀρχομενίων εἶναι τῶν μετὰ Ἰαλμένου πλανηθέντων ἐκεῖσε μετὰ τὴν τῆς Τροίας ἅλωσιν. καὶ περὶ Κάρυστον δ’ ἦν τις Ὀρχομενός. εὖ γὰρ τὴν τοιαύτην ὕλην ὑποβεβλήκασιν ἡμῖν οἱ τὰ περὶ τῶν νεῶν συγγράψαντες, οἷς ἀκολουθοῦμεν ὅταν οἰκεῖα λέγωσι πρὸς τὴν ἡμετέραν ὑπόθεσιν.", "st": "9.2.42"}, {"sp": "N", "t": "μετὰ δὲ τὴν Βοιωτίαν καὶ τὸν Ὀρχομενὸν ἡ Φωκίς ἐστι πρὸς ἄρκτον παραβεβλημένη τῇ Βοιωτίᾳ παραπλησίως ἀπὸ θαλάττης εἰς θάλατταν τό γε παλαιόν. ὁ γὰρ Δαφνοῦς ἦν τότε τῆς Φωκίδος, σχίζων ἐφ’ ἑκάτερα τὴν Λοκρίδα καὶ μέσος ταττόμενος τοῦ τε Ὀπουντίου κόλπου καὶ τῆς τῶν Ἐπικνημιδίων παραλίας· νῦν δὲ Λοκρῶν ἐστὶν ἡ χώρα (τὸ δὲ πόλισμα κατέσκαπται), ὥστ’ οὐδ’ ἐκεῖ καθήκει οὐκέτι μέχρι τῆς πρὸς Εὐβοίᾳ θαλάττης ἡ Φωκίς, τῷ δὲ Κρισαίῳ κόλπῳ συνῆπται. αὐτὴ γὰρ ἡ Κρῖσα τῆς Φωκίδος ἐστὶν ἐπ’ αὐτῆς ἱδρυμένη τῆς θαλάττης καὶ Κίρρα καὶ Ἀντικύρα καὶ τὰ ὑπὲρ αὐτῶν ἐν τῇ μεσογαίᾳ συνεχῆ κείμενα χωρία πρὸς τῷ Παρνασσῷ, Δελφοί τε καὶ Κίρφις καὶ Δαυλὶς καὶ αὐτὸς ὁ Παρνασσὸς τῆς τε Φωκίδος ὢν καὶ ἀφορίζων τὸ ἑσπέριον πλευρόν. ὃν τρόπον δ’ ἡ Φωκὶς τῇ Βοιωτίᾳ παράκειται, τοῦτον καὶ ἡ Λοκρὶς τῇ Φωκίδι ἑκατέρα. διττὴ γάρ ἐστι διῃρημένη ὑπὸ τοῦ Παρνασσοῦ δίχα, ἡ μὲν ἐκ τοῦ ἑσπερίου μέρους παρακειμένη τῷ Παρνασσῷ καὶ μέρος αὐτοῦ νεμομένη, καθήκουσα δ’ ἐπὶ τὸν Κρισαῖον κόλπον, ἡ δ’ ἐκ τοῦ πρὸς ἕω τελευτῶσα ἐπὶ τὴν πρὸς Εὐβοίᾳ θάλατταν. καλοῦνται δ’ οἱ μὲν ἑσπέριοι Λοκροὶ καὶ Ὀζόλαι, ἔχουσί τε ἐπὶ τῇ δημοσίᾳ σφραγῖδι τὸν ἕσπερον ἀστέρα ἐγκεχαραγμένον· οἱ δ’ ἕτεροι δίχα πως καὶ αὐτοὶ διῃρημένοι, οἱ μὲν Ὀπούντιοι ἀπὸ τῆς μητροπόλεως, ὅμοροι Φωκεῦσι καὶ Βοιωτοῖς, οἱ δ’ Ἐπικνημίδιοι ἀπὸ ὄρους Κνημῖδος, προσεχεῖς Οἰταίοις τε καὶ Μαλιεῦσιν. ἐν μέσῳ δὲ ἀμφοῖν τῶν τε Ἑσπερίων καὶ τῶν ἑτέρων Παρνασσός, παραμήκης εἰς τὸ προσάρκτιον μέρος ἐκτεινόμενος ἀπὸ τῶν περὶ Δελφοὺς τόπων μέχρι τῆς συμβολῆς τῶν τε Οἰταίων ὀρῶν καὶ τῶν Αἰτωλικῶν καὶ τῶν ἀνὰ μέσον Δωριέων. πάλιν γὰρ ὥσπερ ἡ Λο[κρὶς διττὴ οὖ]σα τοῖς Φωκεῦσι παραβέβληται, οὕτω [καὶ ἡ πᾶσα Οἰταία] μετὰ τῆς Αἰτωλίας καί τινων ἀνὰ μέσον τ[όπων τῆς Δω]ρικῆς τετραπόλεως τῇ Λοκρίδι ἑκατέρᾳ [καὶ Παρνας]σῷ καὶ τοῖς Δωριεῦσιν. ὑπὲρ τούτων δ’ ἤδη [οἱ Θετταλοὶ] καὶ τῶν Αἰτωλῶν οἱ προσάρκτιοι καὶ Ἀκαρν[ᾶνες καί τινα] τῶν Ἠπειρωτικῶν ἐθνῶν καὶ τῶν Μακεδονικῶν· [δεῖ δέ,] ὅπερ ἔφαμεν καὶ πρότερον, παραλλήλους ὥς[περ ταινίας] τινὰς τεταμένας ἀπὸ τῆς ἑσπέρας ἐπὶ τὰς ἀ[νατολὰς] νοῆσαι τὰς λεχθείσας χώρας. ἱεροπρεπὴς δ’ ἐστὶ πᾶς ὁ Παρνασσός, ἔχων ἄντρα τε καὶ ἄλλα χωρία τιμώμενά τε καὶ ἁγιστευόμενα· ὧν ἐστι γνωριμώτατόν τε καὶ κάλλιστον τὸ Κωρύκιον νυμφῶν ἄντρον ὁμώνυμον τῷ Κιλικίῳ. τῶν δὲ πλευρῶν τοῦ Παρνασσοῦ τὸ μὲν ἑσπέριον νέμονται Λοκροί τε οἱ Ὀζόλαι καί τινες τῶν Δωριέων καὶ Αἰτωλοὶ κατὰ τὸν Κόρακα προσαγορευόμενον Αἰτωλικὸν ὄρος, τὸ δὲ Φωκεῖς καὶ Δωριεῖς οἱ πλείους, ἔχοντες τὴν Τετράπολιν περικειμένην πως τῷ Παρνασσῷ, πλεονάζουσαν δὲ τοῖς πρὸς ἕω. αἱ μὲν οὖν κατὰ τὸ μῆκος πλευ[ραὶ τῶν] λεχθεισῶν χωρῶν τε καὶ ταινιῶν ἑκάστης παρ[άλληλοι] ἅπασαί εἰσιν, ἡ μὲν οὖσα προσάρκτιος ἡ [δὲ πρὸς νότον]. αἱ δὲ λοιπαὶ ἑσπέριοι ταῖς ἑῴαις οὔκ εἰσι π[αράλληλοι· οὐ]δὲ ἡ παραλία ἑκατέρα, ἥ τε τοῦ Κρι[σαίου κόλπου μέ]χρι Ἀκτίου καὶ ἡ πρὸς Εὔβοιαν μέχρι τῆς [Θεσσαλονικείας] παράλληλοι ἀλλήλαις εἰσίν, εἰς ἃς τελ[ευτᾷ ταῦτα τὰ] ἔθνη· ἀλλ’ οὕτω δέχεσθαι δεῖ τὰ σχήματα [τούτων τῶν χω]ρίων ὡς ἂν ἐν τριγώνῳ παρὰ τὴν [βάσιν τεταμένων] γραμμῶν πλειόνων· τὰ γὰρ ἀποληφ[θέντα σχήματα πα]ράλληλα μὲν ἀλλήλοις ἔσται, καὶ τὰς [κατὰ μῆκος ἐναν]τίον πλευρὰς ἕξει παραλλήλους, τ[ὰς δὲ κατὰ πλάτος οὐ]κέτι. ὁ μὲν οὖν ὁλοσχερὴς τύπος οὗτος τῆς λοιπῆς καὶ ἐφεξῆς περιοδείας, τὰ καθ’ ἕκαστα δ’ ἑξῆς λέγωμεν ἀπὸ τῆς Φωκίδος ἀρξάμενοι.", "st": "9.3.1"}, {"sp": "N", "t": "ταύτης δ’ ἐπιφανέσταται δύο πόλεις Δελφοί τε καὶ Ἐλάτεια· Δελφοὶ μὲν διὰ τὸ ἱερὸν τοῦ Πυθίου Ἀπόλλωνος καὶ τὸ μαντεῖον ἀρχαῖον ὄν, εἴ γε Ἀγαμέμνων ἀπ’ αὐτοῦ χρηστηριάσασθαι λέγεται ὑπὸ τοῦ ποιητοῦ· ὁ γὰρ κιθαρῳδὸς ᾁδων εἰσάγεται<br>νεῖκος Ὀδυσσῆος καὶ Πηλείδεω Ἀχιλῆος,<br>ὥς ποτε δηρίσαντο. —ἄναξ δ’ ἀνδρῶν Ἀγαμέμνων<br>χαῖρε νόῳ<br>ὣς γάρ οἱ χρείων μυθήσατο Φοῖβος Ἀπόλλων Πυθοῖ·<br>Δελφοὶ μὲν δὴ διὰ ταῦτα, Ἐλάτεια δὲ ὅτι πασῶν μεγίστη τῶν ἐνταῦθα πόλεων καὶ ἐπικαιριωτάτη διὰ τὸ ἐπικεῖσθαι τοῖς στενοῖς καὶ τὸν ἔχοντα ταύτην ἔχειν τὰς εἰσβολὰς τὰς εἰς τὴν Φωκίδα καὶ τὴν Βοιωτίαν. ὄρη γάρ ἐστιν Οἰταῖα πρῶτον, ἔπειτα τὰ τῶν Λοκρῶν καὶ τῶν Φωκέων, οὐ πανταχοῦ στρατοπέδοις βάσιμα τοῖς ἐκ Θετταλίας ἐμβάλλουσιν, ἀλλ’ ἔχει παρόδους στενὰς μὲν ἀφωρισμένας δέ, ἃς αἱ παρακείμεναι πόλεις φρουροῦσιν· ἁλουσῶν δ’ ἐκείνων κρατεῖσθαι συμβαίνει καὶ τὰς παρόδους. ἐπεὶ δ’ ἡ τοῦ ἱεροῦ ἐπιφάνεια τοῦ ἐν Δελφοῖς ἔχει πρεσβεῖον, καὶ ἅμα ἡ θέσις τῶν χωρίων ἀρχὴν ὑπαγορεύει φυσικήν (ταῦτα γάρ ἐστι τὰ ἑσπεριώτατα μέρη τῆς Φωκίδος), ἐντεῦθεν ἀρκτέον.", "st": "9.3.2"}, {"sp": "N", "t": "εἴρηται δ’ ὅτι καὶ ὁ Παρνασσὸς ἐπὶ τῶν ἑσπερίων ὅρων ἵδρυται τῆς Φωκίδος. τούτου δὴ τὸ μὲν πρὸς δύσιν πλευρὸν οἱ Λοκροὶ κατέχουσιν οἱ Ὀζόλαι, τὸ δὲ νότιον οἱ Δελφοί, πετρῶδες χωρίον θεατροειδές, κατὰ κορυφὴν ἔχον τὸ μαντεῖον καὶ τὴν πόλιν, σταδίων ἑκκαίδεκα κύκλον πληροῦσαν. ὑπέρκειται δ’ αὐτῆς ἡ Λυκώρεια, ἐφ’ οὗ τόπου πρότερον ἵδρυντο οἱ Δελφοὶ ὑπὲρ τοῦ ἱεροῦ· νῦν δ’ ἐπ’ αὐτῷ οἰκοῦσι περὶ τὴν κρήνην τὴν Κασταλίαν. πρόκειται δὲ τῆς πόλεως ἡ Κίρφις ἐκ τοῦ νοτίου μέρους, ὄρος ἀπότομον, νάπην ἀπολιπὸν μεταξύ, δι’ ἧς Πλεῖστος διαρρεῖ ποταμός. ὑποπέπτωκε δὲ τῇ ὁ Κίρφει πόλις ἀρχαία Κίρρα, ἐπὶ τῇ θαλάττῃ ἱδρυμένη, ἀφ’ ἧς ἀνάβασις εἰς Δελφοὺς ὀγδοήκοντά που σταδίων· ἵδρυται δ’ ἀπαντικρὺ Σικυῶνος. πρόκειται δὲ τῆς Κίρρας τὸ Κρισαῖον πεδίον εὔδαιμον. πάλιν γὰρ ἐφεξῆς ἐστιν ἄλλη πόλις Κρῖσα, ἀφ’ ἧς ὁ κόλπος Κρισαῖος· εἶτα Ἀντικύρα, ὁμώνυμος τῇ κατὰ τὸν Μαλιακὸν κόλπον καὶ τὴν Οἴτην. καὶ δή φασιν ἐκεῖ τὸν ἑλλέβορον φύεσθαι τὸν ἀστεῖον, ἐνταῦθα δὲ σκευάζεσθαι βέλτιον, καὶ διὰ τοῦτο ἀποδημεῖν δεῦρο πολλοὺς καθάρσεως καὶ θεραπείας χάριν· γίνεσθαι γάρ τι σησαμοειδὲς φάρμακον ἐν τῇ Φωκικῇ, μεθ’ οὗ σκευάζεσθαι τὸν Οἰταῖον ἑλλέβορον.", "st": "9.3.3"}, {"sp": "N", "t": "αὕτη μὲν οὖν συμμένει, ἡ δὲ Κίρρα καὶ ἡ Κρῖσα κατεσπάσθησαν, ἡ μὲν … ὕστερον ὑπ’ Εὐρυλόχου τοῦ Θετταλοῦ κατὰ τὸν Κρισαῖον πόλεμον· εὐτυχήσαντες γὰρ οἱ Κρισαῖοι διὰ τὰ ἐκ τῆς Σικελίας καὶ τῆς Ἰταλίας τέλη, πικρῶς ἐτελώνουν τοὺς ἐπὶ τὸ ἱερὸν ἀφικνουμένους καὶ παρὰ τὰ προστάγματα τῶν Ἀμφικτυόνων. τὰ δ’ αὐτὰ καὶ τοῖς Ἀμφισσεῦσι συνέβη. Λοκρῶν δ’ εἰσὶν οὗτοι τῶν Ὀζολῶν. ἐπελθόντες γὰρ καὶ οὗτοι τήν τε Κρῖσαν ἀνέλαβον, καὶ τὸ πεδίον τὸ ὑπὸ τῶν Ἀμφικτυόνων ἀνιερωθὲν αὖθις κατεγεώργουν, καὶ χείρους ἦσαν περὶ τοὺς ξένους τῶν πάλαι Κρισαίων. καὶ τούτους οὖν ἐτιμωρήσαντο οἱ Ἀμφικτύονες, καὶ τῷ θεῷ τὴν χώραν ἀπέδοσαν. ὠλιγώρηται δ’ ἱκανῶς καὶ τὸ ἱερόν, πρότερον δ’ ὑπερβαλλόντως [ἐτιμήθη]. δηλοῦσι δ’ οἵ τε θησαυροὶ οὓς καὶ δῆμοι καὶ δυνάσται κατεσκεύασαν, εἰς οὓς καὶ χρήματα ἀνετίθεντο καθιερωμένα καὶ ἔργα τῶν ἀρίστων δημιουργῶν, καὶ ὁ ἀγὼν ὁ Πυθικὸς καὶ τὸ πλῆθος τῶν ἱστορουμένων χρησμῶν.", "st": "9.3.4"}, {"sp": "N", "t": "φασὶ δ’ εἶναι τὸ μαντεῖον ἄντρον κοῖλον κατὰ βάθους οὐ μάλα εὐρύστομον, ἀναφέρεσθαι δ’ ἐξ αὐτοῦ πνεῦμα ἐνθουσιαστικόν, ὑπερκεῖσθαι δὲ τοῦ στομίου τρίποδα ὑψηλόν, ἐφ’ ὃν τὴν Πυθίαν ἀναβαίνουσαν δεχομένην τὸ πνεῦμα ἀποθεσπίζειν ἔμμετρά τε καὶ ἄμετρα· ἐντείνειν δὲ καὶ ταῦτα εἰς μέτρον ποιητάς τινας ὑπουργοῦντας τῷ ἱερῷ. πρώτην δὲ Φημονόην γενέσθαι φασὶ Πυθίαν, κεκλῆσθαι δὲ καὶ τὴν προφῆτιν οὕτω καὶ τὴν πόλιν ἀπὸ τοῦ πυθέσθαι, ἐκτετάσθαι δὲ τὴν πρώτην συλλαβήν, ὡς ἐπὶ τοῦ ἀθανάτου καὶ ἀκαμάτου καὶ διακόνου.", "st": "9.3.5"}, {"sp": "N", "t": "ἡ μὲν οὖν ἐπὶ τὸ πλεῖον τιμὴ τῷ ἱερῷ τούτῳ διὰ τὸ χρηστήριον συνέβη δόξαντι ἀψευδεστάτῳ τῶν πάντων ὑπάρξαι, προσέλαβε δέ τι καὶ ἡ θέσις τοῦ τόπου. τῆς γὰρ Ἑλλάδος ἐν μέσῳ πώς ἐστι τῆς συμπάσης, τῆς τε ἐντὸς Ἰσθμοῦ καὶ τῆς ἐκτός, ἐνομίσθη δὲ καὶ τῆς οἰκουμένης, καὶ ἐκάλεσαν τῆς γῆς ὀμφαλόν, προσπλάσαντες καὶ μῦθον ὅν φησι Πίνδαρος, ὅτι συμπέσοιεν ἐνταῦθα οἱ ἀετοὶ οἱ ἀφεθέντες ὑπὸ τοῦ Διός, ὁ μὲν ἀπὸ τῆς δύσεως ὁ δ’ ἀπὸ τῆς ἀνατολῆς· οἱ δὲ κόρακάς φασι. δείκνυται δὲ καὶ ὀμφαλός τις ἐν τῷ ναῷ τεταινιωμένος καὶ ἐπ’ αὐτῷ αἱ δύο εἰκόνες τοῦ μύθου.", "st": "9.3.6"}, {"sp": "N", "t": "τοιαύτης δὲ τῆς εὐκαιρίας οὔσης τῆς περὶ τοὺς Δελφούς, συνῄεσάν τε ῥᾳδίως ἐκεῖσε, μάλιστα δ’ οἱ ἐγγύθεν, καὶ δὴ καὶ τὸ Ἀμφικτυονικὸν σύστημα ἐκ τούτων συνετάχθη περί τε τῶν κοινῶν βουλευσόμενον καὶ τοῦ ἱεροῦ τὴν ἐπιμέλειαν ἕξον κοινοτέραν, ἅτε καὶ χρημάτων ἀποκειμένων πολλῶν καὶ ἀναθημάτων φυλακῆς καὶ ἁγιστείας δεομένων μεγάλης. τὰ πάλαι μὲν οὖν ἀγνοεῖται, Ἀκρίσιος δὲ τῶν μνημονευομένων πρῶτος διατάξαι δοκεῖ τὰ περὶ τοὺς Ἀμφικτύονας καὶ πόλεις ἀφορίσαι τὰς μετεχούσας τοῦ συνεδρίου καὶ ψῆφον ἑκάστῃ δοῦναι, τῇ μὲν καθ’ αὑτὴν τῇ δὲ μεθ’ ἑτέρας ἢ μετὰ πλειόνων, ἀποδεῖξαι δὲ καὶ τὰς Ἀμφικτυονικὰς δίκας ὅσαι πόλεσι πρὸς πόλεις εἰσίν· ὕστερον δ’ ἄλλαι πλείους διατάξεις γεγόνασιν, ἕως κατελύθη καὶ τοῦτο τὸ σύνταγμα, καθάπερ τὸ τῶν Ἀχαιῶν. αἱ μὲν οὖν πρῶται δυοκαίδεκα συνελθεῖν λέγονται πόλεις· ἑκάστη δ’ ἔπεμπε Πυλαγόραν, δὶς κατ’ ἔτος οὔσης τῆς συνόδου ἔαρός τε καὶ μετοπώρου· ὕστερον δὲ καὶ πλείους προσῆλθον πόλεις. τὴν δὲ σύνοδον Πυλαίαν ἐκάλουν τὴν μὲν ἐαρινὴν τὴν δὲ μετοπωρινήν, ἐπειδὴ ἐν Πύλαις συνήγοντο, ἃς καὶ Θερμοπύλας καλοῦσιν· ἔθυον δὲ τῇ Δήμητρι οἱ πυλαγόροι. τὸ μὲν οὖν ἐξ ἀρχῆς τοῖς ἐγγὺς μετῆν καὶ τούτων καὶ τοῦ μαντείου, ὕστερον δὲ καὶ οἱ πόρρωθεν ἀφικνοῦντο καὶ ἐχρῶντο τῷ μαντείῳ καὶ ἔπεμπον δῶρα καὶ θησαυροὺς κατεσκεύαζον, καθάπερ Κροῖσος καὶ ὁ πατὴρ Ἀλυάττης καὶ Ἰταλιωτῶν τινες καὶ Σικελοί.", "st": "9.3.7"}, {"sp": "N", "t": "ἐπίφθονος δ’ ὢν ὁ πλοῦτος δυσφύλακτός ἐστι κἂν ἱερὸς ᾖ. νυνί γέ τοι πενέστατόν ἐστι τὸ ἐν Δελφοῖς ἱερὸν χρημάτων γε χάριν, τῶν δ’ ἀναθημάτων τὰ μὲν ἦρται τὰ δὲ πλείω μένει. πρότερον δὲ πολυχρήματον ἦν τὸ ἱερόν, καθάπερ Ὅμηρός τε εἴρηκεν “οὐδ’ ὅσα λάινος οὐδὸς ἀφήτορος ἐντὸς ἐέργει Φοίβου Ἀπόλλωνος Πυθοῖ ἐνὶ πετρηέσσῃ,” καὶ οἱ θησαυροὶ δηλοῦσι καὶ ἡ σύλησις ἡ γενηθεῖσα ὑπὸ τῶν Φωκέων, ἐξ ἧς ὁ Φωκικὸς καὶ ἱερὸς καλούμενος ἐξήφθη πόλεμος. αὕτη μὲν οὖν ἡ σύλησις γεγένηται κατὰ Φίλιππον τὸν Ἀμύντου· προτέραν δ’ ἄλλην ὑπονοοῦσιν ἀρχαίαν, ἣ τὸν ὑφ’ Ὁμήρου λεγόμενον πλοῦτον ἐξεφόρησεν· οὐδὲ γὰρ ἴχνος αὐτοῦ σωθῆναι πρὸς τοὺς ὕστερον χρόνους ἐν οἷς οἱ περὶ Ὀνόμαρχον καὶ Φάυλλον ἐσύλησαν τὸ ἱερόν, ἀλλὰ τὰ μὲν … ἀπενεχθέντα νεώτερα ἐκείνων εἶναι τῶν χρημάτων· ἀποκεῖσθαι γὰρ ἐν θησαυροῖς, ἀπὸ λαφύρων ἀνατεθέντα, ἐπιγραφὰς σώζοντα ἐν αἷς καὶ οἱ ἀναθέντες· “Γύγου” γὰρ καὶ “Κροίσου” καὶ “Συβαριτῶν” καὶ “Σπινητῶν τῶν περὶ τὸν Ἀδρίαν,” καὶ οὕτως ἐπὶ τῶν ἄλλων. οὔτ … ήκοι τὰ παλαιὰ χρήματα ἀναμεμῖχθαι· [ὡς] καὶ ἄλλοι τόποι διασημαίνουσιν ὑπὸ τούτων σκευωρηθέντες τῶν ἀνδρῶν. ἔνιοι δὲ τὸν ἀφήτορα δεξάμενοι λέγεσθαι θησαυρόν, ἀφήτορος δ’ οὐδὸν κατὰ γῆς θησαυρισμόν, ἐν τῷ ναῷ κατορωρύχθαι φασὶ τὸν πλοῦτον ἐκεῖνον, καὶ τοὺς περὶ τὸν Ὀνόμαρχον ἐπιχειρήσαντας ἀνασκάπτειν νύκτωρ σεισμῶν γενομένων μεγάλων ἔξω τοῦ ναοῦ φυγεῖν καὶ παύσασθαι τῆς ἀνασκαφῆς, ἐμβαλεῖν δὲ καὶ τοῖς ἄλλοις φόβον τῆς τοιαύτης ἐπιχειρήσεως.", "st": "9.3.8"}, {"sp": "N", "t": "τῶν δὲ ναῶν τὸν μὲν πτέρινον εἰς τοὺς μύθους τακτέον, τὸν δὲ δεύτερον Τροφωνίου καὶ Ἀγαμήδους ἔργον φασί, τὸν δὲ νῦν Ἀμφικτύονες κατεσκεύασαν. δείκνυται δ’ ἐν τῷ τεμένει τάφος Νεοπτολέμου κατὰ χρησμὸν γενόμενος, Μαχαιρέως Δελφοῦ ἀνδρὸς ἀνελόντος αὐτόν, ὡς μὲν ὁ μῦθος, δίκας αἰτοῦντα τὸν θεὸν τοῦ πατρῴου φόνου, ὡς δὲ τὸ εἰκός, ἐπιθέμενον τῷ ἱερῷ. τοῦ δὲ Μαχαιρέως ἀπόγονον Βράγχον φασὶ τὸν προστατήσαντα τοῦ ἐν Διδύμοις ἱεροῦ.", "st": "9.3.9"}, {"sp": "N", "t": "ἀγὼν δὲ ὁ μὲν ἀρχαῖος ἐν Δελφοῖς κιθαρῳδῶν ἐγενήθη παιᾶνα ᾀδόντων εἰς τὸν θεόν· ἔθηκαν δὲ Δελφοί· μετὰ δὲ τὸν Κρισαῖον πόλεμον οἱ Ἀμφικτύονες ἱππικὸν καὶ γυμνικὸν ἐπ’ Εὐρυλόχου διέταξαν στεφανίτην καὶ Πύθια ἐκάλεσαν. προσέθεσαν δὲ τοῖς κιθαρῳδοῖς αὐλητάς τε καὶ κιθαριστὰς χωρὶς ᾠδῆς, ἀποδώσοντάς τι μέλος ὃ καλεῖται νόμος Πυθικός. πέντε δ’ αὐτοῦ μέρη ἐστίν, ἄγκρουσις ἄμπειρα κατακελευσμὸς ἴαμβοι καὶ δάκτυλοι σύριγγες. ἐμελοποίησε μὲν οὖν Τιμοσθένης, ὁ ναύαρχος τοῦ δευτέρου Πτολεμαίου ὁ καὶ τοὺς λιμένας συντάξας ἐν δέκα βίβλοις. βούλεται δὲ τὸν ἀγῶνα τοῦ Ἀπόλλωνος τὸν πρὸς τὸν δράκοντα διὰ τοῦ μέλους ὑμνεῖν, ἄγκρουσιν μὲν τὸ προοίμιον δηλῶν, ἄμπειραν δὲ τὴν πρώτην κατάπειραν τοῦ ἀγῶνος, κατακελευσμὸν δὲ αὐτὸν τὸν ἀγῶνα, ἴαμβον δὲ καὶ δάκτυλον τὸν ἐπιπαιανισμὸν τὸν [γινόμενον] ἐπὶ τῇ νίκῃ μετὰ τοιούτων ῥυθμῶν, ὧν ὁ μὲν ὕμνοις ἐστὶν οἰκεῖος ὁ δ’ ἴαμβος κακισμοῖς, σύριγγας δὲ τὴν ἔκλειψιν τοῦ θηρίου, μιμουμένων ὡς ἂν καταστρέφοντος ἐσχάτους τινὰς συριγμούς.", "st": "9.3.10"}, {"sp": "N", "t": "Ἔφορος δ’, ᾧ τὸ πλεῖστον προσχρώμεθα διὰ τὴν περὶ ταῦτα ἐπιμέλειαν, καθάπερ καὶ Πολύβιος μαρτυρῶν τυγχάνει, ἀνὴρ ἀξιόλογος, δοκεῖ μοι τἀναντία ποιεῖν ἔσθ’ ὅτε τῇ προαιρέσει καὶ ταῖς ἐξ ἀρχῆς ὑποσχέσεσιν. ἐπιτιμήσας γοῦν τοῖς φιλομυθοῦσιν ἐν τῇ τῆς ἱστορίας γραφῇ καὶ τὴν ἀλήθειαν ἐπαινέσας προστίθησι τῷ περὶ τοῦ μαντείου τούτου λόγῳ σεμνήν τινα ὑπόσχεσιν, ὡς πανταχοῦ μὲν ἄριστον νομίζει τἀληθές, μάλιστα δὲ κατὰ τὴν ὑπόθεσιν ταύτην. ἄτοπον γὰρ εἰ περὶ μὲν τῶν ἄλλων τὸν τοιοῦτον ἀεὶ τρόπον διώκομεν, φησί, περὶ δὲ τοῦ μαντείου λέγοντες, ὃ πάντων ἐστὶν ἀψευδέστατον, τοῖς οὕτως ἀπίστοις καὶ ψευδέσι χρησόμεθα λόγοις. ταῦτα δ’ εἰπὼν ἐπιφέρει παραχρῆμα, ὅτι ὑπολαμβάνουσι κατασκευάσαι τὸ μαντεῖον Ἀπόλλωνα μετὰ Θέμιδος ὠφελῆσαι βουλόμενον τὸ γένος ἡμῶν. εἶτα τὴν ὠφέλειαν εἰπὼν ὅτι εἰς ἡμερότητα προὐκαλεῖτο καὶ ἐσωφρόνιζε, τοῖς μὲν χρηστηριάζων καὶ τὰ μὲν προστάττων τὰ δ’ ἀπαγορεύων, τοὺς δ’ οὐδ’ ὅλως προσιέμενος, ταῦτα διοικεῖν νομίζουσι, φησίν, αὐτόν, οἱ μὲν αὐτὸν τὸν θεὸν σωματοειδῆ γινόμενον, οἱ δ’ ἀνθρώποις ἔννοιαν παραδιδόντα τῆς ἑαυτοῦ βουλήσεως.", "st": "9.3.11"}, {"sp": "N", "t": "ὑποβὰς δὲ περὶ τῶν Δελφῶν οἵτινές εἰσι διαλεγόμενος φησὶ τὸ παλαιὸν Παρνασσίους τινὰς αὐτόχθονας καλουμένους οἰκεῖν τὸν Παρνασσόν· καθ’ ὃν χρόνον Ἀπόλλωνα τὴν γῆν ἐπιόντα ἡμεροῦν τοὺς ἀνθρώπους ἀπό τε τῶν ἡμέρων καρπῶν καὶ τῶν βίων, ἐξ Ἀθηνῶν δ’ ὁρμηθέντα ἐπὶ Δελφοὺς ταύτην ἰέναι τὴν ὁδόν, ᾗ νῦν Ἀθηναῖοι τὴν Πυθιάδα πέμπουσι· γενόμενον δὲ κατὰ Πανοπέας Τιτυὸν καταλῦσαι ἔχοντα τὸν τόπον, βίαιον ἄνδρα καὶ παράνομον· τοὺς δὲ Παρνασσίους συμμίξαντας αὐτῷ καὶ ἄλλον μηνῦσαι χαλεπὸν ἄνδρα Πύθωνα τοὔνομα, ἐπίκλησιν δὲ Δράκοντα, κατατοξεύοντος δ’ ἐπικελεύειν ἵε παιάν, ἀφ’ οὗ τὸν παιανισμὸν οὕτως ἐξ ἔθους παραδοθῆναι τοῖς μέλλουσι συμπίπτειν εἰς παράταξιν· ἐμπρησθῆναι δὲ καὶ σκηνὴν τότε τοῦ Πύθωνος ὑπὸ τῶν Δελφῶν, καθάπερ καὶ νῦν ἔτι καὶ ἀεὶ ὑπόμνημα ποιουμένους τῶν τότε γενομένων. τί δ’ ἂν εἴη μυθωδέστερον ἢ Ἀπόλλων τοξεύων καὶ κολάζων Τιτυοὺς καὶ Πύθωνας καὶ ὁδεύων ἐξ Ἀθηνῶν εἰς Δελφοὺς καὶ γῆν πᾶσαν ἐπιών; εἰ δὲ ταῦτα μὴ ὑπελάμβανε μύθους εἶναι, τί ἐχρῆν τὴν μυθευομένην Θέμιν γυναῖκα καλεῖν, τὸν δὲ μυθευόμενον δράκοντα ἄνθρωπον; πλὴν εἰ συγχεῖν ἐβούλετο τόν τε τῆς ἱστορίας καὶ τὸν τοῦ μύθου τύπον. παραπλήσια τούτοις καὶ τὰ περὶ τῶν Αἰτωλῶν εἰρημένα. φήσας γὰρ ἀπορθήτους αὐτοὺς ἐκ παντὸς τοῦ χρόνου τοτὲ μὲν Αἰολέας φησὶν οἰκῆσαι τοὺς κατέχοντας βαρβάρους ἐκβαλόντας, τοτὲ δ’ Αἰτωλὸν μετὰ τῶν ἐξ Ἤλιδος Ἐπειῶν … τῶν ἐχθρῶν· τούτους δ’ ὑπ’ Ἀλκμέωνος καὶ Διομήδους. ἀλλ’ ἐπάνειμι ἐπὶ τοὺς Φωκέας.", "st": "9.3.12"}, {"sp": "N", "t": "ἑξῆς γὰρ ἐν τῇ παραλίᾳ μετὰ τὴν Ἀντικύραν πολίχνιόν ἐστιν Ὀπισθομάραθος· εἶτ’ ἄκρα Φαρύγιον ἔχουσα ὕφορμον· εἶθ’ ὁ λιμὴν ὕστατος ὁ προσαγορευθεὶς μυχὸς ἀπὸ τοῦ συμβεβηκότος, ὑπὸ τῷ Ἑλικῶνι καὶ τῇ Ἄσκρῃ κείμενος. οὐδ’ αἱ Ἀβαὶ δὲ τὸ μαντεῖον ἄπωθεν τῶν τόπων τούτων ἐστίν, οὐδ’ ἡ Ἄμβρυσος, [οὐδ’ ἡ Με]δεὼν ὁμώνυμος τῇ Βοιωτιακῇ. ἔτι δὲ μᾶλλον ἐν τῇ μεσογαίᾳ μετὰ Δελφοὺς ὡς πρὸς τὴν ἕω Δαυλὶς πολίχνιον, ὅπου Τηρέα τὸν Θρᾷκά φασι δυναστεῦσαι· καὶ τὰ περὶ Φιλομήλαν καὶ Πρόκνην ἐκεῖ μυθεύουσι. τοὔνομα δὲ τῷ τόπῳ γεγονέναι ἀπὸ τοῦ δάσους· δαυλοὺς γὰρ καλοῦσι τὰ δάση. Ὅμηρος μὲν οὖν Δαυλίδα εἶπεν, οἱ δ’ ὕστερον Δαυλίαν. καὶ τὸ “[οἳ] Κυπάρισσον ἔχον” δέχονται διττῶς, οἱ μὲν ὁμωνύμως τῷ φυτῷ οἱ δὲ παρωνύμως κώμην ὑπὸ τῇ Λυκωρείᾳ.", "st": "9.3.13"}, {"sp": "N", "t": "Πανοπεὺς δ’ ὁ νῦν Φανοτεύς, ὅμορος τοῖς περὶ Λεβάδειαν τόποις, ἡ τοῦ Ἐπειοῦ πατρίς. καὶ τὰ περὶ τὸν Τιτυὸν δὲ ἐνταῦθα μυθεύουσιν. Ὅμηρος δέ φησιν ὅτι οἱ Φαίηκες τὸν Ῥαδάμανθυν εἰς Εὔβοιαν “ἤγαγον, ὀψόμενον Τιτυὸν γαιήϊον υἱόν.” καὶ Ἐλάριόν τι σπήλαιον ἀπὸ τῆς Τιτυοῦ μητρὸς Ἐλάρας δείκνυται κατὰ τὴν νῆσον καὶ ἡρῷον τοῦ Τιτυοῦ καὶ τιμαί τινες. πλησίον δὲ Λεβαδείας καὶ ἡ Τραχίν, ὁμώνυμος τῇ Οἰταίᾳ, Φωκικὴ πολίχνη· οἱ δ’ ἐνοικοῦντες Τραχίνιοι λέγονται.", "st": "9.3.14"}, {"sp": "N", "t": "ἡ δ’ Ἀνεμώρεια ὠνόμασται ἀπὸ τοῦ συμβαίνοντος πάθους· καταιγίζει γὰρ εἰς αὐτὴν ὁ καλούμενος Κατοπτήριος χῶρος, κρημνός τις ἀπὸ τοῦ Παρνασσοῦ διήκων· ὅριον δ’ ἦν ὁ τόπος οὗτος Δελφῶν τε καὶ Φωκέων, ἡνίκα ἀπέστησαν τοὺς Δελφοὺς ἀπὸ τοῦ κοινοῦ συστήματος τῶν Φωκέων Λακεδαιμόνιοι καὶ ἐπέτρεψαν καθ’ αὑτοὺς πολιτεύεσθαι· τινὲς δὲ Ἀνεμώλειαν καλοῦσιν. εἶθ’ Ὑάμπολις (Ὕα μετὰ ταῦτα ἐκλήθη ὑπό τινων), εἰς ἣν ἐκ Βοιωτίας ἐκπεσεῖν ἔφαμεν τοὺς Ὕαντας· ἔστι δ’ ἐν τῇ μεσογαίᾳ μάλιστα καὶ αὕτη, πλησίον τῶν Παραποταμίων, ἑτέρα οὖσα τῆς ἐν τῷ Παρνασσῷ Ὑαμπεί[ας], καὶ Ἐλάτεια ἡ μεγίστη πόλις τῶν Φωκικῶν, ἣν Ὅμηρος μὲν οὐκ οἶδε (νεωτέρα γάρ ἐστι τῆς ἡλικίας ἐκείνου), ἐπικαιρίως δ’ ἵδρυται πρὸς τὰς ἐκ τῆς Θετταλίας εἰσβολάς. δηλοῖ δὲ τὴν εὐφυΐαν ταύτην καὶ Δημοσθένης, φράζων τὸν θόρυβον τὸν γενηθέντα Ἀθήνησιν αἰφνιδίως, ἐπειδὴ ἧκέ τις ἀπαγγέλλων ὡς τοὺς πρυτάνεις ὡς Ἐλάτεια κατείληπται.", "st": "9.3.15"}, {"sp": "N", "t": "Παραποτάμιοι δ’ εἰσὶ κατοικία τις ἐπὶ τῷ Κηφισσῷ ἱδρυμένη πλησίον Φανοτεῦσι καὶ Χαιρωνεῦσι καὶ Ἐλατείᾳ. φησὶ δὲ Θεόπομπος τὸν τόπον τοῦτον διέχειν τῆς μὲν Χαιρωνείας ὅσον τετταράκοντα σταδίους, διορίζειν δὲ τοὺς Ἀμβρυσέας καὶ Πανοπέας καὶ Δαυλιέας· κεῖσθαι δ’ ἐπὶ τῆς ἐμβολῆς τῆς ἐκ Βοιωτίας εἰς Φωκέας ἐν λόφῳ μετρίως ὑψηλῷ, μεταξὺ τοῦ τε Παρνασσοῦ καὶ τοῦ [Ἁδυλίου ὄ]ρους πενταστάδιον σχεδόν τι ἀπολειπόντων ἀν[ὰ μέσον χω]ρίον, διαιρεῖν δὲ τὸν Κηφισσὸν στενὴν ἑκατέρωθεν διδόντα πάροδον, τὰς μὲν ἀρχὰς ἐκ Λιλαίας ἔχοντα Φωκικῆς πόλεως (καθάπερ καὶ Ὅμηρός φησιν “οἵ τε Λίλαιαν ἔχον πηγῇς ἔπι Κηφισσοῖο” ), εἰς δὲ τὴν Κωπαΐδα λίμνην ἐκδιδόντα· τὸ δὲ Ἁδύλιον παρατείνειν ἐφ’ ἑξήκοντα σταδίους μέχρι τοῦ Ἀκοντίου, ἐφ’ ᾧ κεῖται ὁ Ὀρχομενός. καὶ Ἡσίοδος δ’ ἐπὶ πλέον περὶ τοῦ ποταμοῦ λέγει καὶ τῆς ῥύσεως, ὡς δι’ ὅλης ῥέοι τῆς Φωκίδος σκολιῶς καὶ δρακοντοειδῶς “παρὲκ Πανοπῆα διὰ Γλήχωνά τ’ ἐρυμνὴν καί τε δι’ Ὀρχομενοῦ εἱλιγμένος εἶσι δράκων ὥς.” τὰ δὲ στενὰ τὰ περὶ τοὺς Παραποταμίους ἢ τὴν Παραποταμίαν (λέγεται γὰρ ἀμφοτέρως) περιμάχητα ὑπῆρξεν ἐν τ[ῷ Φωκικῷ πολέ]μῳ, μίαν ἐχόντων ταύτην ἐμβολὴν [εἰς τὴν Φωκίδα]· ἔστι δὲ Κηφισσὸς ὅ τε Φωκικὸς καὶ ὁ Ἀθήνησι καὶ ὁ ἐν Σαλαμῖνι, τέταρτος δὲ καὶ πέμπτος ὁ ἐν Σικυῶνι καὶ ὁ ἐν Σκύρῳ, ἐν Ἀπολλωνίᾳ δὲ τῇ πρὸς Ἐπιδάμνῳ πηγή ἐστι κατὰ τὸ γυμνάσιον, ἣν καλοῦσι Κηφισσόν.", "st": "9.3.16"}, {"sp": "N", "t": "Δαφνοῦς δὲ νῦν μὲν κατέσκαπται· ἦν δέ ποτε τῆς Φωκίδος πόλις ἁπτομένη τῆς Εὐβοϊκῆς θαλάττης, διαιροῦσα τοὺς Ἐπικνημιδίους Λοκρούς, τοὺς μὲν ἐπὶ τὸ πρὸς Βοιω[τίαν μέρος τοὺς δὲ πρὸς] Φωκίδα τὴν ἀπὸ θαλάττης καθήκ[ουσαν τότε ἐπὶ θάλατταν]. τεκμήριον δὲ τὸ ἐν αὐτῷ Σχεδιεῖον, ὅ φασιν εἶναι τάφον Σχεδίου. [εἴρη]ται δὲ ὁ Δαφνοῦς ἐφ’ ἑκάτερα τὴν Λοκρίδα [σχίσαι, ὥστ]ε μηδαμοῦ ἅπτεσθαι ἀλλήλων τούς τ’ Ἐπικνημι[δίους καὶ το]ὺς Ὀπουντίους· ὕστερον δὲ προσωρίσθη τοῖς [Ὀπουντίοις ὁ τό]πος. περὶ μὲν δὴ τῆς Φωκίδος ἀπόχρη.", "st": "9.3.17"}, {"sp": "N", "t": "ἐφεξῆς δ’ ἐστὶν ἡ Λοκρίς, ὥστε περὶ ταύτης λεκτέον. διῄρηται δὲ δίχα· τὸ μὲν γὰρ αὐτῆς ἐστιν οἱ πρὸς Εὔβοιαν Λοκροί, [οὓς ἐλέ]γομεν σχίζεσθαί ποτε ἐφ’ ἑκάτερα τοῦ Δαφνοῦντος· ἐπεκαλοῦντο δ’ οἱ μὲν Ὀπούντιοι ἀπὸ τῆς μητροπόλεως, οἱ δ’ Ἐπικνημίδιοι ἀπὸ ὄρους τινὸς Κνημῖδος· τὸ δὲ λοιπὸν οἱ ἑσπέριοί εἰσι Λοκροί, οἱ δ’ αὐτοὶ καὶ Ὀζόλαι καλοῦνται. χωρίζει δ’ αὐτοὺς ἀπὸ τῶν Ὀπουντίων καὶ τῶν Ἐπικνημιδίων ὅ τε Παρνασσὸς μεταξὺ ἱδρυμένος καὶ ἡ τῶν Δωριέων τετράπολις. ἀρκτέον δ’ ἀπὸ τῶν Ὀπουντίων.", "st": "9.4.1"}, {"sp": "N", "t": "ἐφεξῆς τοίνυν ταῖς Ἁλαῖς, εἰς ἃς κατέληγεν ἡ Βοιωτιακὴ παραλία ἡ πρὸς Εὐβοίᾳ, τὸν Ὀπούντιον κόλπον κεῖσθαι συμβαίνει. ὁ δ’ Ὀποῦς ἐστι μητρόπολις, καθάπερ καὶ τὸ ἐπίγραμμα δηλοῖ τὸ ἐπὶ τῇ πρώτῃ τῶν πέντε στηλῶν τῶν περὶ Θερμοπύλας ἐπιγεγραμμένον πρὸς τῷ πολυανδρίῳ “τούσδε ποθεῖ φθιμένους ὑπὲρ Ἑλλάδος ἀντία Μήδων, μητρόπολις Λοκρῶν εὐθυνόμων Ὀπόεις.” ἀπέχει δὲ τῆς θαλάττης περὶ πεντεκαίδεκα σταδίους, τοῦ δ’ ἐπινείου καὶ ἑξήκοντα. Κῦνος δ’ ἐστὶ τὸ ἐπίνειον, ἄκρα τερματίζουσα τὸν Ὀπούντιον κόλπον σταδίων ὄντα περὶ τετταράκοντα· μεταξὺ δὲ Ὀποῦντος καὶ Κύνου πεδίον εὔδαιμον· κεῖται δὲ κατὰ Αἰδηψὸν τῆς Εὐβοίας, ὅπου τὰ θερμὰ τὰ Ἡρακλέους, πορθμῷ διειργόμενος σταδίων ἑξήκοντα καὶ ἑκατόν. ἐν δὲ τῷ Κύνῳ Δευκαλίωνά φασιν οἰκῆσαι, καὶ τῆς Πύρρας αὐτόθι δείκνυται σῆμα, τοῦ δὲ Δευκαλίωνος Ἀθήνησι. διέχει δὲ τῆς Κνημῖδος ὁ Κῦνος ὅσον πεντήκοντα σταδίους. καὶ ἡ Ἀταλάντη δὲ νῆσος κατὰ Ὀποῦντα ἵδρυται, ὁμώνυμος τῇ πρὸ τῆς Ἀττικῆς. λέγεσθαι δ’ Ὀπουντίους τινὰς καὶ ἐν τῇ Ἠλείᾳ φασίν, ὧν οὐκ ἄξιον μεμνῆσθαι, πλὴν ὅτι συγγένειαν αὐτῶν ἐξανανεοῦνται τοῖς Ὀπουντίοις ὑπάρχουσαν. ὅτι δ’ ἐξ Ὀποῦντος ἦν ὁ Πάτροκλος λέγει Ὅμηρος, καὶ διότι φόνον ἀκούσιον πράξας ἔφυγεν εἰς Πηλέα, ὁ δὲ πατὴρ Μενοίτιος ἔμεινεν ἐν τῇ πατρίδι· ἐκεῖσε γάρ φησιν ὁ Ἀχιλλεὺς ὑποσχέσθαι τῷ Μενοιτίῳ κατάξειν τὸν Πάτροκλον ἐκ τῆς στρατείας ἐπανελθόντα. οὐ μὴν ἐβασίλευέ γε ἐκεῖνος τῶν Ὀπουντίων, ἀλλ’ Αἴας ὁ Λοκρός, πατρίδος ὤν, ὥς φασι, Ναρύκου. Αἰάνην δ’ ὀνομάζουσι τὸν ἀναιρεθέντα ὑπὸ τοῦ Πατρόκλου, ἀφ’ οὗ καὶ τέμενος Αἰάνειον δείκνυται καὶ κρήνη τις Αἰανίς.", "st": "9.4.2"}, {"sp": "N", "t": "ἑξῆς μετὰ τὸν Κῦνον Ἀλόπη ἐστὶ καὶ ὁ Δαφνοῦς, ὃν ἔφαμεν κατεσπάσθαι· λιμὴν δ’ ἐστὶν αὐτόθι διέχων Κύνου περὶ ἐνενήκοντα σταδίους, Ἐλατείας δὲ πεζεύοντι εἰς τὴν μεσόγαιαν ἑκατὸν εἴκοσιν. ἤδη δ’ ἐστὶ ταῦτα τοῦ Μαλιακοῦ κόλπου· μετὰ γὰρ τὸν Ὀπούντιον συνεχής ἐστιν οὗτος.", "st": "9.4.3"}, {"sp": "N", "t": "μετὰ δὲ Δαφνοῦντα Κνημῖδες χωρίον ἐρυμνὸν ὅσον σταδίους εἴκοσι πλεύσαντι· καθ’ ὃ τὸ Κήναιον ἐκ τῆς Εὐβοίας ἀντίκειται ἄκρα βλέπουσα πρὸς ἑσπέραν καὶ τὸν Μαλιέα κόλπον, πορθμῷ διειργομένη σχεδὸν εἰκοσασταδίῳ. ταῦτα δ’ ἤδη τῶν Ἐπικνημιδίων ἐστὶ Λοκρῶν. ἐνταῦθα καὶ αἱ Λιχάδες καλούμεναι τρεῖς νῆσοι πρόκεινται ἀπὸ Λίχα τοὔνομα ἔχουσαι. καὶ ἄλλαι δ’ εἰσὶν ἐν τῷ λεχθέντι παράπλῳ, ἃς ἑκόντες παραλείπομεν. μετὰ δὲ εἴκοσι σταδίους ἀπὸ Κνημίδων λιμήν, ὑπὲρ οὗ κεῖται τὸ Θρόνιον ἐν σταδίοις τοῖς ἴσοις κατὰ τὴν μεσόγαιαν. εἶθ’ ὁ Βοάγριος ποταμὸς ἐκδίδωσιν ὁ παραρρέων τὸ Θρόνιον, Μάνην δ’ ἐπονομάζουσιν αὐτόν· ἔστι δὲ χειμάρρους ὥστ’ ἀβρόχοις ἐμβαίνειν τοῖς ποσίν, ἄλλοτε δὲ καὶ δίπλεθρον ἴσχειν πλάτος. μετὰ δὲ ταῦτα Σκάρφεια σταδίοις ὑπερκειμένη τῆς θαλάττης δέκα, διέχουσα δὲ τοῦ Θρονίου τριάκοντα, ἐλάττοσι δὲ μικρῷ … ἔπειτα Νίκαιά ἐστι καὶ αἱ Θερμοπύλαι.", "st": "9.4.4"}, {"sp": "N", "t": "τῶν δὲ λοιπῶν πόλεων τῶν μὲν ἄλλων οὐκ ἄξιον μεμνῆσθαι· ὧν δ’ Ὅμηρος μέμνηται Καλλίαρος μὲν οὐκέτι οἰκεῖται, [εὐήροτον δὲ νῦν ἐς]τι πεδίον· καλοῦσι δ’ οὕτως ἀπὸ τοῦ [συμβεβηκότος· καὶ Βῆσσα δ’] οὐκ ἔστι, δρυμώδης τις τόπος· οὐδ’ [αἱ Αὐγειαί, τὴν δὲ χώ]ραν ἔχουσι Σκαρφιεῖς· ταύτην μὲν οὖν τὴν Βῆσσαν ἐν τοῖς δυσὶ γραπτέον σίγμα (ἀπὸ γὰρ τοῦ δρυμώδους ὠνόμασται ὁμωνύμως, ὥσπερ καὶ Νάπη ἐν τῷ Μηθύμνης πεδίῳ, ἣν Ἑλλάνικος ἀγνοῶν … Λάπην ὀνομάζει), τὸν δ’ ἐν τῇ Ἀττικῇ δῆμον, ἀφ’ οὗ Βησαιεῖς οἱ δημόται λέγονται, ἐν τῷ ἑνὶ σίγμα.", "st": "9.4.5"}, {"sp": "N", "t": "ἡ δὲ Τάρφη κεῖται ἐφ’ ὕψους, διέχουσα [Θρονίου] σταδίους εἴκοσι, χώραν δ’ εὔκαρπόν τε καὶ εὔδενδρον ἔχει· ἤδη γὰρ καὶ αὕτη ἀπὸ τοῦ δάσους ὠνόμασται. καλεῖται δὲ νῦν Φαρύγαι· ἵδρυται δ’ αὐτόθι Ἥρας Φαρυγαίας ἱερὸν ἀπὸ τῆς ἐν Φαρύγαις τῆς Ἀργείας· καὶ δὴ καὶ ἄποικοί φασιν εἶναι Ἀργείων.", "st": "9.4.6"}, {"sp": "N", "t": "τῶν γε μὴν ἑσπερίων Λοκρῶν Ὅμηρος οὐ μέμνηται, ἢ οὐ ῥητῶς γε, ἀλλὰ μόνον τῷ δοκεῖν ἀντιδιαστέλλεσθαι τούτοις ἐκείνους περὶ ὧν εἰρήκαμεν “Λοκρῶν, οἳ ναίουσι πέρην ἱερῆς Εὐβοίης,” ὡς καὶ ἑτέρων ὄντων. ἀλλ’ οὐδ’ ὑπὸ τῶν ἄλλων τεθρύληνται πολλῶν· πόλεις δ’ ἔσχον Ἄμφισσάν τε καὶ Ναύπακτον, ὧν ἡ Ναύπακτος συμμένει τοῦ Ἀντιρρίου πλησίον, ὠνόμασται δ’ ἀπὸ τῆς ναυπηγίας τῆς ἐκεῖ γενομένης, εἴτε τῶν Ἡρακλειδῶν ἐκεῖ ναυπηγησαμένων τὸν στόλον, εἴθ’ (ὥς φησιν Ἔφορος) Λοκρῶν ἔτι πρότερον παρασκευασάντων· ἔστι δὲ νῦν Αἰτωλῶν Φιλίππου προσκρίναντος.", "st": "9.4.7"}, {"sp": "N", "t": "αὐτοῦ δὲ καὶ ἡ Χαλκίς, ἧς μέμνηται καὶ ὁ ποιητὴς ἐν τῷ Αἰτωλικῷ καταλόγῳ, ὑποκάτω Καλυδῶνος· αὐτοῦ δὲ καὶ ὁ Ταφιασσὸς λόφος, ἐν ᾧ τὸ τοῦ Νέσσου μνῆμα καὶ τῶν ἄλλων Κενταύρων, ὧν ἀπὸ τῆς σηπεδόνος φασὶ τὸ ὑπὸ τῇ ῥίζῃ τοῦ λόφου προχεόμενον δυσῶδες καὶ θρόμβους ἔχον ὕδωρ ῥεῖν· διὰ δὲ τοῦτο καὶ Ὀζόλας καλεῖσθαι τὸ ἔθνος. καὶ ἡ Μολύκρεια δ’ ἐστὶ κατὰ τὸ Ἀντίρριον, Αἰτωλικὸν πολίχνιον. ἡ δ’ Ἄμφισσα ἐπὶ τοῖς ἄκροις ἵδρυται τοῦ Κρισαίου πεδίου, κατέσπασαν δ’ αὐτὴν οἱ Ἀμφικτύονες, καθάπερ εἰρήκαμεν· [καὶ Οἰάνθει]α δὲ καὶ Εὐπάλιον Λοκρῶν εἰσίν. ὁ δὲ πᾶς παράπλους ὁ Λοκρικὸς μικρὸν ὑπερβάλλει τῶν διακοσίων σταδίων.", "st": "9.4.8"}, {"sp": "N", "t": "Ἀλόπην δὲ καὶ ἐνταῦθα καὶ ἐν τοῖς Ἐπικνημιδίοις ὀνομάζουσι καὶ ἐν τῇ Φθιώτιδι· οὗτοι μὲν οὖν ἄποικοι τῶν Ἐπικνημιδίων εἰσίν, οἱ δ’ Ἐπιζεφύριοι τούτων.", "st": "9.4.9"}, {"sp": "N", "t": "τοῖς δὲ Λοκροῖς τοῖς μὲν ἑσπερίοις συνεχεῖς εἰσιν Αἰτωλοί, τοῖς δ’ Ἐπικνημιδίοις Αἰνιᾶνες συνεχεῖς οἱ τὴν Οἴτην ἔχοντες, καὶ μέσοι Δωριεῖς. οὗτοι μὲν οὖν εἰσιν οἱ τὴν τετράπολιν οἰκήσαντες, ἥν φασιν εἶναι μητρόπολιν τῶν ἁπάντων Δωριέων, πόλεις δ’ ἔσχον Ἐρινεὸν Βοῖον Πίνδον Κυτίνιον· ὑπέρκειται δ’ ἡ Πίνδος τοῦ Ἐρινεοῦ, παραρρεῖ δ’ αὐτὴν ὁμώνυμος ποταμὸς ἐμβάλλων εἰς τὸν Κηφισσὸν οὐ πολὺ τῆς Λιλαίας ἄπωθεν· τινὲς δ’ Ἀκύφαντα λέγουσι τὴν Πίνδον. τούτων ὁ βασιλεὺς Αἰγίμιος ἐκπεσὼν τῆς ἀρχῆς κατήχθη πάλιν, ὡς ἱστοροῦσιν, ὑφ’ Ἡρακλέους· ἀπεμνημόνευσεν οὖν αὐτῷ τὴν χάριν τελευτήσαντι περὶ τὴν Οἴτην· Ὕλλον γὰρ εἰσεποιήσατο τὸν πρεσβύτατον τῶν ἐκείνου παίδων, καὶ διεδέξατο ἐκεῖνος τὴν ἀρχὴν καὶ οἱ ἀπόγονοι. ἐντεῦθεν ὁρμηθεῖσι τοῖς Ἡρακλείδαις ὑπῆρξεν ἡ εἰς Πελοπόννησον κάθοδος.", "st": "9.4.10"}, {"sp": "N", "t": "τέως μὲν οὖν ἦσαν ἐν ἀξιώματι αἱ πόλεις, καίπερ οὖσαι μικραὶ καὶ λυπρόχωροι, ἔπειτ’ ὠλιγωρήθησαν· ἐν δὲ τῷ Φωκικῷ πολέμῳ καὶ τῇ Μακεδόνων ἐπικρατείᾳ καὶ Αἰτωλῶν καὶ Ἀθαμάνων θαυμαστὸν εἰ καὶ ἴχνος αὐτῶν εἰς Ῥωμαίους ἦλθε. τὰ δ’ αὐτὰ πεπόνθασι καὶ Αἰνιᾶνες· καὶ γὰρ τούτους ἐξέφθειραν Αἰτωλοί τε καὶ Ἀθαμᾶνες, Αἰτωλοὶ μὲν μετὰ Ἀκαρνάνων πολεμοῦντες καὶ μέγα δυνάμενοι, Ἀθαμᾶνες δ’ ὕστατοι τῶν Ἠπειρωτῶν εἰς ἀξίωμα προαχθέντες, ἤδη τῶν ἄλλων ἀπειρηκότων, καὶ μετ’ Ἀμυνάνδρου τοῦ βασιλέως δύναμιν κατασκευασάμενοι. οὗτοι δὲ τὴν Οἴτην διακατεῖχον.", "st": "9.4.11"}, {"sp": "N", "t": "τὸ δ’ ὄρος διατείνει ἀπὸ Θερμοπυλῶν καὶ τῆς ἀνατολῆς μέχρι πρὸς τὸν κόλπον τὸν Ἀμβρακικὸν καὶ τὴν ἑσπέραν· τρόπον δέ τινα καὶ πρὸς ὀρθὰς τέμνει τὴν ἀπὸ τοῦ Παρνασσοῦ μέχρι Πίνδου καὶ τῶν ὑπερκειμένων βαρβάρων ὀρεινὴν τὸ ὄρος τοῦτο. τούτου δὴ τὸ μὲν πρὸς Θερμοπύλας νενευκὸς μέρος Οἴτη καλεῖται σταδίων διακοσίων τὸ μῆκος, τραχὺ καὶ ὑψηλόν, ὑψηλότατον δὲ κατὰ τὰς Θερμοπύλας· κορυφοῦται γὰρ ἐνταῦθα καὶ τελευτᾷ πρὸς ὀξεῖς καὶ ἀποτόμους μέχρι τῆς θαλάττης κρημνούς, ὀλίγην δ’ ἀπολείπει πάροδον τοῖς ἀπὸ τῆς παραλίας ἐμβάλλουσιν εἰς τοὺς Λοκροὺς ἐκ τῆς Θετταλίας.", "st": "9.4.12"}, {"sp": "N", "t": "τὴν μὲν οὖν πάροδον Πύλας καλοῦσι καὶ στενὰ καὶ Θερμοπύλας· ἔστι γὰρ καὶ θερμὰ πλησίον ὕδατα τιμώμενα ὡς Ἡρακλέους ἱερά· τὸ δ’ ὑπερκείμενον ὄρος Καλλίδρομον· τινὲς δὲ καὶ τὸ λοιπὸν τὸ δι’ Αἰτωλίας καὶ τῆς Ἀκαρνανίας διῆκον μέχρι τοῦ Ἀμβρακικοῦ κόλπου Καλλίδρομον προσαγορεύουσι. πρὸς δὲ ταῖς Θερμοπύλαις ἐστὶ φρούρια ἐντὸς τῶν στενῶν, Νίκαια μὲν ἐπὶ θάλατταν Λοκρῶν, Τειχιοῦς δὲ καὶ Ἡράκλεια ὑπὲρ αὐτῆς, ἡ Τραχὶν καλουμένη πρότερον, Λακεδαιμονίων κτίσμα· διέχει δὲ τῆς ἀρχαίας Τραχῖνος περὶ ἓξ σταδίους ἡ Ἡράκλεια· ἑξῆς δὲ ἡ Ῥοδουντία, χωρίον ἐρυμνόν.", "st": "9.4.13"}, {"sp": "N", "t": "ποιεῖ δὲ δυσείσβολα τὰ χωρία ταῦτα ἥ τε τραχύτης καὶ τὸ πλῆθος τῶν ὑδάτων φάραγγας ποιούντων, ἃς διέξεισι. πρὸς γὰρ τῷ Σπερχειῷ τῷ παραρρέοντι τὴν Ἀντικύραν καὶ ὁ Δύρας ἐστίν, ὅν φασιν ἐπιχειρῆσαι τὴν Ἡρακλέους σβέσαι πυράν· καὶ ἄλλος Μέλας διέχων Τραχῖνος εἰς πέντε σταδίους. πρὸς δὲ μεσημβρίαν τῆς Τραχῖνος φησὶν Ἡρόδοτος εἶναι βαθεῖαν διασφάγα, δι’ ἧς Ἀσωπός, ὁμώνυμος τοῖς εἰρημένοις Ἀσωποῖς, εἰς τὴν θάλατταν ἐκπίπτει τὴν ἐκτὸς Πυλῶν, παραλαβὼν καὶ τὸν Φοίνικα ἐκ τῆς μεσημβρίας συμβάλλοντα αὐτῷ, ὁμώνυμον τῷ ἥρωι, οὗ καὶ τάφος πλησίον δείκνυται· στάδιοι δ’ εἰσὶν ἐπὶ Θερμοπύλας ἀπὸ τοῦ Ἀσωποῦ πεντεκαίδεκα.", "st": "9.4.14"}, {"sp": "N", "t": "τότε μὲν οὖν ἦν ἐνδοξότατα τὰ χωρία ταῦτα, ἡνίκα τῶν κλείθρων ἐκυρίευε τῶν περὶ τὰ στενά, καὶ τοῖς ἔξω τῶν στενῶν πρὸς τοὺς ἐντὸς ἦσαν ἀγῶνες πρωτείων· καθάπερ καὶ πέδας ἐκάλει Φίλιππος τῆς Ἑλλάδος τὴν Χαλκίδα καὶ τὴν Κόρινθον, πρὸς τὰς ἐκ τῆς Μακεδονίας ἀφορμὰς βλέπων· ἐπιδέσμους δ’ οἱ ὕστερον προσηγόρευον ταύτας τε καὶ ἔτι τὴν Δημητριάδα· καὶ γὰρ αὕτη παρόδων ἦν κυρία τῶν περὶ τὰ Τέμπη, τό τε Πήλιον ἔχουσα καὶ τὴν Ὄσσαν. ὕστερον δὲ πάντων ὑπὸ μίαν ἐξουσίαν ὑπηγμένων, ἅπαντ’ ἀτελεύεται πᾶσι καὶ ἀνέῳγε.", "st": "9.4.15"}, {"sp": "N", "t": "περὶ δὲ τὰ στενὰ ταῦτα οἱ περὶ Λεωνίδαν μετὰ ὀλίγων τῶν ὁμόρων τοῖς τόποις ἀντέσχον πρὸς τὰς τοσαύτας τῶν Περσῶν δυνάμεις, μέχρι περιελθόντες δι’ ἀτραπῶν τὰ ὄρη κατέκοψαν αὐτοὺς οἱ βάρβαροι. καὶ νῦν τὸ πολυάνδριον ἐκείνων ἐστὶ καὶ στῆλαι καὶ ἡ θρυλουμένη ἐπιγραφὴ τῇ Λακεδαιμονίων στήλῃ οὕτως ἔχουσα “ὦ ξέν’ ἀπάγγειλον Λακεδαιμονίοις ὅτι τῇδε κείμεθα τοῖς κείνων πειθόμενοι νομίμοις.”", "st": "9.4.16"}, {"sp": "N", "t": "ἔστι δὲ καὶ λιμὴν μέγας αὐτόθι καὶ Δήμητρος ἱερόν, ἐν ᾧ κατὰ πᾶσαν Πυλαίαν θυσίαν ἐτέλουν οἱ Ἀμφικτύονες. ἐκ δὲ τοῦ λιμένος εἰς Ἡράκλειαν τὴν Τραχῖνα πεζῇ στάδιοι τετταράκοντα, πλοῦς δ’ ἐπὶ τὸ Κήναιον ἑβδομήκοντα. ἔξω δὲ Πυλῶν εὐθὺς ὁ Σπερχειὸς ἐκδίδωσιν. ἐπὶ δὲ Πύλας ἀπὸ Εὐρίπου στάδιοι πεντακόσιοι τριάκοντα. καὶ ἡ μὲν Λοκρὶς τέλος ἔχει. τὰ δ’ ἔξω Θετταλῶν ἐστι τὰ πρὸς ἕω καὶ τὸν Μαλιακὸν κόλπον, τὰ δὲ πρὸς δύσιν Αἰτωλῶν καὶ Ἀκαρνάνων. Ἀθαμᾶνες δὲ καὶ αὐτοὶ ἐκλελοίπασι.", "st": "9.4.17"}, {"sp": "N", "t": "μέγιστον δὴ καὶ παλαιότατον τῶν Θετταλῶν σύστημα, ὧν τὰ μὲν Ὅμηρος εἴρηκε τὰ δ’ ἄλλοι πλείους. Αἰτωλοὺς δ’ Ὅμηρος μὲν ἀεὶ ἑνὶ ὀνόματι λέγει, πόλεις οὐκ ἔθνη τάττων ὑπ’ αὐτοῖς, πλὴν εἰ τοὺς Κουρῆτας, οὓς ἐν μέρει τακτέον Αἰτωλικῶν. ἀπὸ Θετταλῶν δ’ ἀρκτέον, τὰ μὲν σφόδρα παλαιὰ καὶ μυθώδη καὶ οὐχ ὁμολογούμενα τὰ πολλὰ ἐῶντες, καθάπερ καὶ ἐν τοῖς ἄλλοις ἐποιήσαμεν, τὰ δὲ φαινόμενα ἡμῖν καίρια λέγοντες.", "st": "9.4.18"}, {"sp": "N", "t": "ἔστι δ’ αὐτῆς πρὸς θαλάττῃ μὲν ἡ ἀπὸ Θερμοπυλῶν μέχρι τῆς ἐκβολῆς τοῦ Πηνειοῦ καὶ τῶν ἄκρων τοῦ Πηλίου παραλία βλέπουσα πρὸς ἕω καὶ πρὸς τὰ ἄκρα τῆς Εὐβοίας τὰ βόρεια. ἔχουσι δὲ τὰ μὲν πρὸς Εὐβοίᾳ καὶ Θερμοπύλαις Μαλιεῖς καὶ οἱ Φθιῶται Ἀχαιοί, τὰ δὲ πρὸς τῷ Πηλίῳ Μάγνητες. αὕτη μὲν οὖν ἡ πλευρὰ τῆς Θετταλίας ἑῴα λεγέσθω καὶ παραλία. ἑκατέρωθεν δ’ ἀπὸ μὲν Πηλίου καὶ Πηνειοῦ πρὸς τὴν μεσόγαιαν Μακεδόνες παράκεινται μέχρι Παιονίας καὶ τῶν Ἠπειρωτικῶν ἐθνῶν, ἀπὸ δὲ τῶν Θερμοπυλῶν τὰ παράλληλα τοῖς Μακεδόσιν ὄρη τὰ Οἰταῖα καὶ Αἰτωλικά, τοῖς Δωριεῦσι καὶ τῷ Παρνασσῷ συνάπτοντα. καλείσθω δὲ τὸ μὲν πρὸς τοῖς Μακεδόσι πλευρὸν ἀρκτικόν, τὸ δ’ ἕτερον νότιον. λοιπὸν δ’ ἐστὶ τὸ ἑσπέριον, ὃ περικλείουσιν Αἰτωλοὶ καὶ Ἀκαρνᾶνες καὶ Ἀμφίλοχοι καὶ τῶν Ἠπειρωτῶν Ἀθαμᾶνες καὶ Μολοττοὶ καὶ ἡ τῶν Αἰθίκων ποτὲ λεγομένη γῆ καὶ ἁπλῶς ἡ περὶ Πίνδον … πλὴν τοῦ Πηλίου καὶ τῆς Ὄσσης. ταῦτ’ ἐξῆρται μὲν ἱκανῶς, οὐ μήν γε πολλὴν περιλαμβάνει κύκλῳ χώραν, ἀλλ’ εἰς τὰ πεδία τελευτᾷ.", "st": "9.5.1"}, {"sp": "N", "t": "ταῦτα δ’ ἐστὶ τὰ μέσα τῆς Θετταλίας, εὐδαιμονεστάτη χώρα πλὴν ὅση ποταμόκλυστός ἐστιν. ὁ γὰρ Πηνειὸς διὰ μέσης ῥέων καὶ πολλοὺς δεχόμενος ποταμοὺς ὑπερχεῖται πολλάκις· τὸ δὲ παλαιὸν καὶ ἐλιμνάζετο, ὡς λόγος, τὸ πεδίον ἔκ τε τῶν ἄλλων μερῶν ὄρεσι περιειργόμενον καὶ τῆς παραλίας μετεωρότερα τῶν πεδίων ἐχούσης τὰ χωρία ὑπὸ δὲ σεισμῶν ῥήγματος γενομένου [κατὰ] τὰ νῦν καλούμενα Τέμπη καὶ τὴν Ὄσσαν ἀποσχίσαντος ἀπὸ τοῦ Ὀλύμπου, διεξέπεσε ταύτῃ πρὸς θάλατταν ὁ Πηνειὸς καὶ ἀνέψυξε τὴν χώραν ταύτην. ὑπολείπεται δ’ ὅμως ἥ τε Νεσσωνὶς λίμνη μεγάλη καὶ ἡ Βοιβηὶς ἐλάττων ἐκείνης καὶ πλησιεστέρα τῇ παραλίᾳ.", "st": "9.5.2"}, {"sp": "N", "t": "τοιαύτη δ’ οὖσα εἰς τέτταρα μέρη διῄρητο· ἐκαλεῖτο δὲ τὸ μὲν Φθιῶτις τὸ δὲ Ἑστιαιῶτις τὸ δὲ Θετταλιῶτις τὸ δὲ Πελασγιῶτις. ἔχει δ’ ἡ μὲν Φθιῶτις τὰ νότια τὰ παρὰ τὴν Οἴτην ἀπὸ τοῦ Μαλιακοῦ κόλπου καὶ Πυλαϊκοῦ μέχρι τῆς Δολοπίας καὶ τῆς Πίνδου διατείνοντα, πλατυνόμενα δὲ μέχρι Φαρσάλου καὶ τῶν πεδίων τῶν Θετταλικῶν· ἡ δ’ Ἑστιαιῶτις τὰ ἑσπέρια καὶ τὰ μεταξὺ Πίνδου καὶ τῆς ἄνω Μακεδονίας· τὰ δὲ λοιπὰ οἵ τε ὑπὸ τῇ Ἑστιαιώτιδι νεμόμενοι τὰ πεδία, καλούμενοι δὲ Πελασγιῶται, συνάπτοντες ἤδη τοῖς κάτω Μακεδόσι, καὶ οἱ ἐφεξῆς τὰ μέχρι Μαγνητικῆς παραλίας ἐκπληροῦντες χωρία. κἀνταῦθα δ’ ἐνδόξων ὀνομάτων ἔσται ἀρίθμησις καὶ ἄλλως [καὶ] διὰ τὴν Ὁμήρου ποίησιν· τῶν δὲ πόλεων ὀλίγαι σώζουσι τὸ πάτριον ἀξίωμα, μάλιστα δὲ Λάρισα.", "st": "9.5.3"}, {"sp": "N", "t": "ὁ δὲ ποιητὴς εἰς δέκα μέρη καὶ δυναστείας διελὼν τὴν σύμπασαν γῆν ἣν νῦν Θετταλίαν προσαγορεύομεν, προσλαβών τινα καὶ τῆς Οἰταίας καὶ τῆς Λοκρικῆς, ὡς δ’ αὕτως καὶ τῆς ὑπὸ Μακεδόσιν νῦν τεταγμένης, ὑπογράφει τι κοινὸν καὶ πάσῃ χώρᾳ συμβαῖνον, τὸ μεταβάλλεσθαι καὶ τὰ ὅλα καὶ τὰ καθ’ ἕκαστα παρὰ τὰς τῶν ἐπικρατούντων δυνάμεις.", "st": "9.5.4"}, {"sp": "N", "t": "πρώτους δὴ καταλέγει τοὺς ὑπ’ Ἀχιλλεῖ τοὺς τὸ νότιον πλευρὸν κατέχοντας καὶ παρακειμένους τῇ τε Οἴτῃ καὶ τοῖς Ἐπικνημιδίοις Λοκροῖς “ὅσσοι τὸ Πελασγικὸν Ἄργος ἔναιον,” “οἵ τ’ Ἄλον οἵ τ’ Ἀλόπην οἵ τε Τρηχῖν’ ἐνέμοντο,” “οἵ τ’ εἶχον Φθίην ἠδ’ Ἑλλάδα καλλιγύναικα,” “Μυρμιδόνες δὲ καλεῦντο καὶ Ἕλληνες καὶ Ἀχαιοί.” συζεύγνυσι δὲ τούτοις καὶ τοὺς ὑπὸ τῷ Φοίνικι καὶ κοινὸν ἀμφοῖν ποιεῖ τὸν στόλον. ὁ μὲν οὖν ποιητὴς οὐδαμοῦ μέμνηται Δολοπικῆς στρατιᾶς κατὰ τοὺς περὶ Ἴλιον ἀγῶνας· οὐδὲ γὰρ αὐτῶν τὸν ἡγεμόνα Φοίνικα πεποίηκεν εἰς τοὺς κινδύνους ἐξιόντα, καθάπερ τὸν Νέστορα· ἄλλοι δ’ εἰρήκασι, καθάπερ καὶ Πίνδαρος μνησθεὶς τοῦ Φοίνικος “ὃς Δολόπων ἄγαγε θρασὺν ὅμιλον σφενδονᾶσαι, ἱπποδάμων Δαναῶν βέλεσι πρόσφορον.” τοῦτο δὴ καὶ παρὰ τῷ ποιητῇ κατὰ τὸ σιωπώμενον, ὡς εἰώθασι λέγειν οἱ γραμματικοί, συνυπακουστέον. γελοῖον γὰρ τὸ τὸν βασιλέα μετέχειν τῆς στρατείας, τοὺς δ’ ὑπηκόους μὴ παρεῖναι [αὐτῷ]· οὐδὲ γὰρ συστρατεύειν ἂν τῷ Ἀχιλλεῖ δόξειεν, ἀλλὰ μόνον ἐπιστάτης καὶ ῥήτωρ ἕπεσθαι, εἰ δ’ ἄρα, σύμβουλος. τὰ δ’ ἔπη βούλεται καὶ τοῦτο δηλοῦν· τοιοῦτον γὰρ τὸ “μύθων τε ῥητῆρ’ ἔμεναι πρηκτῆρά τε ἔργων.” … ταῦτα λέγων.", "st": "9.5.5"}, {"sp": "N", "t": "εἴρηται τό τε ὑπὸ τῷ Ἀχιλλεῖ [καὶ τῷ Φοί]νικι· αὐτὰ δὲ λεχθέντα περὶ τῶν ὑπ’ [Ἀχιλλεῖ] ἐν ἀντιλογίᾳ ἐστί. τό τε [γὰρ] Ἄργος τὸ Πελασγικὸν [οἱ μὲν] καὶ πόλιν δέχονται Θετταλικὴν περὶ Λάρισαν ἱδρυμένην ποτὲ νῦν δ’ οὐκέτι οὖσαν· οἱ δ’ οὐ πόλιν ἀλλὰ τὸ τῶν Θετταλῶν πεδίον οὕτως ὀνοματικῶς λεγόμενον, θεμένου τοὔνομα Ἄβαντος ἐξ Ἄργους δεῦρ’ ἀποικήσαντος. Φθίαν τε οἱ μὲν τὴν αὐτὴν εἶναι τῇ Ἑλλάδι καὶ Ἀχαΐᾳ, ταύτας δ’ εἶναι διατεμνομένης τῆς συμπάσης Θετταλίας θάτερον μέρος τὸ νότιον· οἱ δὲ διαιροῦσιν. ἔοικε δ’ ὁ ποιητὴς δύο ποιεῖν τήν τε Φθίαν καὶ τὴν Ἑλλάδα ὅταν οὕτως φῇ “οἵ τ’ εἶχον Φθίην ἠδ’ Ἑλλάδα,” ὡς δυεῖν οὐσῶν· καὶ ὅταν οὕτως “φεῦ[γον] ἔπειτ’ ἀπάνευθε δι’ Ἑλλάδος εὐρυχόροιο, Φθίην δ’ ἐξικόμην,” καὶ ὅτι “πολλαὶ [Ἀχαιίδε]ς εἰσὶν ἀν’ Ἑλλάδα τε Φθίην τε.” ὁ μὲν οὖν ποιητὴς δύο ποιεῖ, πότερον δὲ πόλεις ἢ χώρας οὐ δηλοῖ. οἱ δ’ ὕστερον τὴν Ἑλλάδα οἱ μὲν εἰπόντες χώραν διατετάσθαι φασὶν [εἰς] τὰς Θήβας τὰς Φθιώτιδας ἀπὸ Παλαιφαρσάλου (ἐν δὲ τῇ χώρᾳ ταύτῃ καὶ τὸ Θετίδειον ἔστι πλησίον τῶν Φαρσάλων ἀμφοῖν τῆς τε παλαιᾶς καὶ τῆς νέας, κἀκ τοῦ Θετιδείου τεκμαιρόμενοι τῆς ὑπὸ τῷ Ἀχιλλεῖ μέρος εἶναι καὶ τήνδε τὴν χώραν), οἱ δ’ εἰπόντες πόλιν Φαρσάλιοι μὲν δεικνύουσιν ἀπὸ ἑξήκοντα σταδίων τῆς ἑαυτῶν πόλεως κατεσκαμμένην πόλιν ἣν πεπιστεύκασιν εἶναι τὴν Ἑλλάδα καὶ δύο κρήνας πλησίον Μεσσηίδα καὶ Ὑπέρειαν, Μελιταιεῖς δ’ ἄπωθεν ἑαυτῶν ὅσον δέκα σταδίους οἰκεῖσθαι τὴν Ἑλλάδα πέραν τοῦ Ἐνιπέως, ἡνίκα ἡ ἑαυτῶν πόλις Πύρρα ὠνομάζετο, ἐκ δὲ τῆς Ἑλλάδος ἐν ταπεινῷ χωρίῳ κειμένης εἰς τὴν ἑαυτῶν μετοικῆσαι τοὺς Ἕλληνας· μαρτύριον δ’ εἶναι τὸν ἐν τῇ ἀγορᾷ τῇ σφετέρᾳ τάφον τοῦ Ἕλληνος τοῦ Δευκαλίωνος υἱοῦ καὶ Πύρρας. ἱστορεῖται γὰρ ὁ Δευκαλίων τῆς Φθιώτιδος ἄρξαι καὶ ἁπλῶς τῆς Θετταλίας· ὁ δ’ Ἐνιπεὺς ἀπὸ τῆς Ὄθρυος παρὰ Φάρσαλον ῥυεὶς εἰς τὸν Ἀπιδανὸν παραβάλλει, ὁ δ’ εἰς τὸν Πηνειόν. περὶ μὲν Ἑλλήνων ταῦτα.", "st": "9.5.6"}, {"sp": "N", "t": "Φθῖοι δὲ καλοῦνται οἵ τε ὑπ’ Ἀχιλλεῖ καὶ ὑπὸ Πρωτεσιλάῳ καὶ Φιλοκτήτῃ· ὁ δὲ ποιητὴς τούτου μάρτυς. εἰπὼν γὰρ ἐν τῷ καταλόγῳ τῶν ὑπ’ Ἀχιλλεῖ “οἵ τ’ εἶχον Φθίην,” ἐν τῇ ἐπὶ ναυσὶ μάχῃ τούτους μὲν ὑπομένοντας ἐν ταῖς ναυσὶ πεποίηκε μετὰ τοῦ Ἀχιλλέως καὶ καθ’ ἡσυχίαν ὄντας, τοὺς δ’ ὑπὸ Φιλοκτήτῃ μαχομένους ἔχοντας Μέδον[τα ἡγεμόνα] καὶ τοὺς ὑπὸ Πρωτεσιλάῳ, Ποδάρκους … ⟨πε⟩ρὶ ὧν κοινῶς μὲν οὕτω φησίν “ἔνθα δὲ Βοιωτοὶ καὶ Ἰάονες ἑλκεχίτωνες, Λοκροὶ καὶ Φθῖοι καὶ φαιδιμόεντες Ἐπειοί·” ἰδίως δέ “πρὸ Φθίων δὲ Μέδων τε μενεπτόλεμός τε Ποδάρκης. οἱ μὲν πρὸ Φθίων μεγαθύμων θωρηχθέντες ναῦφιν ἀμυνόμενοι [μετὰ Βοιω]τῶν ἐμάχοντο.” τάχα δὲ καὶ οἱ σὺν Εὐρυπύλῳ Φθῖοι ἐλέγοντο, ὅμοροι τούτοις ὄντες· νῦν μέντοι Μαγνησίας νομίζουσι τῆς τε ὑπ’ Εὐρυπύλῳ τὰ περὶ Ὀρμένιον καὶ τὴν ὑπὸ Φιλοκτήτῃ πᾶσαν, τὴν δ’ ὑπὸ [Πρωτεσιλάῳ] τῆς Φθίας ἀπὸ Δολοπίας καὶ τῆς Πίνδου μέχρι τῆς Μαγνητικῆς θαλάττης· μέχρι δὲ τῆς ὑπὸ Πρωτεσιλάῳ πόλεως Ἀντρῶνος, ἣ νῦν πληθυντικῶς λέγεται, τὸ πλάτος ἀφορίζεται τῆς ὑπὸ Πηλεῖ καὶ Ἀχιλλεῖ γ[ῆς, ἀπὸ] τῆς Τραχινίας καὶ τῆς Οἰταίας ἀρξαμένοις· [τὸ] δ’ αὐτὸ σχεδόν τι μῆκός ἐστι τοῦ Μαλιακοῦ κ[όλπου].", "st": "9.5.7"}, {"sp": "N", "t": "περὶ Ἅλου δὲ καὶ Ἀλόπης διαποροῦσι μὴ οὐ τούτους λέγει τοὺς τόπους οἳ νῦν ἐν τῷ Φθιωτικῷ τέλει φέρονται, ἀλλὰ τοὺς ἐν Λοκροῖς, μέχρι δεῦρο ἐπικρατοῦντος τοῦ Ἀχιλλέως, ὥσπερ καὶ μέχρι Τραχῖνος καὶ τῆς Οἰταίας. ἔστι γὰρ καὶ Ἅλος καὶ Ἁλιοῦς ἐν τῇ παραλίᾳ τῶν Λοκρῶν, καθάπερ καὶ Ἀλόπη. οἱ δὲ τὸν Ἁλιοῦντα ἀντὶ Ἀλόπης τιθέασι καὶ γράφουσιν οὕτως “οἵ θ’ Ἅλον οἵ θ’ Ἁλιοῦνθ’ οἵ τε Τρηχῖν’ ἐνέμοντο.” ὁ δὲ Φθιωτικὸς Ἅλος ὑπὸ τῷ πέρατι κεῖται τῆς Ὄθρυος ὄρους πρὸς ἄρκτον κειμένου τῇ Φθιώτιδι, ὁμόρου δὲ τῷ Τυφρηστῷ καὶ τοῖς Δόλοψιν, κἀνθένδε παρατείνοντος εἰς τὰ πλησίον τοῦ Μαλιακοῦ κόλπου. ἀπέχει δὲ Ἰτώνου περὶ ἑξήκοντα σταδίους ὁ Ἅλος ἢ ἡ Ἅλος· λέγεται γὰρ ἀμφοτέρως. ᾤκισε δὲ ὁ Ἀθάμας τὴν Ἅλον, ἀφανισθεῖσαν [δὲ] συνῴ[κισαν Φαρσάλιοι] χρόνοις ὕστερον. ὑπέρκειται δὲ τοῦ Κροκίου πεδίου· ῥεῖ δὲ ποταμὸς Ἄμφρυσος πρὸς τῷ [τείχει]. ὑπὸ δὲ τῷ Κροκίῳ Θῆβαι εἰσὶν αἱ Φθιώτιδες, καὶ ἡ Ἅλος δὲ Φθιῶτις καλεῖται καὶ Ἀχαϊκή, συνάπτουσα τοῖς Μαλιεῦσιν, ὥσπερ καὶ οἱ τῆς Ὄθρυος πρόποδες. καθάπερ δὲ ἡ Φυλάκη ἡ ὑπὸ Πρωτεσιλάῳ τῆς Φθιώτιδός ἐστι τῆς προσχώρου τοῖς Μαλιεῦσιν, οὕτω καὶ ἡ Ἅλος· διέχει δὲ Θηβῶν περὶ ἑκατὸν σταδίους, ἐν μέσῳ δ’ ἐστὶ Φαρσάλου καὶ Φθιωτῶν· Φίλιππος μέντοι Φαρσαλίοις προσένειμεν ἀφελόμενος τῶν Φθιωτῶν. οὕτω δὲ συμβαίνει τοὺς ὅρους καὶ τὰς συντάξεις τῶν τε ἐθνῶν καὶ τῶν τόπων ἀλλάττεσθαι ἀεί, καθάπερ εἴπομεν. οὕτω καὶ Σοφοκλῆς τὴν Τραχῖνα Φθιῶτιν εἴρηκεν, Ἀρτεμίδωρος δὲ τὴν Ἅλον ἐν τῇ παραλίᾳ τίθησι, ἔξω μὲν τοῦ Μαλιακοῦ κόλπου κειμένην, Φθιῶτιν δέ. προϊὼν γὰρ ἐνθένδε ὡς ἐπὶ τὸν Πηνειὸν μετὰ τὸν Ἀντρῶνα τίθησι Πτελεόν, εἶτα τὸν Ἅλον ἀπὸ τοῦ Πτελεοῦ διέχοντα ἑκατὸν καὶ δέκα σταδίους. περὶ δὲ τῆς Τραχῖνος εἴρηται ὁποία τις· καὶ ὁ ποιητὴς κατονομάζει.", "st": "9.5.8"}, {"sp": "N", "t": "τοῦ δὲ Σπερχειοῦ μεμνημένος πολλάκις ὡς ἐπιχωρίου ποταμοῦ, τὰς πηγὰς ἔχοντος ἐκ Τυφρηστοῦ Δρυοπικοῦ ὄρους, τοῦ καλουμένου … [πρ]ότερον, ἐκδιδόντος δὲ πλησίον Θερμοπυλῶν μεταξὺ αὐτῶν καὶ Λαμίας, δηλοῖ ὅτι καὶ τὰ ἐντὸς πυλῶν ὅσα τοῦ Μαλιακοῦ κόλπου καὶ τὰ ἐκτὸς ὑπ’ ἐκείνῳ ἦν· ἀπέχει δὲ Λαμίας ὁ Σπερχειὸς περὶ τριάκοντα σταδίους ὑπερκειμένης πεδίου τινὸς καθήκοντος ἐπὶ τὸν Μαλιακὸν κόλπον· ὅτι δ’ ὁ Σπερχειὸς ἐπιχώριος, ἔκ τε τοῦ τρέφειν ἐκείνῳ τὴν κόμην φάσκειν καὶ τοῦ τὸν Μενέσθιον, ἕνα τῶν λοχαγῶν αὐτοῦ, Σπερχειοῦ λέγεσθαι παῖδα καὶ τῆς ἀδελφῆς τῆς Ἀχιλλέως. Μυρμιδόνας δ’ εἰκὸς καλεῖσθαι πάντας τοὺς ὑπὸ τῷ Ἀχιλλεῖ καὶ τῷ Πατρόκλῳ, οἳ συνηκολούθησαν ἐξ Αἰγίνης φεύγοντι τῷ Πηλεῖ. Ἀχαιοὶ δ’ ἐκαλοῦντο οἱ Φθιῶται πάντες.", "st": "9.5.9"}, {"sp": "N", "t": "διαριθμοῦνται δὲ τὰς ὑπὸ τῷ Φθιωτικῷ τέλει τῷ ὑπ’ Ἀχιλλεῖ κατοικίας [ἀπὸ] Μαλιέων ἀρξάμενοι πλείους μέν, ἐν δ’ αὐταῖς Θήβας τὰς Φθιώτιδας Ἐχῖνον Λάμιαν, περὶ ἣν ὁ Λαμιακὸς συνέστη πόλεμος Μακεδόσι καὶ Ἀντιπάτρῳ πρὸς Ἀθηναίους· ἐν ᾧ Λεωσθένης τε ἔπεσε τῶν Ἀθηναίων στρατηγός, [καὶ Λεοννάτος] ὁ Ἀλεξάνδρου τοῦ βασιλέως ἑταῖρος. [ἔτι δὲ Ναρθάκ]ιον Ἐρινεὸν Κορώνειαν, ὁμώνυμον τῇ Βοιωτικῇ, Μελίταιαν Θαυμακοὺς Πρόερναν Φάρσαλον Ἐρέτριαν, ὁμώνυμον τῇ Εὐβοϊκῇ, Παραχελωίτας καὶ τούτους ὁμωνύμους τοῖς Αἰτωλικοῖς· καὶ γὰρ ἐνταῦθά ἐστιν Ἀχελῶος ποταμὸς πλησίον Λαμίας, παρ’ ὃν οἰκοῦσιν οἱ Παραχελωῖται. παρέτεινε δ’ ἡ χώρα αὕτη πρὸς ἄρκτον μὲν τῇ τῶν Ἀσκληπ[ιαδῶν τῶν μά]λιστα προσεσπερίων καὶ τῇ Εὐρυπύλου καὶ [ἔτι τῇ] Πρωτεσιλάου, ταῖς πρὸς ἕω κεκλιμέναις, πρὸς νότον δὲ τῇ Οἰταίᾳ εἰς τετταρεσκαίδεκα δήμους διῃρημένῃ, Ἡράκλειάν τε καὶ τὴν Δρυοπίδα, τετράπολιν γεγονυῖάν ποτε καθάπερ καὶ τὴν Δωρίδα, μητρόπολιν δὲ τῶν ἐν Πελοποννήσῳ Δρυόπων νομιζομένην. τῆς δ’ Οἰταίας καὶ ὁ Ἀκύφας ἐστὶ καὶ Παρασωπιὰς καὶ Οἰνειάδαι καὶ Ἀντικύρα, ὁμώνυμος τῇ ἐν Λοκροῖς τοῖς ἑσπερίοις. λέγω δὲ τὰς διατάξεις ταύτας οὐκ ἀεὶ μεμενηκυίας τὰς αὐτάς, ἀλλὰ ποικίλως μεταβεβλημένας· αἱ δ’ ἐπισημόταται μάλιστα ἄξιαι μνήμης εἰσί.", "st": "9.5.10"}, {"sp": "N", "t": "τοὺς δὲ Δόλοπας φράζει καὶ ὁ ποιητὴς ἱκανῶς ὅτι ἐπὶ ταῖς ἐσχατιαῖς εἰσι τῆς Φθίας, καὶ ὅτι ὑπὸ τῷ αὐτῷ ἡγεμόνι ἦσαν τῷ Πηλεῖ οὗτοί τε καὶ οἱ Φθιῶται· ἔναιον γάρ, φησίν, ἐσχατιὴν Φθίης Δολόπεσσιν ἀνάσσων, δόντος τοῦ Πηλέως. γειτνιᾷ δὲ τῇ Πίνδῳ καὶ τοῖς περὶ αὐτὴν χωρίοις Θετταλικοῖς οὖσι τοῖς πλείστοις. διὰ γὰρ τὴν ἐπιφάνειάν τε καὶ τὴν ἐπικράτειαν τῶν Θετταλῶν καὶ τῶν Μακεδόνων οἱ πλησιάζοντες αὐτοῖς μάλιστα τῶν Ἠπειρωτῶν, οἱ μὲν ἑκόντες οἱ δ’ ἄκοντες, μέρη καθίσταντο Θετταλῶν ἢ Μακεδόνων, καθάπερ Ἀθαμᾶνες καὶ Αἴθικες καὶ Τάλαρες Θετταλῶν, Ὀρέσται δὲ καὶ Πελαγόνες καὶ Ἐλιμιῶται Μακεδόνων.", "st": "9.5.11"}, {"sp": "N", "t": "ἡ δὲ Πίνδος ὄρος ἐστὶ μέγα, πρὸς ἄρκτον μὲν τὴν Μακεδόνων, πρὸς ἑσπέραν δὲ Περραιβοὺς μετανάστας ἀνθρώπους [ἔχον], πρὸς δὲ μεσημβρίαν Δόλοπας, [πρὸς ἕω δὲ] … αὕτη δ’ ἐστὶ τῆς Θετταλίας· ἐπ’ αὐτῇ δὲ τῇ Πίνδῳ ᾤκουν Τάλαρες Μολοττικὸν φῦλον, τῶν περὶ τὸν Τόμαρον ἀπόσπασμα, καὶ Αἴθικες, [εἰς] οὓς ἐξελαθῆναί φησιν ὑπὸ Πειρίθου τοὺς Κενταύρους ὁ ποιητής· ἐκλελοιπέναι δὲ νῦν ἱστοροῦνται. τὴν δ’ ἔκλειψιν διττῶς ἀκουστέον· ἢ γὰρ ἀφανισθέντων τῶν ἀνθρώπων καὶ τῆς χώρας τελέως ἠρημωμένης, ἢ τοῦ ὀνόματος τοῦ ἐθνικοῦ μηκέτι ὄντος, μηδὲ τοῦ συστήματος διαμένοντος τοιούτου. ὅταν οὖν ἄσημον τελέως ᾖ τὸ λειπόμενον νυνὶ σύστημα, οὐκ ἄξιον μνήμης τίθεμεν οὔτ’ αὐτὸ οὔτε τοὔνομα τὸ μεταληφθέν, ὅταν δ’ ἔχῃ τοῦ μεμνῆσθαι δικαίαν πρόφασιν, λέγειν ἀναγκαῖον τὴν μεταβολήν.", "st": "9.5.12"}, {"sp": "N", "t": "λοιπὸν δ’ εἰπεῖν τῆς παραλίας τὴν τάξιν τῆς ὑπὸ τῷ Ἀχιλλεῖ ἀπὸ Θερμοπυλῶν ἀρξαμένους· τὴν γὰρ Λοκρικὴν καὶ [τὴν Οἰταία]ν εἰρήκαμεν. αἱ τοίνυν Θερμοπύλαι τοῦ μὲν Κηναίου διεστήκασιν ἑβδομηκοντασταδίῳ πορθμῷ, παραπλέοντι δ’ ἔξω Πυλῶν τοῦ Σπερχειοῦ ὡς σταδίους δέκα· ἔνθεν δ’ εἰς Φάλαρα εἴκοσι· τῶν δὲ Φαλάρων ἀπὸ θαλάττης ὑπέρκειται πεντήκοντα σταδίους ἡ τῶν [Λαμιέων πόλι]ς. εἶθ’ ἑξῆς παραπλεύσαντι σταδίοις ἑκατὸν ὁ Ἐχῖνος ὑπέρκειται. τῆς δ’ ἑξῆς παραλίας ἐν μεσογαίᾳ ἐστὶν ἡ Κρεμαστὴ Λάρισα εἴκοσι σταδίους αὐτῆς διέχουσα, ἡ δ’ αὐτὴ καὶ Πελασγία λεγομένη Λάρισα. εἶτα Μυόννησος νησίον, εἶτ’ Ἀντρών· ἦν δὲ αὕτη ὑπὸ Πρωτεσιλάῳ. τοσαῦτα μὲν περὶ τῆς ὑπὸ τῷ Ἀχιλλεῖ με[ρίδος].", "st": "9.5.13"}, {"sp": "N", "t": "ἐπεὶ δ’ ὁ ποιητὴς εἰς πολλὰ καὶ γνώριμα μέρη διε[λὼν δι]ὰ τὸ ὀνομάζειν τούς τε ἡγεμόνας καὶ τὰς ὑπ’ αὐτοῖς [πόλεις] τὸν σύμπαντα τῆς Θετταλίας κύκλον διέταξεν, [ἡμεῖς ἀκολ]ουθοῦντες τούτῳ πάλιν ὥσπερ ἐν τοῖς ἐπάνω [προ]σεκπληρώσομεν τὴν λοιπὴν περιοδείαν τῆς χώ[ρα]ς. καταλέγει τοίνυν ἐφεξῆς τοῖς ὑπ’ Ἀχιλλεῖ τοὺς ὑπὸ Πρωτεσιλάῳ· οὗτοι δ’ εἰσὶν οἱ καὶ ἐφεξῆς ὄντες τῇ ὑπὸ τῷ Ἀχιλλεῖ παραλίᾳ μέχρι Ἀντρῶνος. ὁριζομένη τοίνυν [τῆς ἐφ]εξῆς ἐστὶν ἡ ὑπὸ τῷ Πρωτεσιλάῳ, ἔξω μὲν οὖσα τοῦ [Μαλιακ]οῦ κόλπου, ἔτι δ’ ἐντὸς τῆς Φθιώτιδος, οὐ μὴν τῆς [ὑπὸ τῷ Ἀχιλλεῖ]. ἡ μὲν οὖν Φυλάκη ἐγγὺς Θηβῶν ἐστι τῶν Φθιωτίδων, αἵπερ εἰσὶ καὶ αὐταὶ ὑπὸ τῷ Πρωτεσιλάῳ· καὶ Ἅλος δὲ καὶ Λάρισα ἡ Κρεμαστὴ καὶ τὸ Δημήτριον ὑπ’ ἐκείνῳ, πᾶσαι πρὸς ἕω τῆς Ὄθρυος. τὸ δὲ Δημήτριον Δήμητρος εἴρηκε τέμενος καὶ ἐκάλεσε Πύρασον. ἦν δὲ πόλις εὐλίμενος ἡ Πύρασος ἐν δυσὶ σταδίοις, ἔχουσα Δήμητρος ἄλσος καὶ ἱερὸν ἅγιον, διέχουσα Θηβῶν σταδίους εἴκοσι· ὑπέρκεινται δὲ Πυράσου μὲν αἱ Θῆβαι. τῶν Θηβῶν δὲ ἐν τῇ μεσογαίᾳ τὸ Κρόκιον πεδίον πρὸς τῷ καταλήγοντι τῆς Ὄθρυος, δι’ οὗ ὁ Ἄμφρυσος ῥεῖ. τούτου δ’ ὑπέρκειται ὁ Ἴτωνος, ὅπου τὸ τῆς Ἰτωνίας ἱερόν, ἀφ’ οὗ καὶ τὸ ἐν τῇ Βοιωτίᾳ, καὶ ὁ Κουάριος ποταμός· εἴρηται δὲ π[ερὶ τούτου καὶ] τῆς Ἄρνης ἐν τοῖς Βοιωτιακοῖς. ταῦτα δ’ ἐστὶ τῆς Θετταλιώτιδος μιᾶς τῶν τεττάρων μερίδων τῆς συμπάσης Θετταλίας, ἧς καὶ τὰ ὑπ’ Εὐρυπύλῳ καὶ ὁ Φύλλ[ος, ὅπου Ἀπόλλω]νος τοῦ Φυλλίου ἱερόν, καὶ Ἴχναι, ὅπου ἡ Θέμις Ἰχναία τιμᾶται. καὶ Κίερος δ’ εἰς αὐτὴν συντελεῖ καὶ [τἆλλα μέχρι] τῆς Ἀθαμανίας. κατὰ δὲ τὸν Ἀντρῶνα ἕρμα ὕφαλον ἐν τῷ πρὸς Εὐβοίᾳ ἐστὶ πόρῳ καλούμενον ὄνος Ἀντρῶνος. εἶτα Πτελεὸν καὶ ὁ Ἅλος· εἶτα τὸ τῆς Δήμητρος ἱερὸν καὶ ὁ Πύρασος κατεσκαμμένος, ὑπὲρ αὐτὸν δὲ αἱ Θῆβαι· εἶτα ἄκρα Πύρρα καὶ δύο νησία πλησίον, ὧν τὸ μὲν Πύρρα τὸ δὲ Δευκαλίων καλεῖται· ἐνταῦθα δὲ καὶ ἡ Φθιῶτίς πως τελευτᾷ.", "st": "9.5.14"}, {"sp": "N", "t": "ἑξῆς δὲ τοὺς ὑπὸ τῷ Εὐμήλῳ καταλέγει, τὴν συνεχῆ παραλίαν, ἥπερ ἐστὶν ἤδη Μαγνησίας καὶ τῆς Πελασγιώτιδος γῆς. Φεραὶ μὲν οὖν εἰσι πέρας τῶν Πελασγικῶν πεδίων πρὸς τὴν Μαγνησίαν, ἃ παρατείνει μέχρι τοῦ Πηλίου σταδίους ἑκατὸν ἑξήκοντα. ἐπίνειον δὲ τῶν Φερῶν Παγασαὶ διέχον ἐνενήκοντα σταδίους αὐτῶν, Ἰωλκοῦ δὲ εἴκοσιν. ἡ δ’ Ἰωλκὸς κατέσκαπται μὲν ἐκ παλαιοῦ, ἐντεῦθεν δ’ ἔστειλε τὸν Ἰάσονα καὶ τὴν Ἀργὼ Πελίας· ἀπὸ δὲ τῆς ναυπηγίας τῆς Ἀργοῦς καὶ Παγασὰς λέγεσθαι μυθεύουσι τὸν τόπον, οἱ δὲ πιθανώτερον ἡγοῦνται τοὔνομα τῷ τόπῳ τεθῆναι τοῦτο ἀπὸ τῶν πηγῶν αἳ πολλαί τε καὶ δαψιλεῖς ῥέουσι· πλησίον δὲ καὶ Ἀφέται ὡς ἂν ἀφετήριόν τι τῶν Ἀργοναυτῶν. τῆς δὲ Δημητριάδος ἑπτὰ σταδίους ὑπέρκειται τῆς θαλάττης Ἰωλκός. ἔκτισε δὲ Δημήτριος ὁ πολιορκητὴς ἐπώνυμον ἑαυτοῦ τὴν Δημητριάδα μεταξὺ Νηλείας καὶ Παγασῶν ἐπὶ θαλάττῃ τὰς πλησίον πολίχνας εἰς αὐτὴν συνοικίσας, Νήλειάν τε καὶ Παγασὰς καὶ Ὀρμένιον, ἔτι δὲ Ῥιζοῦντα Σηπιάδα Ὀλιζῶνα Βοίβην Ἰωλκόν, αἳ δὴ νῦν εἰσι κῶμαι τῆς Δημητριάδος. καὶ δὴ καὶ ναύσταθμον ἦν τοῦτο καὶ βασίλειον μέχρι πολλοῦ τοῖς βασιλεῦσι τῶν Μακεδόνων, ἐπεκράτει δὲ καὶ τῶν Τεμπῶν καὶ τῶν ὀρῶν ἀμφοῖν, ὥσπερ εἴρηται, τοῦ τε Πηλίου καὶ τῆς Ὄσσης· νῦν δὲ συνέσταλται μέν, τῶν δ’ ἐν τῇ Μαγνησίᾳ πασῶν ὅμως διαφέρει. ἡ δὲ Βοιβηὶς λίμνη πλησιάζει μὲν ταῖς Φεραῖς, συνάπτει δὲ καὶ τοῖς ἀπολήγουσι τοῦ Πηλίου πέρασι καὶ τῆς Μαγνησίας· Βοίβη δὲ χωρίον ἐπὶ τῇ λίμνῃ κείμενον. καθάπερ δὲ τὴν Ἰωλκὸν αὐξηθεῖσαν ἐπὶ πλέον κατέλυσαν αἱ στάσεις καὶ αἱ τυραννίδες, οὕτως καὶ τὰς Φερὰς συνέστειλαν ἐξαρθείσας ποτὲ καὶ συγκαταλυθείσας τοῖς τυράννοις. πλησίον δὲ τῆς Δημητριάδος ὁ Ἄναυρος ῥεῖ. καλεῖται δὲ καὶ συνεχὴς αἰγιαλὸς Ἰωλκός· ἐνταῦθα δὲ καὶ τὴν Πυλαϊκὴν πανήγυριν συνετέλουν. ὁ δ’ Ἀρτεμίδωρος ἀπωτέρω τῆς Δημητριάδος τίθησι τὸν Παγασιτικὸν κόλπον εἰς τοὺς ὑπὸ Φιλοκτήτῃ τόπους· ἐν δὲ τῷ κόλπῳ φησὶν εἶναι τὴν Κικύνηθον νῆσον καὶ πολίχνην ὁμώνυμον.", "st": "9.5.15"}, {"sp": "N", "t": "ἑξῆς δ’ αἱ ὑπὸ Φιλοκτήτῃ πόλεις καταλέγονται. ἡ μὲν οὖν Μηθώνη ἑτέρα ἐστὶ τῆς Θρᾳκίας Μεθώνης, ἣν κατέσκαψε Φίλιππος· ἐμνήσθημεν δὲ καὶ πρότερον τῆς τῶν ὀνομάτων τούτων καὶ τῶν ἐν Πελοποννήσῳ … τροπῆς· τἆλλα δὲ [δι]ηρίθμηται, ἥ τε Θαυμακία καὶ [ὁ Ὀλιζ]ὼν καὶ ἡ Μελίβοια, [ἃ] τῆς ἑξῆς παραλίας ἐστίν. πρόκεινται δὲ τῶν Μαγνήτων νῆσοι συχναὶ μέν, αἱ δ’ ἐν ὀνόματι Σκίαθός τε καὶ Πεπάρηθος καὶ Ἰκὸς Ἁλόννησός τε καὶ Σκῦρος, ὁμωνύμους ἔχουσαι πόλεις. μάλιστα δ’ ἐστὶν ἐν ὀνόματι Σκῦρος διὰ τὴν Λυκομήδους πρὸς Ἀχιλλέα οἰκειότητα καὶ τὴν Νεοπτολέμου τοῦ Ἀχιλλέως ἐνταῦθα γένεσίν τε καὶ ἐκτροφήν. ὕστερον δὲ Φίλιππος αὐξηθείς, ὁρῶν Ἀθηναίους ἐπικρατοῦντας τῆς θαλάττης καὶ τῶν νήσων ἄρχοντας καὶ τούτων καὶ τῶν ἄλλων, ἐποίησε τὰς πλησίον ἑαυτῷ μάλιστα ἐνδόξους. πολεμῶν γὰρ περὶ τῆς ἡγεμονίας ἐπεχείρει πρώτοις ἀεὶ τοῖς ἐγγύθεν, καὶ καθάπερ αὐτῆς τῆς Μαγνήτιδος τὰ πολλὰ μέρη Μακεδονίαν ἐποίησε καὶ τῆς Θρᾴκης καὶ τῆς ἄλλης τῆς κύκλῳ γῆς, οὕτω καὶ τὰς πρὸ τῆς Μαγνησίας νήσους ἀφῃρεῖτο, καὶ τὰς ὑπ’ οὐδενὸς γνωριζομένας πρότερον περιμαχήτους καὶ γνωρίμους ἐποίει. τὴν δ’ οὖν Σκῦρον καὶ μάλιστα μὲν αἱ ἀρχαιολογίαι συνιστῶσιν, ἀλλὰ καὶ τὰ τοιαῦτα θρυλεῖσθαι ποιεῖ, οἷον αἱ τῶν αἰγῶν ἀρεταὶ τῶν Σκυρίων, καὶ τὰ μέταλλα τῆς ποικίλης λίθου τῆς Σκυρίας, καθάπερ τῆς Καρυστίας καὶ τῆς Δοκιμαίας ἢ Συνναδικῆς, καὶ τῆς Ἱεραπολιτικῆς. μονολίθους γὰρ κίονας καὶ πλάκας μεγάλας ὁρᾶν ἔστιν ἐν τῇ Ῥώμῃ τῆς ποικίλης λιθείας, ἀφ’ ἧς ἡ πόλις κοσμεῖται δημοσίᾳ τε καὶ ἰδίᾳ, πεποίηκέ τε τὰ λευκόλιθα οὐ πολλοῦ ἄξια.", "st": "9.5.16"}, {"sp": "N", "t": "ὁ δ’ οὖν ποιητὴς μέχρι δεῦρο προελθὼν τῆς Μαγνητικῆς παραλίας ἐπάνεισιν ἐπὶ τὴν ἄνω Θετταλίαν· καὶ γὰρ τὰ παρατείνοντα τῇ Φ[θιώτιδι], ἀρξάμενος ἀπὸ τῆς Δολοπίας καὶ τῆς Πίνδου, [μέχρι τῆς] κάτω Θετταλίας διέξεισιν “οἳ δ’ εἶχον Τρίκκην καὶ Ἰθώμην κλωμακόεσσαν.” ταῦτα τὰ χωρία ἔστι μὲν τῆς Ἱστιαιώτιδος, ἐκαλεῖτο δ’, ὥς φασι, πρότερον Δωρίς· κατασχόντων δὲ τῶν Περραιβῶν αὐτήν, οἳ καὶ τῆς Εὐβοίας τὴν Ἱστιαιῶτιν κατεστρέψαντο καὶ τοὺς ἀνθρώπους εἰς τὴν ἤπειρον ἀνέσπασαν, διὰ τὸ πλῆθος τῶν ἐποικησάντων Ἱστιαίων τὴν χώραν ἀπ’ ἐκείνων οὕτως ἐκάλεσαν. καλοῦσι δὲ καὶ [αὐτὴν καὶ] τὴν Δολοπίαν τὴν ἄνω Θετταλίαν, ἐπ’ εὐθείας οὖσα[ν τῇ ἄνω] Μακεδονίᾳ, καθάπερ καὶ τὴν κάτω τῇ κάτω. ἔστι δ’ ἡ μὲν Τρίκκη, ὅπου τὸ ἱερὸν τοῦ Ἀσκληπιοῦ τὸ ἀρχαιότατον καὶ ἐπιφανέστατον, ὅμορος τοῖς τε Δόλοψιν καὶ τοῖς περὶ τὴν Πίνδον τόποις. τὴν δ’ Ἰθώμην ὁμωνύμως τῇ Μεσσηνιακῇ λεγομένην οὔ φασι δεῖν οὕτως ἐκφέρειν, ἀλλὰ τὴν πρώτην συλλαβὴν ἀφαιρεῖν· οὕτω γὰρ καλεῖσθαι πρότερον, νῦν δὲ Ἰθώμη μετωνομάσθαι, χωρίον ἐρυμνὸν καὶ τῷ ὄντι κλωμακόεν, ἱδρυμένον μεταξὺ τεττάρων φρουρίων ὥσπερ ἐν τετραπλεύρῳ κειμένων, Τρίκκης τε καὶ Μητροπόλεως καὶ Πελινναίου καὶ Γόμφων. τῆς δὲ δὴ Μητροπολιτῶν ἐστι χώρας ἡ Ἰθώμη. ἡ δὲ Μητρόπολις πρότερον μὲν ἐκ τριῶν συνῴκιστο πολιχνίων ἀσήμων, ὕστερον δὲ καὶ πλείους προσελήφθησαν, ὧν ἦν καὶ ἡ Ἰθώμη. Καλλίμαχος μὲν οὖν φησιν ἐν τοῖς ἰάμβοις τὰς Ἀφροδίτας (ἡ θεὸς γὰρ οὐ μία) τὴν Καστνιῆτιν ὑπερβάλλεσθαι πάσας τῷ φρονεῖν, ὅτι μόνη παραδέχεται τὴν τῶν ὑῶν θυσίαν. καὶ μὴν πολυίστωρ, εἴ τις ἄλλος, καὶ πάντα τὸν βίον, ὡς αὐτὸς εἴρηκεν, ὁ ταῦτα μυθεῖσθαι βουλόμενος. οἱ δ’ ὕστερον ἤλεγξαν οὐ μίαν Ἀφροδίτην μόνον ἀλλὰ καὶ πλείους ἀποδεδεγμένας τὸ ἔθος τοῦτο, ὧν εἶναι καὶ τὴν ἐν τῇ Μητροπόλει· ταύτῃ δὲ μίαν τῶν συνοικισθεισῶν εἰς αὐτὴν πόλεων παραδοῦναι τὸ ἔθος Ὀνθύριον. ἔστι δὲ καὶ Φαρκαδὼν ἐν τῇ Ἱστιαιώτιδι, καὶ ῥεῖ δι’ αὐτῶν ὁ Πηνειὸς καὶ ὁ Κουράλιος· ὧν ὁ Κουράλιος ῥυεὶς παρὰ τὸ τῆς Ἰτωνίας Ἀθηνᾶς ἱερὸν εἰς τὸν Πηνειὸν ἐξίησιν, αὐτὸς δ’ ὁ Πηνειὸς ἄρχεται μὲν ἐκ Πίνδου, καθάπερ εἴρηται, ἐν ἀριστερᾷ δ’ ἀφεὶς Τρίκκην τε καὶ Πελινναῖον καὶ Φαρκαδόνα φέρεται παρά τε Ἄτρακα καὶ Λάρισαν, καὶ τοὺς ἐν τῇ Θετταλιώτιδι δεξάμενος ποταμοὺς πρόεισι διὰ τῶν Τεμπῶν ἐπὶ τὰς ἐκβολάς. τὴν δ’ Οἰχαλίαν πόλιν Εὐρύτου λεγομένην ἔν τε τοῖς τόποις τούτοις ἱστοροῦσι καὶ ἐν Εὐβοίᾳ καὶ ἐν Ἀρκαδίᾳ, καὶ μετονομάζουσιν [ἄλλοι] ἄλλως, ὃ καὶ ἐν τοῖς Πελοποννησιακοῖς εἴρηται. περὶ δὲ τούτων ζητοῦσι καὶ μάλιστα τίς ἦν ἡ ὑπὸ Ἡρακλέους ἁλοῦσα, καὶ περὶ τίνος συνέγραψεν ὁ ποιήσας τὴν Οἰχαλίας ἅλωσιν. ταῦτα μὲν δὴ τὰ χωρία τοῖς Ἀσκληπιάδαις ὑπέταξεν.", "st": "9.5.17"}, {"sp": "N", "t": "ἑξῆς δὲ λέγει τὴν ὑπ’ Εὐρυπύλῳ “οἳ δ’ ἔχον Ὀρμένιον οἵ τε κρήνην Ὑπέρειαν, οἵ τ’ ἔχον Ἀστέριον Τιτάνοιό τε λευκὰ κάρηνα.” τὸ μὲν οὖν Ὀρμένιον νῦν Ὀρμίνιον καλεῖται, ἔστι δ’ ὑπὸ τῷ Πηλίῳ κώμη κατὰ τὸν Παγασιτικὸν κόλπον τῶν συνῳκισμένων εἰς τὴν Δημητριάδα πόλεων, ὡς εἴρηται. ἀνάγκη δὲ καὶ τὴν Βοιβηίδα λίμνην εἶναι πλησίον, ἐπειδὴ καὶ ἡ Βοίβη τῶν περιοικίδων ἦν τῆς Δημητριάδος καὶ αὐτὸ τὸ Ὀρμένιον. τὸ μὲν οὖν Ὀρμένιον ἀπέχει τῆς Δημητριάδος πεζῇ σταδίους ἑπτὰ καὶ εἴκοσιν, ὁ δὲ τῆς Ἰωλκοῦ τόπος ἐν ὁδῷ κείμενος τῆς μὲν Δημητριάδος ἑπτὰ σταδίους διέστηκε, τοῦ δ’ Ὀρμενίου τοὺς λοιποὺς σταδίους εἴκοσι. φησὶ δ’ ὁ Σκήψιος ἐκ τοῦ Ὀρμενίου τὸν Φοίνικα εἶναι, καὶ φεύγειν αὐτὸν ἐνθένδε παρὰ τοῦ “πατρὸς Ἀμύντορος Ὀρμενίδαο” εἰς τὴν Φθίαν “ἐς Πηλῆα ἄνακτα.” ἐκτίσθαι γὰρ ὑπὸ Ὀρμένου τὸ χωρίον τοῦτο τοῦ Κερκάφου τοῦ Αἰόλου· παῖδας δὲ τοῦ Ὀρμένου γενέσθαι τόν τε Ἀμύντορα καὶ Εὐαίμονα, ὧν τοῦ μὲν εἶναι Φοίνικα τοῦ δ’ Εὐρύπυλον· φυλαχθῆναι δὲ τῷ Εὐρυπύλῳ τὴν διαδοχὴν κοινήν, ἅτε ἂν ἀπελθόντος τοῦ Φοίνικος ἐκ τῆς οἰκείας· καὶ δὴ καὶ γράφει οὕτως “οἷον ὅτε πρῶτον λίπον Ὀρμένιον πολύμηλον,” ἀντὶ τοῦ “λίπον Ἑλλάδα καλλιγύναικα.” Κράτης δὲ Φωκέα ποιεῖ τὸν Φοίνικα, τεκμαιρόμενος ἐκ τοῦ κράνους τοῦ Μέγητος ᾧ ἐχρήσατο ὁ Ὀδυσσεὺς κατὰ τὴν νυκτεγερσίαν, περὶ οὗ φησιν ὁ ποιητὴς ὅτι “ἐξ Ἐλεῶνος Ἀμύντορος Ὀρμενίδαο ἐξέλετ’ Αὐτόλυκος, πυκινὸν δόμον ἀντιτορήσας.” τόν τε γὰρ Ἐλεῶνα ἐν τῷ Παρνασσῷ πολίχνιον εἶναι, τόν τε Ὀρμενίδην Ἀμύντορα οὐκ ἄλλον τινὰ λέγεσθαι ἢ τὸν τοῦ Φοίνικος πατέρα, καὶ τὸν Αὐτόλυκον οἰκοῦντα ἐν τῷ Παρνασσῷ τοιχωρυχεῖν τὰ τῶν γειτόνων, ὅπερ κοινόν ἐστι τοιχωρύχου παντός, οὐ τὰ τῶν πόρρωθεν. ὁ δὲ Σκήψιός φησι μήτε Ἐλεῶνα μηδένα τόπον τοῦ Παρνασσοῦ δείκνυσθαι, ἀλλὰ Νεῶνα, καὶ ταύτην οἰκισθεῖσαν μετὰ τὰ Τρωικά, μήτ’ ἐκ γειτόνων τὰς τοιχωρυχίας γίνεσθαι μόνον. καὶ ἄλλα δ’ ἐστὶν ἃ λέγοι τις ἄν, ἀλλ’ οὖν ὀκνῶ διατρίβειν ἐπὶ πλέον. ἄλλοι δὲ γράφουσιν ἐξ Ἑλεῶνος· Ταναγρικὴ δέ ἐστιν αὕτη· καὶ μᾶλλον ἐλέγχοι ἀτόπως ἂν λεγόμενον τό “φεῦγον ἔπειτ’ ἀπάνευθε δι’ Ἑλλάδος, Φθίην δ’ ἐξικόμην.” ἡ δ’ Ὑπέρεια κρήνη ἐν μέσῃ ἐστὶ τῇ Φεραίων πόλει Εὐμήλου οὔσῃ· ἄτοπον τοίνυν [δοῦναι Εὐρυπύ]λῳ. Τίτανος δ’ ἀπὸ τοῦ συμβεβηκότος ὠνομάσθη· λευκόγεων γάρ ἐστι τὸ χωρίον Ἄρνης πλησίον καὶ [τῶν Ἀφε]τῶν· καὶ τὸ Ἀστέριον δ’ οὐκ ἄπωθεν τούτων ἐστί.", "st": "9.5.18"}, {"sp": "N", "t": "συνεχεῖς δὲ τῇ μερίδι ταύτῃ λέγονται οἱ ὑπὸ τῷ Πολυποίτῃ “οἳ δ’ Ἄργισσαν ἔχον καὶ Γυρτώνην ἐνέμοντο, Ὄρθην Ἠλώνην τε πόλιν τ’ Ὀλοοσσόνα λευκήν.” ταύτην τὴν χώραν πρότερον μὲν ᾤκουν Περραιβοί, τὸ πρὸς θαλάττῃ μέρος νεμόμενοι καὶ τῷ Πηνειῷ μέχρι τῆς ἐκβολῆς αὐτοῦ καὶ Γυρτῶνος πόλεως Περραιβίδος. εἶτα ταπεινώσαντες ἐκείνους Λαπίθαι κατέσχον αὐτοὶ τὰ χωρία, Ἰξίων καὶ ὁ υἱὸς Πειρίθους, ὃς καὶ τὸ Πήλιον κατεκτήσατο βιασάμενος τοὺς κατασχόντας Κενταύρους, ἄγριόν τι φῦλον. τούτους μὲν οὖν “ἐκ Πηλίου ὦσε καὶ Αἰθίκεσσι πέλασσε,” τοῖς δὲ Λαπίθαις τὰ πεδία παρέδωκε· τινὰ δ’ αὐτῶν καὶ οἱ Περραιβοὶ κατεῖχον, τὰ πρὸς τῷ Ὀλύμπῳ· ἔστι δ’ ὅπου καὶ ὅλοι ἀναμὶξ τοῖς Λαπίθαις ᾤκουν. ἡ μὲν οὖν Ἄργισσα, ἡ νῦν Ἄργουρα, ἐπὶ τῷ Πηνειῷ κεῖται· ὑπέρκειται δ’ αὐτῆς Ἄτραξ ἐν τετταράκοντα σταδίοις, τῷ ποταμῷ πλησιάζουσα καὶ αὕτη· τὴν δ’ ἀνὰ μέσον ποταμίαν εἶχον Περραιβοί. Ὄρθην δὲ τινὲς τὴν ἀκρόπολιν τῶν Φαλανναίων εἰρήκασιν· ἡ δὲ Φάλαννα Περραιβικὴ πόλις πρὸς τῷ Πηνειῷ πλησίον τῶν Τεμπῶν. οἱ μὲν οὖν Περραιβοὶ καταδυναστευθέντες ὑπὸ τῶν Λαπιθῶν εἰς τὴν ὀρεινὴν ἀπανέστησαν οἱ πλείους τὴν περὶ Πίνδον καὶ Ἀθαμᾶνας καὶ Δόλοπας, τὴν δὲ χώραν καὶ τοὺς ὑπολειφθέντας τῶν Περραιβῶν κατέσχον Λαρισαῖοι, πλησίον μὲν οἰκοῦντες τοῦ Πηνειοῦ, γειτνιῶντες δ’ ἐκείνοις, νεμόμενοι δὲ τὰ εὐδαιμονέστατα μέρη τῶν πεδίων, πλὴν εἴ τι σφόδρα κοῖλον πρὸς τῇ λίμνῃ τῇ Νεσσωνίδι, εἰς ἣν ὑπερκλύζων ὁ ποταμὸς ἀφῃρεῖτό τι τῆς ἀροσίμου τοὺς Λαρισαίους· ἀλλ’ ὕστερον παραχώμασιν ἐπηνώρθωσαν Λαρισαῖοι. οὗτοι δ’ οὖν κατεῖχον τέως τὴν Περραιβίαν καὶ φόρους ἐπράττοντο, ἕως Φίλιππος κατέστη κύριος τῶν τόπων. Λάρισα δ’ ἐστὶ καὶ ἐν τῇ Ὄσσῃ χωρίον· καὶ ἡ Κρεμαστή, ὑπό τινων δὲ Πελασγία λεγομένη· καὶ ἐν τῇ Κρήτῃ πόλις ἡ νῦν εἰς Ἱεράπυτναν συνοικισθεῖσα, ἀφ’ ἧς καὶ τὸ ὑποκείμενον πεδίον νῦν Λαρίσιον καλεῖται· καὶ ἐν Πελοποννήσῳ ἥ τε τῶν Ἀργείων ἄκρα καὶ ὁ τὴν Ἠλείαν ἀπὸ Δύμης διορίζων Λάρισος ποταμός. Θεόπομπος δὲ καὶ πόλιν λέγει ἐν τῇ αὐτῇ μεθορίᾳ κειμένην Λάρισαν· καὶ ἐν τῇ Ἀσίᾳ ἥ τε Φρικωνὶς ἡ περὶ τὴν Κύμην καὶ ἡ κατὰ Ἁμαξιτὸν τῆς Τρῳάδος· καὶ ἡ Ἐφεσία Λάρισά ἐστι καὶ ἐν Συρίᾳ· τῆς δὲ Μιτυλήνης ἀπὸ πεντήκοντα σταδίων εἰσὶ Λαρισαῖαι πέτραι κατὰ τὴν ἐπὶ Μηθύμνης ὁδόν· καὶ ἐν τῇ Ἀττικῇ δ’ ἐστὶ Λάρισα· καὶ τῶν Τράλλεων διέχουσα κώμη τριάκοντα σταδίους ὑπὲρ τῆς πόλεως ἐπὶ Καΰστρου πεδίον διὰ τῆς Μεσωγίδος ἰόντων κατὰ τὸ τῆς Ἰσοδρόμης Μητρὸς ἱερόν, ὁμοίαν τὴν θέσιν καὶ τὴν ἀρετὴν ἔχουσα τῇ Κρεμαστῇ Λαρίσῃ· καὶ γὰρ εὔυδρος καὶ ἀμπελόφυτος· ἴσως δὲ καὶ ὁ Λαρίσιος Ζεὺς ἐκεῖθεν ἐπωνόμασται· καὶ ἐν τοῖς ἀριστεροῖς δὲ τοῦ Πόντου κώμη τις καλεῖται Λάρισα μεταξὺ Ναυλό[χου καὶ Ὀδησσοῦ] πλησίον τῶν ἄκρων τοῦ Αἵμου. καὶ Ὀλοσσὼν δὲ λευκὴ προσαγορευθεῖσα ἀπὸ τοῦ λευκάργιλος εἶναι, καὶ Ἠλώνη Περραιβικαὶ πόλεις, καὶ Γόννος. ἡ δ’ Ἠλώνη μετέβαλε τοὔνομα Λειμώνη μετονομασθεῖσα· κατέσκαπται δὲ νῦν· ἄμφω δ’ ὑπὸ τῷ Ὀλύμπῳ κεῖνται οὐ πολὺ ἄπωθεν τοῦ Εὐρώπου ποταμοῦ, ὃν ὁ ποιητὴς Τιταρήσιον καλεῖ.", "st": "9.5.19"}, {"sp": "N", "t": "λέγει δὲ καὶ περὶ τούτου καὶ περὶ τῶν Περραιβῶν ἐν τοῖς ἑξῆς ὁ ποιητὴς ὅταν φῇ “Γουνεὺς δ’ ἐκ Κύφου ἦγε δύω καὶ εἴκοσι νῆας. τῷ δ’ Ἐνιῆνες ἕποντο μενεπτόλεμοί τε Περαιβοί, οἳ περὶ Δωδώνην δυσχείμερον οἰκί’ ἔθεντο, [οἵ τ’] ἀμφ’ ἱμερτὸν Τιταρήσιον ἔργ’ ἐνέμοντο.” λέγει μὲν οὖν τούτους τοὺς τόπους τῶν Περραιβῶν, ἀπὸ μέρους τῆς Ἑστιαιώτιδος ἐπειληφότας· ἦσαν δὲ καὶ ὑπὸ τῷ Πολυποίτῃ ἐκ μέρους Περραιβικαί, τοῖς μέντοι Λαπίθαις προσένειμε διὰ τὸ ἀναμὶξ οἰκεῖν καὶ τὰ μὲν πεδία κατέχειν τοὺς Λαπίθας καὶ τὸ ἐνταῦθα Περραιβικὸν ὑπὸ τούτοις τετάχθαι ὡς ἐπὶ πλέον, τὰ δ’ ὀρεινότερα χωρία πρὸς τῷ Ὀλύμπῳ καὶ τοῖς Τέμπεσι τοὺς Περραιβούς, καθάπερ τὸν Κύφον καὶ τὴν Δωδώνην καὶ τὰ περὶ τὸν Τιταρήσιον, ὃς ἐξ ὄρους Τιταρίου συμφυοῦς τῷ Ὀλύμπῳ ῥέων εἰς τὰ πλησίον τῶν Τεμπῶν χωρία τῆς Περραιβίας αὐτοῦ που τὰς συμβολὰς ποιεῖται πρὸς τὸν Πηνειόν. τὸ μὲν οὖν τοῦ Πηνειοῦ καθαρόν ἐστιν ὕδωρ, τὸ δὲ τοῦ Τιταρησίου λιπαρὸν ἔκ τινος ὕλης ὥστ’ οὐ συμμίσγεται “ἀλλά τέ μιν καθύπερθεν ἐπιτρέχει ἠύτ’ ἔλαιον.” διὰ δὲ τὸ ἀναμὶξ οἰκεῖν Σιμωνίδης Περραιβοὺς καὶ Λαπίθας καλεῖ τοὺς Πελασγιώτας ἅπαντας, τοὺς τὰ ἑῷα κατέχοντας τὰ περὶ Γυρτῶνα καὶ τὰς ἐκβολὰς τοῦ Πηνειοῦ καὶ Ὄσσαν καὶ Πήλιον καὶ τὰ περὶ Δημητριάδα καὶ τὰ ἐν τῷ πεδίῳ, Λάρισαν Κραννῶνα Σκοτοῦσσαν Μόψιον Ἄτρακα, καὶ τὰ περὶ τὴν Νεσσωνίδα λίμνην καὶ [τὴν] Βοιβηίδα· ὧν ὁ ποιητὴς ὀλίγων μέμνηται διὰ τὸ μὴ οἰκισθῆναί πω τἆλλα ἢ φαύλως οἰκισθῆναι διὰ τοὺς κατακλυσμοὺς ἄλλοτ’ ἄλλους γινομένους· ἐπεὶ οὐδὲ τῆς Νεσσωνίδος μέμνηται λίμνης, ἀλλὰ τῆς Βοιβηίδος μόνον πολὺ ἐλάττονος οὔσης, ταύτης δὲ μόνης μενούσης, ἐκείνης δὲ ὡς εἰκὸς τοτὲ μὲν πληρουμένης ἀτάκτως, τοτὲ δ’ ἐκλειπομένης. τῆς δὲ Σκοτούσσης ἐμνήσθημεν καὶ ἐν τοῖς περὶ Δωδώνης λόγοις καὶ τοῦ μαντείου τοῦ ἐν Θετταλίᾳ, διότι περὶ τοῦτον ὑπῆρξε τὸν τόπον. ἔστι δ’ ἐν τῇ Σκοτούσσῃ χωρίον τι Κυνὸς κεφαλαὶ καλούμενον, περὶ ὃ Ῥωμαῖοι μετ’ Αἰτωλῶν καὶ Τίτος Κοΐντιος ἐνίκων μάχῃ μεγάλῃ Φίλιππον τὸν Δημητρίου, Μακεδόνων βασιλέα.", "st": "9.5.20"}, {"sp": "N", "t": "πέπονθε δέ τι τοιοῦτο καὶ ἡ Μαγνῆτις· κατηριθμημένων γὰρ ἤδη πολλῶν αὐτῆς τόπων οὐδένας τούτων ὠνόμακε Μάγνητας Ὅμηρος, ἀλλ’ ἐκείνους μόνους οὓς τυφλῶς καὶ οὐ γνωρίμως διασαφεῖ “οἳ περὶ Πηνειὸν καὶ Πήλιον εἰνοσίφυλλον ναίεσκον.” ἀλλὰ μὴν περὶ τὸν Πηνειὸν καὶ τὸ Πήλιον οἰκοῦσι καὶ οἱ τὴν Γυρτῶνα ἔχοντες, οὓς ἤδη κατέλεξε, καὶ τὸ Ὀρμένιον καὶ ἄλλοι πλείους, καὶ ἔτι ἀπωτέρω τοῦ Πηλίου ὅμως Μάγνητες ἦσαν ἀρξάμενοι ἀπὸ τῶν ὑπ’ Εὐμήλῳ, κατά γε τοὺς ὕστερον ἀνθρώπους. ἐοίκασιν οὖν διὰ τὰς συνεχεῖς μεταστάσεις καὶ ἐξαλλάξεις τῶν πολιτειῶν καὶ ἐπιμίξεις συγχεῖν καὶ τὰ ὀνόματα καὶ τὰ ἔθνη, ὥστε τοῖς νῦν ἔσθ’ ὅτε ἀπορίαν παρέχειν, καθάπερ τοῦτο τὸ πρῶτον μὲν ἐπὶ Κραννῶνος καὶ τῆς Γυρτῶνος γεγένηται. τοὺς μὲν γὰρ Γυρτωνίους Φλεγύας πρότερον ἐκάλουν ἀπὸ Φλεγύου τοῦ Ἰξίονος ἀδελφοῦ, τοὺς δὲ Κραννωνίους Ἐφύρους, ὥστε διαπορεῖν, ὅταν φῇ ὁ ποιητής “τὼ μὲν ἄρ’ ἐκ Θρῄκης Ἐφύρους μέτα θωρήσσοντο ἠὲ μετὰ Φλεγύας μεγαλήτορας,” τίνας ποτὲ βούλεται λέγειν·", "st": "9.5.21"}, {"sp": "N", "t": "ἔπειτα τοῦτο καὶ ἐπὶ τῶν Περραιβῶν καὶ τῶν Αἰνιάνων συνέβη· Ὅμηρος μὲν γὰρ συνέζευξεν αὐτοὺς ὡς πλησίον ἀλλήλων οἰκοῦντας· καὶ δὴ καὶ λέγεται ὑπὸ τῶν ὕστερον ἐπὶ χρόνον συχνὸν ἡ οἴκησις τῶν Αἰνιάνων ἐν τῷ Δωτίῳ γενέσθαι πεδίῳ, τοῦτο δ’ ἐστὶ πλησίον τῆς ἄρτι λεχθείσης Περραιβίας καὶ τῆς Ὄσσης καὶ ἔτι τῆς Βοιβηίδος λίμνης, ἐν μέσῃ μέν πως τῇ Θετταλίᾳ λόφοις δὲ ἰδίοις περικλειόμενον, περὶ οὗ Ἡσίοδος οὕτως εἴρηκεν ἢ οἵη Διδύμους ἱεροὺς ναίουσα κολωνοὺς Δωτίῳ ἐν πεδίῳ, πολυβότρυος ἄντ’ Ἀμύροιο, νίψατο Βοιβιάδος λίμνης πόδα παρθένος ἀδμής. οἱ μὲν οὖν Αἰνιᾶνες οἱ πλείους εἰς τὴν Οἴτην ἐξηλάθησαν ὑπὸ τῶν Λαπιθῶν, κἀνταῦθα δὲ ἐδυνάστευσαν ἀφελόμενοι τῶν τε Δωριέων τινὰ μέρη καὶ τῶν Μαλιέων μέχρι Ἡρακλείας καὶ Ἐχίνου, τινὲς δ’ αὐτῶν ἔμειναν περὶ Κύφον, Περραιβικὸν ὄρος ὁμώνυμον κατοικίαν ἔχον. οἱ δὲ Περραιβοὶ τινὲς μὲν συσταλέντες περὶ τὰ ἑσπέρια τοῦ Ὀλύμπου μέρη κατέμενον αὐτόθι πρόσχωροι ὄντες Μακεδόσι, τὸ δὲ πολὺ μέρος εἰς τὰ περὶ τὴν Ἀθαμανίαν ὄρη καὶ τὴν Πίνδον ἐξέπεσε· νυνὶ δὲ μικρὸν ἢ οὐδὲν αὐτῶν ἴχνος σώζεται. τοὺς δ’ οὖν ὑπὸ τοῦ ποιητοῦ λεχθέντας Μάγνητας ὑστάτους ἐν τῷ Θετταλικῷ καταλόγῳ νομιστέον τοὺς ἐντὸς τῶν Τεμπῶν ἀπὸ τοῦ Πηνειοῦ καὶ τῆς Ὄσσης ἕως Πηλίου, Μακεδόνων τοῖς Πιεριώταις ὁμόρους τοῖς ἔχουσι τὴν τοῦ Πηνειοῦ περαίαν μέχρι τῆς θαλάττης. τὸ μὲν οὖν Ὁμόλιον ἢ τὴν Ὁμόλην (λέγεται γὰρ ἀμφοτέρως) ἀποδοτέον αὐτοῖς· εἴρηται δ’ ἐν τοῖς Μακεδονικοῖς ὅτι ἐστὶ πρὸς τῇ Ὄσσῃ κατὰ τὴν ἀρχὴν τῆς τοῦ Πηνειοῦ διὰ τῶν Τεμπῶν διεκβολῆς. εἰ δὲ καὶ μέχρι τῆς παραλίας προϊτέον τῆς ἐγγυτάτω τοῦ Ὁμολίου, λόγον ἔχει ὥστε [καὶ] τὸν Ῥιζοῦντα προσνέμειν καὶ Ἐρυμνὰς ἐν τῇ ὑπὸ Φιλοκτήτῃ παραλίᾳ κειμένας καὶ τῇ ὑπὸ Εὐμήλῳ. τοῦτο μὲν οὖν ἐν ἀσαφεῖ κείσθω. καὶ ἡ τάξις δὲ τῶν ἐφεξῆς τόπων μέχρι Πηνειοῦ οὐ διαφανῶς λέγεται, ἀδόξων δ’ ὄντων τῶν τόπων οὐδ’ ἡμῖν περὶ πολλοῦ θετέον. ἡ μέντοι Σηπιὰς ἀκτὴ καὶ τετραγῴδηται μετὰ ταῦτα καὶ ἐξύμνηται διὰ τὸν ἐνταῦθα ἀφανισμὸν τοῦ Περσικοῦ στόλου· ἔστι δ’ αὕτη μὲν ἀκτὴ πετρώδης, μεταξὺ δ’ αὐτῆς καὶ Κασθαναίας κώμης ὑπὸ τῷ Πηλίῳ κειμένης αἰγιαλός ἐστιν, ἐν ᾧ ὁ Ξέρξου στόλος ναυλοχῶν ἀπηλιώτου πολλοῦ πνεύσαντος ὁ μὲν εὐθὺς αὐτοῦ πρὸς τὸ ξηρὸν ἐξώκειλε καὶ διελύθη παραχρῆμα, ὁ δ’ εἰς Ἰπνοὺς τόπον τραχὺν τῶν περὶ τὸ Πήλιον παρενεχθεὶς ὁ δ’ εἰς Μελίβοιαν ὁ δ’ εἰς τὴν Κασθαναίαν διεφθάρη. τραχὺς δ’ ἐστὶν ὁ παράπλους πᾶς ὁ τοῦ Πηλίου ὅσον σταδίων ὀγδοήκοντα· τοσοῦτος δ’ ἐστὶ καὶ τοιοῦτος καὶ ὁ τῆς Ὄσσης. μεταξὺ δὲ κόλπος σταδίων πλειόνων ἢ διακοσίων, ἐν ᾧ ἡ Μελίβοια. ὁ δὲ πᾶς ἀπὸ Δημητριάδος ἐγκολπίζοντι ἐπὶ τὸν Πηνειὸν μείζων τῶν χιλίων, [ἀπὸ δὲ Σπε]ρχειοῦ καὶ ἄλλων ὀκτακοσίων, ἀπὸ δὲ Εὐρίπου δισχιλίων τριακοσίων πεντήκοντα. Ἱερώνυμος δὲ τῆς πεδιάδος Θετταλίας καὶ Μαγνήτιδος τὸν κύκλον τρισχιλίων ἀποφαίνεται σταδίων, ᾠκῆσθαι δ’ ὑπὸ Πελασγῶν, ἐξελαθῆναι δὲ τούτους εἰς τὴν Ἰταλίαν ὑπὸ Λαπιθῶν· εἶναι δὲ τὸ νῦν καλούμενον Πελασγικὸν πεδίον, ἐν [ᾧ] Λάρισα καὶ Γυρτώνη καὶ Φεραὶ καὶ Μόψιον καὶ Βοιβηὶς καὶ Ὄσσα καὶ Ὁμόλη καὶ Πήλιον καὶ Μαγνῆτις· Μόψιον δ’ ὠνόμασται οὐκ ἀπὸ Μόψου τοῦ Μαντοῦς τῆς Τειρεσίου, ἀλλ’ ἀπὸ τοῦ Λαπίθου τοῦ συμπλεύσαντος τοῖς Ἀργοναύταις· ἄλλος δ’ ἐστὶ Μόψοπος, ἀφ’ οὗ ἡ Ἀττικὴ Μοψοπία.", "st": "9.5.22"}, {"sp": "N", "t": "τὰ καθ’ ἕκαστα μὲν ταῦτα περὶ Θετταλίας, καθ’ ὅλου δ’ ὅτι Πυρραία πρότερον ἐκαλεῖτο ἀπὸ Πύρρας τῆς Δευκαλίωνος γυναικός, Αἱμονία δὲ ἀπὸ Αἵμονος, Θετταλία δὲ ἀπὸ Θετταλοῦ τοῦ Αἵμονος. ἔνιοι δὲ διελόντες δίχα τὴν μὲν πρὸς νότον λαχεῖν φασι Δευκαλίωνι καὶ καλέσαι Πανδώραν ἀπὸ τῆς μητρός, τὴν δ’ ἑτέραν Αἵμονι, ἀφ’ οὗ Αἱμονίαν λεχθῆναι· μετωνομάσθαι δὲ τὴν μὲν Ἑλλάδα ἀπὸ Ἕλληνος τοῦ Δευκαλίωνος, τὴν δὲ Θετταλίαν ἀπὸ τοῦ υἱοῦ Αἵμονος· τινὲς δὲ ἀπὸ Ἐφύρας τῆς Θεσπρωτίδος ἀπογόνους Ἀντίφου καὶ Φειδίππου, τῶν Θετταλοῦ τοῦ Ἡρακλέους, ἐπελθόντας ἀπὸ Θετταλοῦ τοῦ ἑαυτῶν προγόνου τὴν χώραν ὀνομάσαι. εἴρ[ηται] δὲ καὶ Νεσσωνὶς ὀνομασθῆναί ποτε ἀπὸ Νέσσωνος τοῦ Θετταλοῦ, καθάπερ καὶ ἡ λίμνη.", "st": "9.5.23"}, {"sp": "HDR", "t": "Βιβλίον Ιʹ", "st": "10"}, {"sp": "N", "t": "ἐπεὶ δὲ ἡ Εὔβοια παρὰ πᾶσαν τὴν παραλίαν ταύτην παραβέβληται τὴν ἀπὸ Σουνίου μέχρι Θετταλίας, πλὴν τῶν ἄκρων ἑκατέρωθεν, οἰκεῖον ἂν εἴη συνάψαι τοῖς εἰρημένοις τὰ περὶ τὴν νῆσον, εἶθ’ οὕτω μεταβῆναι πρός τε τὰ Αἰτωλικὰ καὶ τὰ Ἀκαρνανικά, ἅπερ λοιπά ἐστι τῶν τῆς Εὐρώπης μερῶν.", "st": "10.1.1"}, {"sp": "N", "t": "παραμήκης μὲν τοίνυν ἐστὶν ἡ νῆσος ἐπὶ χιλίους σχεδόν τι καὶ διακοσίους σταδίους ἀπὸ Κηναίου πρὸς Γεραιστόν, τὸ δὲ πλάτος ἀνώμαλος, κατὰ δὲ τὸ πλέον ὅσον πεντήκοντα καὶ ἑκατὸν σταδίων. τὸ μὲν οὖν Κήναιον ἔστι κατὰ Θερμοπύλας καὶ τὰ ἔξω Θερμοπυλῶν ἐπ’ ὀλίγον, Γεραιστὸς δὲ καὶ Πεταλία πρὸς Σουνίῳ. γίνεται οὖν ἀντίπορθμος τῇ τε Ἀττικῇ καὶ Βοιωτίᾳ καὶ Λοκρίδι καὶ τοῖς Μαλιεῦσι. διὰ δὲ τὴν στενότητα καὶ τὸ λεχθὲν μῆκος ὑπὸ τῶν παλαιῶν Μάκρις ὠνομάσθη. συνάπτει δὲ τῇ ἠπείρῳ κατὰ Χαλκίδα μάλιστα, κυρτὴ προπίπτουσα πρὸς τοὺς κατὰ τὴν Αὐλίδα τόπους τῆς Βοιωτίας καὶ ποιοῦσα τὸν Εὔριπον, περὶ οὗ διὰ πλειόνων εἰρήκαμεν, σχεδὸν δέ τι καὶ περὶ τῶν ἀντιπόρθμων ἀλλήλοις τόπων κατά τε τὴν ἤπειρον καὶ κατὰ τὴν νῆσον ἐφ’ ἑκάτερα τοῦ Εὐρίπου, τά τε ἐντὸς καὶ τὰ ἐκτός. εἰ δέ τι ἐλλέλειπται, νῦν προσδιασαφήσομεν. καὶ πρῶτον, ὅτι τῆς Εὐβοίας τὰ Κοῖλα λέγουσι τὰ μεταξὺ Αὐλίδος καὶ τῶν περὶ Γεραιστὸν τόπων· κολποῦται γὰρ ἡ παραλία, πλησιάζουσα δὲ τῇ Χαλκίδι κυρτοῦται πάλιν πρὸς τὴν ἤπειρον.", "st": "10.1.2"}, {"sp": "N", "t": "οὐ μόνον δὲ Μάκρις ἐκλήθη ἡ νῆσος, ἀλλὰ καὶ Ἀβαντίς. Εὔβοιαν γοῦν εἰπὼν ὁ ποιητὴς τοὺς ἀπ’ αὐτῆς Εὐβοέας οὐδέποτε εἴρηκεν, ἀλλ’ Ἄβαντας ἀεί<br>οἳ δ’ Εὔβοιαν ἔχον μένεα πνείοντες Ἄβαντες.<br>τῷ δ’ ἅμ’ Ἄβαντες ἕποντο.<br>φησὶ δ’ Ἀριστοτέλης ἐξ Ἄβας τῆς Φωκικῆς Θρᾷκας ὁρμηθέντας ἐποικῆσαι τὴν νῆσον καὶ ἐπονομάσαι Ἄβαντας τοὺς ἔχοντας αὐτήν· οἱ δ’ ἀπὸ ἥρωός φασι, καθάπερ καὶ Εὔβοιαν ἀπὸ ἡρωίνης. τάχα δ’ ὥσπερ βοὸς αὐλὴ λέγεταί τι ἄντρον ἐν τῇ πρὸς [τὸν] Αἰγαῖον τετραμμένῃ παραλίᾳ, ὅπου τὴν Ἰώ φασι τεκεῖν Ἔπαφον, καὶ ἡ νῆσος ἀπὸ τῆς αὐτῆς αἰτίας ἔσχε τοῦτο τοὔνομα. καὶ Ὄχη δὲ ἐκαλεῖτο ἡ νῆσος, καὶ ἔστιν ὁμώνυμον αὐτῇ τὸ μέγιστον τῶν ἐνταῦθα ὀρῶν. καὶ Ἐλλοπία δ’ ὠνομάσθη ἀπὸ Ἔλλοπος τοῦ Ἴωνος· οἱ δὲ Ἀίκλου καὶ Κόθου ἀδελφόν φασιν, ὃς καὶ τὴν Ἐλλοπίαν κτίσαι λέγεται, χωρίον ἐν τῇ Ὠρείᾳ καλουμένῃ τῆς Ἱστιαιώτιδος πρὸς τῷ Τελεθρίῳ ὄρει, καὶ τὴν Ἱστίαιαν προσκτήσασθαι καὶ τὴν πεδιάδα καὶ Κήρινθον καὶ Αἰδηψὸν καὶ Ὀροβίας, ἐν ᾧ μαντεῖον ἦν ἀψευδέστατον· ἦν δὲ μαντεῖον τοῦ Σελινουντίου Ἀπόλλωνος· μετῴκησαν δ’ εἰς τὴν Ἱστίαιαν οἱ Ἐλλοπιεῖς, καὶ ηὔξησαν τὴν πόλιν Φιλιστίδου τοῦ τυράννου βιασαμένου μετὰ τὰ Λευκτρικά. Δημοσθένης δ’ ὑπὸ Φιλίππου κατασταθῆναι τύραννόν φησι καὶ τῶν Ὠρειτῶν τὸν Φιλιστίδην· οὕτω γὰρ ὠνομάσθησαν ὕστερον οἱ Ἱστιαιεῖς, καὶ ἡ πόλις ἀντὶ Ἱστιαίας Ὠρεός· ἔνιοι δ’ ὑπ’ Ἀθηναίων ἀποικισθῆναί φασι τὴν Ἱστίαιαν ἀπὸ τοῦ δήμου τοῦ Ἱστιαιέων, ὡς καὶ ἀπὸ τοῦ Ἐρετριέων τὴν Ἐρέτριαν. Θεόπομπος δέ φησι Περικλέους χειρουμένου Εὔβοιαν τοὺς Ἱστιαιεῖς καθ’ ὁμολογίας εἰς Μακεδονίαν μεταστῆναι, δισχιλίους δ’ ἐξ Ἀθηναίων ἐλθόντας τὸν Ὠρεὸν οἰκῆσαι, δῆμον ὄντα πρότερον τῶν Ἱστιαιέων.", "st": "10.1.3"}, {"sp": "N", "t": "κεῖται δ’ ὑπὸ τῷ Τελεθρίῳ ὄρει ἐν τῷ Δρυμῷ καλουμένῳ παρὰ τὸν Κάλλαντα ποταμὸν ἐπὶ πέτρας ὑψηλῆς, ὥστε τάχα καὶ διὰ τὸ τοὺς Ἐλλοπιεῖς ὀρείους εἶναι τοὺς προοικήσαντας ἐτέθη τοὔνομα τοῦτο τῇ πόλει· δοκεῖ δὲ καὶ ὁ Ὠρίων ἐνταῦθα τραφεὶς οὕτως ὀνομασθῆναι· ἔνιοι δὲ τοὺς Ὠρείτας πόλιν ἔχοντας ἰδίαν φασὶ πολεμουμένους ὑπὸ τῶν Ἐλλοπιέων μεταβῆναι καὶ συνοικῆσαι τοῖς Ἱστιαιεῦσι, μίαν δὲ γενηθεῖσαν πόλιν ἀμφοτέροις χρήσασθαι τοῖς ὀνόμασι, καθάπερ Λακεδαίμων τε καὶ Σπάρτη ἡ αὐτή. εἴρηται δ’ ὅτι καὶ ἐν Θετταλίᾳ Ἱστιαιῶτις ἀπὸ τῶν ἀνασπασθέντων ἐνθένδε ὑπὸ Περραιβῶν ὠνόμασται.", "st": "10.1.4"}, {"sp": "N", "t": "ἐπεὶ δ’ ἡ Ἐλλοπία τὴν ἀρχὴν ἀπὸ τῆς Ἱστιαίας καὶ τοῦ Ὠρεοῦ προσηγάγετο ἡμᾶς ποιήσασθαι, τὰ συνεχῆ λέγωμεν τοῖς τόποις τούτοις. ἔστι δ’ ἐν τῷ Ὠρεῷ τούτῳ τό τε Κήναιον πλησίον καὶ ἐπ’ αὐτῷ τὸ Δῖον καὶ Ἀθῆναι αἱ Διάδες, κτίσμα Ἀθηναίων, ὑπερκείμενον τοῦ ἐπὶ Κῦνον πορθμοῦ· ἐκ δὲ τοῦ Δίου Κάναι τῆς Αἰολίδος ἀπῳκίσθησαν· ταῦτά τε δὴ τὰ χωρία περὶ τὴν Ἱστίαιάν ἐστι καὶ ἔτι Κήρινθος πολείδιον ἐπὶ τῇ θαλάττῃ· ἐγγὺς δὲ Βούδορος ποταμὸς ὁμώνυμος τῷ κατὰ τὴν Σαλαμῖνα ὄρει τῷ πρὸς τῇ Ἀττικῇ.", "st": "10.1.5"}, {"sp": "N", "t": "Κάρυστος δέ ἐστιν ὑπὸ τῷ ὄρει τῇ Ὄχῃ· πλησίον δὲ τὰ Στύρα καὶ τὸ Μαρμάριον, ἐν ᾧ τὸ λατόμιον τῶν Καρυστίων κιόνων, ἱερὸν ἔχον Ἀπόλλωνος Μαρμαρίνου, ὅθεν διάπλους εἰς Ἁλὰς τὰς Ἀραφηνίδας. ἐν δὲ τῇ Καρύστῳ καὶ ἡ λίθος φύεται ἡ ξαινομένη καὶ ὑφαινομένη, ὥστε τὰ ὕφη χειρόμακτρα γίνεσθαι, ῥυπωθέντα δ’ εἰς φλόγα βάλλεσθαι καὶ ἀποκαθαίρεσθαι τῇ πλύσει τῶν λίνων παραπλησίως· ᾠκίσθαι δὲ τὰ χωρία ταῦτά φασιν ὑπὸ τῶν ἐκ τετραπόλεως τῆς περὶ Μαραθῶνα καὶ Στειριέων· κατεστράφη δὲ τὰ Στύρα ἐν τῷ Λαμιακῷ πολέμῳ ὑπὸ Φαίδρου τοῦ Ἀθηναίων στρατηγοῦ· τὴν δὲ χώραν ἔχουσιν Ἐρετριεῖς. Κάρυστος δέ ἐστι καὶ ἐν τῇ Λακωνικῇ τόπος τῆς Αἴγυος πρὸς Ἀρκαδίαν, ἀφ’ οὗ Καρύστιον οἶνον Ἀλκμὰν εἴρηκε.", "st": "10.1.6"}, {"sp": "N", "t": "Γεραιστὸς δ’ ἐν μὲν τῷ καταλόγῳ τῶν νεῶν οὐκ εἴρηται, μέμνηται δ’ ὁ ποιητὴς ὅμως αὐτοῦ<br>ἐς δὲ Γεραιστὸν<br>ἐννύχιοι κατάγοντο,<br>καὶ δηλοῖ διότι τοῖς διαίρουσιν ἐκ τῆς Ἀσίας εἰς τὴν Ἀττικὴν ἐπικαιρίως κεῖται τῷ Σουνίῳ πλησιάζον τὸ χωρίον· ἔχει δ’ ἱερὸν Ποσειδῶνος ἐπισημότατον τῶν ταύτῃ καὶ κατοικίαν ἀξιόλογον.", "st": "10.1.7"}, {"sp": "N", "t": "μετὰ δὲ τὸν Γεραιστὸν Ἐρέτρια πόλις μεγίστη τῆς Εὐβοίας μετὰ Χαλκίδα, ἔπειθ’ ἡ Χαλκὶς μητρόπολις τῆς νήσου τρόπον τινά, ἐπ’ αὐτῷ τῷ Εὐρίπῳ ἱδρυμένη· ἀμφότεραι δὲ πρὸ τῶν Τρωικῶν ὑπ’ Ἀθηναίων ἐκτίσθαι λέγονται, καὶ μετὰ τὰ Τρωικὰ Ἄικλος καὶ Κόθος ἐξ Ἀθηνῶν ὁρμηθέντες ὁ μὲν τὴν Ἐρέτριαν ᾤκισε Κόθος δὲ τὴν Χαλκίδα· καὶ τῶν Αἰολέων δέ τινες ἀπὸ τῆς Πενθίλου στρατιᾶς κατέμειναν ἐν τῇ νήσῳ, τὸ δὲ παλαιὸν καὶ Ἄραβες οἱ Κάδμῳ συνδιαβάντες. αἱ δ’ οὖν πόλεις αὗται διαφερόντως αὐξηθεῖσαι καὶ ἀποικίας ἔστειλαν ἀξιολόγους εἰς Μακεδονίαν· Ἐρέτρια μὲν γὰρ συνῴκισε τὰς περὶ Παλλήνην καὶ τὸν Ἄθω πόλεις, ἡ δὲ Χαλκὶς τὰς ὑπὸ Ὀλύνθῳ, ἃς Φίλιππος διελυμήνατο. καὶ τῆς Ἰταλίας δὲ καὶ Σικελίας πολλὰ χωρία Χαλκιδέων ἐστίν· ἐστάλησαν δὲ αἱ ἀποικίαι αὗται, καθάπερ εἴρηκεν Ἀριστοτέλης, ἡνίκα ἡ τῶν Ἱπποβοτῶν καλουμένη ἐπεκράτει πολιτεία· προέστησαν γὰρ αὐτῆς ἀπὸ τιμημάτων ἄνδρες ἀριστοκρατικῶς ἄρχοντες. κατὰ δὲ τὴν Ἀλεξάνδρου διάβασιν καὶ τὸν περίβολον τῆς πόλεως ηὔξησαν, ἐντὸς τείχους λαβόντες τόν τε Κάνηθον καὶ τὸν Εὔριπον, ἐπιστήσαντες τῇ γεφύρᾳ πύργους καὶ πύλας καὶ τεῖχος.", "st": "10.1.8"}, {"sp": "N", "t": "ὑπέρκειται δὲ τῆς τῶν Χαλκιδέων πόλεως τὸ Λήλαντον καλούμενον πεδίον. ἐν δὲ τούτῳ θερμῶν τε ὑδάτων εἰσὶν ἐκβολαὶ πρὸς θεραπείαν νόσων εὐφυεῖς, οἷς ἐχρήσατο καὶ Σύλλας Κορνήλιος ὁ τῶν Ῥωμαίων ἡγεμών· καὶ μέταλλον δ’ ὑπῆρχε θαυμαστὸν χαλκοῦ καὶ σιδήρου κοινόν, ὅπερ οὐχ ἱστοροῦσιν ἀλλαχοῦ συμβαῖνον· νυνὶ μέντοι ἀμφότερα ἐκλέλοιπεν, [ὥσπερ καὶ Ἀθήνησι τἀργυρεῖα.] ἔστι δὲ καὶ ἅπασα μὲν ἡ Εὔβοια εὔσειστος, μάλιστα δ’ ἡ περὶ τὸν πορθμόν, καὶ δεχομένη πνευμάτων ὑποφοράς, καθάπερ καὶ ἡ Βοιωτία καὶ ἄλλοι τόποι, περὶ ὧν ἐμνήσθημεν διὰ πλειόνων πρότερον. ὑπὸ τοιοῦδε πάθους καὶ ἡ ὁμώνυμος τῇ νήσῳ πόλις καταποθῆναι λέγεται, ἧς μέμνηται καὶ Αἰσχύλος ἐν τῷ Ποντίῳ Γλαύκῳ<br>Εὐβοΐδα καμπτὴν ἀμφὶ Κηναίου Διὸς<br>ἀκτήν, κατ’ αὐτὸν τύμβον ἀθλίου Λίχα.<br>Χαλκὶς δ’ ὁμωνύμως λέγεται καὶ ἐν Αἰτωλίᾳ<br>Χαλκίδα τ’ ἀγχίαλον, Καλυδῶνά τε πετρήεσσαν,<br>καὶ ἐν τῇ νῦν Ἠλείᾳ<br>βὰν δὲ παρὰ Κρουνοὺς καὶ Χαλκίδα πετρήεσσαν<br>οἱ περὶ Τηλέμαχον ἀπιόντες παρὰ Νέστορος εἰς τὴν οἰκείαν.", "st": "10.1.9"}, {"sp": "N", "t": "Ἐρέτριαν δ’ οἱ μὲν ἀπὸ Μακίστου τῆς Τριφυλίας ἀποικισθῆναί φασιν ὑπ’ Ἐρετριέως, οἱ δ’ ἀπὸ τῆς Ἀθήνησιν Ἐρετρίας, ἣ νῦν ἐστὶν ἀγορά· ἔστι δὲ καὶ περὶ Φάρσαλον Ἐρέτρια, ἱερὰ τοῦ Ἀπόλλωνος. Ἀδμήτου δ’ ἵδρυμα λέγεται τὸ ἱερόν, παρ’ ᾧ θητεῦσαι λέγουσι τὸν θεὸν ἐνιαυτόν, πλησίον τοῦ πορθμοῦ. Μελανηὶς δ’ ἐκαλεῖτο πρότερον ἡ Ἐρέτρια καὶ Ἀρότρια· ταύτης δ’ ἐστὶ κώμη ἡ Ἀμάρυνθος ἀφ’ ἑπτὰ σταδίων τοῦ τείχους. τὴν μὲν οὖν ἀρχαίαν πόλιν κατέσκαψαν Πέρσαι, σαγηνεύσαντες, ὥς φησιν Ἡρόδοτος, τοὺς ἀνθρώπους τῷ πλήθει, περιχυθέντων τῶν βαρβάρων τῷ τείχει· καὶ δεικνύουσιν ἔτι τοὺς θεμελίους, καλοῦσι δὲ παλαιὰν Ἐρέτριαν, ἡ δὲ νῦν ἐπέκτισται. τὴν δὲ δύναμιν τὴν Ἐρετριέων ἣν ἔσχον ποτὲ μαρτυρεῖ ἡ στήλη, ἣν ἀνέθεσάν ποτε ἐν τῷ ἱερῷ τῆς Ἀμαρυνθίας Ἀρτέμιδος· γέγραπται δ’ ἐν αὐτῇ τρισχιλίοις μὲν ὁπλίταις ἑξακοσίοις δ’ ἱππεῦσιν ἑξήκοντα δ’ ἅρμασι ποιεῖν τὴν πομπήν· ἐπῆρχον δὲ καὶ Ἀνδρίων καὶ Τηνίων καὶ Κείων καὶ ἄλλων νήσων. ἐποίκους δ’ ἔσχον ἀπ’ Ἤλιδος, ἀφ’ οὗ καὶ τῷ γράμματι τῷ ῥῶ πολλῷ χρησάμενοι οὐκ ἐπὶ τέλει μόνον τῶν ῥημάτων ἀλλὰ καὶ ἐν μέσῳ κεκωμῴδηνται. ἔστι δὲ καὶ Οἰχαλία κώμη τῆς Ἐρετρικῆς, λείψανον τῆς ἀναιρεθείσης πόλεως ὑπὸ Ἡρακλέους, ὁμώνυμος τῇ Τραχινίᾳ καὶ τῇ περὶ Τρίκκην καὶ τῇ Ἀρκαδικῇ, ἣν Ἀνδανίαν οἱ ὕστερον ἐκάλεσαν, καὶ τῇ ἐν Αἰτωλίᾳ περὶ τοὺς Εὐρυτᾶνας.", "st": "10.1.10"}, {"sp": "N", "t": "νυνὶ μὲν οὖν ὁμολογουμένως ἡ Χαλκὶς φέρεται τὰ πρωτεῖα καὶ μητρόπολις αὕτη λέγεται τῶν Εὐβοέων, δευτερεύει δ’ ἡ Ἐρέτρια. ἀλλὰ καὶ πρότερον αὗται μέγα εἶχον ἀξίωμα καὶ πρὸς πόλεμον καὶ πρὸς εἰρήνην, ὥστε καὶ φιλοσόφοις ἀνδράσι παρασχεῖν διαγωγὴν ἡδεῖαν καὶ ἀθόρυβον. μαρτυρεῖ δ’ ἥ τε τῶν Ἐρετρικῶν φιλοσόφων σχολὴ τῶν περὶ Μενέδημον ἐν τῇ Ἐρετρίᾳ γενομένη, καὶ ἔτι πρότερον ἡ Ἀριστοτέλους ἐν τῇ Χαλκίδι διατριβή, ὅς γε κἀκεῖ κατέλυσε τὸν βίον.", "st": "10.1.11"}, {"sp": "N", "t": "τὸ μὲν οὖν πλέον ὡμολόγουν ἀλλήλαις αἱ πόλεις αὗται, περὶ δὲ Ληλάντου διενεχθεῖσαι … οὐδ’ οὕτω τελέως ἐπαύσαντο … ὥστ’ ἐν τῷ πολέμῳ κατὰ αὐθάδειαν δρᾶν ἕκαστα, ἀλλὰ συνέθεντο ἐφ’ οἷς συστήσονται τὸν ἀγῶνα. δηλοῖ δὲ καὶ τοῦτο ἐν τῷ Ἀμαρυνθίῳ στήλη τις φράζουσα μὴ χρῆσθαι τηλεβόλοις.", "st": "10.1.12"}, {"sp": "N", "t": "οἱ δ’ Εὐβοεῖς ἀγαθοὶ πρὸς μάχην ὑπῆρξαν τὴν σταδίαν, ἣ καὶ συστάδην λέγεται καὶ ἐκ χειρός. δόρασι δ’ ἐχρῶντο τοῖς ὀρεκτοῖς, ὥς φησιν ὁ ποιητής<br>αἰχμηταὶ μεμαῶτες ὀρεκτῇσι μελίῃσι<br>θώρηκας ῥήσσειν.<br>ἀλλοίων ἴσως ὄντων τῶν παλτῶν, οἵαν εἰκὸς εἶναι τὴν Πηλιάδα μελίην ἥν, ὥς φησιν ὁ ποιητής<br>οἶος ἐπίστατο πῆλαι Ἀχιλλεύς<br>καὶ ὁ εἰπών<br>δουρὶ δ’ ἀκοντίζω, ὅσον οὐκ ἄλλος τις ὀιστῷ,<br>τῷ παλτῷ λέγει δόρατι. καὶ οἱ μονομαχοῦντες τοῖς παλτοῖς χρώμενοι δόρασιν εἰσάγονται πρότερον, εἶτα ἐπὶ τὰ ξίφη βαδίζοντες· ἀγχέμαχοι δ’ εἰσὶν οὐχ οἱ ξίφει χρώμενοι μόνον, ἀλλὰ καὶ δόρατι ἐκ χειρός, ὥς φησιν<br>οὔτησε ξυστῷ χαλκήρεϊ, λῦσε δὲ γυῖα.<br>τοὺς μὲν οὖν Εὐβοέας τούτῳ τῷ τρόπῳ χρωμένους εἰσάγει, περὶ δὲ Λοκρῶν τἀναντία λέγει ὡς<br>οὔ σφιν σταδίης ὑσμίνης ἔργα μέμηλεν,<br>ἀλλ’ ἄρα τόξοισι καὶ ἐυστρόφῳ οἰὸς ἀώτῳ<br>Ἴλιον εἰς ἅμ’ ἕποντο.<br>περιφέρεται δὲ καὶ χρησμὸς ἐκδοθεὶς Αἰγιεῦσιν<br>ἵππον Θεσσαλικόν, Λακεδαιμονίαν δὲ γυναῖκα,<br>ἄνδρας θ’ οἳ πίνουσιν ὕδωρ ἱερῆς Ἀρεθούσης,<br>τοὺς Χαλκιδέας λέγων ὡς ἀρίστους· ἐκεῖ γὰρ ἡ Ἀρέθουσα.", "st": "10.1.13"}, {"sp": "N", "t": "εἰσὶ δὲ νῦν Εὐβοῗται ποταμοὶ Κηρεὺς καὶ Νηλεύς, ὧν ἀφ’ οὗ μὲν πίνοντα τὰ πρόβατα λευκὰ γίνεται, ἀφ’ οὗ δὲ μέλανα· καὶ περὶ τὸν Κρᾶθιν δὲ εἴρηται τοιοῦτόν τι συμβαῖνον.", "st": "10.1.14"}, {"sp": "N", "t": "τῶν δ’ ἐκ Τροίας ἐπανιόντων Εὐβοέων τινὲς εἰς Ἰλλυριοὺς ἐκπεσόντες, ἀποβαίνοντες οἴκαδε διὰ τῆς Μακεδονίας περὶ Ἔδεσσαν ἔμειναν συμπολεμήσαντες τοῖς ὑποδεξαμένοις, καὶ ἔκτισαν πόλιν Εὔβοιαν· ἦν δὲ καὶ ἐν Σικελίᾳ Εὔβοια Χαλκιδέων τῶν ἐκεῖ κτίσμα, ἣν Γέλων ἐξανέστησε, καὶ ἐγένετο φρούριον Συρακουσίων· καὶ ἐν Κερκύρᾳ δὲ καὶ ἐν Λήμνῳ τόπος ἦν Εὔβοια καὶ ἐν τῇ Ἀργείᾳ λόφος τις.", "st": "10.1.15"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῖς Θετταλοῖς καὶ Οἰταίοις πρὸς ἑσπέραν Αἰτωλοὶ καὶ Ἀκαρνᾶνές εἰσι καὶ Ἀθαμᾶνες, εἰ χρὴ καὶ τούτους Ἕλληνας εἰπεῖν, λοιπὸν ἐξηγήσασθαι περὶ τούτων, ἵν’ ἔχωμεν τὴν περίοδον ἅπασαν τὴν τῆς Ἑλλάδος· προσθεῖναι δὲ καὶ τὰς νήσους τὰς προσχώρους μάλιστα τῇ Ἑλλάδι καὶ οἰκουμένας ὑπὸ τῶν Ἑλλήνων ὅσας μὴ περιωδεύκαμεν.", "st": "10.1.16"}, {"sp": "N", "t": "Αἰτωλοὶ μὲν τοίνυν καὶ Ἀκαρνᾶνες ὁμοροῦσιν ἀλλήλοις, μέσον ἔχοντες τὸν Ἀχελῶον ποταμὸν ῥέοντα ἀπὸ τῶν ἄρκτων καὶ τῆς Πίνδου πρὸς νότον διά τε Ἀγραίων Αἰτωλικοῦ ἔθνους καὶ Ἀμφιλόχων, Ἀκαρνᾶνες μὲν τὸ πρὸς ἑσπέραν μέρος ἔχοντες τοῦ ποταμοῦ μέχρι τοῦ Ἀμβρακικοῦ κόλπου τοῦ κατὰ Ἀμφιλόχους καὶ τὸ ἱερὸν τοῦ Ἀκτίου Ἀπόλλωνος, Αἰτωλοὶ δὲ τὸ πρὸς ἕω μέχρι τῶν Ὀζολῶν Λοκρῶν καὶ τοῦ Παρνασσοῦ καὶ τῶν Οἰταίων. ὑπέρκεινται δ’ ἐν τῇ μεσογαίᾳ καὶ τοῖς προσβορείοις μέρεσι τῶν μὲν Ἀκαρνάνων Ἀμφίλοχοι, τούτων δὲ Δόλοπες καὶ ἡ Πίνδος, τῶν δ’ Αἰτωλῶν Περραιβοί τε καὶ Ἀθαμᾶνες καὶ Αἰνιάνων τι μέρος τῶν τὴν Οἴτην ἐχόντων· τὸ δὲ νότιον πλευρόν, τό τε Ἀκαρνανικὸν ὁμοίως καὶ τὸ Αἰτωλικόν, κλύζεται τῇ ποιούσῃ θαλάττῃ τὸν Κορινθιακὸν κόλπον, εἰς ὃν καὶ ὁ Ἀχελῶος ποταμὸς ἐξίησιν, ὁρίζων τὴν τῶν Αἰτωλῶν παραλίαν καὶ τὴν Ἀκαρνανικήν· ἐκαλεῖτο δὲ Θόας ὁ Ἀχελῶος πρότερον. ἔστι δὲ καὶ ὁ παρὰ Δύμην ὁμώνυμος τούτῳ, καθάπερ εἴρηται, καὶ ὁ περὶ Λάμιαν. εἴρηται δὲ καὶ ὅτι ἀρχὴν τοῦ Κορινθιακοῦ κόλπου τὸ στόμα τοῦδε τοῦ ποταμοῦ φασι.", "st": "10.2.1"}, {"sp": "N", "t": "πόλεις δ’ εἰσὶν ἐν μὲν τοῖς Ἀκαρνᾶσιν Ἀνακτόριόν τε ἐπὶ χερρονήσου ἱδρυμένον Ἀκτίου πλησίον, ἐμπόριον τῆς νῦν ἐκτισμένης ἐφ’ ἡμῶν Νικοπόλεως, καὶ Στράτος, ἀνάπλουν ἔχουσα τῷ Ἀχελώῳ πλειόνων ἢ διακοσίων σταδίων, καὶ Οἰνειάδαι, καὶ αὐτὴ ἐπὶ τῷ ποταμῷ, ἡ μὲν παλαιὰ οὐ κατοικουμένη, ἴσον ἀπέχουσα τῆς τε θαλάττης καὶ τοῦ Στράτου, ἡ δὲ νῦν ὅσον ἑβδομήκοντα σταδίους ὑπὲρ τῆς ἐκβολῆς διέχουσα· καὶ ἄλλαι δ’ εἰσί, Πάλαιρός τε καὶ Ἀλυζία καὶ Λευκὰς καὶ Ἄργος τὸ Ἀμφιλοχικὸν καὶ Ἀμβρακία, ὧν αἱ πλεῖσται περιοικίδες γεγόνασιν ἢ καὶ πᾶσαι τῆς Νικοπόλεως· κεῖται δ’ ὁ Στράτος κατὰ μέσην τὴν ἐξ Ἀλυζίας ὁδὸν εἰς Ἀνακτόριον.", "st": "10.2.2"}, {"sp": "N", "t": "Αἰτωλῶν δ’ εἰσὶ Καλυδών τε καὶ Πλευρών, νῦν μὲν τεταπεινωμέναι, τὸ δὲ παλαιὸν πρόσχημα τῆς Ἑλλάδος ἦν ταῦτα τὰ κτίσματα. καὶ δὴ καὶ διῃρῆσθαι συνέβαινε δίχα τὴν Αἰτωλίαν, καὶ τὴν μὲν ἀρχαίαν λέγεσθαι τὴν δ’ ἐπίκτητον· ἀρχαίαν μὲν τὴν ἀπὸ τοῦ Ἀχελώου μέχρι Καλυδῶνος παραλίαν ἐπὶ πολὺ καὶ τῆς μεσογαίας ἀνήκουσαν εὐκάρπου τε καὶ πεδιάδος, ᾗ ἐστὶ καὶ Στράτος καὶ τὸ Τριχώνιον ἀρίστην ἔχον γῆν· ἐπίκτητον δὲ τὴν τοῖς Λοκροῖς συνάπτουσαν ὡς ἐπὶ Ναύπακτόν τε καὶ Εὐπάλιον, τραχυτέραν τε οὖσαν καὶ λυπροτέραν, μέχρι τῆς Οἰταίας καὶ τῆς Ἀθαμάνων καὶ τῶν ἐφεξῆς ἐπὶ τὴν ἄρκτον ἤδη περιισταμένων ὀρῶν τε καὶ ἐθνῶν.", "st": "10.2.3"}, {"sp": "N", "t": "ἔχει δὲ καὶ ἡ Αἰτωλία ὄρος μέγιστον μὲν τὸν Κόρακα, συνάπτοντα τῇ Οἴτῃ, τῶν δ’ ἄλλων ἐν μέσῳ μὲν μᾶλλον τὸν Ἀράκυνθον, περὶ ὃν τὴν νεωτέραν Πλευρῶνα συνῴκισαν ἀφέντες τὴν παλαιὰν ἐγγὺς κειμένην Καλυδῶνος οἱ οἰκήτορες, εὔκαρπον οὖσαν καὶ πεδιάδα, πορθοῦντος τὴν χώραν Δημητρίου τοῦ ἐπικληθέντος Αἰτωλικοῦ· ὑπὲρ δὲ τῆς Μολυκρείας Ταφιασσὸν καὶ Χαλκίδα, ὄρη ἱκανῶς ὑψηλά, ἐφ’ οἷς πολίχνια ἵδρυτο Μακυνία τε καὶ Χαλκίς, ὁμώνυμος τῷ ὄρει, ἣν καὶ Ὑποχαλκίδα καλοῦσι· Κούριον δὲ πλησίον τῆς παλαιᾶς Πλευρῶνος, ἀφ’ οὗ τοὺς Πλευρωνίους Κουρῆτας ὀνομασθῆναί τινες ὑπέλαβον.", "st": "10.2.4"}, {"sp": "N", "t": "ὁ δ’ Εὔηνος ποταμὸς ἄρχεται μὲν ἐκ Βωμιέων τῶν ἐν Ὀφιεῦσιν Αἰτωλικῷ ἔθνει (καθάπερ καὶ οἱ Εὐρυτᾶνες καὶ Ἀγραῖοι καὶ Κουρῆτες καὶ ἄλλοι), ῥεῖ δ’ οὐ διὰ τῆς Κουρητικῆς κατ’ ἀρχάς, ἥτις ἐστὶν ἡ αὐτὴ τῇ Πλευρωνίᾳ, ἀλλὰ διὰ τῆς προσεῴας μᾶλλον παρὰ τὴν Χαλκίδα καὶ Καλυδῶνα· εἶτ’ ἀνακάμψας ἐπὶ τὰ τῆς Πλευρῶνος πεδία τῆς παλαιᾶς καὶ παραλλάξας εἰς δύσιν ἐπιστρέφει πρὸς τὰς ἐκβολὰς καὶ τὴν μεσημβρίαν· ἐκαλεῖτο δὲ Λυκόρμας πρότερον· καὶ ὁ Νέσσος ἐνταῦθα λέγεται πορθμεὺς ἀποδεδειγμένος ὑφ’ Ἡρακλέους ἀποθανεῖν, ἐπειδὴ πορθμεύων τὴν Δηιάνειραν ἐπεχείρει βιάσασθαι.", "st": "10.2.5"}, {"sp": "N", "t": "καὶ Ὤλενον δὲ καὶ Πυλήνην ὀνομάζει πόλεις ὁ ποιητὴς Αἰτωλικάς, ὧν τὴν μὲν Ὤλενον ὁμωνύμως τῇ Ἀχαϊκῇ λεγομένην Αἰολεῖς κατέσκαψαν, πλησίον οὖσαν τῆς νεωτέρας Πλευρῶνος, τῆς δὲ χώρας ἠμφισβήτουν Ἀκαρνᾶνες· τὴν δὲ Πυλήνην μετενέγκαντες εἰς τοὺς ἀνώτερον τόπους ἤλλαξαν αὐτῆς καὶ τοὔνομα Πρόσχιον καλέσαντες. Ἑλλάνικος δ’ οὐδὲ τὴν περὶ ταύτας ἱστορίαν οἶδεν, ἀλλ’ ὡς ἔτι καὶ αὐτῶν οὐσῶν ἐν τῇ ἀρχαίᾳ καταστάσει μέμνηται, τὰς δ’ ὕστερον καὶ τῆς τῶν Ἡρακλειδῶν καθόδου κτισθείσας Μακυνίαν καὶ Μολύκρειαν ἐν ταῖς ἀρχαίαις καταλέγει, πλείστην εὐχέρειαν ἐπιδεικνύμενος ἐν πάσῃ σχεδόν τι τῇ γραφῇ.", "st": "10.2.6"}, {"sp": "N", "t": "καθόλου μὲν οὖν ταῦτα περὶ τῆς χώρας ἐστὶ τῆς τῶν Ἀκαρνάνων καὶ τῶν Αἰτωλῶν, περὶ δὲ τῆς παραλίας καὶ τῶν προκειμένων νήσων ἔτι καὶ ταῦτα προσληπτέον· ἀπὸ γὰρ τοῦ στόματος ἀρξαμένοις τοῦ Ἀμβρακικοῦ κόλπου πρῶτόν ἐστιν Ἀκαρνάνων χωρίον τὸ Ἄκτιον. ὁμωνύμως δὲ λέγεται τό τε ἱερὸν τοῦ Ἀκτίου Ἀπόλλωνος καὶ ἡ ἄκρα ἡ ποιοῦσα τὸ στόμα τοῦ κόλπου, ἔχουσα καὶ λιμένα ἐκτός. τοῦ δ’ ἱεροῦ τετταράκοντα μὲν σταδίους ἀπέχει τὸ Ἀνακτόριον ἐν τῷ κόλπῳ ἱδρυμένον, διακοσίους δὲ καὶ τετταράκοντα ἡ Λευκάς.", "st": "10.2.7"}, {"sp": "N", "t": "αὕτη δ’ ἦν τὸ παλαιὸν μὲν χερρόνησος τῆς Ἀκαρνάνων γῆς, καλεῖ δ’ ὁ ποιητὴς αὐτὴν ἀκτὴν ἠπείροιο, τὴν περαίαν τῆς Ἰθάκης καὶ τῆς Κεφαλληνίας ἤπειρον καλῶν· αὕτη δ’ ἐστὶν ἡ Ἀκαρνανία· ὥστε, ὅταν φῇ ἀκτὴν ἠπείροιο, τῆς Ἀκαρνανίας ἀκτὴν δέχεσθαι δεῖ. τῆς δὲ Λευκάδος ἥ τε Νήριτος, ἥν φησιν ἑλεῖν ὁ Λαέρτης<br>ἦ μὲν Νήριτον εἷλον ἐϋκτίμενον πτολίεθρον,<br>ἀκτὴν ἠπείροιο, Κεφαλλήνεσσιν ἀνάσσων,<br>καὶ ἃς ἐν καταλόγῳ φησί<br>καὶ Κροκύλει’ ἐνέμοντο καὶ Αἰγίλιπα τρηχεῖαν.<br>Κορίνθιοι δὲ πεμφθέντες ὑπὸ Κυψέλου καὶ Γόργου ταύτην τε κατέσχον τὴν ἀκτὴν καὶ μέχρι τοῦ Ἀμβρακικοῦ κόλπου προῆλθον, καὶ ἥ τε Ἀμβρακία συνῳκίσθη καὶ Ἀνακτόριον, καὶ τῆς χερρονήσου διορύξαντες τὸν ἰσθμὸν ἐποίησαν νῆσον τὴν Λευκάδα, καὶ μετενέγκαντες τὴν Νήριτον ἐπὶ τὸν τόπον, ὃς ἦν ποτὲ μὲν ἰσθμὸς νῦν δὲ πορθμὸς γεφύρᾳ ζευκτός, μετωνόμασαν Λευκάδα, ἐπώνυμον δοκῶ μοι τοῦ Λευκάτα· πέτρα γάρ ἐστι λευκὴ τὴν χρόαν, προκειμένη τῆς Λευκάδος εἰς τὸ πέλαγος καὶ τὴν Κεφαλληνίαν, ὡς ἐντεῦθεν τοὔνομα λαβεῖν.", "st": "10.2.8"}, {"sp": "N", "t": "ἔχει δὲ τὸ τοῦ Λευκάτα Ἀπόλλωνος ἱερὸν καὶ τὸ ἅλμα τὸ τοὺς ἔρωτας παύειν πεπιστευμένον·<br>οὗ δὴ λέγεται πρώτη Σαπφώ<br>ὥς φησιν ὁ Μένανδρος<br>τὸν ὑπέρκομπον θηρῶσα Φάων’<br>οἰστρῶντι πόθῳ ῥῖψαι πέτρας<br>ἀπὸ τηλεφανοῦς ἅλμα κατ’ εὐχὴν<br>σήν, δέσποτ’ ἄναξ.<br>ὁ μὲν οὖν Μένανδρος πρώτην ἁλέσθαι λέγει τὴν Σαπφώ, οἱ δ’ ἔτι ἀρχαιολογικώτεροι Κέφαλόν φασιν ἐρασθέντα Πτερέλα τὸν Δηιονέως. ἦν δὲ καὶ πάτριον τοῖς Λευκαδίοις κατ’ ἐνιαυτὸν ἐν τῇ θυσίᾳ τοῦ Ἀπόλλωνος ἀπὸ τῆς σκοπῆς ῥιπτεῖσθαί τινα τῶν ἐν αἰτίαις ὄντων ἀποτροπῆς χάριν, ἐξαπτομένων ἐξ αὐτοῦ παντοδαπῶν πτερῶν καὶ ὀρνέων ἀνακουφίζειν δυναμένων τῇ πτήσει τὸ ἅλμα, ὑποδέχεσθαι δὲ κάτω μικραῖς ἁλιάσι κύκλῳ περιεστῶτας πολλοὺς καὶ περισώζειν εἰς δύναμιν τῶν ὅρων ἔξω τὸν ἀναληφθέντα. ὁ δὲ τὴν Ἀλκμαιονίδα γράψας, Ἰκαρίου τοῦ Πηνελόπης πατρὸς υἱεῖς γενέσθαι δύο, Ἀλυζέα καὶ Λευκάδιον, δυναστεῦσαι δ’ ἐν τῇ Ἀκαρνανίᾳ τούτους μετὰ τοῦ πατρός· τούτων οὖν ἐπωνύμους τὰς πόλεις Ἔφορος λέγεσθαι δοκεῖ.", "st": "10.2.9"}, {"sp": "N", "t": "Κεφαλλῆνας δὲ νῦν μὲν τοὺς ἐκ τῆς νήσου τῆς Κεφαλληνίας λέγουσιν, Ὅμηρος δὲ πάντας τοὺς ὑπὸ τῷ Ὀδυσσεῖ, ὧν εἰσι καὶ οἱ Ἀκαρνᾶνες· εἰπὼν γάρ<br>αὐτὰρ Ὀδυσσεὺς ἦγε Κεφαλλῆνας,<br>οἵ ῥ’ Ἰθάκην εἶχον καὶ Νήριτον εἰνοσίφυλλον<br>(τὸ ἐν ταύτῃ ὄρος ἐπιφανές, ὡς καί<br>οἳ δ’ ἐκ Δουλιχίοιο Ἐχινάων θ’ ἱεράων<br>καὶ αὐτοῦ τοῦ Δουλιχίου τῶν Ἐχινάδων ὄντος· καί<br>οἳ δ’ ἄρα Βουπράσιόν τε καὶ Ἤλιδα<br>καὶ τοῦ Βουπρασίου ἐν Ἤλιδι ὄντος· [καί]<br>οἳ δ’ Εὔβοιαν ἔχον καὶ Χαλκίδα τ’ Εἰρέτριάν τε<br>καὶ τούτων ἐν Εὐβοίᾳ οὐσῶν· καί<br>Τρῶες καὶ Λύκιοι καὶ Δάρδανοι<br>ὡς καὶ ἐκείνων Τρώων ὄντων)· πλὴν μετά γε Νήριτον φησί<br>καὶ Κροκύλει’ ἐνέμοντο καὶ Αἰγίλιπα τρηχεῖαν,<br>οἵ τε Ζάκυνθον ἔχον ἠδ’ οἳ Σάμον ἀμφενέμοντο,<br>οἵ τ’ ἤπειρον ἔχον ἠδ’ ἀντιπέραι’ ἐνέμοντο.<br>ἤπειρον μὲν οὖν τὰ ἀντιπέρα τῶν νήσων βούλεται λέγειν, ἅμα τῇ Λευκάδι καὶ τὴν ἄλλην Ἀκαρνανίαν συμπεριλαβεῖν βουλόμενος, περὶ ἧς καὶ οὕτω λέγει<br>δώδεκ’ ἐν ἠπείρῳ ἀγέλαι, τόσα πώεα μήλων,<br>τάχα τῆς Ἠπειρώτιδος τὸ παλαιὸν μέχρι δεῦρο διατεινούσης καὶ ὀνόματι κοινῷ ἠπείρου λεγομένης· Σάμον δὲ τὴν νῦν Κεφαλληνίαν, ὡς καὶ ὅταν φῇ<br>ἐν πορθμῷ Ἰθάκης τε Σάμοιό τε παιπαλοέσσης.<br>τῷ γὰρ ἐπιθέτῳ τὴν ὁμωνυμίαν διέσταλται, ὡς οὐκ ἐπὶ τῆς πόλεως ἀλλ’ ἐπὶ τῆς νήσου τιθεὶς τοὔνομα. τετραπόλεως γὰρ οὔσης τῆς νήσου μία τῶν τεττάρων ἐστὶν ἡ καὶ Σάμος καὶ Σάμη καλουμένη καθ’ ἑκάτερον τοὔνομα, ὁμωνυμοῦσα τῇ νήσῳ. ὅταν δ’ εἴπῃ<br>ὅσσοι γὰρ νήσοισιν ἐπικρατέουσιν ἄριστοι<br>Δουλιχίῳ τε Σάμῃ τε καὶ ὑλήεντι Ζακύνθῳ,<br>τῶν νήσων ἀριθμὸν ποιῶν δῆλός ἐστι καὶ Σάμην καλῶν τὴν νῆσον, ἣν πρότερον Σάμον ἐκάλεσεν. Ἀπολλόδωρος δὲ τοτὲ μὲν τῷ ἐπιθέτῳ λέγων διεστάλθαι τὴν ἀμφιβολίαν εἰπόντα<br>Σάμοιό τε παιπαλοέσσης,<br>ὡς τὴν νῆσον λέγοντα, τοτὲ δὲ γράφεσθαι δεῖν<br>Δουλιχίῳ τε Σάμῳ τε<br>ἀλλὰ μή “Σάμῃ τε” δῆλός ἐστι τὴν μὲν πόλιν Σάμην καὶ Σάμον συνωνύμως ὑπολαμβάνων ἐκφέρεσθαι, τὴν δὲ νῆσον Σάμον μόνον· ὅτι γὰρ Σάμη λέγεται ἡ πόλις δῆλον εἶναι ἔκ τε τοῦ διαριθμούμενον τοὺς ἐξ ἑκάστης πόλεως μνηστῆρας φάναι<br>ἐκ δὲ Σάμης πίσυρές τε καὶ εἴκοσι φῶτες ἔασι,<br>καὶ ἐκ τοῦ περὶ τῆς Κτιμένης λόγου<br>τὴν μὲν ἔπειτα Σάμηνδ’ ἔδοσαν.<br>ἔχει δὲ ταῦτα λόγον. οὐ γὰρ εὐκρινῶς ἀποδίδωσιν ὁ ποιητὴς οὔτε περὶ τῆς Κεφαλληνίας οὔτε περὶ τῆς Ἰθάκης καὶ τῶν ἄλλων πλησίον τόπων, ὥστε καὶ οἱ ἐξηγούμενοι διαφέρονται καὶ οἱ ἱστοροῦντες.", "st": "10.2.10"}, {"sp": "N", "t": "αὐτίκα γὰρ ἐπὶ τῆς Ἰθάκης ὅταν φῇ<br>οἵ ῥ’ Ἰθάκην εἶχον καὶ Νήριτον εἰνοσίφυλλον,<br>ὅτι μὲν τὸ Νήριτον ὄρος λέγει τῷ ἐπιθέτῳ δηλοῖ. ἐν ἄλλοις δὲ καὶ ῥητῶς ὄρος<br>ναιετάω δ’ Ἰθάκην εὐδείελον· ἐν δ’ ὄρος αὐτῇ,<br>Νήριτον εἰνοσίφυλλον ἀριπρεπές.<br>Ἰθάκην δ’ εἴτε τὴν πόλιν εἴτε τὴν νῆσον λέγει, οὐ δῆλον ἐν τούτῳ γε τῷ ἔπει<br>οἵ ῥ’ Ἰθάκην εἶχον καὶ Νήριτον.<br>κυρίως μὲν γὰρ ἀκούων τις τὴν πόλιν δέξαιτ’ ἄν, ὡς καὶ Ἀθήνας καὶ Λυκαβηττὸν εἴ τις λέγοι, καὶ Ῥόδον καὶ Ἀτάβυριν, καὶ ἔτι Λακεδαίμονα καὶ Ταΰγετον· ποιητικῶς δὲ τοὐναντίον. ἐν μέντοι τῷ<br>ναιετάω δ’ Ἰθάκην εὐδείελον· ἐν δ’ ὄρος αὐτῇ<br>Νήριτον<br>[δῆλον]· ἐν γὰρ τῇ νήσῳ οὐκ ἐν τῇ πόλει τὸ ὄρος. ὅταν δὲ οὕτω φῇ<br>ἡμεῖς ἐξ Ἰθάκης ὑπὸ Νηίου εἰλήλουθμεν,<br>ἄδηλον, εἴτε τὸ αὐτὸ τῷ Νηρίτῳ λέγει τὸ Νήιον εἴτε ἕτερον ἢ ὄρος ἢ χωρίον.", "st": "10.2.11"}, {"sp": "N", "t": "καὶ τοῦτο δὲ δοκεῖ ὑπεναντιότητά τινα δηλοῦν<br>αὐτὴ δὲ χθαμαλὴ πανυπερτάτη εἰν ἁλὶ κεῖται.<br>χθαμαλὴ μὲν γὰρ ἡ ταπεινὴ καὶ χαμηλή, πανυπερτάτη δὲ ἡ ὑψηλή, οἵαν διὰ πλειόνων σημαίνει, Κραναὴν καλῶν· καὶ τὴν ὁδὸν τὴν ἐκ τοῦ λιμένος<br>τρηχεῖαν ἀταρπὸν<br>χῶρον ἀν’ ὑλήεντα<br>καί<br>οὐ γάρ τις νήσων εὐδείελος, οὐδ’ εὐλείμων,<br>αἵ θ’ ἁλὶ κεκλίαται· Ἰθάκη δέ τε καὶ περὶ πασέων.<br>ἔχει μὲν οὖν ἀπεμφάσεις τοιαύτας ἡ φράσις, ἐξηγοῦνται δὲ οὐ κακῶς· οὔτε γὰρ χθαμαλὴν δέχονται ταπεινὴν ἐνταῦθα, ἀλλὰ πρόσχωρον τῇ ἠπείρῳ ἐγγυτάτω οὖσαν αὐτῆς· οὔτε πανυπερτάτην ὑψηλοτάτην ἀλλὰ πανυπερτάτην πρὸς ζόφον, οἷον ὑπὲρ πάσας ἐσχάτην τετραμμένην πρὸς ἄρκτον· τοῦτο γὰρ βούλεται λέγειν τὸ πρὸς ζόφον, τὸ δ’ ἐναντίον πρὸς νότον<br>αἱ δέ τ’ ἄνευθε πρὸς ἠῶ τ’ ἠέλιόν τε.<br>τὸ γὰρ ἄνευθε πόρρω καὶ χωρὶς ἔστιν, ὡς τῶν μὲν ἄλλων πρὸς νότον κεκλιμένων καὶ ἀπωτέρω τῆς ἠπείρου, τῆς δ’ Ἰθάκης ἐγγύθεν καὶ πρὸς ἄρκτον. ὅτι δ’ οὕτω λέγει τὸ νότιον μέρος καὶ ἐν τοῖσδε φανερόν<br>εἴτ’ ἐπὶ δεξί’ ἴωσι, πρὸς ἠῶ τ’ ἠέλιόν τε,<br>εἴτ’ ἐπ’ ἀριστερὰ τοί γε, ποτὶ ζόφον ἠερόεντα<br>καὶ ἔτι μᾶλλον ἐν τοῖσδε<br>ὦ φίλοι, οὐ γάρ τ’ ἴδμεν, ὅπη ζόφος, οὐδ’ ὅπη ἠώς,<br>οὐδ’ ὅπη ἠέλιος φαεσίμβροτος εἶσ’ ὑπὸ γαῖαν,<br>οὐδ’ ὅπη ἀννεῖται.<br>ἔστι μὲν γὰρ δέξασθαι τὰ τέτταρα κλίματα τὴν ἠῶ δεχομένους τὸ νότιον μέρος, ἔχει τέ τινα τοῦτ’ ἔμφασιν· ἀλλὰ βέλτιον τὸ κατὰ τὴν πάροδον τοῦ ἡλίου νοεῖν ἀντιτιθέμενον τῷ ἀρκτικῷ μέρει· ἐξάλλαξιν γάρ τινα τῶν οὐρανίων πολλὴν βούλεται σημαίνειν ὁ λόγος, οὐχὶ ψιλὴν ἐπίκρυψιν τῶν κλιμάτων. δεῖ γὰρ κατὰ πάντα συννεφῆ καιρόν, ἄν θ’ ἡμέρας ἄν τε νύκτωρ συμβῇ, παρακολουθεῖν· τὰ δ’ οὐράνια ἐξαλλάττει ἐπὶ πλέον τῷ πρὸς μεσημβρίαν μᾶλλον ἢ ἧττον παραχωρεῖν ἡμᾶς ἢ εἰς τοὐναντίον. τοῦτο δὲ οὐ δύσεως καὶ ἀνατολῆς ἐγκαλύψεις ποιεῖ (καὶ γὰρ αἰθρίας οὔσης συμβαίνει), ἀλλὰ μεσημβρίας καὶ ἄρκτου. μάλιστα γὰρ ἀρκτικός ἐστιν ὁ πόλος· τούτου δὲ κινουμένου, καὶ ποτὲ μὲν κατὰ κορυφὴν ἡμῖν γινομένου ποτὲ δὲ ὑπὸ γῆς ὄντος, καὶ οἱ ἀρκτικοὶ συμμεταβάλλουσι, ποτὲ δὲ συνεκλείπουσι κατὰ τὰς τοιαύτας παραχωρήσεις, ὥστε οὐκ ἂν εἰδείης ὅπου ἐστὶ τὸ ἀρκτικὸν κλίμα, οὐδ’ εἰ ἀρχὴν ἐστίν· εἰ δὲ τοῦτο, οὐδὲ τοὐναντίον ἂν γνοίης. κύκλος δὲ τῆς Ἰθάκης ἐστὶν ὡς ὀγδοήκοντα σταδίων. περὶ μὲν Ἰθάκης ταῦτα.", "st": "10.2.12"}, {"sp": "N", "t": "τὴν δὲ Κεφαλληνίαν τετράπολιν οὖσαν οὔτ’ αὐτὴν εἴρηκε τῷ νῦν ὀνόματι οὔτε τῶν πόλεων οὐδεμίαν, πλὴν μιᾶς εἴτε Σάμης εἴτε Σάμου, ἣ νῦν μὲν οὐκέτ’ ἐστίν, ἴχνη δ’ αὐτῆς δείκνυται κατὰ μέσον τὸν πρὸς Ἰθάκῃ πορθμόν· οἱ δ’ ἀπ’ αὐτῆς Σαμαῖοι καλοῦνται· αἱ δ’ ἄλλαι καὶ νῦν εἰσὶν ἔτι μικραὶ πόλεις τινές, [Παλεῖς] Πρώνησος καὶ Κράνιοι. ἐφ’ ἡμῶν δὲ καὶ ἄλλην προσέκτισε Γάιος Ἀντώνιος, ὁ θεῖος Μάρκου Ἀντωνίου, ἡνίκα φυγὰς γενόμενος μετὰ τὴν ὑπατείαν, ἣν συνῆρξε Κικέρωνι τῷ ῥήτορι, ἐν τῇ Κεφαλληνίᾳ διέτριψε καὶ τὴν ὅλην νῆσον ὑπήκοον ἔσχεν ὡς ἴδιον κτῆμα· οὐκ ἔφθη μέντοι συνοικίσας, ἀλλὰ καθόδου τυχὼν πρὸς ἄλλοις μείζοσιν ὢν κατέλυσε τὸν βίον.", "st": "10.2.13"}, {"sp": "N", "t": "οὐκ ὤκνησαν δέ τινες τὴν Κεφαλληνίαν τὴν αὐτὴν τῷ Δουλιχίῳ φάναι, οἱ δὲ τῇ Τάφῳ, καὶ Ταφίους τοὺς Κεφαλληνίους, τοὺς δ’ αὐτοὺς καὶ Τηλεβόας, καὶ τὸν Ἀμφιτρύωνα δεῦρο στρατεῦσαι μετὰ Κεφάλου τοῦ Δηιονέως ἐξ Ἀθηνῶν φυγάδος παραληφθέντος, κατασχόντα δὲ τὴν νῆσον παραδοῦναι τῷ Κεφάλῳ, καὶ ταύτην μὲν ἐπώνυμον ἐκείνου γενέσθαι τὰς δὲ πόλεις τῶν παίδων αὐτοῦ. ταῦτα δ’ οὐχ ὁμηρικά· οἱ μὲν γὰρ Κεφαλλῆνες ὑπὸ Ὀδυσσεῖ καὶ Λαέρτῃ, ἡ δὲ Τάφος ὑπὸ τῷ Μέντῃ<br>Μέντης Ἀγχιάλοιο δαΐφρονος εὔχομαι εἶναι υἱός, ἀτὰρ Ταφίοισι φιληρέτμοισιν ἀνάσσω.<br>καλεῖται δὲ νῦν Ταφιὰς ἡ Τάφος. οὐδ’ Ἑλλάνικος ὁμηρικὸς Δουλίχιον τὴν Κεφαλληνίαν λέγων. τὸ μὲν γὰρ ὑπὸ Μέγητι εἴρηται καὶ αἱ λοιπαὶ Ἐχινάδες, οἵ τε ἐνοικοῦντες Ἐπειοὶ ἐξ Ἤλιδος ἀφιγμένοι· διόπερ καὶ τὸν Ὦτον τὸν Κυλλήνιον<br>Φυλείδεω ἕταρον μεγαθύμων ἀρχὸν Ἐπειῶν<br>καλεῖ.<br>αὐτὰρ Ὀδυσσεὺς ἦγε Κεφαλλῆνας μεγαθύμους.<br>οὔτ’ οὖν Δουλίχιον ἡ Κεφαλληνία καθ’ Ὅμηρον οὔτε τῆς Κεφαλληνίας τὸ Δουλίχιον, ὡς Ἄνδρων φησί· τὸ μὲν γὰρ Ἐπειοὶ κατεῖχον, τὴν δὲ Κεφαλληνίαν ὅλην Κεφαλλῆνες ὑπὸ Ὀδυσσεῖ, οἱ δ’ ὑπὸ Μέγητι. οὐδὲ Παλεῖς Δουλίχιον ὑφ’ Ὁμήρου λέγονται, ὡς γράφει Φερεκύδης. μάλιστα δ’ ἐναντιοῦται Ὁμήρῳ ὁ τὴν Κεφαλληνίαν τὴν αὐτὴν τῷ Δουλιχίῳ λέγων, εἴπερ τῶν μνηστήρων ἐκ μὲν Δουλιχίοιο δύω καὶ πεντήκοντα ἦσαν, ἐκ δὲ Σάμης πίσυρές τε καὶ εἴκοσιν. οὐ γὰρ τοῦτ’ ἂν εἴη λέγων, ἐξ ὅλης μὲν τόσους ἐκ δὲ μιᾶς τῶν τεττάρων παρὰ δύο τοὺς ἡμίσεις. εἰ δ’ ἄρα τοῦτο δώσει τις, ἐρησόμεθα τίς ἂν εἴη ἡ Σάμη, ὅταν οὕτω φῇ<br>Δουλίχιόν τε Σάμην τ’ ἠδ’ ὑλήεντα Ζάκυνθον.", "st": "10.2.14"}, {"sp": "N", "t": "κεῖται δ’ ἡ Κεφαλληνία κατὰ Ἀκαρνανίαν, διέχουσα τοῦ Λευκάτα περὶ πεντήκοντα (οἱ δὲ τετταράκοντά φασι) σταδίους, τοῦ δὲ Χελωνάτα περὶ ὀγδοήκοντα. αὐτὴ δ’ ἐστὶν ὡς τριακοσίων τὴν περίμετρον, μακρὰ δ’ ἀνήκουσα πρὸς εὖρον, ὀρεινή· μέγιστον δ’ ὄρος ἐν αὐτῇ ἐν ᾧ τὸ Διὸς Αἰνησίου ἱερόν· καθ’ ὃ δὲ στενωτάτη ἐστὶν ἡ νῆσος, ταπεινὸν ἰσθμὸν ποιεῖ ὥσθ’ ὑπερκλύζεσθαι πολλάκις ἐκ θαλάττης εἰς θάλατταν· πλησίον δ’ εἰσὶ τῶν στενῶν ἐν κόλπῳ Κράνιοί τε καὶ Παλεῖς.", "st": "10.2.15"}, {"sp": "N", "t": "μεταξὺ δὲ τῆς Ἰθάκης καὶ τῆς Κεφαλληνίας ἡ Ἀστερία νησίον (Ἀστερὶς δ’ ὑπὸ τοῦ ποιητοῦ λέγεται) ἣν ὁ μὲν Σκήψιος μὴ μένειν τοιαύτην οἵαν φησὶν ὁ ποιητής<br>λιμένες δ’ ἔνι ναύλοχοι αὐτῇ<br>ἀμφίδυμοι.<br>ὁ δὲ Ἀπολλόδωρος μένειν καὶ νῦν, καὶ πολίχνιον λέγει ἐν αὐτῇ Ἀλαλκομενὰς τὸ ἐπ’ αὐτῷ τῷ ἰσθμῷ κείμενον.", "st": "10.2.16"}, {"sp": "N", "t": "καλεῖ δ’ ὁ ποιητὴς Σάμον καὶ τὴν Θρᾳκίαν, ἣν νῦν Σαμοθρᾴκην καλοῦμεν. τὴν δ’ Ἰωνικὴν οἶδε μέν, ὡς εἰκός· καὶ γὰρ τὴν Ἰωνικὴν ἀποικίαν εἰδέναι φαίνεται· οὐκ [ἂν] ἀντιδιέστειλε δὲ τὴν ὁμωνυμίαν, περὶ τῆς Σαμοθρᾴκης λέγων, τοτὲ μὲν τῷ ἐπιθέτῳ<br>ὑψοῦ ἐπ’ ἀκροτάτης κορυφῆς Σάμου ὑληέσσης,<br>Θρηικίης<br>τοτὲ δὲ τῇ συζυγίᾳ τῶν πλησίον νήσων<br>ἐς Σάμον ἔς τ’ Ἴμβρον καὶ Λῆμνον ἀμιχθαλόεσσαν<br>καὶ πάλιν<br>μεσσηγύς τε Σάμοιο καὶ Ἴμβρου παιπαλοέσσης.<br>ᾔδει μὲν οὖν, οὐκ ὠνόμακε δ’ αὐτήν· οὐδ’ ἐκαλεῖτο τῷ αὐτῷ ὀνόματι πρότερον, ἀλλὰ Μελάμφυλλος, εἶτ’ Ἀνθεμίς, εἶτα Παρθενία ἀπὸ τοῦ ποταμοῦ τοῦ Παρθενίου, ὃς Ἴμβρασος μετωνομάσθη. ἐπεὶ οὖν κατὰ τὰ Τρωικὰ Σάμος μὲν καὶ ἡ Κεφαλληνία ἐκαλεῖτο καὶ ἡ Σαμοθρᾴκη (οὐ γὰρ ἂν Ἑκάβη εἰσήγετο λέγουσα ὅτι τοὺς παῖδας αὐτῆς πέρνασχ’ ὅν κε λάβοι ἐς Σάμον ἔς τ’ Ἴμβρον), Ἰωνικὴ δ’ οὐκ ἀπῴκιστό πω, δῆλον ὅτι ἀπὸ τῶν προτέρων τινὸς τὴν ὁμωνυμίαν ἔσχεν· ἐξ ὧν κἀκεῖνο δῆλον, ὅτι παρὰ τὴν ἀρχαίαν ἱστορίαν ὃ λέγουσιν οἱ φήσαντες, μετὰ τὴν Ἰωνικὴν ἀποικίαν καὶ τὴν Τεμβρίωνος παρουσίαν ἀποίκους ἐλθεῖν ἐκ Σάμου καὶ ὀνομάσαι Σάμον τὴν Σαμοθρᾴκην, ὡς οἱ Σάμιοι τοῦτ’ ἐπλάσαντο δόξης χάριν. πιθανώτεροι δ’ εἰσὶν [οἱ] ἀπὸ τοῦ Σάμους καλεῖσθαι τὰ ὕψη φήσαντες εὑρῆσθαι τοῦτο τοὔνομα τὴν νῆσον· ἐντεῦθεν γάρ<br>ἐφαίνετο πᾶσα μὲν Ἴδη, φαίνετο δὲ Πριάμοιο πόλις καὶ νῆες Ἀχαιῶν.<br>τινὲς δὲ Σάμον καλεῖσθαί φασιν ἀπὸ Σαΐων, τῶν οἰκούντων Θρᾳκῶν πρότερον, οἳ καὶ τὴν ἤπειρον ἔσχον τὴν προσεχῆ, εἴτε οἱ αὐτοὶ τοῖς Σαπαίοις ὄντες ἢ τοῖς Σιντοῖς, οὓς Σίντιας καλεῖ ὁ ποιητής, εἴθ’ ἕτεροι. μέμνηται δὲ τῶν Σαΐων Ἀρχίλοχος<br>ἀσπίδα μὲν Σαΐων τὶς ἀνείλετο, τὴν παρὰ θάμνῳ<br>ἔντος ἀμώμητον κάλλιπον οὐκ ἐθέλων.", "st": "10.2.17"}, {"sp": "N", "t": "λοιπὴ δ’ ἐστὶ τῶν ὑπὸ τῷ Ὀδυσσεῖ τεταγμένων νήσων ἡ Ζάκυνθος, μικρῷ πρὸς ἑσπέραν μᾶλλον τῆς Κεφαλληνίας κεκλιμένη τῆς Πελοποννήσου, συνάπτουσα δ’ αὐτῇ πλέον. ἔστι δ’ ὁ κύκλος τῆς Ζακύνθου σταδίων ἑκατὸν ἑξήκοντα· διέχει δὲ καὶ τῆς Κεφαλληνίας ὅσον ἑξήκοντα σταδίους, ὑλώδης μὲν εὔκαρπος δέ· καὶ ἡ πόλις ἀξιόλογος, ὁμώνυμος. ἐντεῦθεν εἰς Ἑσπερίδας τῆς Λιβύης στάδιοι τρισχίλιοι ἑξακόσιοι.", "st": "10.2.18"}, {"sp": "N", "t": "καὶ ταύτης δὲ καὶ τῆς Κεφαλληνίας πρὸς ἕω τὰς Ἐχινάδας ἱδρῦσθαι νήσους συμβέβηκεν, ὧν τό τε Δουλίχιόν ἐστι (καλοῦσι δὲ νῦν Δολίχαν) καὶ αἱ Ὀξεῖαι καλούμεναι, ἃς Θοὰς ὁ ποιητὴς εἶπε· καὶ ἡ μὲν Δολίχα κεῖται κατὰ Οἰνιάδας καὶ τὴν ἐκβολὴν τοῦ Ἀχελώου, διέχουσα Ἀράξου τῆς τῶν Ἠλείων ἄκρας ἑκατόν, αἱ λοιπαὶ δ’ Ἐχινάδες (πλείους δ’ εἰσί, πᾶσαι λυπραὶ καὶ τραχεῖαι) πρὸ τῆς ἐκβολῆς τοῦ Ἀχελώου, πεντεκαίδεκα σταδίους ἀφεστῶσα ἡ ἀπωτάτω, ἡ δ’ ἐγγυτάτω πέντε, πελαγίζουσαι πρότερον, ἀλλ’ ἡ χοῦς τὰς μὲν ἐξηπείρωκεν αὐτῶν ἤδη, τὰς δὲ μέλλει πολλὴ καταφερομένη· ἥπερ καὶ τὴν Παραχελωῖτιν καλουμένην χώραν, ἣν ὁ ποταμὸς ἐπικλύζει, περιμάχητον ἐποίει τὸ παλαιὸν τοὺς ὅρους συγχέουσα ἀεὶ τοὺς ἀποδεικνυμένους τοῖς Ἀκαρνᾶσι καὶ τοῖς Αἰτωλοῖς· ἐκρίνοντο γὰρ τοῖς ὅπλοις οὐκ ἔχοντες διαιτητάς, ἐνίκων δ’ οἱ πλέον δυνάμενοι· ἀφ’ ἧς αἰτίας καὶ μῦθος ἐπλάσθη τις; ὡς Ἡρακλέους καταπολεμήσαντος τὸν Ἀχελῶον καὶ ἐνεγκαμένου τῆς νίκης ἆθλον τὸν Δηιανείρας γάμον τῆς Οἰνέως θυγατρός, ἣν πεποίηκε Σοφοκλῆς τοιαῦτα λέγουσαν<br>μνηστὴρ γὰρ ἦν μοι ποταμός, Ἀχελῶον λέγω,<br>ὅς μ’ ἐν τρισὶν μορφαῖσιν ἐξῄτει πατρός,<br>φοιτῶν ἐναργὴς ταῦρος, ἄλλοτ’ αἰόλος<br>δράκων ἑλικτός, ἄλλοτ’ ἀνδρείῳ κύτει<br>βούπρῳρος.<br>προστιθέασι δ’ ἔνιοι καὶ τὸ τῆς Ἀμαλθείας τοῦτ’ εἶναι λέγοντες κέρας, ὃ ἀπέκλασεν ὁ Ἡρακλῆς τοῦ Ἀχελώου καὶ ἔδωκεν Οἰνεῖ τῶν γάμων ἕδνον· οἱ δ’ εἰκάζοντες ἐξ αὐτῶν τἀληθὲς ταύρῳ μὲν ἐοικότα λέγεσθαι τὸν Ἀχελῶόν φασι, καθάπερ καὶ τοὺς ἄλλους ποταμούς, ἀπό τε τῶν ἤχων καὶ τῶν κατὰ τὰ ῥεῖθρα καμπῶν, ἃς καλοῦσι κέρατα, δράκοντι δὲ διὰ τὸ μῆκος καὶ τὴν σκολιότητα, βούπρῳρον δὲ διὰ τὴν αὐτὴν αἰτίαν δι’ ἣν καὶ ταυρωπόν· τὸν Ἡρακλέα δὲ καὶ ἄλλως εὐεργετικὸν ὄντα καὶ τῷ Οἰνεῖ κηδεύσοντα παραχώμασί τε καὶ διοχετείαις βιάσασθαι τὸν ποταμὸν πλημμελῶς ῥέοντα καὶ πολλὴν τῆς Παραχελωίτιδος ἀναψύξαι χαριζόμενον τῷ Οἰνεῖ· καὶ τοῦτ’ εἶναι τὸ τῆς Ἀμαλθείας κέρας. τῶν μὲν οὖν Ἐχινάδων καὶ τῶν Ὀξειῶν κατὰ τὰ Τρωικὰ Μέγητα ἄρχειν φησὶν Ὅμηρος<br>ὃν τίκτε Διὶ φίλος ἱππότα Φυλεύς,<br>ὅς ποτε Δουλίχιόνδ’ ἀπενάσσατο, πατρὶ χολωθείς.<br>πατὴρ δ’ ἦν Αὐγέας ὁ τῆς Ἠλείας καὶ τῶν Ἐπειῶν ἄρχων· ὥστ’ Ἐπειοὶ τὰς νήσους ταύτας εἶχον οἱ συνεξάραντες εἰς τὸ Δουλίχιον τῷ Φυλεῖ.", "st": "10.2.19"}, {"sp": "N", "t": "αἱ δὲ τῶν Ταφίων νῆσοι, πρότερον δὲ Τηλεβοῶν, ὧν ἦν καὶ ἡ Τάφος νῦν δὲ Ταφιὰς καλουμένη, χωρὶς ἦσαν τούτων οὐ τοῖς διαστήμασιν (ἐγγὺς γὰρ κεῖνται) ἀλλὰ ὑφ’ ἑτέροις ἡγεμόσι ταττόμεναι, Ταφίοις καὶ Τηλεβόαις· πρότερον μὲν οὖν Ἀμφιτρύων ἐπιστρατεύσας αὐτοῖς μετὰ Κεφάλου τοῦ Δηιονέως ἐξ Ἀθηνῶν φυγάδος, ἐκείνῳ τὴν ἀρχὴν παρέδωκεν αὐτῶν· ὁ δὲ ποιητὴς ὑπὸ Μέντῃ τετάχθαι φησὶ λῃστὰς καλῶν αὐτούς, καθάπερ καὶ τοὺς Τηλεβόας ἅπαντάς φασι. τὰ μὲν περὶ τὰς νήσους τὰς πρὸ τῆς Ἀκαρνανίας ταῦτα.", "st": "10.2.20"}, {"sp": "N", "t": "μεταξὺ δὲ Λευκάδος καὶ τοῦ Ἀμβρακικοῦ κόλπου λιμνοθάλαττά ἐστι Μυρτούντιον λεγομένη. ἀπὸ δὲ Λευκάδος ἑξῆς Πάλαιρος καὶ Ἀλυζία τῆς Ἀκαρνανίας εἰσὶ πόλεις, ὧν ἡ Ἀλυζία πεντεκαίδεκα ἀπὸ θαλάττης διέχει σταδίους, καθ’ ἥν ἐστι λιμὴν Ἡρακλέους ἱερὸς καὶ τέμενος, ἐξ οὗ τοὺς Ἡρακλέους ἄθλους, ἔργα Λυσίππου, μετήνεγκεν εἰς Ῥώμην τῶν ἡγεμόνων τις, παρὰ τόπον κειμένους διὰ τὴν ἐρημίαν. εἶτα ἄκρα Κριθώτη καὶ [αἱ] Ἐχινάδες καὶ πόλις Ἀστακός, ὁμώνυμος τῇ περὶ Νικομήδειαν καὶ τὸν Ἀστακηνὸν κόλπον (καὶ ἡ Κριθώτη δ’ ὁμώνυμος πολίχνη τῶν ἐν τῇ Θρᾳκίᾳ Χερρονήσῳ)· πάντα δ’ εὐλίμενα τὰ μεταξύ· εἶτ’ Οἰνιάδαι καὶ ὁ Ἀχελῶος· εἶτα λίμνη τῶν Οἰνιαδῶν Μελίτη καλουμένη, μῆκος μὲν ἔχουσα τριάκοντα σταδίων πλάτος δὲ εἴκοσι, καὶ ἄλλη Κυνία διπλασία ταύτης καὶ μῆκος καὶ πλάτος, τρίτη δ’ Οὐρία πολλῷ τούτων μικροτέρα· ἡ μὲν οὖν Κυνία καὶ ἐκδίδωσιν εἰς τὴν θάλατταν, αἱ λοιπαὶ δ’ ὑπέρκεινται ὅσον ἡμιστάδιον· εἶθ’ ὁ Εὔηνος, εἰς ὃν ἀπὸ τοῦ Ἀκτίου στάδιοι ἑξακόσιοι ἑβδομήκοντα· μετὰ δὲ τὸν Εὔηνον τὸ ὄρος ἡ Χαλκίς, ἣν Χαλκίαν εἴρηκεν Ἀρτεμίδωρος· εἶθ’ ἡ Πλευρών, εἶθ’ ἡ Ἁλίκυρνα κώμη, ἧς ὑπέρκειται Καλυδὼν ἐν τῇ μεσογαίᾳ σταδίοις τριάκοντα· περὶ δὲ τὴν Καλυδῶνά ἐστι τὸ τοῦ Λαφρίου Ἀπόλλωνος ἱερόν· εἶθ’ ὁ Ταφιασσὸς τὸ ὄρος, εἶτα Μακυνία πόλις, εἶτα Μολύκρεια καὶ πλησίον τὸ Ἀντίρριον τὸ τῆς Αἰτωλίας ὅριον καὶ τῆς Λοκρίδος, εἰς ὃ ἀπὸ τοῦ Εὐήνου στάδιοι περὶ ἑκατὸν εἴκοσιν. Ἀρτεμίδωρος μὲν [οὐχ] οὕτω περὶ τῆς εἴτε Χαλκίδος εἴτε Χαλκίας τοῦ ὄρους, μεταξὺ τοῦ Ἀχελώου καὶ τῆς Πλευρῶνος ἱδρύων αὐτήν, Ἀπολλόδωρος δέ, ὡς πρότερον εἶπον, ὑπὲρ τῆς Μολυκρείας καὶ τὴν Χαλκίδα καὶ τὸν Ταφιασσόν· καὶ τὴν δὲ Καλυδῶνα μεταξὺ ἱδρῦσθαί φησι τῆς τε Πλευρῶνος καὶ τῆς Χαλκίδος· εἰ μὴ ἄρα ἕτερον θετέον τὸ πρὸς Πλευρῶνι ὄρος Χαλκίαν καλούμενον, ἕτερον δὲ τὴν Χαλκίδα τὴν πρὸς Μολυκρείᾳ. ἔστι δέ τις καὶ πρὸς τῇ Καλυδῶνι λίμνη μεγάλη καὶ εὔοψος, ἣν ἔχουσιν οἱ ἐν Πάτραις Ῥωμαῖοι.", "st": "10.2.21"}, {"sp": "N", "t": "τῆς δὲ μεσογαίας κατὰ μὲν τὴν Ἀκαρνανίαν Ἐρυσιχαίους τινάς φησιν Ἀπολλόδωρος λέγεσθαι, ὧν Ἀλκμὰν μέμνηται<br>οὐδ’ Ἐρυσιχαῖος, οὐδὲ ποιμήν,<br>ἀλλὰ Σαρδίων ἀπ’ ἀκρᾶν.<br>κατὰ δὲ τὴν Αἰτωλίαν ἦν Ὤλενος, ἧς ἐν τῷ Αἰτωλικῷ καταλόγῳ μέμνηται Ὅμηρος, ἴχνη δ’ αὐτῆς λείπεται μόνον ἐγγὺς τῆς Πλευρῶνος ὑπὸ τῷ Ἀρακύνθῳ· ἦν δὲ καὶ Λυσιμάχεια πλησίον, ἠφανισμένη καὶ αὐτή, κειμένη πρὸς τῇ λίμνῃ τῇ νῦν μὲν Λυσιμαχείᾳ πρότερον δ’ Ὕδρᾳ, μεταξὺ Πλευρῶνος καὶ Ἀρσινόης πόλεως, ἣ κώμη μὲν ἦν πρότερον καλουμένη Κωνώπα, κτίσμα δ’ ὑπῆρξεν Ἀρσινόης τῆς Πτολεμαίου τοῦ δευτέρου γυναικὸς ἅμα καὶ ἀδελφῆς, εὐφυῶς ἐπικειμένη πως τῇ τοῦ Ἀχελώου διαβάσει· παραπλήσιον δέ τι καὶ ἡ Πυλήνη τῷ Ὠλένῳ πέπονθεν. ὅταν δὲ φῇ τὴν Καλυδῶνα αἰπεῖάν τε καὶ πετρήεσσαν, ἀπὸ τῆς χώρας δεκτέον· εἴρηται γὰρ ὅτι τὴν χώραν δίχα διελόντες τὴν μὲν ὀρεινὴν καὶ ἐπίκτητον τῇ Καλυδῶνι προσένειμαν, τὴν πεδιάδα δὲ τῇ Πλευρῶνι.", "st": "10.2.22"}, {"sp": "N", "t": "νυνὶ μὲν οὖν ἐκπεπόνηται καὶ ἀπηγόρευκεν ὑπὸ τῶν συνεχῶν πολέμων ἥ τ’ Ἀκαρνανία καὶ Αἰτωλοί, καθάπερ καὶ πολλὰ τῶν ἄλλων ἐθνῶν· πλεῖστον μέντοι χρόνον συνέμειναν Αἰτωλοὶ μετὰ τῶν Ἀκαρνάνων πρός τε τοὺς Μακεδόνας καὶ τοὺς ἄλλους Ἕλληνας, ὕστατα δὲ καὶ πρὸς Ῥωμαίους περὶ τῆς αὐτονομίας ἀγωνιζόμενοι. ἐπεὶ δὲ καὶ Ὅμηρος αὐτῶν ἐπὶ πολὺ μέμνηται καὶ οἱ ἄλλοι ποιηταί τε καὶ συγγραφεῖς, τὰ μὲν εὐσήμως τε καὶ ὁμολογουμένως, τὰ δ’ ἧττον γνωρίμως (καθάπερ τοῦτο καὶ ἐν τοῖς ἤδη λεχθεῖσι περὶ αὐτῶν ἀποδέδεικται), προσληπτέον καὶ τῶν παλαιοτέρων τινὰ τῶν ἀρχῆς ἐχόντων τάξιν ἢ διαπορουμένων.", "st": "10.2.23"}, {"sp": "N", "t": "εὐθὺς ἐπὶ τῆς Ἀκαρνανίας ὅτι μὲν αὐτὴν ὁ Λαέρτης καὶ οἱ Κεφαλλῆνες κατεκτήσαντο εἴρηται ἡμῖν, τίνων δὲ κατεχόντων πρότερον πολλοὶ μὲν εἰρήκασιν· οὐχ ὁμολογούμενα δὲ εἰπόντων ἐπιφανῆ δέ, ἀπολείπεταί τις λόγος ἡμῖν διαιτητικὸς περὶ αὐτῶν. φασὶ γὰρ τοὺς Ταφίους τε καὶ Τηλεβόας λεγομένους οἰκεῖν τὴν Ἀκαρνανίαν πρότερον, καὶ τὸν ἡγεμόνα αὐτῶν Κέφαλον τὸν κατασταθέντα ὑπὸ Ἀμφιτρύωνος κύριον τῶν περὶ τὴν Τάφον νήσων κυριεῦσαι καὶ ταύτης τῆς χώρας· ἐντεῦθεν δὲ καὶ τὸ ἀπὸ τοῦ Λευκάτα νομιζόμενον ἅλμα τούτῳ πρώτῳ προσμυθεύουσιν, ὡς προείρηται. ὁ δὲ ποιητὴς ὅτι μὲν ἦρχον οἱ Τάφιοι τῶν Ἀκαρνάνων πρὶν ἢ τοὺς Κεφαλλῆνας καὶ τὸν Λαέρτην ἐπελθεῖν οὐ λέγει, διότι δ’ ἦσαν φίλοι τοῖς Ἰθακησίοις λέγει, ὥστ’ ἢ οὐδ’ ὅλως ἐπῆρξαν τῶν τόπων κατ’ αὐτόν, ἢ ἑκόντες παρεχώρησαν ἢ καὶ σύνοικοι ἐγένοντο. φαίνονται δὲ καὶ ἐκ Λακεδαίμονός τινες ἐποικῆσαι τὴν Ἀκαρνανίαν, οἱ μετ’ Ἰκαρίου τοῦ Πηνελόπης πατρός· καὶ γὰρ τοῦτον καὶ τοὺς ἀδελφοὺς αὐτῆς ζῶντας παραδίδωσιν ὁ ποιητὴς κατὰ τὴν Ὀδύσσειαν<br>οἳ πατρὸς μὲν ἐς οἶκον ἀπερρίγασι νέεσθαι Ἰκαρίου, ὥς κ’ αὐτὸς ἐεδνώσαιτο θύγατρα.<br>καὶ περὶ τῶν ἀδελφῶν<br>ἤδη γάρ ῥα πατήρ τε κασίγνητοί τε κέλονται Εὐρυμάχῳ γήμασθαι<br>οὔτε γὰρ ἐν Λακεδαίμονι πιθανὸν αὐτοὺς οἰκεῖν (οὐ γὰρ ἂν ὁ Τηλέμαχος παρὰ Μενελάῳ κατήγετο ἀφιγμένος ἐκεῖσε), οὔτ’ ἄλλην οἴκησιν παρειλήφαμεν αὐτῶν. φασὶ δὲ Τυνδάρεων καὶ τὸν ἀδελφὸν αὐτοῦ τὸν Ἰκάριον ἐκπεσόντας ὑπὸ Ἱπποκόωντος τῆς οἰκείας ἐλθεῖν παρὰ Θέστιον τὸν τῶν Πλευρωνίων ἄρχοντα, καὶ συγκατακτήσασθαι τὴν πέραν τοῦ Ἀχελώου πολλὴν ἐπὶ μέρει· τὸν μὲν οὖν Τυνδάρεων ἐπανελθεῖν οἴκαδε γήμαντα Λήδαν τὴν τοῦ Θεστίου θυγατέρα, τὸν δ’ Ἰκάριον ὑπομεῖναι τῆς Ἀκαρνανίας ἔχοντα μέρος, καὶ τεκνοποιήσασθαι τήν τε Πηνελόπην ἐκ Πολυκάστης τῆς Λυγαίου θυγατρὸς καὶ τοὺς ἀδελφοὺς αὐτῆς. ἡμεῖς μὲν οὖν ἀπεδείξαμεν ἐν τῷ καταλόγῳ τῶν νεῶν καὶ τοὺς Ἀκαρνᾶνας καταριθμουμένους καὶ μετασχόντας τῆς ἐπὶ Ἴλιον στρατείας, ἐν οἷς κατωνομάζοντο οἵ τε τὴν ἀκτὴν οἰκοῦντες καὶ ἔτι<br>οἵ τ’ ἤπειρον ἔχον ἠδ’ ἀντιπέραι’ ἐνέμοντο.<br>οὔτε δ’ ἡ ἤπειρος Ἀκαρνανία ὠνομάζετό πω οὔθ’ ἡ ἀκτὴ Λευκάς.", "st": "10.2.24"}, {"sp": "N", "t": "Ἔφορος δ’ οὔ φησι συστρατεῦσαι· Ἀλκμέωνα γὰρ τὸν Ἀμφιάρεω στρατεύσαντα μετὰ Διομήδους καὶ τῶν ἄλλων Ἐπιγόνων καὶ κατορθώσαντα τὸν πρὸς Θηβαίους πόλεμον συνελθεῖν Διομήδει καὶ τιμωρήσασθαι μετ’ αὐτοῦ τοὺς Οἰνέως ἐχθρούς, παραδόντα δ’ ἐκείνοις τὴν Αἰτωλίαν αὐτὸν εἰς τὴν Ἀκαρνανίαν παρελθεῖν καὶ ταύτην καταστρέφεσθαι. Ἀγαμέμνονα δ’ ἐν τούτῳ τοῖς Ἀργείοις ἐπιθέμενον κρατῆσαι ῥᾳδίως, τῶν πλείστων τοῖς περὶ Διομήδη συνακολουθησάντων. μικρὸν δ’ ὕστερον ἐπιπεσούσης τῆς ἐπ’ Ἴλιον ἐξόδου, δείσαντα μὴ ἀπόντος αὐτοῦ κατὰ τὴν στρατείαν ἐπανελθόντες οἴκαδε οἱ περὶ τὸν Διομήδη (καὶ γὰρ ἀκούεσθαι μεγάλην περὶ αὐτὸν συνεστραμμένην δύναμιν) κατάσχοιεν τὴν μάλιστα προσήκουσαν αὐτοῖς ἀρχήν (τὸν μὲν γὰρ Ἀδράστου τὸν δὲ τοῦ πατρὸς εἶναι κληρονόμον), ταῦτα δὴ διανοηθέντα καλεῖν αὐτοὺς ἐπί τε τὴν τοῦ Ἄργους ἀπόληψιν καὶ τὴν κοινωνίαν τοῦ πολέμου· τὸν μὲν οὖν Διομήδη πεισθέντα μετασχεῖν τῆς στρατείας, τὸν δὲ Ἀλκμέωνα ἀγανακτοῦντα μὴ φροντίσαι· διὰ δὲ τοῦτο μηδὲ κοινωνῆσαι τῆς στρατείας μόνους τοὺς Ἀκαρνᾶνας τοῖς Ἕλλησι· τούτοις δ’, ὡς εἰκός, τοῖς λόγοις ἐπακολουθήσαντες οἱ Ἀκαρνᾶνες σοφίσασθαι λέγονται Ῥωμαίους καὶ τὴν αὐτονομίαν παρ’ αὐτῶν ἐξανύσασθαι, λέγοντες ὡς οὐ μετάσχοιεν μόνοι τῆς ἐπὶ τοὺς προγόνους τοὺς ἐκείνων στρατείας· οὔτε γὰρ ἐν τῷ Αἰτωλικῷ καταλόγῳ φράζοιντο οὔτε ἰδίᾳ· οὐδὲ γὰρ ὅλως τοὔνομα τοῦτ’ ἐμφέροιτο ἐν τοῖς ἔπεσιν.", "st": "10.2.25"}, {"sp": "N", "t": "ὁ μὲν οὖν Ἔφορος πρὸ τῶν Τρωικῶν ἤδη τὴν Ἀκαρνανίαν ὑπὸ τῷ Ἀλκμέωνι ποιήσας, τό τε Ἄργος τὸ Ἀμφιλοχικὸν ἐκείνου κτίσμα ἀποφαίνει, καὶ τὴν Ἀκαρνανίαν ὠνομάσθαι φησὶν ἀπὸ τοῦ παιδὸς αὐτοῦ Ἀκαρνᾶνος, Ἀμφιλόχους δὲ ἀπὸ τοῦ ἀδελφοῦ Ἀμφιλόχου· ὥστε ἐκπίπτει εἰς τὰ παρὰ τὴν ὁμηρικὴν ἱστορίαν λεγόμενα. Θουκυδίδης δὲ καὶ ἄλλοι τὸν Ἀμφίλοχον ἀπὸ τῆς στρατείας τῆς Τρωικῆς ἐπανιόντα, οὐκ ἀρεσκόμενον τοῖς ἐν Ἄργει, ταύτην οἰκῆσαί φασι τὴν χώραν, οἱ μὲν κατὰ διαδοχὴν ἥκοντα τῆς τοῦ ἀδελφοῦ δυναστείας, οἱ δ’ ἄλλως. καὶ ἰδίᾳ μὲν περὶ Ἀκαρνάνων ταῦτα λέγοιτ’ ἄν, κοινῇ δ’ ὅσα καὶ τοῖς Αἰτωλικοῖς ἐπιπλέκεται νῦν ἐροῦμεν, τὰ Αἰτωλικὰ λέγοντες ἐφεξῆς ὅσα προσλαβεῖν τοῖς εἰρημένοις ἔγνωμεν.", "st": "10.2.26"}, {"sp": "N", "t": "τοὺς δὲ Κουρῆτας τῶν μὲν Ἀκαρνᾶσι τῶν δ’ Αἰτωλοῖς προσνεμόντων, καὶ τῶν μὲν ἐκ Κρήτης τῶν δ’ ἐξ Εὐβοίας τὸ γένος εἶναι φασκόντων, ἐπειδὴ καὶ Ὅμηρος αὐτῶν μέμνηται, τὰ παρ’ ἐκείνου πρῶτον ἐπισκεπτέον. οἴονται δ’ αὐτὸν λέγειν Αἰτωλοὺς μᾶλλον ἢ Ἀκαρνᾶνας, εἴπερ οἱ Πορθαονίδαι ἦσαν<br>ἄγριος ἠδὲ Μέλας, τρίτατος δ’ ἦν ἱππότα Οἰνεύς·<br>ᾤκεον δ’ ἐν Πλευρῶνι καὶ αἰπεινῇ Καλυδῶνι.<br>αὗται δ’ εἰσὶν Αἰτωλικαὶ πόλεις ἀμφότεραι καὶ φέρονται ἐν τῷ Αἰτωλικῷ καταλόγῳ ὥστε, ἐπεὶ τὴν Πλευρῶνα οἰκοῦντες φαίνονται καὶ κατ’ αὐτὸν οἱ Κουρῆτες, Αἰτωλοὶ ἂν εἶεν. οἱ δ’ ἀντιλέγοντες τῷ τρόπῳ τῆς φράσεως παράγονται ὅταν φῇ<br>Κουρῆτές τ’ ἐμάχοντο καὶ Αἰτωλοὶ μενεχάρμαι<br>ἀμφὶ πόλιν Καλυδῶνα.<br>οὐδὲ γὰρ ἂν κυρίως εἶπεν οὕτως “ἐμάχοντο Βοιωτοὶ καὶ Θηβαῖοι πρὸς ἀλλήλους” οὐδ’ “Ἀργεῖοι καὶ Πελοποννήσιοι.” ἐδείχθη δ’ ἐν τοῖς ἔμπροσθεν ὅτι ἐστὶ καὶ ὁμηρικὸν τὸ ἔθος τοῦτο τῆς φράσεως καὶ ὑπὸ τῶν ἄλλων ποιητῶν τετριμμένον· τοῦτο μὲν οὖν εὐαπολόγητον. ἐκεῖνοι δὲ λεγέτωσαν πῶς ἂν μὴ ὁμοεθνεῖς ὄντας μηδ’ Αἰτωλοὺς τοὺς Πλευρωνίους ἐν τοῖς Αἰτωλοῖς κατέλεγεν.", "st": "10.3.1"}, {"sp": "N", "t": "Ἔφορος δὲ τοὺς Αἰτωλοὺς εἰπὼν ἔθνος εἶναι μηδεπώποτε γεγενημένον ὑφ’ ἑτέροις, ἀλλὰ πάντα τὸν μνημονευόμενον χρόνον μεμενηκὸς ἀπόρθητον διά τε τὰς δυσχωρίας τῶν τόπων καὶ διὰ τὴν περὶ τὸν πόλεμον ἄσκησιν, ἐξ ἀρχῆς μέν φησιν ἅπασαν τὴν χώραν Κουρῆτας κατασχεῖν, ἀφικομένου δ’ ἐξ Ἤλιδος Αἰτωλοῦ τοῦ Ἐνδυμίωνος καὶ τοῖς πολέμοις κρατοῦντος αὐτῶν, τοὺς μὲν Κουρῆτας εἰς τὴν νῦν καλουμένην Ἀκαρνανίαν ὑποχωρῆσαι, τοὺς δ’ Αἰτωλοὺς συγκατελθόντας Ἐπειοῖς τὰς ἀρχαιοτάτας κτίσαι τῶν ἐν Αἰτωλίᾳ πόλεων, δεκάτῃ δ’ ὕστερον γενεᾷ τὴν Ἦλιν ὑπὸ Ὀξύλου τοῦ Αἵμονος συνοικισθῆναι περαιωθέντος ἐκ τῆς Αἰτωλίας. παρατίθησι δὲ τούτων μαρτύρια τὰ ἐπιγράμματα, τὸ μὲν ἐν Θέρμοις τῆς Αἰτωλίας, ὅπου τὰς ἀρχαιρεσίας ποιεῖσθαι πάτριον αὐτοῖς ἐστιν, ἐγκεχαραγμένον τῇ βάσει τῆς Αἰτωλοῦ εἰκόνος<br>χώρης οἰκιστῆρα, παρ’ Ἀλφειοῦ ποτε δίναις<br>θρεφθέντα, σταδίων γείτον’ Ὀλυμπιάδος,<br>Ἐνδυμίωνος παῖδ’ Αἰτωλὸν τόνδ’ ἀνέθηκαν<br>Αἰτωλοί, σφετέρας μνῆμ’ ἀρετῆς ἐσορᾶν.<br>τὸ δ’ ἐν τῇ ἀγορᾷ τῶν Ἠλείων ἐπὶ τῷ Ὀξύλου ἀνδριάντι<br>Αἰτωλός ποτε τόνδε λιπὼν αὐτόχθονα δῆμον<br>κτήσατο Κουρῆτιν γῆν δορὶ πολλὰ καμών·<br>τῆς δ’ αὐτῆς γενεᾶς δεκατόσπορος Αἵμονος υἱός<br>Ὄξυλος ἀρχαίην ἔκτισε τήνδε πόλιν.", "st": "10.3.2"}, {"sp": "N", "t": "τὴν μὲν οὖν συγγένειαν τὴν πρὸς ἀλλήλους τῶν τε Ἠλείων καὶ τῶν Αἰτωλῶν ὀρθῶς ἐπισημαίνεται διὰ τῶν ἐπιγραμμάτων, ἐξομολογουμένων ἀμφοῖν οὐ τὴν συγγένειαν μόνον ἀλλὰ καὶ τὸ ἀρχηγέτας ἀλλήλων εἶναι· δι’ οὗ καλῶς ἐξελέγχει ψευδομένους τοὺς φάσκοντας τῶν μὲν Αἰτωλῶν ἀποίκους εἶναι τοὺς Ἠλείους, μὴ μέντοι τῶν Ἠλείων τοὺς Αἰτωλούς. τὴν δ’ ἀνομολογίαν τῆς γραφῆς καὶ τῆς ἀποφάσεως φαίνεται τὴν αὐτὴν ἐπιδεδειγμένος κἀνταῦθα ἥνπερ ἐπὶ τοῦ μαντείου τοῦ ἐν Δελφοῖς παρεστήσαμεν. εἰπὼν γὰρ ἀπόρθητον ἐκ τοῦ μνημονευομένου χρόνου παντὸς τὴν Αἰτωλίαν, εἰπὼν δὲ καὶ ἐξ ἀρχῆς τὴν χώραν ταύτην τοὺς Κουρῆτας κατασχεῖν ὤφειλε μὲν τοῖς εἰρημένοις ἀκόλουθον τοῦτο [ἐπι]φέρειν, ὅτι οἱ Κουρῆτες διέμειναν ἕως εἰς αὐτὸν κατέχοντες τὴν Αἰτωλίαν γῆν· οὕτω γὰρ ἔμελλεν ἀπόρθητός τε καὶ οὐδέποτε ὑπ’ ἄλλοις γεγονυῖα ὀρθῶς λεχθήσεσθαι· ὁ δ’ ἐκλαθόμενος τῆς ὑποσχέσεως οὐ τοῦτ’ ἐπιφέρει ἀλλὰ τοὐναντίον, ὡς ἀφικομένου ἐξ Ἤλιδος Αἰτωλοῦ καὶ τοῖς πολέμοις κρατοῦντος αὐτῶν οἱ Κουρῆτες ἀπῆλθον εἰς τὴν Ἀκαρνανίαν· τί οὖν ἄλλο πορθήσεως ἴδιον ἢ τῷ πολέμῳ κρατηθῆναι καὶ τὴν χώραν ἐκλιπεῖν; τοῦτο δὲ καὶ τὸ ἐπίγραμμα μαρτυρεῖ τὸ παρὰ τοῖς Ἠλείοις· ὁ γὰρ Αἰτωλός φησί<br>κτήσατο Κουρῆτιν γῆν δορὶ πολλὰ καμών.", "st": "10.3.3"}, {"sp": "N", "t": "ἴσως δή τις ἂν φαίη λέγειν αὐτὸν ἀπόρθητον τὴν Αἰτωλίαν ἀφ’ οὗ τοὔνομα τοῦτ’ ἔσχε μετὰ τὴν Αἰτωλοῦ παρουσίαν· ἀλλ’ ἀφῄρηται καὶ [τούτου] τοῦ νοήματος τὸν λόγον, φήσας ἐν τοῖς ἐφεξῆς τὸ μὲν πλεῖστον τοῦ λαοῦ τοῦ διαμένοντος ἐν τοῖς Αἰτωλοῖς τοῦτο εἶναι τὸ τῶν Ἐπειῶν, συμμιχθέντων δ’ αὐτοῖς ὕστερον Αἰολέων τῶν ἅμα Βοιωτοῖς ἐκ Θετταλίας ἀναστάντων κοινῇ μετὰ τούτων τὴν χώραν κατασχεῖν. ἆρ’ οὖν ἔστι [πιστὸν] χωρὶς πολέμου τὴν ἀλλοτρίαν ἐπελθόντας συγκατανείμασθαι τοῖς ἔχουσι μηδὲν δεομένοις κοινωνίας τοιαύτης; ἢ τοῦτο μὲν οὐ πιστόν, τὸ δὲ κρατουμένοις τοῖς ὅπλοις ἐπ’ ἴσοις συμβῆναι πιστόν; τί οὖν ἄλλο πόρθησις ἢ τὸ κρατεῖσθαι τοῖς ὅπλοις; καὶ Ἀπολλόδωρος δ’ εἴρηκεν ἐκ τῆς Βοιωτίας ἐπελθόντας Ὕαντας ἱστορεῖσθαι καὶ ἐποίκους τοῖς Αἰτωλοῖς γενομένους· ὁ δ’ ὥσπερ κατωρθωκὼς ἐπιλέγει διότι ταῦτα καὶ τὰ τοιαῦτα διακριβοῦν εἰώθαμεν, ὅταν ᾖ τι τῶν πραγμάτων ἢ παντελῶς ἀπορούμενον ἢ ψευδῆ δόξαν ἔχον.", "st": "10.3.4"}, {"sp": "N", "t": "τοιοῦτος δ’ ὢν Ἔφορος ἑτέρων ὅμως κρείττων ἐστί· καὶ αὐτὸς ὁ ἐσπουδασμένως οὕτως ἐπαινέσας αὐτὸν Πολύβιος καὶ φήσας περὶ τῶν Ἑλληνικῶν καλῶς μὲν Εὔδοξον, κάλλιστα δ’ Ἔφορον ἐξηγεῖσθαι περὶ κτίσεων συγγενειῶν μεταναστάσεων ἀρχηγετῶν, ἡμεῖς δέ φησί τὰ νῦν ὄντα δηλώσομεν καὶ περὶ θέσεως τόπων καὶ διαστημάτων· τοῦτο γάρ ἐστιν οἰκειότατον χωρογραφίᾳ. ἀλλὰ μὴν σύ γε, ὦ Πολύβιε, ὁ τὰς λαοδογματικὰς ἀποφάσεις περὶ τῶν διαστημάτων εἰσάγων οὐκ ἐν τοῖς ἔξω τῆς Ἑλλάδος μόνον, ἀλλὰ καὶ ἐν τοῖς Ἑλληνικοῖς, καὶ διδοῖς εὐθύνας τὰς μὲν Ποσειδωνίῳ τὰς δ’ Ἀρτεμιδώρῳ τὰς δ’ ἄλλοις πλείοσι. καὶ ἡμῖν οὖν συγγνώμην … καὶ οὐ δυσχεραίνειν δεῖ παρὰ τῶν τοιούτων μεταφέρουσι τὴν πολλὴν ἱστορίαν ἐάν τι πταίωμεν, ἀλλ’ ἀγαπᾶν ἐὰν τὰ πλείω τῶν εἰρημένων ἑτέροις ἄμεινον λέγωμεν ἢ τὰ παραλειφθέντα κατ’ ἄγνοιαν προστιθῶμεν.", "st": "10.3.5"}, {"sp": "N", "t": "περὶ δὲ Κουρήτων ἔτι καὶ τοιαῦτα λέγεται, τὰ μὲν ἐγγυτέρω ὄντα τῆς περὶ Αἰτωλῶν καὶ Ἀκαρνάνων ἱστορίας τὰ δ’ ἀπωτέρω· ἐγγυτέρω μὲν τὰ τοιαῦτα οἷα προείρηται, ὅτι τὴν χώραν ἣ νῦν Αἰτωλία καλεῖται Κουρῆτες ᾤκουν, ἐλθόντες δ’ οἱ Αἰτωλοὶ μετὰ Αἰτωλοῦ τούτους ἐξέβαλον εἰς τὴν Ἀκαρνανίαν· καὶ ἔτι τὰ τοιαῦτα, ὅτι τὴν Πλευρωνίαν ὑπὸ Κουρήτων οἰκουμένην καὶ Κουρῆτιν προσαγορευομένην Αἰολεῖς ἐπελθόντες ἀφείλοντο, τοὺς δὲ κατέχοντας ἐξέβαλον. Ἀρχέμαχος δ’ ὁ Εὐβοεύς φησι τοὺς Κουρῆτας ἐν Χαλκίδι συνοικῆσαι, συνεχῶς δὲ περὶ τοῦ Ληλάντου πεδίου πολεμοῦντας, ἐπειδὴ οἱ πολέμιοι τῆς κόμης ἐδράττοντο τῆς ἔμπροσθεν καὶ κατέσπων αὐτούς, ὄπισθεν κομῶντας γενέσθαι, τὰ δ’ ἔμπροσθεν κείρεσθαι· διὸ καὶ Κουρῆτας ἀπὸ τῆς κουρᾶς κληθῆναι· μετοικῆσαι δ’ εἰς τὴν Αἰτωλίαν, καὶ κατασχόντας τὰ περὶ Πλευρῶνα χωρία τοὺς πέραν οἰκοῦντας τοῦ Ἀχελώου διὰ τὸ ἀκούρους φυλάττειν τὰς κεφαλὰς Ἀκαρνᾶνας καλέσαι· ἔνιοι δ’ ἀπὸ ἥρωος τοὔνομα σχεῖν ἑκάτερον τὸ φῦλον· οἱ δ’ ἀπὸ τοῦ ὄρους τοῦ Κουρίου τοὺς Κουρῆτας ὀνομασθῆναι τοῦ ὑπερκειμένου τῆς Πλευρῶνος, εἶναί τε φῦλόν τι Αἰτωλικὸν τοῦτο, ὡς Ὀφιεῖς καὶ Ἀγραίους καὶ Εὐρυτᾶνας καὶ ἄλλα πλείω. ὡς δ’ εἴρηται, τῆς Αἰτωλίας δίχα διῃρημένης τὰ μὲν περὶ Καλυδῶνα τὸν Οἰνέα ἔχειν φασί, τῆς δὲ Πλευρωνίας μέρος μέν τι καὶ τοὺς Πορθαονίδας ἔχειν τοὺς περὶ τὸν Ἄγριον, εἴπερ<br>ᾤκεον ἐν Πλευρῶνι καὶ αἰπεινῇ Καλυδῶνι.<br>ἐπικρατεῖν μέντοι Θέστιον τῆς Πλευρωνίας, τὸν πενθερὸν τοῦ Οἰνέως Ἀλθαίας δὲ πατέρα, ἡγούμενον τῶν Κουρήτων· πολέμου δ’ ἐμπεσόντος τοῖς Θεστιάδαις πρὸς Οἰνέα καὶ Μελέαγρον, ὡς μὲν ὁ ποιητής<br>ἀμφὶ συὸς κεφαλῇ καὶ δέρματι<br>κατὰ τὴν περὶ τοῦ κάπρου μυθολογίαν, ὡς δὲ τὸ εἰκὸς περὶ μέρος τῆς χώρας, οὕτω δὴ λέγεται<br>Κουρῆτές τ’ ἐμάχοντο καὶ Αἰτωλοὶ μενεχάρμαι.<br>ταῦτα μὲν τὰ ἐγγυτέρω.", "st": "10.3.6"}, {"sp": "N", "t": "τὰ δ’ ἀπωτέρω τῆς ὑποθέσεως ταύτης, ἄλλως δὲ διὰ τὴν ὁμωνυμίαν εἰς ταὐτὸν ὑπὸ τῶν ἱστορικῶν ἀγόμενα, ἅπερ Κουρητικὰ μὲν καὶ περὶ Κουρήτων λέγεται, ὁμοίως ὥσπερ καὶ τὰ περὶ τῶν τὴν Αἰτωλίαν καὶ τὴν Ἀκαρνανίαν οἰκησάντων, ἐκείνων μὲν διαφέρει, ἔοικε δὲ μᾶλλον τῷ περὶ Σατύρων καὶ Σειληνῶν καὶ Βακχῶν καὶ Τιτύρων λόγῳ· τοιούτους γάρ τινας δαίμονας ἢ προπόλους θεῶν τοὺς Κουρῆτάς φασιν οἱ παραδόντες τὰ Κρητικὰ καὶ τὰ Φρύγια, ἱερουργίαις τισὶν ἐμπεπλεγμένα ταῖς μὲν μυστικαῖς ταῖς δ’ ἄλλαις περί τε τὴν τοῦ Διὸς παιδοτροφίαν τὴν ἐν Κρήτῃ καὶ τοὺς τῆς μητρὸς τῶν θεῶν ὀργιασμοὺς ἐν τῇ Φρυγίᾳ καὶ τοῖς περὶ τὴν Ἴδην τὴν Τρωικὴν τόποις. τοσαύτη δ’ ἐστὶν ἐν τοῖς λόγοις τούτοις ποικιλία, τῶν μὲν τοὺς αὐτοὺς τοῖς Κουρῆσι τοὺς Κορύβαντας καὶ Καβείρους καὶ Ἰδαίους δακτύλους καὶ Τελχῖνας ἀποφαινόντων, τῶν δὲ συγγενεῖς ἀλλήλων καὶ μικράς τινας αὐτῶν πρὸς ἀλλήλους διαφορὰς διαστελλομένων, ὡς δὲ τύπῳ εἰπεῖν καὶ κατὰ τὸ πλέον, ἅπαντας ἐνθουσιαστικούς τινας καὶ βακχικοὺς καὶ ἐνοπλίῳ κινήσει μετὰ θορύβου καὶ ψόφου καὶ κυμβάλων καὶ τυμπάνων καὶ ὅπλων, ἔτι δ’ αὐλοῦ καὶ βοῆς ἐκπλήττοντας κατὰ τὰς ἱερουργίας ἐν σχήματι διακόνων, [ὥς]τε καὶ τὰ ἱερὰ τρόπον τινὰ κοινοποιεῖσθαι ταῦτά τε καὶ τῶν Σαμοθρᾴκων καὶ τὰ ἐν Λήμνῳ καὶ ἄλλα πλείω διὰ τὸ τοὺς προπόλους λέγεσθαι τοὺς αὐτούς. ἔστι μὲν οὖν θεολογικὸς πᾶς ὁ τοιοῦτος τρόπος τῆς ἐπισκέψεως καὶ οὐκ ἀλλότριος τῆς τοῦ φιλοσόφου θεωρίας.", "st": "10.3.7"}, {"sp": "N", "t": "ἐπεὶ δὲ δι’ ὁμωνυμίαν τῶν Κουρήτων καὶ οἱ ἱστορικοὶ συνήγαγον εἰς ἓν τὰ ἀνόμοια, οὐδ’ ἂν αὐτὸς ὀκνήσαιμ’ ἂν εἰπεῖν περὶ αὐτῶν ἐπὶ πλέον ἐν παραβάσει, προσθεὶς τὸν οἰκεῖον τῇ ἱστορίᾳ φυσικὸν λόγον. καίτοι τινὲς καὶ συνοικειοῦν βούλονται ταῦτ’ ἐκείνοις, καὶ τυχὸν ἴσως ἔχονταί τινος πιθανοῦ· θηλυστολοῦντας γὰρ ὡς αἱ κόραι τοὔνομα σχεῖν τοῦτο τοὺς περὶ τὴν Αἰτωλίαν φασίν· εἶναι γὰρ καί τινα τοιοῦτον ζῆλον ἐν τοῖς Ἕλλησι, καὶ Ἰάονας ἑλκεχίτωνας εἰρῆσθαι, καὶ τοὺς περὶ Λεωνίδαν κτενιζομένους, ὅτ’ ἐξῄεσαν εἰς τὴν μάχην, καταφρονηθῆναι λέγουσιν ὑπὸ τῶν Περσῶν, ἐν δὲ τῇ μάχῃ θαυμασθῆναι. ἁπλῶς δ’ ἡ περὶ τὰς κόμας φιλοτεχνία συνέστηκε περί τε θρέψιν καὶ κουρὰν τριχός, ἄμφω δὲ κόραις καὶ κόροις ἐστὶν οἰκεῖα, ὥστε πλεοναχῶς τὸ ἐτυμολογεῖν τοὺς Κουρῆτας ἐν εὐπόρῳ κεῖται. εἰκὸς δὲ καὶ τὴν ἐνόπλιον ὄρχησιν ὑπὸ τῶν ἠσκημένων οὕτω περὶ κόμην καὶ στολὴν πρῶτον εἰσαχθεῖσαν, ἐκείνων Κουρήτων καλουμένων, παρασχεῖν πρόφασιν καὶ τοῖς στρατιωτικωτέροις ἑτέρων καὶ τὸν βίον ἐνόπλιον ἔχουσιν, ὥσθ’ ὁμωνύμως καὶ αὐτοὺς Κουρῆτας λεχθῆναι, τοὺς ἐν Εὐβοίᾳ λέγω καὶ Αἰτωλίᾳ καὶ Ἀκαρνανίᾳ. καὶ Ὅμηρος δὲ τοὺς νέους στρατιώτας οὕτω προσηγόρευσε<br>κρινάμενος κούρητας ἀριστῆας Παναχαιῶν,<br>δῶρα θοῆς παρὰ νηὸς ἐνεγκεῖν, ὅσσ’ Ἀχιλῆι<br>χθιζοὶ ὑπέστημεν<br>καὶ πάλιν<br>δῶρα φέρον κούρητες Ἀχαιοί.<br>περὶ μὲν οὖν τῆς τῶν Κουρήτων ἐτυμολογίας ταῦτα.", "st": "10.3.8"}, {"sp": "N", "t": "τὸ δ’ εἰς ἓν συμφέρεσθαι τὰ τοσαῦτα ὀνόματα καὶ τὴν ἐνοῦσαν θεολογίαν ἐν τῇ περὶ αὐτῶν ἱστορίᾳ νῦν ἐπισκεπτέον. κοινὸν δὴ τοῦτο καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων ἐστὶ τὸ τὰς ἱεροποιίας μετὰ ἀνέσεως ἑορταστικῆς ποιεῖσθαι, τὰς μὲν σὺν ἐνθουσιασμῷ τὰς δὲ χωρίς, καὶ τὰς μὲν μετὰ μουσικῆς τὰς δὲ μή, καὶ τὰς μὲν μυστικῶς τὰς δὲ ἐν φανερῷ· καὶ τοῦθ’ ἡ φύσις οὕτως ὑπαγορεύει. ἥ τε γὰρ ἄνεσις τὸν νοῦν ἀπάγει ἀπὸ τῶν ἀνθρωπικῶν ἀσχολημάτων, τὸν δὲ ὄντως νοῦν τρέπει πρὸς τὸ θεῖον· ὅ τε ἐνθουσιασμὸς ἐπίπνευσίν τινα θείαν ἔχειν δοκεῖ καὶ τῷ μαντικῷ γένει πλησιάζειν· ἥ τε κρύψις ἡ μυστικὴ τῶν ἱερῶν σεμνοποιεῖ τὸ θεῖον, μιμουμένη τὴν φύσιν αὐτοῦ φεύγουσαν ἡμῶν τὴν αἴσθησιν· ἥ τε μουσικὴ περί τε ὄρχησιν οὖσα καὶ ῥυθμὸν καὶ μέλος ἡδονῇ τε ἅμα καὶ καλλιτεχνίᾳ πρὸς τὸ θεῖον ἡμᾶς συνάπτει κατὰ τοιαύτην αἰτίαν. εὖ μὲν γὰρ εἴρηται καὶ τοῦτο, τοὺς ἀνθρώπους τότε μάλιστα μιμεῖσθαι τοὺς θεοὺς ὅταν εὐεργετῶσιν· ἄμεινον δ’ ἂν λέγοι τις, ὅταν εὐδαιμονῶσι· τοιοῦτον δὲ τὸ χαίρειν καὶ τὸ ἑορτάζειν καὶ τὸ φιλοσοφεῖν καὶ μουσικῆς ἅπτεσθαι· μὴ γὰρ εἴ τις ἔκπτωσις πρὸς τὸ χεῖρον [γε]γένηται, τῶν μουσικῶν εἰς ἡδυπαθείας τρεπόντων τὰς τέχνας ἐν τοῖς συμποσίοις καὶ θυμέλαις καὶ σκηναῖς καὶ ἄλλοις τοιούτοις, διαβαλλέσθω τὸ πρᾶγμα, ἀλλ’ ἡ φύσις ἡ τῶν παιδευμάτων ἐξεταζέσθω τὴν ἀρχὴν ἐνθένδε ἔχουσα.", "st": "10.3.9"}, {"sp": "N", "t": "καὶ διὰ τοῦτο μουσικὴν ἐκάλεσε Πλάτων καὶ ἔτι πρότερον οἱ Πυθαγόρειοι τὴν φιλοσοφίαν, καὶ καθ’ ἁρμονίαν τὸν κόσμον συνεστάναι φασί, πᾶν τὸ μουσικὸν εἶδος θεῶν ἔργον ὑπολαμβάνοντες. οὕτω δὲ καὶ αἱ Μοῦσαι θεαὶ καὶ Ἀπόλλων μουσηγέτης καὶ ἡ ποιητικὴ πᾶσα ὑμνητική. ὡσαύτως δὲ καὶ τὴν τῶν ἠθῶν κατασκευὴν τῇ μουσικῇ προσνέμουσιν, ὡς πᾶν τὸ ἐπανορθωτικὸν τοῦ νοῦ τοῖς θεοῖς ἐγγὺς ὄν. οἱ μὲν οὖν Ἕλληνες οἱ πλεῖστοι τῷ Διονύσῳ προσέθεσαν καὶ τῷ Ἀπόλλωνι καὶ τῇ Ἑκάτῃ καὶ ταῖς Μούσαις καὶ Δήμητρι, νὴ Δία, τὸ ὀργιαστικὸν πᾶν καὶ τὸ βακχικὸν καὶ τὸ χορικὸν καὶ τὸ περὶ τὰς τελετὰς μυστικόν, Ἴακχόν τε καὶ τὸν Διόνυσον καλοῦσι καὶ τὸν ἀρχηγέτην τῶν μυστηρίων, τῆς Δήμητρος δαίμονα· δενδροφορίαι τε καὶ χορεῖαι καὶ τελεταὶ κοιναὶ τῶν θεῶν εἰσι τούτων· αἱ δὲ Μοῦσαι καὶ ὁ Ἀπόλλων αἱ μὲν τῶν χορῶν προεστᾶσιν ὁ δὲ καὶ τούτων καὶ τῶν κατὰ μαντικήν· πρόπολοι δὲ τῶν Μουσῶν οἱ πεπαιδευμένοι πάντες, καὶ ἰδίως οἱ μουσικοί, τοῦ δ’ Ἀπόλλωνος οὗτοί τε καὶ οἱ περὶ μαντικήν, Δήμητρος δὲ οἵ τε μύσται καὶ δᾳδοῦχοι καὶ ἱεροφάνται, Διονύσου δὲ Σειληνοί τε καὶ Σάτυροι καὶ Τίτυροι καὶ Βάκχαι, Λῆναί τε καὶ Θυῖαι καὶ Μιμαλλόνες καὶ Ναΐδες καὶ Νύμφαι προσαγορευόμεναι.", "st": "10.3.10"}, {"sp": "N", "t": "ἐν δὲ τῇ Κρήτῃ καὶ ταῦτα καὶ τὰ τοῦ Διὸς ἱερὰ ἰδίως ἐπετελεῖτο μετ’ ὀργιασμοῦ καὶ τοιούτων προπόλων οἷοι περὶ τὸν Διόνυσόν εἰσιν οἱ Σάτυροι· τούτους δ’ ὠνόμαζον Κουρῆτας, νέους τινὰς ἐνόπλιον κίνησιν μετ’ ὀρχήσεως ἀποδιδόντας, προστησάμενοι μῦθον τὸν περὶ τῆς τοῦ Διὸς γενέσεως, ἐν ᾧ τὸν μὲν Κρόνον εἰσάγουσιν εἰθισμένον καταπίνειν τὰ τέκνα ἀπὸ τῆς γενέσεως εὐθύς, τὴν δὲ Ῥέαν πειρωμένην ἐπικρύπτεσθαι τὰς ὠδῖνας καὶ τὸ γεννηθὲν βρέφος ἐκποδὼν ποιεῖν καὶ περισώζειν εἰς δύναμιν, πρὸς δὲ τοῦτο συνεργοὺς λαβεῖν τοὺς Κουρῆτας, οἳ μετὰ τυμπάνων καὶ τοιούτων ἄλλων ψόφων καὶ ἐνοπλίου χορείας καὶ θορύβου περιέποντες τὴν θεὸν ἐκπλήξειν ἔμελλον τὸν Κρόνον καὶ λήσειν ὑποσπάσαντες αὐτοῦ τὸν παῖδα, τῇ δ’ αὐτῇ ἐπιμελείᾳ καὶ τρεφόμενον ὑπ’ αὐτῶν παραδίδοσθαι· ὥσθ’ οἱ Κουρῆτες ἤτοι διὰ τὸ νέοι καὶ κόροι ὄντες ὑπουργεῖν ἢ διὰ τὸ κουροτροφεῖν τὸν Δία (λέγεται γὰρ ἀμφοτέρως) ταύτης ἠξιώθησαν τῆς προσηγορίας, οἱονεὶ Σάτυροί τινες ὄντες περὶ τὸν Δία. οἱ μὲν οὖν Ἕλληνες τοιοῦτοι περὶ τοὺς ὀργιασμούς.", "st": "10.3.11"}, {"sp": "N", "t": "οἱ δὲ Βερέκυντες Φρυγῶν τι φῦλον καὶ ἁπλῶς οἱ Φρύγες καὶ τῶν Τρώων οἱ περὶ τὴν Ἴδην κατοικοῦντες Ῥέαν μὲν καὶ αὐτοὶ τιμῶσι καὶ ὀργιάζουσι ταύτῃ, μητέρα καλοῦντες θεῶν καὶ Ἄγδιστιν καὶ Φρυγίαν θεὸν μεγάλην, ἀπὸ δὲ τῶν τόπων Ἰδαίαν καὶ Δινδυμήνην καὶ Σιπυληνὴν καὶ Πεσσινουντίδα καὶ Κυβέλην [καὶ Κυβήβην]. οἱ δ’ Ἕλληνες τοὺς προπόλους αὐτῆς ὁμωνύμως Κουρῆτας λέγουσιν, οὐ μήν γε ἀπὸ τῆς αὐτῆς μυθοποιίας, ἀλλ’ ἑτέρους ὡς ἂν ὑπουργούς τινας, τοῖς Σατύροις ἀνὰ λόγον· τοὺς δ’ αὐτοὺς καὶ Κορύβαντας καλοῦσι.", "st": "10.3.12"}, {"sp": "N", "t": "μάρτυρες δ’ οἱ ποιηταὶ τῶν τοιούτων ὑπονοιῶν· ὅ τε γὰρ Πίνδαρος ἐν τῷ διθυράμβῳ οὗ ἡ ἀρχή<br>πρὶν μὲν εἷρπε σχοινοτένεια τ’ ἀοιδὰ<br>διθυράμβων,<br>μνησθεὶς τῶν περὶ τὸν Διόνυσον ὕμνων τῶν τε παλαιῶν καὶ τῶν ὕστερον, μεταβὰς ἀπὸ τούτων φησί<br>σοὶ μὲν κατάρχειν,<br>μᾶτερ μεγάλα, πάρα ῥόμβοι κυμβάλων,<br>ἐν δὲ κεχλάδειν κρόταλ’, αἰθομένα τε<br>δᾲς ὑπὸ ξανθαῖσι πεύκαις,<br>τὴν κοινωνίαν τῶν περὶ τὸν Διόνυσον ἀποδειχθέντων νομίμων παρὰ τοῖς Ἕλλησι καὶ τῶν παρὰ τοῖς Φρυξὶ περὶ τὴν μητέρα τῶν θεῶν συνοικειῶν ἀλλήλοις. Εὐριπίδης τε ἐν ταῖς Βάκχαις τὰ παραπλήσια ποιεῖ, τοῖς Φρυγίοις ἅμα καὶ τὰ Λύδια συμφέρων διὰ τὸ ὅμορον<br>ἀλλ’ ὦ λιποῦσαι Τμῶλον, ἔρυμα Λυδίας,<br>θίασος ἐμὸς γυναῖκες, [ἃς ἐκ βαρβάρων]<br>[ἐκόμισα παρέδρους καὶ ξυνεμπόρους ἐμοί,]<br>[αἴρεσθε τἀπιχώρι’ ἐν πόλει Φρυγῶν]<br>[τύμπανα, Ῥέας τε μητρὸς] ἐμά θ’ εὑρήματα<br>καὶ πάλιν<br>ὦ μάκαρ, ὅστις εὐδαίμων [τελετὰς θεῶν]<br>[εἰδώς], βιοτὰν ἁγιστεύει.<br>τά τε ματρὸς μεγάλας ὄργια Κυβέλας θεμιστεύων<br>ἀνὰ θύρσον τε τινάσσων, κισσῷ [τε] στεφανωθεὶς<br>[Διόνυσον] θεραπεύει.<br>ἴτε Βάκχαι, [ἴτε Βάκχαι,] βρόμιον παῖδα θεὸν θεοῦ<br>Διόνυσον κατάγουσαι Φρυγίων ἐξ ὀρέων<br>Ἑλλάδος εἰς εὐρυχόρους ἀγυιάς.<br>πάλιν δ’ ἐν τοῖς ἑξῆς καὶ τὰ Κρητικὰ συμπλέκει τούτοις<br>ὦ θαλάμευμα Κουρήτων, ζάθεοί τε Κρήτας<br>διογενέτορες ἔναυλοι,<br>ἔνθα τρικόρυθες ἄντροις<br>βυρσότονον κύκλωμα τόδε<br>μοι Κορύβαντες εὗρον.<br>ἀνὰ δὲ βακχεῖα συντόνῳ<br>κέρασαν ἁδυβόᾳ Φρυγίων<br>αὐλῶν πνεύματι, ματρός τε Ῥέας<br>εἰς χέρα θῆκαν κτύπον εὐάσμασι Βακχᾶν,<br>παρὰ δὲ μαινόμενοι Σάτυροι<br>ματέρος ἐξανύσαντο Ῥέας.<br>εἰς δὲ χορεύματα<br>προσῆψαν τριετηρίδων,<br>αἷς χαίρει Διόνυσος.<br>καὶ ἐν Παλαμήδει φησὶν ὁ χορός<br>Θύσαν Διονύσου<br>κόραν, ὃς ἀν’ Ἴδαν<br>τέρπεται σὺν ματρὶ φίλᾳ<br>τυμπάνων ἐπ’ ἰακχαῖς.", "st": "10.3.13"}, {"sp": "N", "t": "καὶ Σειληνὸν καὶ Μαρσύαν καὶ Ὄλυμπον συνάγοντες εἰς ἓν καὶ εὑρετὰς αὐλῶν ἱστοροῦντες πάλιν καὶ οὕτως τὰ Διονυσιακὰ καὶ Φρύγια εἰς ἓν συμφέρουσι, τήν τε Ἴδην καὶ τὸν Ὄλυμπον συγκεχυμένως πολλάκις ὡς τὸ αὐτὸ ὄρος κτυποῦσιν. εἰσὶ μὲν οὖν λόφοι τέτταρες Ὄλυμποι καλούμενοι τῆς Ἴδης κατὰ τὴν Ἀντανδρίαν, ἔστι δὲ καὶ ὁ Μυσὸς Ὄλυμπος, ὅμορος μὲν οὐχ ὁ αὐτὸς δὲ τῇ Ἴδῃ. ὁ δ’ οὖν Σοφοκλῆς ποιήσας τὸν Μενέλαον ἐκ τῆς Τροίας ἀπαίρειν σπεύδοντα ἐν τῇ Πολυξένῃ, τὸν δ’ Ἀγαμέμνονα μικρὸν ὑπολειφθῆναι βουλόμενον τοῦ ἐξιλάσασθαι τὴν Ἀθηνᾶν χάριν, εἰσάγει λέγοντα τὸν Μενέλαον<br>σὺ δ’ αὖθι μίμνων που κατ’ Ἰδαίαν χθόνα<br>ποίμνας Ὀλύμπου συναγαγὼν θυηπόλει.", "st": "10.3.14"}, {"sp": "N", "t": "τῷ δ’ αὐλῷ καὶ κτύπῳ κροτάλων τε καὶ κυμβάλων καὶ τυμπάνων καὶ ταῖς ἐπιβοήσεσι καὶ εὐασμοῖς καὶ ποδοκρουστίαις οἰκεῖα ἐξεύροντο καί τινα τῶν ὀνομάτων, ἃ τοὺς προπόλους καὶ χορευτὰς καὶ θεραπευτὰς τῶν ἱερῶν ἐκάλουν, Καβείρους καὶ Κορύβαντας καὶ Πᾶνας καὶ Σατύρους καὶ Τιτύρους καὶ τὸν θεὸν Βάκχον καὶ τὴν Ῥέαν Κυβέλην καὶ Κυβήβην καὶ Δινδυμήνην κατὰ τοὺς τόπους αὐτούς. καὶ ὁ Σαβάζιος δὲ τῶν Φρυγιακῶν ἐστι καὶ τρόπον τινὰ τῆς μητρὸς τὸ παιδίον παραδοὺς τὰ τοῦ Διονύσου καὶ αὐτός.", "st": "10.3.15"}, {"sp": "N", "t": "τούτοις δ’ ἔοικε καὶ τὰ παρὰ τοῖς Θρᾳξὶ τά τε Κοτύττια καὶ τὰ Βενδίδεια, παρ’ οἷς καὶ τὰ Ὀρφικὰ τὴν καταρχὴν ἔσχε. τῆς μὲν οὖν Κότυος τῆς ἐν τοῖς Ἠδωνοῖς Αἰσχύλος μέμνηται καὶ τῶν περὶ αὐτὴν ὀργάνων. εἰπὼν γάρ<br>σεμνὰ Κότυς ἐν τοῖς Ἠδωνοῖς<br>ὄρεια δ’ ὄργαν’ ἔχοντες,<br>τοὺς περὶ τὸν Διόνυσον εὐθέως ἐπιφέρει<br>ὁ μὲν ἐν χερσὶν<br>βόμβυκας ἔχων, τόρνου κάματον,<br>δακτυλόδικτον πίμπλησι μέλος,<br>μανίας ἐπαγωγὸν ὁμοκλάν·<br>ὁ δὲ χαλκοδέτοις κοτύλαις ὀτοβεῖ.<br>καὶ πάλιν<br>ψαλμὸς δ’ ἀλαλάζει·<br>ταυρόφθογγοι δ’ ὑπομυκῶνται<br>ποθὲν ἐξ ἀφανοῦς φοβεροὶ μῖμοι,<br>τυπάνου δ’ εἰκὼν ὥσθ’ ὑπογαίου<br>βροντῆς φέρεται βαρυταρβής.<br>ταῦτα γὰρ ἔοικε τοῖς Φρυγίοις· καὶ οὐκ ἀπεικός γε, ὥσπερ αὐτοὶ οἱ Φρύγες Θρᾳκῶν ἄποικοί εἰσιν, οὕτω καὶ τὰ ἱερὰ ἐκεῖθεν μετενηνέχθαι. καὶ τὸν Διόνυσον δὲ καὶ τὸν Ἠδωνὸν Λυκοῦργον συνάγοντες εἰς ἓν τὴν ὁμοιοτροπίαν τῶν ἱερῶν αἰνίττονται.", "st": "10.3.16"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ μέλους καὶ τοῦ ῥυθμοῦ καὶ τῶν ὀργάνων καὶ ἡ μουσικὴ πᾶσα Θρᾳκία καὶ Ἀσιᾶτις νενόμισται. δῆλον δ’ ἔκ τε τῶν τόπων ἐν οἷς αἱ Μοῦσαι τετίμηνται· Πιερία γὰρ καὶ Ὄλυμπος καὶ Πίμπλα καὶ Λείβηθρον τὸ παλαιὸν ἦν Θρᾴκια χωρία καὶ ὄρη, νῦν δὲ ἔχουσι Μακεδόνες· τόν τε Ἑλικῶνα καθιέρωσαν ταῖς Μούσαις Θρᾷκες οἱ τὴν Βοιωτίαν ἐποικήσαντες, οἵπερ καὶ τὸ τῶν Λειβηθριάδων νυμφῶν ἄντρον καθιέρωσαν. οἵ τ’ ἐπιμεληθέντες τῆς ἀρχαίας μουσικῆς Θρᾷκες λέγονται, Ὀρφεύς τε καὶ Μουσαῖος καὶ Θάμυρις, καὶ τῷ Εὐμόλπῳ δὲ τοὔνομα ἐνθένδε, καὶ οἱ τῷ Διονύσῳ τὴν Ἀσίαν ὅλην καθιερώσαντες μέχρι τῆς Ἰνδικῆς ἐκεῖθεν καὶ τὴν πολλὴν μουσικὴν μεταφέρουσι· καὶ ὁ μέν τίς φησιν “κιθάραν Ἀσιᾶτιν ῥάσσων,” ὁ δὲ τοὺς αὐλοὺς Βερεκυντίους καλεῖ καὶ Φρυγίους· καὶ τῶν ὀργάνων ἔνια βαρβάρως ὠνόμασται νάβλας καὶ σαμβύκη καὶ βάρβιτος καὶ μαγάδις καὶ ἄλλα πλείω.", "st": "10.3.17"}, {"sp": "N", "t": "Ἀθηναῖοι δ’ ὥσπερ περὶ τὰ ἄλλα φιλοξενοῦντες διατελοῦσιν, οὕτω καὶ περὶ τοὺς θεούς. πολλὰ γὰρ τῶν ξενικῶν ἱερῶν παρεδέξαντο ὥστε καὶ ἐκωμῳδήθησαν· καὶ δὴ καὶ τὰ Θρᾴκια καὶ τὰ Φρύγια. τῶν μὲν γὰρ Βενδιδείων Πλάτων μέμνηται, τῶν δὲ Φρυγίων Δημοσθένης διαβάλλων τὴν Αἰσχίνου μητέρα καὶ αὐτὸν ὡς τελούσῃ τῇ μητρὶ συνόντα καὶ συνθιασεύοντα καὶ ἐπιφθεγγόμενον “εὐοῖ σαβοῖ” πολλάκις καὶ “ὕης ἄττης [ἄττης] ὕης.” ταῦτα γάρ ἐστι σαβάζια καὶ μητρῷα.", "st": "10.3.18"}, {"sp": "N", "t": "ἔτι δ’ ἄν τις καὶ ταῦτα [εὕροι] περὶ τῶν δαιμόνων τούτων καὶ τῆς τῶν ὀνομάτων ποικιλίας, καὶ ὅτι οὐ πρόπολοι θεῶν μόνον ἀλλὰ καὶ αὐτοὶ θεοὶ προσηγορεύθησαν. Ἡσίοδος μὲν γὰρ Ἑκατέρου καὶ τῆς Φορωνέως θυγατρὸς πέντε γενέσθαι θυγατέρας φησίν<br>ἐξ ὧν οὔρειαι Νύμφαι θεαὶ [ἐξ]εγένοντο,<br>καὶ γένος οὐτιδανῶν Σατύρων καὶ ἀμηχανοεργῶν,<br>Κουρῆτές τε θεοὶ φιλοπαίγμονες ὀρχηστῆρες.<br>ὁ δὲ τὴν Φορωνίδα γράψας αὐλητὰς καὶ Φρύγας τοὺς Κουρῆτας λέγει, ἄλλοι δὲ γηγενεῖς καὶ χαλκάσπιδας· οἱ δ’ οὐ τοὺς Κουρῆτας, ἀλλὰ τοὺς Κορύβαντας Φρύγας, ἐκείνους δὲ Κρῆτας, περιθέσθαι δ’ ὅπλα χαλκᾶ πρώτους ἐν Εὐβοίᾳ· διὸ καὶ Χαλκιδέας αὐτοὺς κληθῆναι· οἱ δ’ ὑπὸ Τιτάνων Ῥέᾳ δοθῆναι προπόλους ἐνόπλους τοὺς Κορύβαντας ἐκ τῆς Βακτριανῆς ἀφιγμένους, οἱ δ’ ἐκ Κόλχων φασίν. ἐν δὲ τοῖς Κρητικοῖς λόγοις οἱ Κουρῆτες Διὸς τροφεῖς λέγονται καὶ φύλακες, εἰς Κρήτην ἐκ Φρυγίας μεταπεμφθέντες ὑπὸ τῆς Ῥέας· οἱ δὲ Τελχίνων ἐν Ῥόδῳ ἐννέα ὄντων τοὺς Ῥέᾳ συνακολουθήσαντας εἰς Κρήτην καὶ τὸν Δία κουροτροφήσαντας Κουρῆτας ὀνομασθῆναι· Κύρβαντα δὲ τούτων ἑταῖρον Ἱεραπύτνης ὄντα κτίστην παρὰ τοῖς Ῥοδίοις παρασχεῖν πρόφασιν τοῖς Πρασίοις ὥστε λέγειν, ὡς εἶεν Κορύβαντες δαίμονές τινες Ἀθηνᾶς καὶ Ἡλίου παῖδες. ἔτι δὲ Κρόνου τινές, ἄλλοι δὲ Διὸς καὶ Καλλιόπης φασὶ τοὺς Κορύβαντας τοὺς αὐτοὺς τοῖς Καβείροις ὄντας, ἀπελθεῖν δὲ τούτους εἰς Σαμοθρᾴκην καλουμένην πρότερον Μελίτην, τὰς δὲ πράξεις αὐτῶν μυστικὰς εἶναι.", "st": "10.3.19"}, {"sp": "N", "t": "ταῦτα δ’ οὐκ ἀποδεξάμενος ὁ Σκήψιος ὁ τοὺς μύθους συναγαγὼν τούτους, ὡς μηδενὸς ἐν Σαμοθρᾴκῃ μυστικοῦ λόγου περὶ Καβείρων λεγομένου, παρατίθησιν ὁμοίως καὶ Στησιμβρότου τοῦ Θασίου δόξαν, ὡς τὰ ἐν Σαμοθρᾴκῃ ἱερὰ τοῖς Καβείροις ἐπιτελοῖτο· καλεῖσθαι δέ φησιν αὐτοὺς ἐκεῖνος ἀπὸ τοῦ ὄρους τοῦ ἐν τῇ Βερεκυντίᾳ Καβείρου. οἱ δ’ Ἑκάτης προπόλους νομίζουσι τοὺς Κουρῆτας τοὺς αὐτοὺς τοῖς Κορύβασιν ὄντας. φησὶ δὲ πάλιν ὁ Σκήψιος ἐν τῇ Κρήτῃ τὰς τῆς Ῥέας τιμὰς μὴ νομίζεσθαι μηδὲ ἐπιχωριάζειν, ὑπεναντιούμενος τῷ τοῦ Εὐριπίδου λόγῳ, ἀλλ’ ἐν τῇ Φρυγίᾳ μόνον καὶ τῇ Τρῳάδι, τοὺς δὲ λέγοντας μυθολογεῖν μᾶλλον ἢ ἱστορεῖν, πρὸς τοῦτο δὲ καὶ τὴν τῶν τόπων ὁμωνυμίαν συμπρᾶξαι τυχὸν ἴσως αὐτοῖς· Ἴδη γὰρ τὸ ὄρος τό τε Τρωικὸν καὶ τὸ Κρητικόν, καὶ Δίκτη τόπος ἐν τῇ Σκηψίᾳ καὶ ὄρος ἐν Κρήτῃ· τῆς δὲ Ἴδης λόφος Πύτνα … ἀφ’ οὗ Ἱεράπυτνα ἡ πόλις, Ἱπποκόρωνά τε τῆς Ἀδραμυττηνῆς καὶ Ἱπποκορώνιον ἐν Κρήτῃ, Σαμώνιόν τε τὸ ἑωθινὸν ἀκρωτήριον τῆς νήσου καὶ πεδίον ἐν τῇ Νεανδρίδι καὶ τῇ Ἀλεξανδρέων.", "st": "10.3.20"}, {"sp": "N", "t": "Ἀκουσίλαος δ’ ὁ Ἀργεῖος ἐκ Καβειροῦς καὶ Ἡφαίστου Κάμιλλον λέγει, τοῦ δὲ τρεῖς Καβείρους, ὧν νύμφας Καβειρίδας· Φερεκύδης δ’ ἐξ Ἀπόλλωνος καὶ Ῥητίας Κύρβαντας ἐννέα, οἰκῆσαι δ’ αὐτοὺς ἐν Σαμοθρᾴκῃ· ἐκ δὲ Καβειροῦς τῆς Πρωτέως καὶ Ἡφαίστου Καβείρους τρεῖς καὶ νύμφας τρεῖς Καβειρίδας, ἑκατέροις δ’ ἱερὰ γίνεσθαι. μάλιστα μὲν οὖν ἐν Ἴμβρῳ καὶ Λήμνῳ τοὺς Καβείρους τιμᾶσθαι συμβέβηκεν, ἀλλὰ καὶ ἐν Τροίᾳ κατὰ πόλεις· τὰ δ’ ὀνόματα αὐτῶν ἐστι μυστικά. Ἡρόδοτος δὲ καὶ ἐν Μέμφει λέγει τῶν Καβείρων ἱερὰ καθάπερ καὶ τοῦ Ἡφαίστου, διαφθεῖραι δ’ αὐτὰ Καμβύσην. ἔστι δ’ ἀοίκητα τὰ χωρία τῆς τῶν δαιμόνων τούτων τιμῆς, τό τε Κορυβαντεῖον τὸ ἐν τῇ Ἁμαξιτίᾳ τῆς νῦν Ἀλεξανδρέων χώρας ἐγγὺς τοῦ Σμινθίου, καὶ ἡ Κορύβισσα ἐν τῇ Σκηψίᾳ περὶ ποταμὸν Εὐρήεντα καὶ κώμην ὁμώνυμον καὶ ἔτι χείμαρρον Αἰθαλόεντα. πιθανὸν δέ φησιν ὁ Σκήψιος, Κουρῆτας μὲν καὶ Κορύβαντας εἶναι τοὺς αὐτούς, οἳ περὶ τὰς τῆς μητρὸς τῶν θεῶν ἁγιστείας πρὸς ἐνόπλιον ὄρχησιν ᾔθεοι καὶ κόροι τυγχάνουσι παρειλημμένοι. καὶ Κορύβαντες δὲ ἀπὸ τοῦ κορύπτοντας βαίνειν ὀρχηστικῶς, οὓς καὶ βητάρμονας λέγει ὁ ποιητής<br>δεῦτ’ ἄγε Φαιήκων βητάρμονες, ὅσσοι ἄριστοι.<br>τῶν δὲ Κορυβάντων ὀρχηστικῶν καὶ ἐνθουσιαστικῶν ὄντων καὶ τοὺς μανικῶς κινουμένους κορυβαντιᾶν φαμεν.", "st": "10.3.21"}, {"sp": "N", "t": "δακτύλους δ’ Ἰδαίους φασί τινες κεκλῆσθαι τοὺς πρώτους οἰκήτορας τῆς κατὰ τὴν Ἴδην ὑπωρείας· πόδας μὲν γὰρ λέγεσθαι τὰς ὑπωρείας, κορυφὰς δὲ τὰ ἄκρα τῶν ὀρῶν· αἱ οὖν κατὰ μέρος ἐσχατιαὶ καὶ πᾶσαι τῆς μητρὸς τῶν θεῶν ἱεραὶ περὶ τὴν Ἴδην … Σοφοκλῆς δὲ οἴεται πέντε τοὺς πρώτους ἄρσενας γενέσθαι, οἳ σίδηρόν τε ἐξεῦρον καὶ εἰργάσαντο πρῶτοι καὶ ἄλλα πολλὰ τῶν πρὸς τὸν βίον χρησίμων, πέντε δὲ καὶ ἀδελφὰς τούτων, ἀπὸ δὲ τοῦ ἀριθμοῦ δακτύλους κληθῆναι. ἄλλοι δ’ ἄλλως μυθεύουσιν ἀπόροις ἄπορα συνάπτοντες, διαφόροις δὲ καὶ τοῖς ὀνόμασι καὶ τοῖς ἀριθμοῖς χρῶνται, ὧν Κέλμιν ὀνομάζουσί τινα καὶ Δαμναμενέα καὶ Ἡρακλέα καὶ Ἄκμονα· καὶ οἱ μὲν ἐπιχωρίους τῆς Ἴδης οἱ δὲ ἐποίκους, πάντες δὲ σίδηρον εἰργάσθαι ὑπὸ τούτων ἐν Ἴδῃ πρῶτόν φασι, πάντες δὲ καὶ γόητας ὑπειλήφασι καὶ περὶ τὴν μητέρα τῶν θεῶν καὶ ἐν Φρυγίᾳ ᾠκηκότας περὶ τὴν Ἴδην, Φρυγίαν τὴν Τρῳάδα καλοῦντες διὰ τὸ τοὺς Φρύγας ἐπικρατῆσαι πλησιοχώρους ὄντας τῆς Τροίας ἐκπεπορθημένης. ὑπονοοῦσι δὲ τῶν Ἰδαίων δακτύλων ἐκγόνους εἶναι τούς τε Κουρῆτας καὶ τοὺς Κορύβαντας· τοὺς γοῦν πρώτους γεννηθέντας ἐν Κρήτῃ ἑκατὸν ἄνδρας Ἰδαίους δακτύλους κληθῆναι, τούτων δ’ ἀπογόνους φασὶ Κουρῆτας ἐννέα γενέσθαι, τούτων δ’ ἕκαστον δέκα παῖδας τεκνῶσαι τοὺς Ἰδαίους καλουμένους δακτύλους.", "st": "10.3.22"}, {"sp": "N", "t": "προήχθημεν δὲ διὰ πλειόνων εἰπεῖν περὶ τούτων καίπερ ἥκιστα φιλομυθοῦντες, ὅτι τοῦ θεολογικοῦ γένους ἐφάπτεται τὰ πράγματα ταῦτα. πᾶς δὲ ὁ περὶ τῶν θεῶν λόγος ἀρχαίας ἐξετάζει δόξας καὶ μύθους, αἰνιττομένων τῶν παλαιῶν ἃς εἶχον ἐννοίας φυσικὰς περὶ τῶν πραγμάτων καὶ προστιθέντων ἀεὶ τοῖς λόγοις τὸν μῦθον. ἅπαντα μὲν οὖν τὰ αἰνίγματα λύειν ἐπ’ ἀκριβὲς οὐ ῥᾴδιον, τοῦ δὲ πλήθους τῶν μυθευομένων ἐκτεθέντος εἰς τὸ μέσον, τῶν μὲν ὁμολογούντων ἀλλήλοις τῶν δ’ ἐναντιουμένων, εὐπορώτερον ἄν τις δύναιτο εἰκάζειν ἐξ αὐτῶν τἀληθές· οἷον τὰς ὀρειβασίας τῶν περὶ τὸ θεῖον σπουδαζόντων καὶ αὐτῶν τῶν θεῶν καὶ τοὺς ἐνθουσιασμοὺς εἰκότως μυθεύουσι κατὰ τὴν αὐτὴν αἰτίαν καθ’ ἣν καὶ οὐρανίους νομίζουσι τοὺς θεοὺς καὶ προνοητικοὺς τῶν τε ἄλλων καὶ τῶν προσημασιῶν· τῇ μὲν οὖν ὀρειβασίᾳ τὸ μεταλλευτικὸν καὶ τὸ θηρευτικὸν [καὶ] ζητητικὸν τῶν πρὸς τὸν βίον χρησίμων ἐφάνη συγγενές, τῶν δ’ ἐνθουσιασμῶν καὶ θρησκείας καὶ μαντικῆς τὸ ἀγυρτικὸν καὶ γοητεία ἐγγύς. τοιοῦτον δὲ καὶ τὸ φιλότεχνον μάλιστα τὸ περὶ τὰς Διονυσιακὰς τέχνας καὶ τὰς Ὀρφικάς. ἀλλ’ ἀπόχρη περὶ αὐτῶν.", "st": "10.3.23"}, {"sp": "N", "t": "ἐπεὶ δὲ πρῶτον περὶ τῶν τῆς Πελοποννήσου νήσων τῶν τε ἄλλων διῆλθον καὶ τῶν ἐν τῷ Κορινθιακῷ κόλπῳ καὶ τῶν πρὸ αὐτοῦ, περὶ τῆς Κρήτης ἐφεξῆς ῥητέον (καὶ γὰρ αὕτη τῆς Πελοποννήσου ἐστί) καὶ εἴ τις περὶ τὴν Κρήτην· ἐν δὲ ταύταις αἵ τε Κυκλάδες εἰσὶ καὶ αἱ Σποράδες, αἱ μὲν ἄξιαι μνήμης αἱ δ’ ἀσημότεραι.", "st": "10.4.1"}, {"sp": "N", "t": "νυνὶ δὲ περὶ τῆς Κρήτης πρῶτον λέγωμεν. Εὔδοξος μὲν οὖν ἐν τῷ Αἰγαίῳ φησὶν αὐτὴν ἱδρῦσθαι· δεῖ δὲ μὴ οὕτως, ἀλλὰ κεῖσθαι μὲν μεταξὺ τῆς Κυρηναίας καὶ τῆς Ἑλλάδος τῆς ἀπὸ Σουνίου μέχρι τῆς Λακωνικῆς, ἐπὶ μῆκος ταύταις ταῖς χώραις παράλληλον ἀπὸ τῆς ἑσπέρας ἐπὶ τὴν ἕω· κλύζεσθαι δὲ ἀπὸ μὲν τῶν ἄρκτων τῷ Αἰγαίῳ πελάγει καὶ τῷ Κρητικῷ, ἀπὸ δὲ τοῦ νότου τῷ Λιβυκῷ τῷ συνάπτοντι πρὸς τὸ Αἰγύπτιον πέλαγος. τῶν δὲ ἄκρων τὸ μὲν ἑσπέριόν ἐστι τὸ περὶ Φαλάσαρνα, πλάτος ἔχον διακοσίων που σταδίων καὶ εἰς δύο ἀκρωτήρια μεριζόμενον (ὧν τὸ μὲν νότιον καλεῖται Κριοῦ μέτωπον τὸ δ’ ἀρκτικὸν Κίμαρος), τὸ δ’ ἑῷον τὸ Σαμώνιόν ἐστιν ὑπερπῖπτον τοῦ Σουνίου οὐ πολὺ πρὸς ἕω.", "st": "10.4.2"}, {"sp": "N", "t": "μέγεθος δὲ Σωσικράτης μέν, ὅν φησιν ἀκριβοῦν Ἀπολλόδωρος τὰ περὶ τὴν νῆσον, ἀφορίζεται μήκει μὲν πλειόνων ἢ δισχιλίων σταδίων καὶ τριακοσίων, πλάτει δὲ ὑπὸ τὸ μέγεθος, ὥσθ’ ὁ κύκλος κατὰ τοῦτον γίνοιτ’ ἂν πλέον ἢ πεντακισχίλιοι στάδιοι· Ἀρτεμίδωρος δὲ τετρακισχιλίους καὶ ἑκατόν φησιν. Ἱερώνυμος δὲ μῆκος δισχιλίων φήσας τὸ δὲ πλάτος ἀνώμαλον, πλειόνων ἂν εἴη λέγων τὸν κύκλον ἢ ὅσων Ἀρτεμίδωρος. κατὰ δὲ τὸ τρίτον μέρος τοῦ μήκους.. … τὸ δὲ ἔνθεν ἰσθμός ἐστιν ὡς ἑκατὸν σταδίων ἔχων κατοικίαν πρὸς μὲν τῇ βορείῳ θαλάττῃ Ἀμφίμαλλαν, πρὸς δὲ τῇ νοτίῳ Φοίνικα τὸν Λαμπέων· πλατυτάτη δὲ κατὰ τὸ μέσον ἐστί, πάλιν δ’ ἐντεῦθεν εἰς στενώτερον τοῦ προτέρου συμπίπτουσιν ἰσθμὸν αἱ ᾐόνες περὶ ἑξήκοντα σταδίων, τὸν ἀπὸ Μινῴας τῆς Λυττίων εἰς Ἱεράπυτναν καὶ τὸ Λιβυκὸν πέλαγος· ἐν κόλπῳ δ’ ἐστὶν ἡ πόλις. εἶτα πρόεισιν εἰς ὀξὺ ἀκρωτήριον τὸ Σαμώνιον ἐπὶ τὴν Αἴγυπτον νεῦον καὶ τὰς Ῥοδίων νήσους.", "st": "10.4.3"}, {"sp": "N", "t": "ἔστι δ’ ὀρεινὴ καὶ δασεῖα ἡ νῆσος, ἔχει δ’ αὐλῶνας εὐκάρπους. τῶν δ’ ὀρῶν τὰ μὲν πρὸς δύσιν καλεῖται Λευκά, οὐ λειπόμενα τοῦ Ταϋγέτου κατὰ τὸ ὕψος, ἐπὶ τὸ μῆκος δ’ ἐκτεταμένα ὅσον τριακοσίων σταδίων καὶ ποιοῦντα ῥάχιν τελευτῶσάν πως ἐπὶ τὰ στενά. ἐν μέσῳ δ’ ἐστὶ κατὰ τὸ εὐρυχωρότατον τῆς νήσου τὸ Ἰδαῖον ὄρος ὑψηλότατον τῶν ἐκεῖ, περιφερὲς δ’ ἐν κύκλῳ σταδίων ἑξακοσίων· περιοικεῖται δ’ ὑπὸ τῶν ἀρίστων πόλεων. ἄλλα δ’ ἐστὶ πάρισα τοῖς Λευκοῖς, τὰ μὲν ἐπὶ νότον τὰ δ’ ἐπὶ τὴν ἕω λήγοντα.", "st": "10.4.4"}, {"sp": "N", "t": "ἔστι δ’ ἀπὸ τῆς Κυρηναίας ἐπὶ τὸ Κριοῦ μέτωπον δυεῖν ἡμερῶν καὶ νυκτῶν πλοῦς, ἀπὸ δὲ Κιμάρου [ἐπὶ Ταίναρον] εἰσὶ στάδιοι ἑπτακόσιοι (μεταξὺ δὲ Κύθηρα), ἀπὸ δὲ τοῦ Σαμωνίου πρὸς Αἴγυπτον τεττάρων ἡμερῶν καὶ νυκτῶν πλοῦς, οἱ δὲ τριῶν φασι· σταδίων δ’ εἶναι τοῦτόν τινες πεντακισχιλίων εἰρήκασιν, οἱ δὲ ἔτι ἐλαττόνων. Ἐρατοσθένης δ’ ἀπὸ μὲν τῆς Κυρηναίας μέχρι Κριοῦ μετώπου δισχιλίους φησίν, ἔνθεν δ’ εἰς Πελοπόννησον ἐλάττους …", "st": "10.4.5"}, {"sp": "N", "t": "ἄλλη δ’ ἄλλων γλῶσσα μεμιγμένη<br>φησὶν ὁ ποιητής<br>ἐν μὲν Ἀχαιοί,<br>ἐν δ’ Ἐτεόκρητες μεγαλήτορες, ἐν δὲ Κύδωνες,<br>Δωριέες τε τριχάικες δῖοί τε Πελασγοί.<br>τούτων φησὶ Στάφυλος τὸ μὲν πρὸς ἕω Δωριεῖς κατέχειν, τὸ δὲ δυσμικὸν Κύδωνας, τὸ [δὲ] νότιον Ἐτεόκρητας, ὧν εἶναι πολίχνιον Πρᾶσον, ὅπου τὸ τοῦ Δικταίου Διὸς ἱερόν· τοὺς δ’ ἄλλους ἰσχύοντας πλέον οἰκῆσαι τὰ πεδία. τοὺς μὲν οὖν Ἐτεόκρητας καὶ τοὺς Κύδωνας αὐτόχθονας ὑπάρξαι εἰκός, τοὺς δὲ λοιποὺς ἐπήλυδας, οὓς ἐκ Θετταλίας φησὶν ἐλθεῖν Ἄνδρων τῆς Δωρίδος μὲν πρότερον νῦν δὲ Ἑστιαιώτιδος λεγομένης· ἐξ ἧς ὡρμήθησαν, ὥς φησιν, οἱ περὶ τὸν Παρνασσὸν οἰκήσαντες Δωριεῖς καὶ ἔκτισαν τήν τε Ἐρινεὸν καὶ Βοιὸν καὶ Κυτίνιον, ἀφ’ οὗ καὶ τριχάικες ὑπὸ τοῦ ποιητοῦ λέγονται. οὐ πάνυ δὲ τὸν τοῦ Ἄνδρωνος λόγον ἀποδέχονται, τὴν μὲν τετράπολιν Δωρίδα τρίπολιν ἀποφαίνοντος, τὴν δὲ μητρόπολιν τῶν Δωριέων ἄποικον Θετταλῶν· τριχάικας δὲ δέχονται ἤτοι ἀπὸ τῆς τριλοφίας ἢ ἀπὸ τοῦ τριχίνους εἶναι τοὺς λόφους.", "st": "10.4.6"}, {"sp": "N", "t": "πόλεις δ’ εἰσὶν ἐν τῇ Κρήτῃ πλείους μέν, μέγισται δὲ καὶ ἐπιφανέσταται τρεῖς, Κνωσσὸς Γόρτυνα Κυδωνία. διαφερόντως δὲ τὴν Κνωσσὸν καὶ Ὅμηρος ὑμνεῖ μεγάλην καλῶν καὶ βασίλειον τοῦ Μίνω καὶ οἱ ὕστερον. καὶ δὴ καὶ διετέλεσε μέχρι πολλοῦ φερομένη τὰ πρῶτα, εἶτα ἐταπεινώθη καὶ πολλὰ τῶν νομίμων ἀφῃρέθη, μετέστη δὲ τὸ ἀξίωμα εἴς τε Γόρτυναν καὶ Λύττον, ὕστερον δ’ ἀνέλαβε πάλιν τὸ παλαιὸν σχῆμα τὸ τῆς μητροπόλεως. κεῖται δ’ ἐν πεδίῳ κύκλον ἔχουσα ἡ Κνωσσὸς τὸν ἀρχαῖον τριάκοντα σταδίων, μεταξὺ τῆς Λυκτίας καὶ τῆς Γορτυνίας, [διέχουσα τῆς μὲν Γορτύνης] σταδίους διακοσίους, τῆς δὲ Λύττου, ἣν ὁ ποιητὴς Λύκτον ὠνόμασεν, ἑκατὸν εἴκοσι· τῆς δὲ θαλάττης Κνωσσὸς μὲν τῆς βορείου πέντε καὶ εἴκοσι, Γόρτυνα δὲ τῆς Λιβυκῆς ἐνενήκοντα, Λύττος δὲ καὶ αὐτὴ τῆς Λιβυκῆς ὀγδοήκοντα. ἔχει δ’ ἐπίνειον τὸ Ἡράκλειον ἡ Κνωσσός.", "st": "10.4.7"}, {"sp": "N", "t": "Μίνω δέ φασιν ἐπινείῳ χρήσασθαι τῷ Ἀμνισῷ, ὅπου τὸ τῆς Εἰλειθυίας ἱερόν. ἐκαλεῖτο δ’ ἡ Κνωσσὸς Καίρατος πρότερον ὁμώνυμος τῷ παραρρέοντι ποταμῷ. ἱστόρηται δ’ ὁ Μίνως νομοθέτης γενέσθαι σπουδαῖος θαλαττοκρατῆσαί τε πρῶτος, τριχῆ δὲ διελὼν τὴν νῆσον ἐν ἑκάστῳ τῷ μέρει κτίσαι πόλιν, τὴν μὲν Κνωσσὸν ἐν τῷ … καταντικρὺ τῆς Πελοποννήσου· καὶ αὐτὴ δ’ ἐστὶ προσβόρειος. ὡς δ’ εἴρηκεν Ἔφορος, ζηλωτὴς ὁ Μίνως ἀρχαίου τινὸς Ῥαδαμάνθυος δικαιοτάτου ἀνδρὸς ὁμωνύμου τοῦ ἀδελφοῦ αὐτοῦ, ὃς πρῶτος τὴν νῆσον ἐξημερῶσαι δοκεῖ νομίμοις καὶ συνοικισμοῖς πόλεων καὶ πολιτείαις, σκηψάμενος παρὰ Διὸς φέρειν ἕκαστα τῶν τιθεμένων δογμάτων εἰς μέσον. τοῦτον δὴ μιμούμενος καὶ ὁ Μίνως δι’ ἐννέα ἐτῶν, ὡς ἔοικεν, ἀναβαίνων ἐπὶ τὸ τοῦ Διὸς ἄντρον καὶ διατρίβων ἐνθάδε, ἀπῄει συντεταγμένα ἔχων παραγγέλματά τινα, ἃ ἔφασκεν εἶναι προστάγματα τοῦ Διός· ἀφ’ ἧς αἰτίας καὶ τὸν ποιητὴν οὕτως εἰρηκέναι<br>ἐνθάδε Μίνως<br>ἐννέωρος βασίλευε Διὸς μεγάλου ὀαριστής.<br>τοιαῦτα δ’ εἰπόντος οἱ ἀρχαῖοι περὶ αὐτοῦ πάλιν ἄλλους εἰρήκασι λόγους ὑπεναντίους τούτοις, ὡς τυραννικός τε γένοιτο καὶ βίαιος καὶ δασμολόγος, τραγῳδοῦντες τὰ περὶ τὸν Μινώταυρον καὶ τὸν λαβύρινθον καὶ τὰ Θησεῖ συμβάντα καὶ Δαιδάλῳ.", "st": "10.4.8"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ὁποτέρως ἔχει χαλεπὸν εἰπεῖν. ἔστι δὲ καὶ ἄλλος λόγος οὐχ ὁμολογούμενος, τῶν μὲν ξένον τῆς νήσου τὸν Μίνω λεγόντων τῶν δ’ ἐπιχώριον. ὁ μέντοι ποιητὴς τῇ δευτέρᾳ δοκεῖ μᾶλλον συνηγορεῖν ἀποφάσει, ὅταν φῇ ὅτι [Ζεὺς]<br>πρῶτον Μίνωα τέκε Κρήτῃ ἐπίουρον.<br>ὑπὲρ τῆς Κρήτης ὁμολογεῖται διότι κατὰ τοὺς παλαιοὺς χρόνους ἐτύγχανεν εὐνομουμένη καὶ ζηλωτὰς ἑαυτῆς τοὺς ἀρίστους τῶν Ἑλλήνων ἀπέφηνεν, ἐν δὲ τοῖς πρώτοις Λακεδαιμονίους, καθάπερ Πλάτων τε ἐν τοῖς νόμοις δηλοῖ καὶ Ἔφορος ἐν τῇ Εὐρώπῃ ἀναγέγραφεν· ὕστερον δὲ πρὸς τὸ χεῖρον μετέβαλεν ἐπὶ πλεῖστον. μετὰ γὰρ τοὺς Τυρρηνούς, οἳ μάλιστα ἐδῄωσαν τὴν καθ’ ἡμᾶς θάλατταν, οὗτοί εἰσιν οἱ διαδεξάμενοι τὰ λῃστήρια· τούτους δ’ ἐπόρθησαν ὕστερον οἱ Κίλικες· κατέλυσαν δὲ πάντας Ῥωμαῖοι τήν τε Κρήτην ἐκπολεμήσαντες καὶ τὰ πειρατικὰ τῶν Κιλίκων φρούρια. νῦν δὲ Κνωσσὸς καὶ Ῥωμαίων ἀποικίαν ἔχει.", "st": "10.4.9"}, {"sp": "N", "t": "περὶ μὲν οὖν Κνωσσοῦ ταῦτα, πόλεως οὐκ ἀλλοτρίας ἡμῖν, διὰ δὲ τἀνθρώπινα καὶ τὰς ἐν αὐτοῖς μεταβολὰς καὶ συντυχίας ἐκλελειμμένων τῶν συμβολαίων τῶν ὑπαρξάντων ἡμῖν πρὸς τὴν πόλιν. Δορύλαος γὰρ ἦν ἀνὴρ τακτικός, τῶν Μιθριδάτου τοῦ Εὐεργέτου φίλων· οὗτος διὰ τὴν ἐν τοῖς πολεμικοῖς ἐμπειρίαν ξενολογεῖν ἀποδειχθεὶς πολὺς ἦν ἔν τε τῇ Ἑλλάδι καὶ τῇ Θρᾴκῃ, πολὺς δὲ καὶ τοῖς παρὰ τῆς Κρήτης ἰοῦσιν, οὔπω τὴν νῆσον ἐχόντων Ῥωμαίων, συχνοῦ δὲ ὄντος ἐν αὐτῇ τοῦ μισθοφορικοῦ καὶ στρατιωτικοῦ πλήθους, ἐξ οὗ καὶ τὰ λῃστήρια πληροῦσθαι συνέβαινεν. ἐπιδημοῦντος δὲ τοῦ Δορυλάου κατὰ τύχην ἐνέστη πόλεμος τοῖς Κνωσσίοις πρὸς τοὺς Γορτυνίους· αἱρεθεὶς δὲ στρατηγὸς καὶ κατορθώσας διὰ ταχέων ἤρατο τιμὰς τὰς μεγίστας, καὶ ἐπειδὴ μικρὸν ὕστερον ἐξ ἐπιβουλῆς δολοφονηθέντα ἔγνω τὸν Εὐεργέτην ὑπὸ τῶν φίλων ἐν Σινώπῃ, τὴν διαδοχὴν δὲ εἰς γυναῖκα καὶ παιδία ἥκουσαν, ἀπογνοὺς τῶν ἐκεῖ κατέμεινεν [ἐν] τῇ Κνωσσῷ· τεκνοποιεῖται δ’ ἐκ Μακέτιδος γυναικὸς Στερόπης τοὔνομα δύο μὲν υἱεῖς Λαγέταν καὶ Στρατάρχαν, ὧν τὸν Στρατάρχαν ἐσχατόγηρων καὶ ἡμεῖς ἤδη εἴδομεν, θυγατέρα δὲ μίαν. δυεῖν δὲ ὄντων υἱῶν τοῦ Εὐεργέτου διεδέξατο τὴν βασιλείαν Μιθριδάτης ὁ προσαγορευθεὶς Εὐπάτωρ ἕνδεκα ἔτη γεγονώς· τούτῳ σύντροφος ὑπῆρξεν ὁ τοῦ Φιλεταίρου Δορύλαος· ἦν δ’ ὁ Φιλέταιρος ἀδελφὸς τοῦ τακτικοῦ Δορυλάου. ἀνδρωθεὶς δ’ ὁ βασιλεὺς ἐπὶ τοσοῦτο ᾕρητο τῇ συντροφίᾳ τῇ πρὸς τὸν Δορύλαον ὥστ’ οὐκ ἐκεῖνον μόνον εἰς τιμὰς ἦγε τὰς μεγίστας, ἀλλὰ καὶ τῶν συγγενῶν ἐπεμελεῖτο καὶ τοὺς ἐν Κνωσσῷ μετεπέμπετο· ἦσαν δ’ οἱ περὶ Λαγέταν, τοῦ μὲν πατρὸς ἤδη τετελευτηκότος, αὐτοὶ δ’ ἠνδρωμένοι, καὶ ἧκον ἀφέντες τὰ ἐν Κνωσσῷ· τοῦ δὲ Λαγέτα θυγάτηρ ἦν ἡ μήτηρ τῆς ἐμῆς μητρός. εὐτυχοῦντος μὲν δὴ ἐκείνου συνευτυχεῖν καὶ τούτοις συνέβαινε, καταλυθέντος δὲ (ἐφωράθη γὰρ ἀφιστὰς τοῖς Ῥωμαίοις τὴν βασιλείαν ἐφ’ ᾧ αὐτὸς εἰς τὴν ἀρχὴν καταστήσεται) συγκατελύθη καὶ τὰ τούτων καὶ ἐταπεινώθησαν· ὠλιγωρήθη δὲ καὶ τὰ πρὸς τοὺς Κνωσσίους συμβόλαια καὶ αὐτοὺς μυρίας μεταβολὰς δεξαμένους.", "st": "10.4.10"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὁ μὲν περὶ τῆς Κνωσσοῦ λόγος τοιοῦτος. μετὰ δὲ ταύτην δευτερεῦσαι δοκεῖ κατὰ τὴν δύναμιν ἡ τῶν Γορτυνίων πόλις. συμπράττουσαί τε γὰρ ἀλλήλαις ἅπαντας ὑπηκόους εἶχον αὗται τοὺς ἄλλους, στασιάσασαί τε διέστησαν τὰ κατὰ τὴν νῆσον· προσθήκη δ’ ἦν ἡ Κυδωνία μεγίστη ὁποτέροις προσγένοιτο. κεῖται δ’ ἐν πεδίῳ καὶ ἡ τῶν Γορτυνίων πόλις, τὸ παλαιὸν μὲν ἴσως τετειχισμένη (καθάπερ καὶ Ὅμηρος εἴρηκε<br>Γόρτυνά τε τειχήεσσαν<br>), ὕστερον δ’ ἀποβαλοῦσα τὸ τεῖχος ἐκ θεμελίων καὶ πάντα τὸν χρόνον μείνασα ἀτείχιστος· καὶ γὰρ ὁ Φιλοπάτωρ Πτολεμαῖος ἀρξάμενος τειχίζειν ὅσον ἐπὶ ὀγδοήκοντα σταδίους παρῆλθε μόνον· ἀξιόλογον δ’ οὖν ἐξεπλήρου ποτὲ κύκλον ἡ οἴκησις ὅσον πεντήκοντα σταδίων· διέχει δὲ τῆς Λιβυκῆς θαλάττης κατὰ Λεβῆνα τὸ ἐμπόριον αὐτῆς ἐνενήκοντα· ἔχει δέ τι καὶ ἄλλο ἐπίνειον τὸ Μάταλον, διέχει δ’ αὐτῆς ἑκατὸν τριάκοντα. διαρρεῖ δ’ αὐτὴν ὅλην ὁ Ληθαῖος ποταμός.", "st": "10.4.11"}, {"sp": "N", "t": "ἐκ δὲ Λεβῆνος ἦν Λευκοκόμας τε καὶ ὁ ἐραστὴς αὐτοῦ Εὐξύνθετος, οὓς ἱστορεῖ Θεόφραστος ἐν τῷ περὶ ἔρωτος λόγῳ, ἄθλων ὧν ὁ Λευκοκόμας τῷ Εὐξυνθέτῳ προσέταξεν ἕνα φήσας εἶναι τοῦτον, τὸν ἐν Πράσῳ κύνα ἀναγαγεῖν αὐτῷ· ὅμοροι δ’ εἰσὶν αὐτοῖς οἱ Πράσιοι, τῆς μὲν θαλάττης ἑβδομήκοντα Γόρτυνος δὲ διέχοντες ἑκατὸν καὶ ὀγδοήκοντα. εἴρηται δὲ ὅτι τῶν Ἐτεοκρήτων ὑπῆρχεν ἡ Πρᾶσος καὶ διότι ἐνταῦθα τὸ τοῦ Δικταίου Διὸς ἱερόν· καὶ γὰρ ἡ Δίκτη πλησίον, οὐχ ὡς Ἄρατος “ὄρεος σχεδὸν Ἰδαίοιο.” καὶ γὰρ χιλίους ἡ Δίκτη τῆς Ἴδης ἀπέχει, πρὸς ἀνίσχοντα ἥλιον ἀπ’ αὐτῆς κειμένη, τοῦ δὲ Σαμωνίου ἑκατόν. μεταξὺ δὲ τοῦ Σαμωνίου καὶ τῆς Χερρονήσου ἡ Πρᾶσος ἵδρυτο ὑπὲρ τῆς θαλάττης ἑξήκοντα σταδίοις· κατέσκαψαν δ’ Ἱεραπύτνιοι. οὐκ εὖ δὲ οὐδὲ τὸν Καλλίμαχον λέγειν φασίν, ὡς ἡ Βριτόμαρτις φεύγουσα τὴν Μίνω βίαν ἀπὸ τῆς Δίκτης ἅλοιτο εἰς ἁλιέων δίκτυα, καὶ διὰ τοῦτο αὐτὴ μὲν Δίκτυννα ὑπὸ τῶν Κυδωνιατῶν προσαγορευθείη, Δίκτη δὲ τὸ ὄρος· οὐδὲ γὰρ ὅλως ἐκ γειτόνων ἐστὶ τοῖς τόποις τούτοις ἡ Κυδωνία, πρὸς δὲ τοῖς ἑσπερίοις κεῖται τῆς νήσου πέρασι. τῆς μέντοι Κυδωνίας ὄρος ἐστὶ Τίτυρος, ἐν ᾧ ἱερόν ἐστιν οὐ Δικταῖον ἀλλὰ Δικτύνναιον.", "st": "10.4.12"}, {"sp": "N", "t": "Κυδωνία δ’ ἐπὶ θαλάττῃ μὲν ἵδρυται βλέπουσα πρὸς τὴν Λακωνικήν, διέχει δ’ ἑκατέρας τὸ ἴσον τῆς τε Κνωσσοῦ καὶ τῆς Γόρτυνος οἷον ὀκτακοσίους σταδίους, Ἀπτέρας δὲ ὀγδοήκοντα, τῆς ταύτῃ δὲ θαλάττης τετταράκοντα. Ἀπτέρας δ’ ἐπίνειόν ἐστι Κίσαμος· πρὸς ἑσπέραν δ’ ὅμοροι τοῖς Κυδωνιάταις Πολυρρήνιοι, παρ’ οἷς ἐστι τὸ τῆς Δικτύννης ἱερόν· ἀπέχουσι δὲ τῆς θαλάττης ὡς τριάκοντα σταδίους, Φαλασάρνης δὲ ἑξήκοντα. κωμηδὸν δ’ ᾤκουν πρότερον· εἶτ’ Ἀχαιοὶ καὶ Λάκωνες συνῴκησαν τειχίσαντες ἐρυμνὸν χωρίον βλέπον πρὸς μεσημβρίαν.", "st": "10.4.13"}, {"sp": "N", "t": "τῶν δ’ ὑπὸ Μίνω συνῳκισμένων τριῶν τὴν λοιπὴν (Φαιστὸς δ’ ἦν αὕτη) κατέσκαψαν Γορτύνιοι, τῆς μὲν Γόρτυνος διέχουσαν ἑξήκοντα, τῆς δὲ θαλάττης εἴκοσι, τοῦ δὲ Ματάλου τοῦ ἐπινείου τετταράκοντα· τὴν δὲ χώραν ἔχουσιν οἱ κατασκάψαντες. Γορτυνίων δ’ ἐστὶ καὶ τὸ Ῥύτιον σὺν τῇ Φαιστῷ<br>Φαιστόν τε Ῥύτιόν τε.<br>ἐκ δὲ τῆς Φαιστοῦ τὸν τοὺς καθαρμοὺς ποιήσαντα διὰ τῶν ἐπῶν Ἐπιμενίδην φασὶν εἶναι. καὶ ὁ Λισσὴν δὲ τῆς Φαιστίας. Λύττου δέ, ἧς ἐμνήσθημεν καὶ πρότερον, ἐπίνειόν ἐστιν ἡ λεγομένη Χερρόνησος, ἐν ᾗ τὸ τῆς Βριτομάρτεως ἱερόν· αἱ δὲ συγκαταλεχθεῖσαι πόλεις οὐκέτ’ εἰσὶ Μίλητός τε καὶ Λύκαστος, τὴν δὲ χώραν τὴν μὲν ἐνείμαντο Λύττιοι τὴν δὲ Κνώσσιοι κατασκάψαντες τὴν πόλιν.", "st": "10.4.14"}, {"sp": "N", "t": "τοῦ δὲ ποιητοῦ τὸ μὲν ἑκατόμπολιν λέγοντος τὴν Κρήτην τὸ δὲ ἐνενηκοντάπολιν, Ἔφορος μὲν ὕστερον ἐπικτισθῆναι τὰς δέκα φησὶ μετὰ τὰ Τρωικὰ ὑπὸ τῶν Ἀλθαιμένει τῷ Ἀργείῳ συνακολουθησάντων Δωριέων· τὸν μὲν οὖν Ὀδυσσέα λέγει ἐνενηκοντάπολιν ὀνομάσαι· οὗτος μὲν οὖν πιθανός ἐστιν ὁ λόγος, ἄλλοι δ’ ὑπὸ τῶν Ἰδομενέως ἐχθρῶν κατασκαφῆναί φασι τὰς δέκα· ἀλλ’ οὔτε κατὰ τὰ Τρωικά φησιν ὁ ποιητὴς ἑκατοντάπολιν ὑπάρξαι τὴν Κρήτην, ἀλλὰ μᾶλλον κατ’ αὐτόν (ἐκ γὰρ τοῦ ἰδίου προσώπου λέγει· εἰ δ’ ἐκ τῶν τότε ὄντων τινὸς ἦν ὁ λόγος, καθάπερ ἐν τῇ Ὀδυσσείᾳ, ἡνίκα ἐνενηκοντάπολιν φράζει, καλῶς εἶχεν [ἂν] οὕτω δέχεσθαι), οὔτ’ εἰ συγχωρήσαιμεν τοῦτό γε, ὁ ἑξῆς λόγος σώζοιτ’ ἄν. οὔτε γὰρ κατὰ τὴν στρατείαν οὔτε μετὰ τὴν ἐπάνοδον τὴν ἐκεῖθεν τοῦ Ἰδομενέως εἰκός ἐστιν ὑπὸ τῶν ἐχθρῶν αὐτοῦ τὰς πόλεις ἠφανίσθαι ταύτας· ὁ γὰρ ποιητὴς φήσας<br>πάντας δ’ Ἰδομενεὺς Κρήτην εἰσήγαγ’ ἑταίρους,<br>οἳ φύγον ἐκ πολέμου, πόντος δέ οἱ οὔτιν’ ἀπηύρα,<br>καὶ τούτου τοῦ πάθους ἐμέμνητ’ ἄν· οὐ γὰρ δήπου Ὀδυσσεὺς μὲν ἔγνω τὸν ἀφανισμὸν τῶν πόλεων ὁ μηδενὶ συμμίξας τῶν Ἑλλήνων μήτε κατὰ τὴν πλάνην μήθ’ ὕστερον, ὁ δὲ καὶ συστρατεύσας τῷ Ἰδομενεῖ καὶ συνανασωθεὶς οὐκ ἔγνω τὰ συμβάντα οἴκοι αὐτῷ. ἀλλὰ μὴν οὐδὲ μετὰ τὴν ἐπάνοδον· εἰ γὰρ μετὰ πάντων ἐσώθη τῶν ἑταίρων, ἰσχυρὸς ἐπανῆλθεν, ὥστ’ οὐκ ἔμελλον ἰσχύσειν οἱ ἐχθροὶ τοσοῦτον ὅσον δέκα ἀφαιρεῖσθαι πόλεις αὐτόν. τῆς μὲν οὖν χώρας τῶν Κρητῶν τοιαύτη τις ἡ περιοδεία.", "st": "10.4.15"}, {"sp": "N", "t": "τῆς δὲ πολιτείας ἧς Ἔφορος ἀνέγραψε τὰ κυριώτατα ἐπιδραμεῖν ἀποχρώντως ἂν ἔχοι. δοκεῖ δέ, φησίν, ὁ νομοθέτης μέγιστον ὑποθέσθαι ταῖς πόλεσιν ἀγαθὸν τὴν ἐλευθερίαν· μόνην γὰρ ταύτην ἴδια ποιεῖν τῶν κτησαμένων τὰ ἀγαθά, τὰ δ’ ἐν δουλείᾳ τῶν ἀρχόντων ἀλλ’ οὐχὶ τῶν ἀρχομένων εἶναι· τοῖς δ’ ἔχουσι ταύτην φυλακῆς δεῖν· τὴν μὲν οὖν ὁμόνοιαν διχοστασίας αἰρομένης ἀπαντᾶν, ἣ γίνεται διὰ πλεονεξίαν καὶ τρυφήν· σωφρόνως γὰρ καὶ λιτῶς ζῶσιν ἅπασιν οὔτε φθόνον οὔθ’ ὕβριν οὔτε μῖσος ἀπαντᾶν πρὸς τοὺς ὁμοίους· διόπερ τοὺς μὲν παῖδας εἰς τὰς ὀνομαζομένας ἀγέλας κελεῦσαι φοιτᾶν, τοὺς δὲ τελείους ἐν τοῖς συσσιτίοις ἃ καλοῦσιν ἀνδρεῖα συσσιτεῖν, ὅπως τῶν ἴσων μετάσχοιεν τοῖς εὐπόροις οἱ πενέστεροι δημοσίᾳ τρεφόμενοι· πρὸς δὲ τὸ μὴ δειλίαν ἀλλ’ ἀνδρείαν κρατεῖν ἐκ παίδων ὅπλοις καὶ πόνοις συντρέφειν, ὥστε καταφρονεῖν καύματος καὶ ψύχους καὶ τραχείας ὁδοῦ καὶ ἀνάντους καὶ πληγῶν τῶν ἐν γυμνασίοις καὶ μάχαις ταῖς κατὰ σύνταγμα· ἀσκεῖν δὲ καὶ τοξικῇ καὶ ἐνοπλίῳ ὀρχήσει, ἣν καταδεῖξαι Κουρῆτα πρῶτον, ὕστερον δὲ καὶ συντάξαντα τὴν κληθεῖσαν ἀπ’ αὐτοῦ πυρρίχην, ὥστε μηδὲ τὴν παιδιὰν ἄμοιρον εἶναι τῶν πρὸς πόλεμον χρησίμων· ὡς δ’ αὕτως καὶ τοῖς ῥυθμοῖς Κρητικοῖς χρῆσθαι κατὰ τὰς ᾠδὰς συντονωτάτοις οὖσιν οὓς Θάλητα ἀνευρεῖν, ᾧ καὶ τοὺς παιᾶνας καὶ τὰς ἄλλας τὰς ἐπιχωρίους ᾠδὰς ἀνατιθέασι καὶ πολλὰ τῶν νομίμων· καὶ ἐσθῆτι δὲ καὶ ὑποδέσει πολεμικῇ χρῆσθαι, καὶ τῶν δώρων τιμιώτατα αὐτοῖς εἶναι τὰ ὅπλα.", "st": "10.4.16"}, {"sp": "N", "t": "λέγεσθαι δ’ ὑπό τινων ὡς Λακωνικὰ εἴη τὰ πολλὰ τῶν νομιζομένων Κρητικῶν, τὸ δ’ ἀληθὲς εὑρῆσθαι μὲν ὑπ’ ἐκείνων, ἠκριβωκέναι δὲ τοὺς Σπαρτιάτας, τοὺς δὲ Κρῆτας ὀλιγωρῆσαι, κακωθεισῶν τῶν πόλεων καὶ μάλιστα τῆς Κνωσσίων, τῶν πολεμικῶν· μεῖναι δέ τινα τῶν νομίμων παρὰ Λυττίοις καὶ Γορτυνίοις καὶ ἄλλοις τισὶ πολιχνίοις μᾶλλον ἢ παρ’ ἐκείνοις· καὶ δὴ καὶ τὰ Λυττίων νόμιμα ποιεῖσθαι μαρτύρια τοὺς τὰ Λακωνικὰ πρεσβύτερα ἀποφαίνοντας· ἀποίκους γὰρ ὄντας φυλάττειν τὰ τῆς μητροπόλεως ἔθη, ἐπεὶ ἄλλως γε εὔηθες εἶναι τὸ τοὺς βέλτιον συνεστῶτας καὶ πολιτευομένους τῶν χειρόνων ζηλωτὰς ἀποφαίνειν· οὐκ εὖ δὲ ταῦτα λέγεσθαι· οὔτε γὰρ ἐκ τῶν νῦν καθεστηκότων τὰ παλαιὰ τεκμηριοῦσθαι δεῖν, εἰς τἀναντία ἑκατέρων μεταπεπτωκότων· καὶ γὰρ ναυκρατεῖν πρότερον τοὺς Κρῆτας, ὥστε καὶ παροιμιάζεσθαι πρὸς τοὺς προσποιουμένους μὴ εἰδέναι ἃ ἴσασιν “ὁ Κρὴς ἀγνοεῖ τὴν θάλατταν,” νῦν δ’ ἀποβεβληκέναι τὸ ναυτικόν· [οὔτε] ὅτι ἄποικοί τινες τῶν πόλεων γεγόνασι τῶν ἐν Κρήτῃ Σπαρτιατῶν, ἐν τοῖς ἐκείνων νομίμοις διαμένειν ἐπηναγκάσθαι· πολλὰς γοῦν τῶν ἀποικίδων μὴ φυλάττειν τὰ πάτρια, πολλὰς δὲ καὶ τῶν μὴ ἀποικίδων ἐν Κρήτῃ τὰ αὐτὰ ἔχειν τοῖς ἀποίκοις ἔθη.", "st": "10.4.17"}, {"sp": "N", "t": "τῶν τε Σπαρτιατῶν τὸν νομοθέτην Λυκοῦργον πέντε γενεαῖς νεώτερον Ἀλθαιμένους εἶναι τοῦ στείλαντος τὴν εἰς Κρήτην ἀποικίαν· τὸν μὲν γὰρ ἱστορεῖσθαι Κίσσου παῖδα τοῦ τὸ Ἄργος κτίσαντος περὶ τὸν αὐτὸν χρόνον ἡνίκα Προκλῆς τὴν Σπάρτην συνῴκιζε, Λυκοῦργον δ’ ὁμολογεῖσθαι παρὰ πάντων ἕκτον ἀπὸ Προκλέους γεγονέναι· τὰ δὲ μιμήματα μὴ εἶναι πρότερα τῶν παραδειγμάτων μηδὲ τὰ νεώτερα τῶν πρεσβυτέρων· τήν τε ὄρχησιν τὴν παρὰ τοῖς Λακεδαιμονίοις ἐπιχωριάζουσαν καὶ τοὺς ῥυθμοὺς καὶ παιᾶνας τοὺς κατὰ νόμον ᾀδομένους καὶ ἄλλα πολλὰ τῶν νομίμων Κρητικὰ καλεῖσθαι παρ’ αὐτοῖς ὡς ἂν ἐκεῖθεν ὁρμώμενα· τῶν δ’ ἀρχείων τὰ μὲν καὶ τὰς διοικήσεις ἔχειν τὰς αὐτὰς καὶ τὰς ἐπωνυμίας, ὥσπερ καὶ τὴν τῶν γερόντων ἀρχὴν καὶ τὴν τῶν ἱππέων (πλὴν ὅτι τοὺς ἐν Κρήτῃ ἱππέας καὶ ἵππους κεκτῆσθαι συμβέβηκεν· ἐξ οὗ τεκμαίρονται πρεσβυτέραν εἶναι τῶν ἐν Κρήτῃ ἱππέων τὴν ἀρχήν· σώζειν γὰρ τὴν ἐτυμότητα τῆς προσηγορίας· τοὺς δὲ μὴ ἱπποτροφεῖν), τοὺς ἐφόρους δὲ τὰ αὐτὰ τοῖς ἐν Κρήτῃ κόσμοις διοικοῦντας ἑτέρως ὠνομάσθαι· τὰ δὲ συσσίτια ἀνδρεῖα παρὰ μὲν τοῖς Κρησὶν καὶ νῦν ἔτι καλεῖσθαι, παρὰ δὲ τοῖς Σπαρτιάταις μὴ διαμεῖναι καλούμενα ὁμοίως πρότερον· παρ’ Ἀλκμᾶνι γοῦν οὕτω κεῖσθαι<br>φοίναις δὲ καὶ ἐν θιάσοισιν<br>ἀνδρείων παρὰ δαιτυμόνεσσι πρέπει παιᾶνα κατάρχειν.", "st": "10.4.18"}, {"sp": "N", "t": "λέγεσθαι δ’ ὑπὸ τῶν Κρητῶν ὡς καὶ παρ’ αὐτοὺς ἀφίκοιτο Λυκοῦργος κατὰ τοιαύτην αἰτίαν· ἀδελφὸς ἦν πρεσβύτερος τοῦ Λυκούργου Πολυδέκτης· οὗτος τελευτῶν ἔγκυον κατέλιπε τὴν γυναῖκα· τέως μὲν οὖν ἐβασίλευεν ὁ Λυκοῦργος ἀντὶ τοῦ ἀδελφοῦ, γενομένου δὲ παιδὸς ἐπετρόπευεν ἐκεῖνον, εἰς ὃν ἡ ἀρχὴ καθήκουσα ἐτύγχανε· λοιδορούμενος δή τις αὐτῷ σαφῶς εἶπεν εἰδέναι διότι βασιλεύσοι· λαβὼν δ’ ὑπόνοιαν ἐκεῖνος ὡς ἐκ τοῦ λόγου τούτου διαβάλλοιτο ἐπιβουλὴ ἐξ αὐτοῦ τοῦ παιδός, δείσας μὴ ἐκ τύχης ἀποθανόντος αἰτίαν αὐτὸς ἔχοι παρὰ τῶν ἐχθρῶν, ἀπῆρεν εἰς Κρήτην. ταύτην μὲν δὴ λέγεσθαι τῆς ἀποδημίας αἰτίαν· ἐλθόντα δὲ πλησιάσαι Θάλητι μελοποιῷ ἀνδρὶ καὶ νομοθετικῷ, ἱστορήσαντα δὲ παρ’ αὐτοῦ τὸν τρόπον ὃν Ῥαδάμανθύς τε πρότερον καὶ ὕστερον Μίνως, ὡς παρὰ τοῦ Διός, τοὺς νόμους ἐκφέροι εἰς ἀνθρώπους, γενόμενον δὲ καὶ ἐν Αἰγύπτῳ καὶ καταμαθόντα καὶ τὰ ἐκεῖ νόμιμα, ἐντυχόντα δ’, ὥς φασί τινες, καὶ Ὁμήρῳ διατρίβοντι ἐν Χίῳ, κατᾶραι πάλιν εἰς τὴν οἰκείαν, καταλαβεῖν δὲ τὸν τοῦ ἀδελφοῦ υἱὸν τὸν Πολυδέκτου Χαρίλαον βασιλεύοντα· εἶθ’ ὁρμῆσαι διαθεῖναι τοὺς νόμους φοιτῶντα ὡς τὸν θεὸν τὸν ἐν Δελφοῖς, κἀκεῖθεν κομίζοντα τὰ προστάγματα, καθάπερ οἱ περὶ Μίνω ἐκ τοῦ ἄντρου τοῦ Διὸς παραπλήσια ἐκείνοις τὰ πλείω.", "st": "10.4.19"}, {"sp": "N", "t": "τῶν Κρητικῶν τὰ κυριώτατα τῶν καθ’ ἕκαστα τοιαῦτα εἴρηκε. γαμεῖν μὲν ἅμα πάντες ἀναγκάζονται παρ’ αὐτοῖς οἱ κατὰ τὸν αὐτὸν χρόνον ἐκ τῆς τῶν παίδων ἀγέλης ἐκκριθέντες, οὐκ εὐθὺς δ’ ἄγονται παρ’ ἑαυτοὺς τὰς γαμηθείσας παῖδας, ἀλλ’ ἐπὰν ἤδη διοικεῖν ἱκαναὶ ὦσι τὰ περὶ τοὺς οἴκους· φερνὴ δ’ ἐστίν, ἂν ἀδελφοὶ ὦσι, τὸ ἥμισυ τῆς τοῦ ἀδελφοῦ μερίδος· παῖδας δὲ γράμματά τε μανθάνειν καὶ τὰς ἐκ τῶν νόμων ᾠδὰς καί τινα εἴδη τῆς μουσικῆς. τοὺς μὲν οὖν ἔτι νεωτέρους εἰς τὰ συσσίτια ἄγουσι τὰ ἀνδρεῖα· χαμαὶ δὲ καθήμενοι διαιτῶνται μετ’ ἀλλήλων ἐν φαύλοις τριβωνίοις καὶ χειμῶνος καὶ θέρους τὰ αὐτά, διακονοῦσί τε καὶ ἑαυτοῖς καὶ τοῖς ἀνδράσι· συμβάλλουσι δ’ εἰς μάχην καὶ οἱ ἐκ τοῦ αὐτοῦ συσσιτίου πρὸς ἀλλήλους, καὶ πρὸς ἕτερα συσσίτια· καθ’ ἕκαστον δὲ ἀνδρεῖον ἐφέστηκε παιδονόμος· οἱ δὲ μείζους εἰς τὰς ἀγέλας ἄγονται· τὰς δ’ ἀγέλας συνάγουσιν οἱ ἐπιφανέστατοι τῶν παίδων καὶ δυνατώτατοι ἕκαστος ὅσους πλείστους οἷός τέ ἐστιν ἀθροίζων· ἑκάστης δὲ τῆς ἀγέλης ἄρχων ἐστὶν ὡς τὸ πολὺ ὁ πατὴρ τοῦ συναγαγόντος, κύριος ὢν ἐξάγειν ἐπὶ θήραν καὶ δρόμους, τὸν δ’ ἀπειθοῦντα κολάζειν· τρέφονται δὲ δημοσίᾳ· τακταῖς δέ τισιν ἡμέραις ἀγέλη πρὸς ἀγέλην συμβάλλει μετὰ αὐλοῦ καὶ λύρας εἰς μάχην ἐν ῥυθμῷ, ὥσπερ καὶ ἐν τοῖς πολεμικοῖς εἰώθασιν, ἐκφέρουσι δὲ καὶ τὰς πληγὰς τὰς μὲν διὰ χειρὸς τὰς δὲ καὶ δι’ ὅπλων σιδηρῶν.", "st": "10.4.20"}, {"sp": "N", "t": "ἴδιον δ’ αὐτοῖς τὸ περὶ τοὺς ἔρωτας νόμιμον· οὐ γὰρ πειθοῖ κατεργάζονται τοὺς ἐρωμένους ἀλλ’ ἁρπαγῇ· προλέγει τοῖς φίλοις πρὸ τριῶν ἢ πλειόνων ἡμερῶν ὁ ἐραστὴς ὅτι μέλλει τὴν ἁρπαγὴν ποιεῖσθαι· τοῖς δ’ ἀποκρύπτειν μὲν τὸν παῖδα ἢ μὴ ἐᾶν πορεύεσθαι τὴν τεταγμένην ὁδὸν τῶν αἰσχίστων ἐστίν, ὡς ἐξομολογουμένοις ὅτι ἀνάξιος ὁ παῖς εἴη τοιούτου ἐραστοῦ τυγχάνειν· συνιόντες δ’, ἂν μὲν τῶν ἴσων ἢ τῶν ὑπερεχόντων τις ᾖ τοῦ παιδὸς τιμῇ καὶ τοῖς ἄλλοις ὁ ἁρπάζων, ἐπιδιώκοντες ἀνθήψαντο μόνον μετρίως τὸ νόμιμον ἐκπληροῦντες, τἆλλα δ’ ἐπιτρέπουσιν ἄγειν χαίροντες· ἂν δ’ ἀνάξιος, ἀφαιροῦνται· πέρας δὲ τῆς ἐπιδιώξεώς ἐστιν ἕως ἂν ἀχθῇ ὁ παῖς εἰς τὸ τοῦ ἁρπάσαντος ἀνδρεῖον. ἐράσμιον δὲ νομίζουσιν οὐ τὸν κάλλει διαφέροντα, ἀλλὰ τὸν ἀνδρείᾳ καὶ κοσμιότητι … καὶ δωρησάμενος ἀπάγει τὸν παῖδα τῆς χώρας εἰς ὃν βούλεται τόπον· ἐπακολουθοῦσι δὲ τῇ ἁρπαγῇ οἱ παραγενόμενοι, ἑστιαθέντες δὲ καὶ συνθηρεύσαντες δίμηνον (οὐ γὰρ ἔξεστι πλείω χρόνον κατέχειν τὸν παῖδα) εἰς τὴν πόλιν καταβαίνουσιν. ἀφίεται δ’ ὁ παῖς δῶρα λαβὼν στολὴν πολεμικὴν καὶ βοῦν καὶ ποτήριον. ταῦτα μὲν τὰ κατὰ τὸν νόμον δῶρα … καὶ ἄλλα πλείω καὶ πολυτελῆ, ὥστε συνερανίζειν τοὺς φίλους διὰ τὸ πλῆθος τῶν ἀναλωμάτων. τὸν μὲν οὖν βοῦν θύει τῷ Διὶ καὶ ἑστιᾷ τοὺς συγκαταβαίνοντας, εἶτ’ ἀποφαίνεται περὶ τῆς πρὸς τὸν ἐραστὴν ὁμιλίας εἴτ’ ἀσμενίζων τετύχηκεν εἴτε μή, τοῦ νόμου τοῦτ’ ἐπιτρέψαντος, ἵν’ εἴ τις αὐτῷ βία προσενήνεκται κατὰ τὴν ἁρπαγήν, ἐνταῦθα παρῇ τιμωρεῖν ἑαυτῷ καὶ ἀπαλλάττεσθαι. τοῖς δὲ καλοῖς τὴν ἰδέαν καὶ προγόνων ἐπιφανῶν [αἰσχρὸν] ἐραστῶν μὴ τυχεῖν, ὡς διὰ τὸν τρόπον τοῦτο παθοῦσιν. ἔχουσι δὲ τιμὰς οἱ παρασταθέντες (οὕτω γὰρ καλοῦσι τοὺς ἁρπαγέντας)· ἔν τε γὰρ τοῖς χοροῖς καὶ τοῖς δρόμοις ἔχουσι τὰς ἐντιμοτάτας χώρας, τῇ τε στολῇ κοσμεῖσθαι διαφερόντως τῶν ἄλλων ἐφίεται τῇ δοθείσῃ παρὰ τῶν ἐραστῶν, καὶ οὐ τότε μόνον ἀλλὰ καὶ τέλειοι γενόμενοι διάσημον ἐσθῆτα φέρουσιν, ἀφ’ ἧς γνωσθήσεται ἕκαστος κλεινὸς γενόμενος· τὸν μὲν γὰρ ἐρώμενον καλοῦσι κλεινὸν τὸν δ’ ἐραστὴν φιλήτορα.", "st": "10.4.21"}, {"sp": "N", "t": "ταῦτα μὲν τὰ περὶ τοὺς ἔρωτας νόμιμα. ἄρχοντας δὲ δέκα αἱροῦνται· περὶ δὲ τῶν μεγίστων συμβούλοις χρῶνται τοῖς γέρουσι καλουμένοις· καθίστανται δ’ εἰς τοῦτο τὸ συνέδριον οἱ τῆς τῶν κόσμων ἀρχῆς ἠξιωμένοι καὶ τἆλλα δόκιμοι κρινόμενοι. ἀξίαν δ’ ἀναγραφῆς τὴν τῶν Κρητῶν πολιτείαν ὑπέλαβον διά τε τὴν ἰδιότητα καὶ τὴν δόξαν· οὐ πολλὰ δὲ διαμένει τούτων τῶν νομίμων, ἀλλὰ τοῖς Ῥωμαίων διατάγμασι τὰ πλεῖστα διοικεῖται, καθάπερ καὶ ἐν ταῖς ἄλλαις ἐπαρχίαις συμβαίνει.", "st": "10.4.22"}, {"sp": "N", "t": "περὶ δὲ τὴν Κρήτην εἰσὶ νῆσοι, Θήρα μὲν ἡ τῶν Κυρηναίων μητρόπολις, ἄποικος Λακεδαιμονίων, καὶ πλησίον ταύτης Ἀνάφη, ἐν ᾗ τὸ τοῦ Αἰγλήτου Ἀπόλλωνος ἱερόν. λέγει δὲ καὶ Καλλίμαχος τοτὲ μὲν οὕτως<br>Αἰγλήτην Ἀνάφην τε Λακωνίδι γείτονα Θήρῃ,<br>τοτὲ δὲ τῆς Θήρας μνησθείς<br>μήτηρ εὐίππου πατρίδος ἡμετέρης.<br>ἔστι δὲ μακρὰ ἡ Θήρα, διακοσίων οὖσα τὴν περίμετρον σταδίων, κειμένη δὲ κατὰ Δίαν νῆσον τὴν πρὸς Ἡρακλείῳ τῷ Κνωσσίῳ, διέχει δὲ τῆς Κρήτης εἰς ἑπτακοσίους· πλησίον δ’ αὐτῆς ἥ τε Ἀνάφη καὶ Θηρασία. ταύτης δ’ εἰς ἑκατὸν ἀπέχει νησίδιον Ἴος, ἐν ᾧ κεκηδεῦσθαί τινές φασι τὸν ποιητὴν Ὅμηρον· ἀπὸ δὲ τῆς Ἴου πρὸς ἑσπέραν ἰόντι Σίκινος καὶ Λάγουσα καὶ Φολέγανδρος, ἣν Ἄρατος σιδηρείην ὀνομάζει διὰ τὴν τραχύτητα· ἐγγὺς δὲ τούτων Κίμωλος, ὅθεν ἡ γῆ ἡ Κιμωλία· ἔνθεν ἡ Σίφνος ἐν ὄψει ἐστίν, ἐφ’ ᾗ λέγουσι Σίφνιον ἀστράγαλον διὰ τὴν εὐτέλειαν. ἔτι δ’ ἐγγυτέρω καὶ τῆς Κιμώλου καὶ τῆς Κρήτης ἡ Μῆλος ἀξιολογωτέρα τούτων, διέχουσα τοῦ Ἑρμιονικοῦ ἀκρωτηρίου τοῦ Σκυλλαίου σταδίους ἑπτακοσίους· τοσούτους δὲ σχεδόν τι καὶ τοῦ Δικτυνναίου· Ἀθηναῖοι δέ ποτε πέμψαντες στρατείαν ἡβηδὸν κατέσφαξαν τοὺς πλείους. αὗται μὲν οὖν ἐν τῷ Κρητικῷ πελάγει, ἐν δὲ τῷ Αἰγαίῳ μᾶλλον αὐτή τε ἡ Δῆλος καὶ αἱ περὶ αὐτὴν Κυκλάδες καὶ αἱ ταύταις προσκείμεναι Σποράδες, ὧν εἰσι καὶ αἱ λεχθεῖσαι περὶ τὴν Κρήτην.", "st": "10.5.1"}, {"sp": "N", "t": "ἡ μὲν οὖν Δῆλος ἐν πεδίῳ κειμένην ἔχει τὴν πόλιν καὶ τὸ ἱερὸν τοῦ Ἀπόλλωνος καὶ τὸ Λητῷον· ὑπέρκειται δὲ τῆς πόλεως ὄρος ψιλὸν ὁ Κύνθος καὶ τραχύ, ποταμὸς δὲ διαρρεῖ τὴν νῆσον Ἰνωπὸς οὐ μέγας· καὶ γὰρ ἡ νῆσος μικρά. τετίμηται δὲ ἐκ παλαιοῦ διὰ τοὺς θεοὺς ἀπὸ τῶν ἡρωικῶν χρόνων ἀρξαμένη· μυθεύεται γὰρ ἐνταῦθα ἡ Λητὼ τὰς ὠδῖνας ἀποθέσθαι τοῦ τε Ἀπόλλωνος καὶ τῆς Ἀρτέμιδος.<br>ἦν γὰρ τοπάροιθε φορητά<br>φησὶν ὁ Πίνδαρος<br>κυμάτεσσιν παντοδαπῶν τ’ ἀνέμων<br>ῥιπαῖσιν· ἀλλ’ ἁ Κοιογενὴς ὁπότ’ ὠδίνεσσι θύοισ’<br>ἀγχιτόκοις ἐπέβα νιν, δὴ τότε τέσσαρες ὀρθαὶ<br>πρέμνων ἀπώρουσαν χθονίων,<br>ἂν δ’ ἐπικράνοις σχέθον πέτραν ἀδαμαντοπέδιλοι<br>κίονες· ἔνθα τεκοῖσ’ εὐδαίμον’ ἐπόψατο γένναν.<br>ἔνδοξον δ’ ἐποίησαν αὐτὴν αἱ περιοικίδες νῆσοι, καλούμεναι Κυκλάδες, κατὰ τιμὴν πέμπουσαι δημοσίᾳ θεωρούς τε καὶ θυσίας καὶ χοροὺς παρθένων πανηγύρεις τε ἐν αὐτῇ συνάγουσαι μεγάλας.", "st": "10.5.2"}, {"sp": "N", "t": "κατ’ ἀρχὰς μὲν οὖν δώδεκα λέγονται· προσεγένοντο δὲ καὶ πλείους. Ἀρτεμίδωρος γοῦν [πεντεκαίδεκα] διαριθμεῖται, περὶ τῆς Ἑλένης εἰπὼν ὅτι ἀπὸ Θορίκου μέχρι Σουνίου παράκειται μακρὰ σταδίων ὅσον ἑξήκοντα τὸ μῆκος, ἀπὸ ταύτης γάρ, φησίν, αἱ καλούμεναι Κυκλάδες εἰσίν· ὀνομάζει δὲ Κέω τὴν ἐγγυτάτω τῇ Ἑλένῃ, καὶ μετὰ ταύτην Κύθνον καὶ Σέριφον καὶ Μῆλον καὶ Σίφνον καὶ Κίμωλον καὶ Πρεπέσινθον καὶ Ὠλίαρον, καὶ πρὸς ταύταις Πάρον Νάξον Σῦρον Μύκονον Τῆνον Ἄνδρον Γύαρον. τὰς μὲν οὖν ἄλλας τῶν δώδεκα νομίζω, τὴν δὲ Πρεπέσινθον καὶ Ὠλίαρον καὶ Γύαρον ἧττον· ὧν τῇ Γυάρῳ προσορμισθεὶς ἔγνων κώμιον ὑπὸ ἁλιέων συνοικούμενον· ἀπαίροντες δ’ ἐδεξάμεθα πρεσβευτὴν ἐνθένδε ὡς Καίσαρα προκεχειρισμένον τῶν ἁλιέων τινά (ἦν δ’ ἐν Κορίνθῳ Καῖσαρ βαδίζων ἐπὶ τὸν θρίαμβον τὸν Ἀκτιακόν)· συμπλέων δὴ ἔλεγε πρὸς τοὺς πυθομένους ὅτι πρεσβεύοι περὶ κουφισμοῦ τοῦ φόρου· τελοῖεν γὰρ δραχμὰς ἑκατὸν πεντήκοντα καὶ τὰς ἑκατὸν χαλεπῶς ἂν τελοῦντες. δηλοῖ δὲ τὰς ἀπορίας αὐτῶν καὶ Ἄρατος ἐν τοῖς κατὰ λεπτόν<br>ὦ Λητοῖ, σὺ μὲν ἤ με σιδηρείῃ Φολεγάνδρῳ<br>δειλὴν ἢ Γυάρῳ παρελεύσεαι αὐτίχ’ ὁμοίην.", "st": "10.5.3"}, {"sp": "N", "t": "τὴν μὲν οὖν Δῆλον ἔνδοξον γενομένην οὕτως ἔτι μᾶλλον ηὔξησε κατασκαφεῖσα ὑπὸ Ῥωμαίων Κόρινθος· ἐκεῖσε γὰρ μετεχώρησαν οἱ ἔμποροι, καὶ τῆς ἀτελείας τοῦ ἱεροῦ προκαλουμένης αὐτοὺς καὶ τῆς εὐκαιρίας τοῦ λιμένος· ἐν καλῷ γὰρ κεῖται τοῖς ἐκ τῆς Ἰταλίας καὶ τῆς Ἑλλάδος εἰς τὴν Ἀσίαν πλέουσιν· ἥ τε πανήγυρις ἐμπορικόν τι πρᾶγμά ἐστι, καὶ συνήθεις ἦσαν αὐτῇ καὶ Ῥωμαῖοι τῶν ἄλλων μάλιστα, καὶ ὅτε συνειστήκει ἡ Κόρινθος· Ἀθηναῖοί τε λαβόντες τὴν νῆσον καὶ τῶν ἱερῶν ἅμα καὶ τῶν ἐμπόρων ἐπεμελοῦντο ἱκανῶς· ἐπελθόντες δ’ οἱ τοῦ Μιθριδάτου στρατηγοὶ καὶ ὁ ἀποστήσας τύραννος αὐτὴν διελυμήναντο πάντα, καὶ παρέλαβον ἐρήμην οἱ Ῥωμαῖοι πάλιν τὴν νῆσον, ἀναχωρήσαντος εἰς τὴν οἰκείαν τοῦ βασιλέως, καὶ διετέλεσε μέχρι νῦν ἐνδεῶς πράττουσα. ἔχουσι δ’ αὐτὴν Ἀθηναῖοι.", "st": "10.5.4"}, {"sp": "N", "t": "Ῥήναια δ’ ἔρημον νησίδιόν ἐστιν ἐν τέτταρσι τῆς Δήλου σταδίοις, ὅπου τὰ μνήματα τοῖς Δηλίοις ἐστίν. οὐ γὰρ ἔξεστιν ἐν αὐτῇ τῇ Δήλῳ θάπτειν οὐδὲ καίειν νεκρόν. οὐκ ἔξεστι δὲ οὐδὲ κύνα ἐν Δήλῳ τρέφειν. ὠνομάζετο δὲ καὶ Ὀρτυγία πρότερον.", "st": "10.5.5"}, {"sp": "N", "t": "Κέως δὲ τετράπολις μὲν ὑπῆρξε, λείπονται δὲ δύο, ἥ τε Ἰουλὶς καὶ ἡ Καρθαία, εἰς ἃς συνεπολίσθησαν αἱ λοιπαί, ἡ μὲν Ποιήεσσα εἰς τὴν Καρθαίαν ἡ δὲ Κορησία εἰς τὴν Ἰουλίδα. ἐκ δὲ τῆς Ἰουλίδος ὅ τε Σιμωνίδης ἦν ὁ μελοποιὸς καὶ Βακχυλίδης ἀδελφιδοῦς ἐκείνου, καὶ μετὰ ταῦτα Ἐρασίστρατος ὁ ἰατρὸς καὶ τῶν ἐκ τοῦ περιπάτου φιλοσόφων Ἀρίστων ὁ τοῦ Βορυσθενίτου Βίωνος ζηλωτής. παρὰ τούτοις δὲ δοκεῖ τεθῆναί ποτε νόμος, οὗ μέμνηται καὶ Μένανδρος<br>καλὸν τὸ Κείων νόμιμόν ἐστι, Φανία·<br>ὁ μὴ δυνάμενος ζῆν καλῶς οὐ ζῇ κακῶς.<br>προσέταττε γάρ, ὡς ἔοικεν, ὁ νόμος τοὺς ὑπὲρ ἑξήκοντα ἔτη γεγονότας κωνειάζεσθαι καὶ τοῦ διαρκεῖν τοῖς ἄλλοις τὴν τροφήν· καὶ πολιορκουμένους δέ ποτε ὑπ’ Ἀθηναίων ψηφίσασθαί φασι τοὺς πρεσβυτάτους ἐξ αὐτῶν ἀποθανεῖν, ὁρισθέντος πλήθους ἐτῶν, τοὺς δὲ παύσασθαι πολιορκοῦντας. κεῖται δ’ ἐν ὄρει τῆς θαλάττης διέχουσα ἡ πόλις ὅσον πέντε καὶ εἴκοσι σταδίους, ἐπίνειον δ’ ἐστὶν αὐτῆς τὸ χωρίον ἐν ᾧ ἵδρυτο ἡ Κορησία κατοικίαν οὐδὲ κώμης ἔχουσα. ἔστι δὲ καὶ πρὸς τῇ Κορησίᾳ Σμινθαίου Ἀπόλλωνος ἱερὸν καὶ πρὸς Ποιηέσσῃ, μεταξὺ δὲ τοῦ ἱεροῦ καὶ τῶν τῆς Ποιηέσσης ἐρειπίων τὸ τῆς Νεδουσίας Ἀθηνᾶς ἱερόν, ἱδρυσαμένου Νέστορος κατὰ τὴν ἐκ Τροίας ἐπάνοδον. ἔστι δὲ καὶ Ἔλιξος ποταμὸς περὶ τὴν Κορησίαν.", "st": "10.5.6"}, {"sp": "N", "t": "μετὰ δὲ ταύτην Νάξος καὶ Ἄνδρος ἀξιόλογοι καὶ Πάρος· ἐντεῦθεν ἦν Ἀρχίλοχος ὁ ποιητής. ὑπὸ δὲ Παρίων ἐκτίσθη Θάσος καὶ Πάριον ἐν τῇ Προποντίδι πόλις. ἐν ταύτῃ μὲν οὖν ὁ βωμὸς λέγεται θέας ἄξιος, σταδιαίας ἔχων τὰς πλευράς· ἐν δὲ τῇ Πάρῳ ἡ Παρία λίθος λεγομένη ἀρίστη πρὸς τὴν μαρμαρογλυφίαν.", "st": "10.5.7"}, {"sp": "N", "t": "Σῦρος δ’ ἐστὶ μηκύνουσι τὴν πρώτην συλλαβήν, ἐξ ἧς Φερεκύδης ὁ Βάβυος ἦν· νεώτερος δ’ ἐστὶν ὁ Ἀθηναῖος ἐκείνου. ταύτης δοκεῖ μνημονεύειν ὁ ποιητὴς Συρίην καλῶν<br>νῆσός τις Συρίη κικλήσκεται<br>Ὀρτυγίης καθύπερθε.", "st": "10.5.8"}, {"sp": "N", "t": "Μύκονος δ’ ἐστὶν ὑφ’ ᾗ μυθεύουσι κεῖσθαι τῶν γιγάντων τοὺς ὑστάτους ὑφ’ Ἡρακλέους καταλυθέντας, ἀφ’ ὧν ἡ παροιμία “πάνθ’ ὑπὸ μίαν Μύκονον” ἐπὶ τῶν ὑπὸ μίαν ἐπιγραφὴν ἀγόντων καὶ τὰ διηρτημένα τῇ φύσει. καὶ τοὺς φαλακροὺς δέ τινες Μυκονίους καλοῦσιν ἀπὸ τοῦ τὸ πάθος τοῦτο ἐπιχωριάζειν τῇ νήσῳ.", "st": "10.5.9"}, {"sp": "N", "t": "Σέριφος δ’ ἐστὶν ἐν ᾗ τὰ περὶ τὸν Δίκτυν μεμύθευται τὸν ἀνελκύσαντα τὴν λάρνακα τοῖς δικτύοις τὴν περιέχουσαν τὸν Περσέα καὶ τὴν μητέρα Δανάην, καταπεποντωμένους ὑπ’ Ἀκρισίου τοῦ πατρὸς τῆς Δανάης· τραφῆναί τε γὰρ ἐνταῦθα τὸν Περσέα φασί, καὶ κομίσαντα τὴν τῆς Γοργόνος κεφαλήν, δείξαντα τοῖς Σεριφίοις ἀπολιθῶσαι πάντας· τοῦτο δὲ πρᾶξαι τιμωροῦντα τῇ μητρί, ὅτι αὐτὴν Πολυδέκτης ὁ βασιλεὺς ἄκουσαν ἄγεσθαι προείλετο πρὸς γάμον συμπραττόντων ἐκείνων. οὕτω δ’ ἐστὶ πετρώδης ἡ νῆσος ὥστε ὑπὸ τῆς Γοργόνος τοῦτο παθεῖν αὐτήν φασιν οἱ κωμῳδοῦντες.", "st": "10.5.10"}, {"sp": "N", "t": "τῆνος δὲ πόλιν μὲν οὐ μεγάλην ἔχει, τὸ δ’ ἱερὸν τοῦ Ποσειδῶνος μέγα ἐν ἄλσει τῆς πόλεως ἔξω θέας ἄξιον, ἐν ᾧ καὶ ἑστιατόρια πεποίηται μεγάλα, σημεῖον τοῦ συνέρχεσθαι πλῆθος ἱκανὸν τῶν συνθυόντων αὐτοῖς ἀστυγειτόνων τὰ Ποσειδώνια.", "st": "10.5.11"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ἀμοργὸς τῶν Σποράδων, ὅθεν ἦν Σιμωνίδης ὁ τῶν ἰάμβων ποιητής, καὶ Λέβινθος καὶ Λέρος …<br>καὶ τόδε Φωκυλίδου· Λέριοι κακοί, οὐχ ὁ μὲν ὃς δ’ οὔ,<br>πάντες, πλὴν Προκλέους, καὶ Προκλέης Λέριος.<br>διεβέβληντο γὰρ ὡς κακοήθεις οἱ ἐνθένδε ἄνθρωποι.", "st": "10.5.12"}, {"sp": "N", "t": "πλησίον δ’ ἐστὶ καὶ ἡ Πάτμος καὶ Κορασσίαι πρὸς δύσιν κείμεναι τῇ Ἰκαρίᾳ, αὕτη δὲ Σάμῳ. ἡ μὲν οὖν Ἰκαρία ἔρημός ἐστι, νομὰς δ’ ἔχει καὶ χρῶνται αὐταῖς Σάμιοι· τοιαύτη δ’ οὖσα ἔνδοξος ὅμως ἐστί, καὶ ἀπ’ αὐτῆς Ἰκάριον καλεῖται τὸ προκείμενον πέλαγος, ἐν ᾧ καὶ αὐτὴ καὶ Σάμος καὶ Κῶς ἐστι καὶ αἱ ἄρτι λεχθεῖσαι Κορασσίαι καὶ Πάτμος καὶ Λέρος. συνάπτει δὲ τῷ Ἰκαρίῳ τὸ Καρπάθιον πέλαγος πρὸς νότον, τούτῳ δὲ τὸ Αἰγύπτιον, πρὸς δὲ δύσιν τό τε Κρητικὸν καὶ τὸ Λιβυκόν.", "st": "10.5.13"}, {"sp": "N", "t": "καὶ ἐν τῷ Καρπαθίῳ δ’ εἰσὶ πολλαὶ τῶν Σποράδων μεταξὺ τῆς Κῶ μάλιστα καὶ Ῥόδου καὶ Κρήτης· ὧν εἰσιν Ἀστυπάλαιά τε καὶ Τῆλος καὶ Χαλκία καὶ ἃς Ὅμηρος ὀνομάζει ἐν τῷ καταλόγῳ<br>οἳ δ’ ἄρα Νίσυρόν τ’ εἶχον Κράπαθόν τε Κάσον τε,<br>καὶ Κῶν, Εὐρυπύλοιο πόλιν, νήσους τε Καλύδνας.<br>ἔξω γὰρ τῆς Κῶ καὶ τῆς Ῥόδου, περὶ ὧν ἐροῦμεν ὕστερον, τάς τε ἄλλας ἐν ταῖς Σποράσι τίθεμεν καὶ δὴ καὶ ἐνταῦθα μεμνήμεθα αὐτῶν, καίπερ τῆς Ἀσίας οὐ τῆς Εὐρώπης ἐγγὺς οὐσῶν, ἐπειδὴ τῇ Κρήτῃ καὶ ταῖς Κυκλάσι καὶ τὰς Σποράδας συμπεριλαβεῖν ἠπείγετό πως ὁ λόγος· ἐν δὲ τῇ τῆς Ἀσίας περιοδείᾳ τὰς προσεχεῖς αὐτῇ τῶν ἀξιολόγων νήσων προσπεριοδεύσομεν, Κύπρον καὶ Ῥόδον καὶ Κῶν καὶ τὰς ἐν τῇ ἐφεξῆς παραλίᾳ κειμένας, Σάμον Χίον Λέσβον Τένεδον· νῦν δὲ τὰς Σποράδας ὧν ἄξιον μνησθῆναι λοιπὸν ἔπιμεν.", "st": "10.5.14"}, {"sp": "N", "t": "ἡ μὲν οὖν Ἀστυπάλαια ἱκανῶς ἐστι πελαγία, πόλιν ἔχουσα. ἡ δὲ Τῆλος ἐκτέταται παρὰ τὴν Κνιδίαν μακρὰ ὑψηλὴ στενή, τὴν περίμετρον ὅσον ἑκατὸν καὶ τετταράκοντα σταδίων, ἔχουσα ὕφορμον. ἡ δὲ Χαλκία τῆς Τήλου διέχει σταδίους ὀγδοήκοντα, Καρπάθου δὲ τετρακοσίους, Ἀστυπαλαίας δὲ περὶ διπλασίους· ἔχει δὲ καὶ κατοικίαν ὁμώνυμον καὶ ἱερὸν Ἀπόλλωνος καὶ λιμένα.", "st": "10.5.15"}, {"sp": "N", "t": "Νίσυρος δὲ πρὸς ἄρκτον μέν ἐστι Τήλου διέχουσα αὐτῆς ὅσον ἑξήκοντα σταδίους ὅσους καὶ Κῶ διέχει, στρογγύλη δὲ καὶ ὑψηλὴ καὶ πετρώδης τοῦ μυλίου λίθου· τοῖς γοῦν ἀστυγείτοσιν ἐκεῖθέν ἐστιν ἡ τῶν μύλων εὐπορία. ἔχει δὲ καὶ πόλιν ὁμώνυμον καὶ λιμένα καὶ θερμὰ καὶ Ποσειδῶνος ἱερόν· περίμετρον δὲ αὐτῆς ὀγδοήκοντα στάδιοι. ἔστι δὲ καὶ νησία πρὸς αὐτῇ Νισυρίων λεγόμενα. φασὶ δὲ τὴν Νίσυρον ἀπόθραυσμα εἶναι τῆς Κῶ, προσθέντες καὶ μῦθον, ὅτι Ποσειδῶν διώκων ἕνα τῶν γιγάντων Πολυβώτην ἀποθραύσας τῇ τριαίνῃ τρύφος τῆς Κῶ ἐπ’ αὐτὸν βάλοι, καὶ γένοιτο νῆσος τὸ βληθὲν ἡ Νίσυρος ὑποκείμενον ἔχουσα ἐν αὐτῇ τὸν γίγαντα· τινὲς δὲ αὐτὸν ὑποκεῖσθαι τῇ Κῷ φασιν.", "st": "10.5.16"}, {"sp": "N", "t": "ἡ δὲ Κάρπαθος, ἣν Κράπαθον εἶπεν ὁ ποιητής, ὑψηλή ἐστι, κύκλον ἔχουσα σταδίων διακοσίων. τετράπολις δ’ ὑπῆρξε καὶ ὄνομα εἶχεν ἀξιόλογον, ἀφ’ οὗ καὶ τῷ πελάγει τοὔνομα ἐγένετο. μία δὲ τῶν πόλεων ἐκαλεῖτο Νίσυρος ὁμώνυμος τῇ τῶν Νισυρίων νήσῳ. κεῖται δὲ τῆς Λιβύης κατὰ Λευκὴν ἀκτήν, ἣ τῆς μὲν Ἀλεξανδρείας περὶ χιλίους διέχει σταδίους, τῆς δὲ Καρπάθου περὶ τετρακισχιλίους.", "st": "10.5.17"}, {"sp": "N", "t": "Κάσος δὲ ταύτης μὲν ἀπὸ ἑβδομήκοντά ἐστι σταδίων, τοῦ δὲ Σαμωνίου τοῦ ἄκρου τῆς Κρήτης διακοσίων πεντήκοντα· κύκλον δὲ ἔχει σταδίων ὀγδοήκοντα. ἔστι δ’ ἐν αὐτῇ καὶ πόλις ὁμώνυμος, καὶ Κασίων νῆσοι καλούμεναι πλείους περὶ αὐτήν.", "st": "10.5.18"}, {"sp": "N", "t": "νήσους δὲ Καλύδνας τὰς Σποράδας λέγειν φασὶ τὸν ποιητήν, ὧν μίαν εἶναι Κάλυμναν· εἰκὸς δ’ ὡς ἐκ τῶν Νισυρίων λέγονται καὶ Κασίων αἱ ἐγγὺς καὶ ὑπήκοοι, οὕτως καὶ τὰς τῇ Καλύμνῃ περικειμένας ἴσως τότε λεγομένῃ Καλύδνῃ· τινὲς δὲ δύο εἶναι Καλύδνας φασὶ Λέρον καὶ Κάλυμναν, ἅσπερ καὶ λέγειν τὸν ποιητήν. ὁ δὲ Σκήψιος πληθυντικῶς ὠνομάσθαι τὴν νῆσον Καλύμνας φησίν, ὡς Ἀθήνας καὶ Θήβας, δεῖν δὲ ὑπερβατῶς δέξασθαι τὸ τοῦ ποιητοῦ· οὐ γὰρ νήσους Καλύδνας λέγειν, ἀλλ’ οἳ δ’ ἄρα νήσους Νίσυρόν τ’ εἶχον Κράπαθόν τε Κάσον τε καὶ Κῶν, Εὐρυπύλοιο πόλιν, Καλύδνας τε. ἅπαν μὲν οὖν τὸ νησιωτικὸν μέλι ὡς ἐπὶ τὸ πολὺ ἀστεῖόν ἐστι καὶ ἐνάμιλλον τῷ Ἀττικῷ, τὸ δ’ ἐν ταῖσδε ταῖς νήσοις διαφερόντως, μάλιστα δὲ τὸ Καλύμνιον.", "st": "10.5.19"}], []);})();
